'use strict';

// DATA_DIR: raiz dos dados MUTÁVEIS (state/trips/charges/tokens/.env). Em multi-tenant
// cada instância recebe ECOTRIP_DATA_DIR=<.../tenants/NOME>; sem ela cai em __dirname
// (instância principal, comportamento legado inalterado). Código/estáticos (public/, certs,
// git) continuam em __dirname e são compartilhados. NUNCA gravar dados em __dirname.
const DATA_DIR = process.env.ECOTRIP_DATA_DIR || __dirname;
try { require('fs').mkdirSync(DATA_DIR, { recursive: true }); } catch (_) {}
require('dotenv').config({ path: require('path').join(DATA_DIR, '.env') });
const express  = require('express');
const { WebSocketServer } = require('ws');
const mqtt     = require('mqtt');
const fs       = require('fs');
const path     = require('path');
const http     = require('http');
const https    = require('https');
const { exec } = require('child_process');
const webpush  = require('web-push');
const apnsLive = require('./apns_live_activity');
apnsLive.init();
const impulseHelp = require('./impulse-help');
const carHelp     = require('./car-help');
const bluettiCloud = require('./bluetti-cloud');
const starlink     = require('./starlink-sitio');
const sajCloud     = require('./saj-cloud');   // nuvem SAJ direta (Catalão), sem o HA no caminho
const ocpp         = require('./ocpp-server'); // central system do carregador (OCPP 1.6J)

// Sem isto, uma rejection/exception fora de rota (timer, callback MQTT, fetch em
// background) derrubava o processo inteiro. Loga e segue — pm2 só reinicia em crash real.

// ── Health events: crashes + restarts persistidos em disco ───────────────────
// Guarda os últimos 30 dias (máx 5000 entradas). Cada restart do bridge é
// registrado como tipo 'restart' — assim dá pra ver quantas quedas houve em
// 1h/24h/7d/30d mesmo depois de o processo ter reiniciado.
const HEALTH_EVENTS_FILE = path.join(__dirname, 'health_events.json');
const HEALTH_EVENTS_MAX  = 5000;
const HEALTH_EVENTS_TTL  = 30 * 24 * 3600_000;  // 30 dias

function _loadHealthEvents() {
  try {
    const raw = JSON.parse(require('fs').readFileSync(HEALTH_EVENTS_FILE, 'utf8'));
    const cutoff = Date.now() - HEALTH_EVENTS_TTL;
    return Array.isArray(raw) ? raw.filter(e => e.ts > cutoff) : [];
  } catch (_) { return []; }
}
let _healthEvents = _loadHealthEvents();

let _healthSaveTimer = null;
function _saveHealthEvents() {
  if (_healthSaveTimer) return;
  _healthSaveTimer = setTimeout(() => {
    _healthSaveTimer = null;
    try { atomicWriteFileSync(HEALTH_EVENTS_FILE, JSON.stringify(_healthEvents)); } catch (_) {}
  }, 2000);
}

function _recordHealthEvent(type, msg, extra) {
  _healthEvents.push({ ts: Date.now(), type, msg: String(msg).slice(0, 400), ...(extra || {}) });
  // Mantém dentro do limite e remove entradas antigas
  const cutoff = Date.now() - HEALTH_EVENTS_TTL;
  if (_healthEvents.length > HEALTH_EVENTS_MAX)
    _healthEvents = _healthEvents.slice(-HEALTH_EVENTS_MAX);
  _healthEvents = _healthEvents.filter(e => e.ts > cutoff);
  _saveHealthEvents();
}
function _healthStats() {
  const now = Date.now();
  const windows = { h1: 3_600_000, h24: 86_400_000, d7: 604_800_000, d30: 2_592_000_000 };
  const r = {};
  for (const [k, ms] of Object.entries(windows)) {
    const cutoff = now - ms;
    const slice  = _healthEvents.filter(e => e.ts > cutoff);
    const restarts = slice.filter(e => e.type === 'restart');
    r[k] = {
      restarts:        restarts.length,
      restarts_planned: restarts.filter(e => e.planned).length,  // ajustes/deploys
      restarts_crash:   restarts.filter(e => !e.planned).length, // quedas
      errors:   slice.filter(e => e.type !== 'restart').length,
      total:    slice.length,
    };
  }
  return r;
}

// ── Marker de shutdown limpo: distingue restart de ajuste/deploy (SIGINT/SIGTERM
// recebido → escrevemos o marker antes de sair) de queda (crash sem marker). ──
const SHUTDOWN_MARKER = path.join(__dirname, '.clean_shutdown');
function _markCleanShutdown(reason) {
  try { require('fs').writeFileSync(SHUTDOWN_MARKER, JSON.stringify({ ts: Date.now(), reason })); } catch (_) {}
}
// Lido no boot: true se o processo anterior saiu por sinal há < 90s. Consome o marker.
function _wasPlannedRestart() {
  try {
    const fs2 = require('fs');
    if (!fs2.existsSync(SHUTDOWN_MARKER)) return false;
    const m = JSON.parse(fs2.readFileSync(SHUTDOWN_MARKER, 'utf8'));
    fs2.unlinkSync(SHUTDOWN_MARKER);
    return m && (Date.now() - m.ts) < 90_000;
  } catch (_) { return false; }
}

// ── Tailscale status (polled a cada 30s) ─────────────────────────────────────
const TS_BIN = '/Applications/Tailscale.app/Contents/MacOS/Tailscale';
let _tsStatus = { checked_at: 0, backend: null, ips: [], error: null };
function _pollTailscale() {
  exec(`"${TS_BIN}" status --json`, { timeout: 8000 }, (err, stdout) => {
    const now = Date.now();
    if (err) { _tsStatus = { checked_at: now, backend: null, ips: [], error: err.message }; return; }
    try {
      const j = JSON.parse(stdout);
      _tsStatus = { checked_at: now, backend: j.BackendState || null, ips: j.TailscaleIPs || [], error: null };
    } catch (e) { _tsStatus = { checked_at: now, backend: null, ips: [], error: 'parse error' }; }
  });
}
_pollTailscale();
setInterval(_pollTailscale, 30_000);

// ── DuckDNS + IP público (polled a cada 2min) ────────────────────────────────
const dns = require('dns');
const DUCKDNS_HOST = 'mqttrafael.duckdns.org';
// Resolve via DNS-over-HTTPS público (por HOSTNAME) — NÃO pelo resolver do
// sistema. O Mac usa MagicDNS do Tailscale (100.100.100.100) como primário, que
// dá SERVFAIL pro duckdns.org; e 1.1.1.1 literal é inalcançável daqui (UDP 53 e
// :443 atravancados). DoH por hostname é HTTPS puro (egress funciona) e reflete o
// DNS público que clientes externos (carro/OBD) enxergam.
// IMPORTANTE: falha de resolução (SERVFAIL/timeout — o DuckDNS surta de vez em
// quando) NÃO é "Divergente". match=null+error = estado transitório (amarelo);
// só vira match=false quando resolvemos um IP que REALMENTE difere do público.
const DOH_URLS = ['https://cloudflare-dns.com/dns-query', 'https://dns.google/resolve'];
let _netStatus = { checked_at: 0, public_ip: null, duckdns_ip: null, duckdns_ip_cached: null, match: null, error: null };
// Tenta cada provedor DoH em ordem até um responder com um registro A (Status 0).
function _resolveViaPublic(host, urls, cb) {
  if (!urls.length) return cb(new Error('DuckDNS não resolveu (SERVFAIL/timeout nos DNS públicos)'));
  const url = `${urls[0]}?name=${encodeURIComponent(host)}&type=A`;
  const req = https.get(url, { headers: { accept: 'application/dns-json' }, timeout: 5000 }, res => {
    let b = '';
    res.on('data', d => b += d);
    res.on('end', () => {
      try {
        const j = JSON.parse(b);
        const a = (j.Answer || []).filter(x => x.type === 1).map(x => x.data);
        if (j.Status === 0 && a.length) return cb(null, a[0]);
      } catch (_) {}
      _resolveViaPublic(host, urls.slice(1), cb);   // SERVFAIL/parse → próximo provedor
    });
  });
  req.on('timeout', () => { req.destroy(); _resolveViaPublic(host, urls.slice(1), cb); });
  req.on('error', () => _resolveViaPublic(host, urls.slice(1), cb));
}
function _fetchPublicIp(cb) {
  const req = https.get('https://api.ipify.org?format=text', { timeout: 5000 }, res => {
    let raw = ''; res.on('data', d => raw += d); res.on('end', () => cb(null, raw.trim()));
  });
  req.on('timeout', () => { req.destroy(); cb(new Error('ipify timeout')); });
  req.on('error', e => cb(e));
}
function _pollNet() {
  // IP público e resolução DuckDNS em paralelo — independentes.
  _fetchPublicIp((ipErr, pubIp) => {
    // DuckDNS NS é flaky (~60% por query); 2 passadas por provedor ⇒ ~97% de acerto.
    _resolveViaPublic(DUCKDNS_HOST, [...DOH_URLS, ...DOH_URLS], (dnsErr, duckIp) => {
      const haveBoth = !!pubIp && !!duckIp;
      const cached   = duckIp || _netStatus.duckdns_ip_cached;   // mantém último IP bom
      _netStatus = {
        checked_at: Date.now(),
        public_ip:  pubIp || null,
        duckdns_ip: duckIp || null,
        duckdns_ip_cached: cached || null,
        match:      haveBoth ? (pubIp === duckIp) : null,   // null = não dá pra comparar
        error:      dnsErr ? dnsErr.message : (ipErr ? ipErr.message : null),
      };
    });
  });
}
_pollNet();
setInterval(_pollNet, 2 * 60_000);

// ── Tailscale Funnel HTTP probe (a cada 60s) ─────────────────────────────────
// Resolve via DNS público (1.1.1.1) pra evitar MagicDNS local mascarar falha.
const FUNNEL_HOST  = 'mac-mini.tailacc6e7.ts.net';
const FUNNEL_PORTS = [443, 8443, 10000];
// Funnel desligado em 28/07/2026 (migração pro malha.dev via Cloudflare Tunnel).
// Com ele fora do ar o probe alertaria "Funnel caiu" pra sempre — alerta falso no
// canal que serve pra confiar que está tudo de pé. Flag em vez de arrancar o
// código: se algum dia o Funnel voltar como rota de emergência, é só inverter.
// FUNNEL_WATCH=1 no .env reativa.
const FUNNEL_WATCH = process.env.FUNNEL_WATCH === '1';
// Identifica o probe interno: usado pra excluí-lo do contador de host-hits.
const FUNNEL_PROBE_UA = 'ecotrip-funnel-probe/1';
let _funnelStatus     = { checked_at: 0, up: null, failed: [], error: null };
let _funnelFailCount  = 0;
function _pollFunnel() {
  dns.resolve4(FUNNEL_HOST, (err, addrs) => {
    const now = Date.now();
    if (err || !addrs?.length) {
      _funnelFailCount++;
      _funnelStatus = { checked_at: now, up: _funnelFailCount < 2 ? null : false, failed: [], fail_count: _funnelFailCount, error: 'DNS falhou: ' + (err?.message || 'sem resultado') };
      return;
    }
    const ip = addrs[0];
    const checks = FUNNEL_PORTS.map(port => new Promise(resolve => {
      // UA próprio pra este probe sair da contagem de host-hits: ele bate no
      // Funnel a cada 15s em 3 portas (~48 requests/4min) e inflava o número que
      // usamos pra decidir se ainda tem cliente de verdade no hostname antigo.
      const opts = { hostname: ip, port, path: '/', method: 'HEAD', timeout: 7000,
                     headers: { Host: FUNNEL_HOST, 'User-Agent': FUNNEL_PROBE_UA },
                     rejectUnauthorized: false };
      const req = https.request(opts, res => { res.resume(); resolve({ port, ok: true }); });
      req.on('error', () => resolve({ port, ok: false }));
      req.on('timeout', () => { req.destroy(); resolve({ port, ok: false }); });
      req.end();
    }));
    Promise.all(checks).then(results => {
      const failed = results.filter(r => !r.ok).map(r => r.port);
      if (failed.length > 0) {
        _funnelFailCount++;
      } else {
        _funnelFailCount = 0;
      }
      // up=false só após 2 falhas consecutivas (evita falso positivo de 1 ciclo)
      _funnelStatus = { checked_at: Date.now(), up: failed.length === 0 ? true : (_funnelFailCount >= 2 ? false : null), failed, fail_count: _funnelFailCount, ip, error: null };
    });
  });
}
_pollFunnel();
if (FUNNEL_WATCH) setInterval(_pollFunnel, 15_000);   // 15s — só quando o Funnel está em uso (ver FUNNEL_WATCH)

// Registra transições UP↔DOWN do Funnel em _healthEvents pra correlacionar
// com alertas externos ("Mac Mini inalcançável" do HA do Sítio). Antes
// dependia só do state do alert; agora deixa rastro forense com timestamp.
let _lastFunnelUp = null;
setInterval(() => {
  const up = _funnelStatus.up;
  if (up === null) return;
  if (_lastFunnelUp === null) { _lastFunnelUp = up; return; }
  // 8 dos 9 episódios em 8 dias duraram 15s: uma porta piscando em 2 polls vira
  // par down/up no log. Não empurra push (funnel_down é AGENT_OWNED), mas polui o
  // forense e acorda o agente à toa. Só registra o que sobreviver a 2min.
  if (up !== _lastFunnelUp) {
    if (!_sustained('funnel_transition', true, true, 2 * 60_000)) return;
    _sustain.delete('funnel_transition');
    _recordHealthEvent('funnel_' + (up ? 'up' : 'down'),
      `Funnel ${up ? 'voltou' : 'caiu'} · failed=${(_funnelStatus.failed||[]).join(',')} · fail_count=${_funnelStatus.fail_count}`);
    _lastFunnelUp = up;
  } else {
    _sustain.delete('funnel_transition');   // voltou sozinho antes de confirmar
  }
}, 15_000);

// Ping externo (8.8.8.8) contínuo pra distinguir "Funnel/Tailscale caiu" vs
// "toda a internet caiu". Assim, quando bater rajada, dá pra ver no log se
// foi ISP flap (external_gap dispara) ou só Tailscale (só funnel_down).
let _externalReachable = null;
function _pollExternal() {
  const { spawn } = require('child_process');
  const p = spawn('ping', ['-c', '1', '-W', '1500', '8.8.8.8']);
  let done = false;
  const timer = setTimeout(() => { if (!done) { done = true; p.kill(); react(false); } }, 3000);
  const react = (ok) => {
    if (done) return; done = true; clearTimeout(timer);
    if (_externalReachable !== null && _externalReachable !== ok) {
      _recordHealthEvent('external_' + (ok ? 'up' : 'down'),
        `Ping externo ${ok ? 'voltou' : 'perdeu'} (8.8.8.8)`);
    }
    _externalReachable = ok;
  };
  p.on('exit', code => react(code === 0));
  p.on('error', () => react(false));
}
_pollExternal();
setInterval(_pollExternal, 15_000);

// ── MQTT latency ping (dispara após connect, a cada 30s) ─────────────────────
let _mqttPing = { checked_at: 0, latency_ms: null, error: null };
let _mqttPingTs = 0;
function _pingMqtt() {
  if (!mqttClient?.connected) return;
  _mqttPingTs = Date.now();
  mqttClient.publish(`${MQTT_PREFIX}/_ping`, String(_mqttPingTs), { qos: 0, retain: false });
}

// ── Home Assistant health (polled a cada 30s) ────────────────────────────────
// URL vem do env pra usar a MESMA rota que o resto do bridge (evita split-brain
// onde o probe cai mas o bridge segue acessando HA). Fallback só se env vazio.
// process.env é lido a cada poll pelo mesmo motivo do token: TDZ (HA_URL como
// const só é declarada bem depois no arquivo).
let _haStatus    = { checked_at: 0, up: null, latency_ms: null, error: null };
let _haFailCount = 0;
function _pollHA() {
  const t0 = Date.now();
  // /api/ exige auth — sem o Bearer, HA loga "invalid authentication" (ban.py)
  // a cada poll e pode banir o IP do bridge. Token lido de process.env porque
  // a const HA_TOKEN só é declarada depois deste ponto (TDZ no _pollHA inicial).
  const tok = process.env.HA_TOKEN || '';
  const primary = (process.env.HA_URL || 'http://192.168.1.30:8123').replace(/\/$/, '');
  // Fallback é a outra rota pra mesma VM: se HA_URL é a UTM shared (.64.3),
  // tenta a LAN (.1.30) — e vice-versa. As duas rotas oscilam de forma
  // independente (rota UTM stale via bridge sem IP; LAN flapa em WiFi/idle),
  // então só reporta down se AMBAS falharem. Elimina falso positivo do monitor.
  const fallback = /192\.168\.64\.3/.test(primary)
    ? 'http://192.168.1.30:8123'
    : 'http://192.168.64.3:8123';
  const opts = { timeout: 5000, headers: tok ? { Authorization: `Bearer ${tok}` } : {} };
  const onSuccess = () => {
    _haFailCount = 0;
    _haStatus = { checked_at: Date.now(), up: true, latency_ms: Date.now() - t0, error: null };
  };
  const onFail = (msg) => {
    _haFailCount++;
    _haStatus = { checked_at: Date.now(), up: _haFailCount >= 2 ? false : null, latency_ms: null, error: msg };
  };
  const probe = (url, onDone) => {
    const req = http.get(url + '/api/', opts, res => { res.resume(); onDone(null); });
    req.on('error', e => onDone(e.message));
    req.on('timeout', () => { req.destroy(); onDone('timeout'); });
  };
  probe(primary, (err1) => {
    if (!err1) return onSuccess();
    if (primary === fallback) return onFail(`${primary}: ${err1}`);
    probe(fallback, (err2) => err2
      ? onFail(`primary(${primary}): ${err1} · fallback(${fallback}): ${err2}`)
      : onSuccess());
  });
}
_pollHA();
setInterval(_pollHA, 5_000);

// ── Mosquitto ports probe (1883 plain + 8883 TLS, a cada 30s) ───────────────
const net = require('net');
let _mqttBrokerStatus = { checked_at: 0, port1883: null, port8883: null, fail_count: 0, errors: null };
let _mqttBrokerFailCount = 0;
function _probeTcpPort(host, port) {
  return new Promise(resolve => {
    const sock = new net.Socket();
    const timer = setTimeout(() => { sock.destroy(); resolve({ ok: false, error: 'timeout' }); }, 3000);
    sock.connect(port, host, () => { clearTimeout(timer); sock.destroy(); resolve({ ok: true, error: null }); });
    sock.on('error', (e) => { clearTimeout(timer); resolve({ ok: false, error: e.code || e.message }); });
  });
}
async function _pollMqttBroker() {
  const [r1883, r1884, r8883] = await Promise.all([
    _probeTcpPort('127.0.0.1', 1883),
    _probeTcpPort('127.0.0.1', 1884),
    _probeTcpPort('127.0.0.1', 8883),
  ]);
  const allOk = r1883.ok && r1884.ok && r8883.ok;
  if (!allOk) _mqttBrokerFailCount++; else _mqttBrokerFailCount = 0;
  _mqttBrokerStatus = {
    checked_at: Date.now(), port1883: r1883.ok, port1884: r1884.ok, port8883: r8883.ok,
    fail_count: _mqttBrokerFailCount,
    errors: [r1883.error && `1883:${r1883.error}`, r1884.error && `1884:${r1884.error}`, r8883.error && `8883:${r8883.error}`]
      .filter(Boolean).join(', ') || null,
  };
}
_pollMqttBroker();
setInterval(_pollMqttBroker, 5_000);

// ── Gateway LAN ping (polled a cada 30s) ─────────────────────────────────────
let _gwStatus    = { checked_at: 0, up: null, latency_ms: null, error: null };
let _gwFailCount = 0;
function _pollGateway() {
  const t0 = Date.now();
  exec('ping -c 1 -W 2 192.168.1.1', { timeout: 4000 }, (err, stdout, stderr) => {
    if (!err) { _gwFailCount = 0; _gwStatus = { checked_at: Date.now(), up: true, latency_ms: Date.now() - t0, error: null }; }
    else {
      _gwFailCount++;
      const errMsg = (stderr || err.message || '').trim().slice(0, 200);
      _gwStatus = { checked_at: Date.now(), up: _gwFailCount >= 2 ? false : null, latency_ms: null,
        error: errMsg };
    }
  });
}
_pollGateway();
setInterval(_pollGateway, 5_000);

// ── TLS cert expiry ───────────────────────────────────────────────────────────
const crypto = require('crypto');
const { X509Certificate } = crypto;
let _certStatus = { checked_at: 0, expires_at: null, days_left: null, error: null };
function _checkCert() {
  try {
    const pem = fs.readFileSync(path.join(__dirname, 'cert.pem'), 'utf8');
    const cert = new X509Certificate(pem);
    const expiresAt = new Date(cert.validTo).getTime();
    const daysLeft  = Math.floor((expiresAt - Date.now()) / 86_400_000);
    _certStatus = { checked_at: Date.now(), expires_at: expiresAt, days_left: daysLeft, error: null };
  } catch (e) { _certStatus = { checked_at: Date.now(), expires_at: null, days_left: null, error: e.message }; }
}
_checkCert();
setInterval(_checkCert, 6 * 3600_000);   // a cada 6h

// Cert TLS do broker MQTT (listener 8883). Renovado pelo acme.sh; se vencer, o
// carro/NavRelay/OBD param de conectar. Path != cert.pem do bridge.
const BROKER_CERT_PATH = process.env.MQTT_BROKER_CERT ||
  '/Users/consorciolimpagyn/.acme.sh/mqttrafael.duckdns.org_ecc/fullchain.cer';
let _certBrokerStatus = { checked_at: 0, expires_at: null, days_left: null, error: null };
function _checkBrokerCert() {
  try {
    const cert = new X509Certificate(fs.readFileSync(BROKER_CERT_PATH, 'utf8'));
    const expiresAt = new Date(cert.validTo).getTime();
    _certBrokerStatus = { checked_at: Date.now(), expires_at: expiresAt,
      days_left: Math.floor((expiresAt - Date.now()) / 86_400_000), error: null };
  } catch (e) { _certBrokerStatus = { checked_at: Date.now(), expires_at: null, days_left: null, error: e.message }; }
}
_checkBrokerCert();
setInterval(_checkBrokerCert, 6 * 3600_000);

// ── Central de monitoramento inteligente → ntfy ───────────────────────────────
const NTFY_URL   = 'https://ntfy.sh/tailscale-watchdog-863a94c906c1428974be4d4fa5b3e572';
const NTFY_COOLDOWN    = 60 * 60_000;   // mínimo 60min entre notifs "(ainda)" do mesmo alerta
const ALERT_FIRE_DELAY = 2.5 * 60_000; // só notifica se falha persistir 2.5min
// Silêncio noturno: nessa janela só entra 1ª queda e recuperação — pula "(ainda)".
const QUIET_START_H = 23;
const QUIET_END_H   = 7;
function _inQuietHours() {
  const h = new Date().getHours();
  return QUIET_START_H > QUIET_END_H ? (h >= QUIET_START_H || h < QUIET_END_H)
                                      : (h >= QUIET_START_H && h < QUIET_END_H);
}
// Gap de wall-clock entre ticks que delata sleep/suspend do Mac (setInterval
// pausa dormindo, mas os timers de debounce usam Date.now()). Acima disso,
// trata como wake: reseta o debounce e pula 1 ciclo pros pollers reamostrarem.
const WAKE_GAP_MS      = 3 * 60_000;

// alertId → { firing, firedAt, lastNotifiedAt, notified }
// Persistido em disco pra sobreviver a restarts do bridge — senão a transição
// firing→!firing (recovery) some quando o restart acontece entre a queda e a
// recuperação, e o "Recuperado" nunca sai pro ntfy → HA do Sítio fica com badge
// preso em "atenção".
const ALERT_STATE_FILE = path.join(DATA_DIR, 'alert_state.json');
const _alertState = new Map();
try {
  const raw = fs.readFileSync(ALERT_STATE_FILE, 'utf8');
  for (const [k, v] of Object.entries(JSON.parse(raw))) _alertState.set(k, v);
} catch (_) { /* primeira execução ou arquivo corrompido: começa vazio */ }
let _alertStateSaveTimer = null;
function _saveAlertState() {
  if (_alertStateSaveTimer) return;               // debounce 500ms — muitas escritas por ciclo
  _alertStateSaveTimer = setTimeout(() => {
    _alertStateSaveTimer = null;
    try {
      const obj = Object.fromEntries(_alertState);
      atomicWriteFileSync(ALERT_STATE_FILE, JSON.stringify(obj));
    } catch (e) { /* não paralisa o bridge por falha de disco */ }
  }, 500);
}

// Header HTTP só aceita Latin-1. Emoji e travessão no Title faziam o Node lançar
// ERR_INVALID_CHAR ANTES de mandar a requisição — e como todo chamador de _alert
// está sob .catch, o push sumia calado. 29 dos 60 títulos de alerta caíam nisso
// (todo o solar, o Bluetti, o pré-clima). RFC 2047 é o que o ntfy documenta pra
// título não-ASCII.
function _hdrSafe(v) {
  const s = String(v);
  return /^[\x20-\x7E]*$/.test(s) ? s
    : '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=';
}
function _ntfy(title, body, priority = 'default', tags = [], urlOverride = null) {
  const bodyBuf = Buffer.from(body, 'utf8');
  const headers = {
    'Title':          _hdrSafe(title),
    'Priority':       priority,
    'Content-Type':   'text/plain; charset=utf-8',
    'Content-Length': bodyBuf.length,
  };
  if (tags.length) headers['Tags'] = _hdrSafe(tags.join(','));
  let req;
  try {
    req = https.request(urlOverride || NTFY_URL, { method: 'POST', headers }, res => res.resume());
  } catch (e) { console.warn('[ntfy] request inválida:', e.message); return; }
  req.on('error', () => {});
  req.write(bodyBuf);
  req.end();
}

// ── Baseline matrix (preditivo) ────────────────────────────────────────────
// Grava a mediana rolante de ETAs Google observados por (par-de-locais, dow, hora).
// Roda a cada 15 min entre 6-20h; refresca cada par se cache > 60 min (rush) OU
// > 180 min (fora do rush). Pares "úteis" = os que apareceram em autotrips últimos
// 30d + os das Saídas monitoradas (_group departure_share). Cap de 15 pares por
// tick pra segurar custo (~$40/mês).
const BASELINE_MATRIX_FILE = path.join(DATA_DIR, 'baseline_matrix.json');
const BASELINE_COST_FILE   = path.join(DATA_DIR, 'baseline_cost.json');
let _baselineMatrix = {};    // { "roundLat,roundLng→roundLat,roundLng_dow_hour": { samples:[{ts,etaMin}], median, updated_ms } }
let _baselineCostToday = { date: '', calls: 0, cost_usd: 0 };
try { _baselineMatrix = JSON.parse(fs.readFileSync(BASELINE_MATRIX_FILE, 'utf8')) || {}; } catch (_) {}
try { _baselineCostToday = JSON.parse(fs.readFileSync(BASELINE_COST_FILE, 'utf8')) || _baselineCostToday; } catch (_) {}
function _bmKey(from, to, dow, hour) {
  const r = (v) => (Math.round(v * 200) / 200).toFixed(3);   // grade ~500m
  return `${r(from.lat)},${r(from.lng)}→${r(to.lat)},${r(to.lng)}_${dow}_${hour}`;
}
function _bmSave() {
  try { atomicWriteFileSync(BASELINE_MATRIX_FILE, JSON.stringify(_baselineMatrix)); } catch (_) {}
  try { atomicWriteFileSync(BASELINE_COST_FILE, JSON.stringify(_baselineCostToday)); } catch (_) {}
}
function _bmMedian(samples) { const a = samples.map(s => s.etaMin).sort((x,y) => x-y); return a[Math.floor(a.length/2)]; }
function _bmIsRushHour(h) { return (h >= 6 && h < 9) || (h >= 16 && h < 20); }

// Pares úteis: SOMENTE Saídas monitoradas (_group: departure_share). O usuário
// escolhe explicitamente o que quer monitorar (origem, destino, dias, janela).
// Retorna com dias/janela pra o scanner respeitar o horário de cada config.
function _bmUsefulPairs() {
  const out = [];
  for (const r of (automationRules || [])) {
    if (!((r._group || '').startsWith('departure_share:'))) continue;
    if ((r.action || {}).type !== 'notify' || r.action.template !== 'traffic_delay') continue;
    if (r.enabled === false) continue;
    const from = r.action.from, to = r.action.to;
    if (!from || !to || from.lat == null || to.lat == null) continue;
    const cond = ((r.conditions || {}).items || []).find(i => i.type === 'time') || {};
    out.push({
      from: { lat: from.lat, lng: from.lng },
      to:   { lat: to.lat,   lng: to.lng   },
      days: cond.days || [],
      fromHhmm:  cond.from_hhmm ?? 0,
      untilHhmm: cond.to_hhmm ?? 1439,
      group: r._group,
    });
  }
  return out.slice(0, 15);   // cap 15 pares (custo)
}

async function _bmTick() {
  if (notifPrefs.baseline_predictive === false) return;
  const now = new Date();
  const hour = now.getHours(), min = now.getMinutes(), dow = now.getDay();
  const minuteOfDay = hour * 60 + min;
  const nowMs = Date.now();
  const todayStr = `${now.getFullYear()}-${now.getMonth()+1}-${now.getDate()}`;
  if (_baselineCostToday.date !== todayStr) _baselineCostToday = { date: todayStr, calls: 0, cost_usd: 0 };
  // Só pares cuja janela cobre AGORA (com folga de ±60min pra ter dados quando
  // a rule dispara na borda) E cujo dia da semana bate.
  const pairs = _bmUsefulPairs().filter(p => {
    if (p.days.length && !p.days.includes(dow)) return false;
    const from = Math.max(0, p.fromHhmm - 60);
    const until = Math.min(1439, p.untilHhmm + 60);
    return minuteOfDay >= from && minuteOfDay <= until;
  });
  const maxAgeMs = _bmIsRushHour(hour) ? 60 * 60_000 : 180 * 60_000;
  for (const p of pairs) {
    const key = _bmKey(p.from, p.to, dow, hour);
    const cur = _baselineMatrix[key];
    if (cur && (nowMs - (cur.updated_ms || 0)) < maxAgeMs) continue;
    // Refresca via Google Directions (departure_time=now)
    try {
      const route = await _fetchRoute(p.from.lat, p.from.lng, p.to.lat, p.to.lng);
      if (!route) continue;
      const etaMin = Math.round(route.duration / 60);
      const rec = cur || { samples: [], median: etaMin, updated_ms: 0 };
      rec.samples.push({ ts: nowMs, etaMin });
      if (rec.samples.length > 30) rec.samples.splice(0, rec.samples.length - 30);
      rec.median = _bmMedian(rec.samples);
      rec.updated_ms = nowMs;
      _baselineMatrix[key] = rec;
      _baselineCostToday.calls += 1;
      _baselineCostToday.cost_usd = +(_baselineCostToday.calls * 0.01).toFixed(4);
    } catch (e) { console.warn('[baseline] falhou:', e.message); }
  }
  _bmSave();
}
setInterval(() => { _bmTick().catch(() => {}); }, 15 * 60_000);
setTimeout(() => { _bmTick().catch(() => {}); }, 60_000);   // primeiro tick 1min após boot

// GET /api/baseline-status registrado depois do `const app = express()` (linha ~4137);
// aqui só define matrix + scanner. Se registrar `app.get` neste ponto, TDZ mata o boot.

// ── Saídas monitoradas: LA "Indo pra <dest>?" via APNs push-to-start ────────
// Quando o motor liga (engine_state 0→1), o bridge verifica todas as configs
// de Saídas monitoradas (rules com _group=departure_share:*): se a posição do
// carro cai dentro do raio da origem + o horário está na janela + dia da
// semana bate + a config não foi acionada hoje ainda, dispara push-to-start
// da DepartureAskActivityAttributes no iPhone do dono. A LA nasce mesmo com
// o app fechado (iOS 17.2+).
const DEPARTURE_ASKED_FILE = path.join(DATA_DIR, 'departure_asked.json');
let _departureAsked = {};
try { _departureAsked = JSON.parse(fs.readFileSync(DEPARTURE_ASKED_FILE, 'utf8')) || {}; } catch (_) {}
// Última coord com motor DESLIGADO — usada em _evalDepartureAsk pra compensar
// o gap entre engine 0→1 e a chegada da 1a msg MQTT (que pode ser 30s+ depois).
let _lastParkedLoc = null;   // { lat, lng, ts }
function _saveDepartureAsked() {
  try { atomicWriteFileSync(DEPARTURE_ASKED_FILE, JSON.stringify(_departureAsked)); } catch (_) {}
}
function _evalDepartureAsk() {
  if (!apnsLive.enabled) return;
  // GPS de referência: prioriza a última coord com motor DESLIGADO (onde o carro
  // ESTACIONOU) — o APK pode demorar segundos/minutos pra reconectar MQTT
  // depois de ligar, e nesse gap o carro já pode ter saído do raio da origem.
  // Se a última parking coord tem <10min, usa ela. Senão fallback pra GPS atual.
  let lat = +state.gps_lat, lng = +state.gps_lng;
  const parked = _lastParkedLoc;
  if (parked && parked.lat && (Date.now() - parked.ts) < 10 * 60_000) {
    lat = parked.lat; lng = parked.lng;
  }
  if (!Number.isFinite(lat) || !Number.isFinite(lng) || (lat === 0 && lng === 0)) {
    console.log('[departure-ask] pulou: sem GPS ainda'); return;
  }
  console.log(`[departure-ask] avaliando de lat=${lat.toFixed(5)} lng=${lng.toFixed(5)}`);
  const now = new Date();
  const dow = now.getDay();                             // 0=Dom..6=Sáb
  const minuteOfDay = now.getHours() * 60 + now.getMinutes();
  const today = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  const hav = (a, b, c, d) => {
    const R = 6_371_000, r = x => x * Math.PI / 180;
    const dLat = r(c - a), dLon = r(d - b);
    const h = Math.sin(dLat/2)**2 + Math.cos(r(a)) * Math.cos(r(c)) * Math.sin(dLon/2)**2;
    return 2 * R * Math.asin(Math.sqrt(h));
  };
  // Configs = rules com _group departure_share, action.type=notify, template=traffic_delay
  for (const r of (automationRules || [])) {
    const g = r._group || '';
    if (!g.startsWith('departure_share:')) continue;
    if (r.enabled === false) continue;
    if ((r.action || {}).type !== 'notify' || r.action.template !== 'traffic_delay') continue;
    if ((r.trigger || {}).edge !== 'exit') continue;    // pega só o "sair"
    const cid = g.replace('departure_share:', '');
    const src = r.trigger || {}; const a = r.action || {};
    const to = a.to || {};
    if (src.lat == null || to.lat == null) continue;
    const cond = ((r.conditions || {}).items || []).find(x => x.type === 'time') || {};
    const days = cond.days || [];
    if (days.length && !days.includes(dow)) continue;
    const from = cond.from_hhmm ?? 0, until = cond.to_hhmm ?? 1439;
    if (minuteOfDay < from || minuteOfDay > until) continue;
    const d = hav(lat, lng, src.lat, src.lng);
    // Raio efetivo maior: geofence do editor pode ser 15m (bom pra rules do
    // AutomationManager no carro), mas o bridge só recebe engine_on segundos
    // depois — nesse ponto GPS já se moveu. 500m cobre o gap sem falso match.
    const radius = Math.max(+src.radius_m || 50, 500);
    if (d > radius) { console.log(`[departure-ask] cid=${cid} fora do raio (${Math.round(d)}m > ${radius}m)`); continue; }
    // Já perguntou hoje?
    const askedKey = `${cid}_${today}`;
    if (_departureAsked[askedKey]) { console.log(`[departure-ask] cid=${cid} já perguntado hoje, pula`); continue; }
    // Passou tudo — marca ANTES do push pra evitar duplicidade em race
    _departureAsked[askedKey] = Date.now(); _saveDepartureAsked();
    const sourceName = (a.from || {}).name || r.name || 'Origem';
    const destName   = to.name || 'Destino';
    const subject    = a.subject || 'Grasi';
    console.log(`[departure-ask] cid=${cid} disparando LA (${sourceName} → ${destName})`);
    apnsLive.pushStart('DepartureAskActivityAttributes', '',
      { configId: cid, sourceName, destName, subject },
      { startedMs: Date.now(), status: 'asking', resultText: null },
      { staleDate: Date.now() + 15 * 60_000,
        alert: { title: `Indo pra ${destName}?`, body: `Toque nos botões pra decidir.` } })
      .catch(e => { console.warn('[departure-ask] pushStart falhou:', e.message);
                    delete _departureAsked[askedKey]; _saveDepartureAsked(); });
  }
  // Limpa entries antigas (>7 dias) da tabela asked pra não crescer sem limite
  const cutoff = Date.now() - 7 * 24 * 3600_000;
  for (const k of Object.keys(_departureAsked)) {
    if (_departureAsked[k] < cutoff) delete _departureAsked[k];
  }
}

// Snapshot de trânsito: cada vez que a rule traffic_delay dispara (Rafael saiu
// do trabalho), grava um registro pra auditoria. Rolling 200 entradas.
const TRAFFIC_SNAPSHOTS_FILE = path.join(DATA_DIR, 'traffic_snapshots.json');
let _trafficSnapshots = [];
try { _trafficSnapshots = JSON.parse(fs.readFileSync(TRAFFIC_SNAPSHOTS_FILE, 'utf8')) || []; } catch (_) {}
function _appendTrafficSnapshot(snap) {
  _trafficSnapshots.push(snap);
  if (_trafficSnapshots.length > 200) _trafficSnapshots.splice(0, _trafficSnapshots.length - 200);
  try { atomicWriteFileSync(TRAFFIC_SNAPSHOTS_FILE, JSON.stringify(_trafficSnapshots)); } catch (_) {}
}

// Baseline dinâmico: PRIMEIRO tenta a matrix preditiva (Google ETAs observados
// no mesmo dow+hour, mediana rolante) — se tiver ≥3 samples, usa. SENÃO cai em
// autotrips (viagens reais últimos 30d, same-dow). Retorna {minMedian, samples,
// source}. Null se nenhum dos dois tiver dado.
function _dynamicTrafficBaseline(from, to, opts = {}) {
  // (1) Matrix — mesmo dow, hour ± 1h (mais tolerante que exato pra ter samples)
  const now = new Date();
  const dow = now.getDay(), hour = now.getHours();
  const collected = [];
  for (const dh of [0, -1, 1]) {
    const h = hour + dh; if (h < 0 || h > 23) continue;
    const key = _bmKey(from, to, dow, h);
    const rec = _baselineMatrix[key];
    if (rec && Array.isArray(rec.samples)) collected.push(...rec.samples);
  }
  if (collected.length >= 3) {
    const arr = collected.map(s => s.etaMin).sort((x, y) => x - y);
    return { minMedian: arr[Math.floor(arr.length / 2)], samples: arr.length, source: 'matrix' };
  }
  // (2) autotrips fallback (comportamento original)
  const matchM = opts.matchM || 500;              // raio de pareamento (m)
  const days = opts.days || 60;                   // janela histórica
  const minSamples = opts.minSamples || 3;        // mínimo pra confiar na mediana
  const cutoffMs = Date.now() - days * 24 * 3600 * 1000;
  const dir = path.join(DATA_DIR, 'autotrips');
  let files = [];
  try { files = fs.readdirSync(dir).filter(f => f.endsWith('.json')); } catch { return null; }
  const secs = [];
  const hav = (a, b, c, d) => {
    const R = 6_371_000, r = x => x * Math.PI / 180;
    const dLat = r(c - a), dLon = r(d - b);
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(r(a)) * Math.cos(r(c)) * Math.sin(dLon / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(h));
  };
  for (const f of files) {
    try {
      const t = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')).autoTrip;
      if (!t || !t.timeSec || !t.startLat || !t.endLat || !t.endMs) continue;
      if (t.endMs < cutoffMs) continue;
      if (new Date(t.endMs).getDay() !== dow) continue;
      if (hav(t.startLat, t.startLng, from.lat, from.lng) > matchM) continue;
      if (hav(t.endLat, t.endLng, to.lat, to.lng) > matchM) continue;
      secs.push(t.timeSec);
    } catch (_) {}
  }
  if (secs.length < minSamples) return null;
  secs.sort((a, b) => a - b);
  const median = secs[Math.floor(secs.length / 2)];
  return { minMedian: Math.round(median / 60), samples: secs.length };
}

// Envia mensagem WhatsApp via whats-assistant Mari (POST /api/say com basic auth).
// Env do bridge: WA_ASSIST_URL, WA_ASSIST_USER, WA_ASSIST_PASS. jid vem por rule
// (action.jid) ou fallback env WA_FAMILY_JID.
async function _waSend(jid, text) {
  const base = process.env.WA_ASSIST_URL;
  const user = process.env.WA_ASSIST_USER, pass = process.env.WA_ASSIST_PASS;
  if (!base || !jid) { console.warn('[notify] whatsapp: WA_ASSIST_URL ou jid ausente'); return false; }
  const auth = user && pass ? 'Basic ' + Buffer.from(`${user}:${pass}`).toString('base64') : null;
  try {
    const r = await fetch(base.replace(/\/$/, '') + '/api/say', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(auth ? { Authorization: auth } : {}) },
      body: JSON.stringify({ jid, text }),
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) { console.warn('[notify] whatsapp HTTP', r.status); return false; }
    return true;
  } catch (e) { console.warn('[notify] whatsapp erro:', e.message); return false; }
}

// Executa `action.type = "notify"` disparada por regra do APK. Templates conhecidos:
//   • traffic_delay — mede ETA now vs baseline (Google Directions). Baseline vem
//     do drive_history via _dynamicTrafficBaseline se houver ≥3 viagens no mesmo
//     dow, senão cai no `baseline_min` fixo da regra. Só notifica se atrasado
//     ≥ threshold. Evita ruído de "trânsito normal, saí do trabalho".
//   • arrived_home — mensagem simples de chegada, formatada com hora local.
//   • (fallback) usa title/body direto da regra sem processar.
// Canal: `action.channel` = "ntfy" (default) | "whatsapp" | "both".
//   ntfy topic: `action.ntfy_url` OU env NTFY_FAMILY_URL OU NTFY_URL.
//   whatsapp: usa Mari (whats-assistant) via WA_ASSIST_URL; JID de `action.jid`
//   ou env WA_FAMILY_JID.
async function _handleNotifyAction(rule) {
  const a = rule.action || {};
  const tpl = a.template || '';
  // channel aceita string ("ntfy"|"whatsapp"|"la"|"both"|"all") OU array (["ntfy","la"]).
  //   "la" = usa a LA SharedTripActivityAttributes no app Grasi Recarga (reaproveita
  //   o compartilhamento de trajeto que hoje é manual). "all" = ntfy+whatsapp+la.
  //   "both" mantém compat = ntfy+whatsapp.
  const raw = a.channel || 'ntfy';
  const ch = Array.isArray(raw) ? raw : (raw === 'all' ? ['ntfy','whatsapp','la'] : raw === 'both' ? ['ntfy','whatsapp'] : [raw]);
  const wantNtfy = ch.includes('ntfy');
  const wantWa   = ch.includes('whatsapp');
  const wantLa   = ch.includes('la');
  const ntfyUrl = a.ntfy_url || process.env.NTFY_FAMILY_URL || NTFY_URL;
  const jid = a.jid || process.env.WA_FAMILY_JID;
  const who = a.subject || 'Rafael';
  // Helper pra canais "texto" (ntfy/whatsapp). LA é tratada nos templates específicos.
  const send = async (title, body, tags = ['bell']) => {
    if (wantNtfy) _ntfy(title, body, 'default', tags, ntfyUrl);
    if (wantWa) {
      const text = title ? `*${title}*\n${body}` : body;
      await _waSend(jid, text);
    }
  };
  if (tpl === 'traffic_delay') {
    const from = a.from, to = a.to;
    if (!from || !to || from.lat == null || to.lat == null) {
      console.warn('[notify] traffic_delay sem from/to na regra', rule.id); return;
    }
    const route = await _fetchRoute(from.lat, from.lng, to.lat, to.lng);
    if (!route) { console.warn('[notify] traffic_delay: rota indisponível'); return; }
    const etaMin = Math.round(route.duration / 60);
    const dyn = _dynamicTrafficBaseline(from, to);
    const baseline = (dyn && dyn.minMedian) || +a.baseline_min || 27;
    const source = dyn ? `histórico dow (${dyn.samples})` : `fixo ${baseline}min`;
    const threshold = +a.threshold_min || 10;
    const delta = etaMin - baseline;
    if (delta < threshold) {
      console.log(`[notify] traffic_delay skip: eta=${etaMin} baseline=${baseline} (${source}) delta=${delta} < ${threshold}`);
      return;
    }
    const arrive = new Date(Date.now() + route.duration * 1000);
    const hhmm = arrive.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    await send(a.title || `Trânsito ruim, ${who} vai atrasar`,
               `Saindo agora. ETA ${hhmm} · trânsito +${delta} min acima do normal (baseline ${baseline}min).`,
               ['car', 'hourglass']);
    // Snapshot pra auditoria: fica salvo aqui mesmo se não houver share ativa.
    // A LA (quando Rafael compartilhar) puxa delayMin do cs — não precisamos
    // pushar alert-banner separado. Silêncio > ruído.
    _appendTrafficSnapshot({
      ts: Date.now(), from, to, etaMin, baseline, source, threshold, delta,
      shared: wantLa && Object.values(_sharedTripLAs).some(st => {
        const tk = _shareTokens[st.token]; return st.laActive && tk && tk.recipientRole === 'grasi';
      }),
    });
    // Nada mais a fazer no LA aqui — o _evalSharedTripLAs vai pegar o delayMin
    // no próximo ciclo (≤20s) e atualizar a LA da Grasi se ela estiver ativa.
    return;
  }
  if (tpl === 'arrived_home') {
    const hhmm = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    await send(a.title || `${who} chegou em casa`,
               a.body || `${who} chegou em casa às ${hhmm}.`,
               ['house']);
    // Canal LA: só encerra se existir Shared Trip LA ativa pra Grasi (Rafael
    // compartilhou antes de sair). Sem share, silêncio.
    if (wantLa && apnsLive.enabled) {
      const finalAlert = { title: a.title || `${who} chegou em casa`, body: a.body || `Chegada às ${hhmm}.` };
      const active = Object.entries(_sharedTripLAs).filter(([tok, st]) => {
        const tk = _shareTokens[tok];
        return st.laActive && tk && tk.recipientRole === 'grasi' && tk.expiresMs > Date.now();
      });
      if (active.length === 0) {
        console.log('[notify] arrived_home: sem share ativa pra Grasi — pula LA');
      } else for (const [tok, st] of active) {
        try {
          // `tk` precisa ser resolvido AQUI: o do filter acima é escopo do callback,
          // e usá-lo aqui lançava ReferenceError ("tk is not defined", visto em 18/08).
          // Com a exceção no meio, a LA compartilhada nunca encerrava e ficava pinada
          // na tela da destinatária — mesmo sintoma de LA congelada, causa diferente.
          const tk = _shareTokens[tok];
          const cs = _sharedTripContentState(st.recipientName, st.tokenDestName, tk);
          cs.from = st.from; cs.destName = 'Casa'; cs.active = false;
          await apnsLive.pushUpdate(SHARED_TRIP_LA_TYPE, {}, cs,
            { isFinal: true, dismissalDate: Date.now() + 60_000, alert: finalAlert });
        } catch (e) { console.warn('[notify] LA end falhou:', e.message); }
        delete _sharedTripLAs[tok];
      }
    }
    return;
  }
  // Custom (title + body direto da regra).
  if (a.title || a.body) {
    await send(a.title || rule.name || 'Automação', a.body || '', ['bell']);
  }
}

// Alertas cuja NOTIFICAÇÃO é delegada ao it-agent: ele tenta corrigir (ts/mqtt/pm2)
// ou verifica ao vivo + sugere (claude) ANTES de te incomodar, e só notifica em
// "corrigindo/persiste/resolvido". O bridge segue registrando o evento e expondo
// em /api/health (o app enxerga), mas NÃO manda push próprio — evita o ping
// prematuro "antes do agente nem tentar" + a notificação duplicada.
// Fora daqui de propósito (push DIRETO, fail-open — o agente não pode ser porteiro
// de coisa que, se ele cair, você precisa saber assim mesmo): perda-de-dado/
// expiração (disk/ssd/icloud/backup/cert/apns) e failsafe/ignorados pelo agente
// (ext_monitor_down, restarts, dns_mismatch, mqtt_slow, local_blind).
const AGENT_OWNED = new Set([
  'ts_down', 'mqtt_down', 'broker_ports',                 // it-agent auto-corrige
  'ha_down', 'gw_down', 'funnel_down', 'mem_high', 'rss_leak',
  'apk_executor_dead', 'car_apk_stall', 'car_gwm_stall', 'car_total_silence', // claude verifica ao vivo antes
]);

const DNS_MISMATCH_SUSTAIN_MS = +(process.env.DNS_MISMATCH_SUSTAIN_MIN || 10) * 60_000;
// Baileys cai e religa sozinho em quedinha de rede — sustentacao evita push por
// reconexao de um ciclo.
const LARI_SUSTAIN_MS      = +(process.env.LARI_SUSTAIN_MIN || 15) * 60_000;
const DELEGA_SUSTAIN_MS    = +(process.env.DELEGA_SUSTAIN_MIN || 3) * 60_000;
const ICLOUD_SUSTAIN_MS    = +(process.env.ICLOUD_SUSTAIN_H || 4) * 3600_000;
const COLLECTOR_SUSTAIN_MS = +(process.env.COLLECTOR_SUSTAIN_MIN || 15) * 60_000;
const BLUETTI_SUSTAIN_MS   = +(process.env.BLUETTI_SUSTAIN_MIN   || 10) * 60_000;
// Janelas medidas em 10 dias de eventos reais. A mediana de cada episódio é o
// que separa problema de excursão: temperatura alta durava 17min (pico de sol),
// geração perdida 3-5min (nuvem), inversor solo 2min (restart do próprio).
// Problema térmico ou elétrico de verdade não some sozinho em minutos.
const SOLAR_TEMP_SUSTAIN_MS = +(process.env.SOLAR_TEMP_SUSTAIN_MIN || 45) * 60_000;
const SOLAR_GEN_SUSTAIN_MS  = +(process.env.SOLAR_GEN_SUSTAIN_MIN  || 20) * 60_000;
const SOLAR_SOLO_SUSTAIN_MS = +(process.env.SOLAR_SOLO_SUSTAIN_MIN || 15) * 60_000;
const STR_IMB_RATIO      = +(process.env.STRING_IMBALANCE_RATIO || 0.5);
const STR_IMB_MIN_W       = +(process.env.STRING_IMBALANCE_MIN_W || 1500);
const STR_IMB_SUSTAIN_MS  = +(process.env.STRING_IMBALANCE_SUSTAIN_MIN || 30) * 60_000;

// ── Condição SUSTENTADA ──────────────────────────────────────────────────────
// Quarta vez que este padrão aparece (ventilador, geração baixa, offline da
// página, agora strings), então vira função. A diferença que importa não é
// "verdadeiro/falso", são TRÊS estados:
//
//   bad        → acumula tempo
//   good       → zera o relógio
//   não sei    → CONGELA (nem acumula, nem zera)
//
// O terceiro é o que faltava. O alerta de string chamava _alert(false) sempre que
// uma string caía abaixo do piso — ou seja, nuvem passando era lida como "está
// tudo bem", zerava o relógio e rearmava o alerta. Era esse o motor do flapping.
//
// O relógio é PERSISTIDO. Ele vivia só em memória enquanto o `_alertState` ia pro
// disco, e a assimetria produzia mentira: no restart o alerta lembrava que estava
// disparado, o relógio começava do zero, e o `_alert()` recebia `false` → mandava
// "Recuperado" sem nada ter recuperado. Aconteceu de verdade em 02/09 com o
// `local_perm_lost`. Além disso a detecção real atrasava uma janela inteira a cada
// restart, e eu reinicio o bridge toda hora.
//
// `seen` é o antídoto pro outro extremo: se o bridge ficou fora por horas, o
// `since` guardado não prova continuidade nenhuma — ninguém estava observando.
// Entrada velha demais é descartada em vez de virar veredito instantâneo.
const _sustain = new Map();     // key → { since, seen }
const SUSTAIN_FILE = path.join(DATA_DIR, 'sustain-state.json');
const SUSTAIN_MAX_GAP_MS = +(process.env.SUSTAIN_MAX_GAP_MIN || 30) * 60_000;
let _sustainSaveTimer = null;
function _saveSustain() {
  if (_sustainSaveTimer) return;                       // debounce, igual ao _alertState
  _sustainSaveTimer = setTimeout(() => {
    _sustainSaveTimer = null;
    try { atomicWriteFileSync(SUSTAIN_FILE, JSON.stringify(Object.fromEntries(_sustain))); }
    catch (_) { /* falha de disco não paralisa o bridge */ }
  }, 500);
}
(function _loadSustain() {
  try {
    const j = JSON.parse(fs.readFileSync(SUSTAIN_FILE, 'utf8'));
    const now = Date.now();
    let vivos = 0, velhos = 0;
    for (const [k, v] of Object.entries(j || {})) {
      if (!v || !v.since) continue;
      if (now - (v.seen || v.since) > SUSTAIN_MAX_GAP_MS) { velhos++; continue; }
      _sustain.set(k, v); vivos++;
    }
    if (vivos || velhos) console.log(`[sustain] ${vivos} relógio(s) restaurado(s), ${velhos} descartado(s) por gap`);
  } catch (_) {}
})();
function _sustained(key, evaluable, bad, minMs) {
  const now = Date.now();
  const st = _sustain.get(key);
  if (!evaluable) return !!(st && st.since && (now - st.since) >= minMs);  // congela
  if (!bad) { if (st) { _sustain.delete(key); _saveSustain(); } return false; }
  if (!st || !st.since) { _sustain.set(key, { since: now, seen: now }); _saveSustain(); return false; }
  st.seen = now; _saveSustain();
  return (now - st.since) >= minMs;
}
/// Há quanto tempo a condição está ruim, pra escrever no corpo do alerta.
function _sustainedFor(key) {
  const st = _sustain.get(key);
  return st && st.since ? Math.round((Date.now() - st.since) / 60_000) : 0;
}

function _alert(id, firing, title, body, priority = 'default', tags = [], opts = {}) {
  if (AGENT_OWNED.has(id)) opts = { ...opts, silent: true };
  const prev = _alertState.get(id) || { firing: false, firedAt: 0, lastNotifiedAt: 0, notified: false };
  const now  = Date.now();
  const repeatEvery = opts.repeatEvery ?? NTFY_COOLDOWN;  // intervalo entre repetições "(ainda)"
  const fireDelay   = opts.fireDelay  ?? ALERT_FIRE_DELAY; // debounce antes da 1ª notif (0 = imediato)

  if (firing && !prev.firing) {
    // nova queda. Com fireDelay=0 notifica na hora (o próprio timeout já é debounce);
    // senão só registra e aguarda fireDelay antes de notificar.
    if (fireDelay <= 0) {
      _alertState.set(id, { firing: true, firedAt: now, lastNotifiedAt: now, notified: true, title, priority });
      if (!opts.silent) _ntfy(title, body, priority, tags);
      _recordHealthEvent(id, title + ': ' + body);
    } else {
      _alertState.set(id, { firing: true, firedAt: now, lastNotifiedAt: 0, notified: false, title, priority });
    }
  } else if (firing && prev.firing && !prev.notified && (now - prev.firedAt) >= fireDelay) {
    // falha persistiu o tempo mínimo → primeira notificação
    _alertState.set(id, { ...prev, lastNotifiedAt: now, notified: true, title, priority });
    if (!opts.silent) _ntfy(title, body, priority, tags);
    _recordHealthEvent(id, title + ': ' + body);
  } else if (firing && prev.firing && prev.notified && (now - prev.lastNotifiedAt) > repeatEvery) {
    // repetição (ainda caído, cooldown passou). No silêncio noturno só marca o
    // tempo (pra reset do backoff) mas NÃO manda push — evita spammar de noite.
    _alertState.set(id, { ...prev, lastNotifiedAt: now, title, priority });
    if (_inQuietHours()) {
      _recordHealthEvent(id, title + ' (ainda, silenciado noturno): ' + body);
    } else {
      if (!opts.silent) _ntfy(title + ' (ainda)', body, 'low', tags);
      _recordHealthEvent(id, title + ' (ainda): ' + body);
    }
  } else if (firing && prev.firing) {
    // Nada a notificar neste ciclo, mas o TEXTO tem que acompanhar: ele era
    // gravado só no disparo inicial e congelava. Efeito: mudar a redação de um
    // alerta não valia enquanto ele estivesse ativo, e texto que carrega valor
    // vivo (a causa vinda do HA, por exemplo) nunca aparecia. 15/09.
    if (prev.title !== title || prev.priority !== priority) {
      _alertState.set(id, { ...prev, title, priority });
    }
  } else if (!firing && prev.firing) {
    // recuperado — só notifica se tinha enviado alerta
    if (prev.notified) {
      if (!opts.silent) _ntfy('Recuperado: ' + title, 'Voltou ao normal.', 'low', ['white_check_mark']);
      _recordHealthEvent(id + '_recovery', 'Recuperado: ' + title);
    }
    _alertState.set(id, { firing: false, firedAt: 0, lastNotifiedAt: 0, notified: false });
  } else if (!firing) {
    _alertState.set(id, { firing: false, firedAt: 0, lastNotifiedAt: 0, notified: false });
  }
  _saveAlertState();   // persiste após qualquer transição pra sobreviver a restart
}

let _lastRestartCount = 0;
let _mqttDownCount    = 0;
let _lastAlertTick    = 0;

// Dead-man's-switch do monitor externo: o HA do Sítio (que vigia o Mac de fora)
// faz POST periódico em /api/monitor-heartbeat. Se parar de chegar, o Mac está
// sendo monitorado às cegas → alerta. Persiste em disco pra sobreviver a restart
// do bridge (senão restart com HA já caído = silêncio eterno).
const EXT_MONITOR_BEAT_FILE = path.join(DATA_DIR, 'ext-monitor-beat.json');
const EXT_MONITOR_TIMEOUT   = 5 * 60_000;    // 5min sem beat = monitor externo parado (HA bate a cada 60s → 5 perdidos)
let _extMonitorLastBeat = null;
try { _extMonitorLastBeat = JSON.parse(fs.readFileSync(EXT_MONITOR_BEAT_FILE, 'utf8')).ts || null; } catch (_) {}

// ── Status do HA do Sítio (push) ────────────────────────────────────────
// O HA do Sítio tem IP dinâmico — não dá pra puxar dele de fora. Solução:
// ele empurra o próprio status pra cá via POST periódico, e o /health.html
// mostra isso pra dar visão externa igual à do dashboard local (uptime 7d,
// serviços up/down, guards). Puramente informativo: o bridge NÃO alerta em
// cima disso — a decisão de push desses serviços já é do HA (/api/infra-status).
const HA_WORK_FILE        = path.join(DATA_DIR, 'ha-work-status.json');
const HA_WORK_EVENTS_FILE = path.join(DATA_DIR, 'ha-work-events.json');
const HA_WORK_EVENTS_MAX  = 1000;
const HA_WORK_EVENTS_TTL  = 30 * 24 * 3600_000; // 30 dias
const HA_WORK_STALE_MS    = 5 * 60_000;         // HA publica a cada 2min
let _haWorkLatest = null;
try { _haWorkLatest = JSON.parse(fs.readFileSync(HA_WORK_FILE, 'utf8')); } catch (_) {}
let _haWorkEvents = [];
try {
  const raw = JSON.parse(fs.readFileSync(HA_WORK_EVENTS_FILE, 'utf8'));
  const cutoff = Date.now() - HA_WORK_EVENTS_TTL;
  _haWorkEvents = Array.isArray(raw) ? raw.filter(e => e.ts > cutoff) : [];
} catch (_) {}

function _recordHaWorkTransitions(prevServices, nextServices, ts) {
  if (!prevServices) return;
  let changed = false;
  for (const key of Object.keys(nextServices)) {
    if (prevServices[key] !== undefined && prevServices[key] !== nextServices[key]) {
      _haWorkEvents.push({ ts, service: key, up: !!nextServices[key] });
      changed = true;
    }
  }
  if (!changed) return;
  const cutoff = ts - HA_WORK_EVENTS_TTL;
  _haWorkEvents = _haWorkEvents.filter(e => e.ts > cutoff).slice(-HA_WORK_EVENTS_MAX);
  try { atomicWriteFileSync(HA_WORK_EVENTS_FILE, JSON.stringify(_haWorkEvents)); } catch (_) {}
}

// ── Self-heal "cegueira local" ────────────────────────────────────────────
// HA-LAN + gateway ping + mosquitto loopback + SSD caindo TODOS juntos é
// assinatura de processo isolado (rede/FD do próprio bridge), não 4 outages
// reais e independentes ao mesmo tempo. `pm2 restart` sozinho não resolveu
// historicamente — precisa matar e ressuscitar o daemon inteiro (mesma
// correção manual validada em produção). Cooldown evita loop de restart se
// a causa for persistente (aí o alerta único continua soando "(ainda)").
const LOCAL_BLIND_HEAL_COOLDOWN = 30 * 60_000;
let _lastLocalBlindHeal = 0;
function _selfHealPm2() {
  const now = Date.now();
  if (now - _lastLocalBlindHeal < LOCAL_BLIND_HEAL_COOLDOWN) return;
  _lastLocalBlindHeal = now;
  _recordHealthEvent('restart', 'Self-heal: cegueira local detectada (pm2 kill+resurrect)');
  const { spawn } = require('child_process');
  const pm2Bin = process.env.PM2_BIN || '/usr/local/bin/pm2';
  const child = spawn('/bin/sh', ['-c', `${pm2Bin} kill && sleep 1 && ${pm2Bin} resurrect`],
    { detached: true, stdio: 'ignore' });
  child.unref();
}

// ── Perda da permissão "Rede Local" do daemon pm2 ────────────────────────────
// Recorrente: o Mac reinicia, o daemon sobe sem a permissão e TODO TCP pra LAN
// passa a dar EHOSTUNREACH. O bridge fica cego pro HA — solar, ventilador,
// família, tudo — enquanto `curl` do terminal alcança o mesmo IP em 3ms.
//
// O guard genérico de cegueira local (3 de 4 sinais) NÃO pega este caso: só o HA
// cai. Mosquitto é 127.0.0.1 e loopback não passa por TCC; o SSD é disco; e o
// gateway é sondado com `ping`, que é ICMP e também escapa. Sobra 1 de 4.
//
// Discriminador: se o processo NUNCA alcançou o HA desde que subiu, é permissão
// nascida quebrada. HA que cai depois de ter funcionado nesta encarnação é outage
// de verdade, e aí reciclar o pm2 não conserta nada — por isso a distinção.
//
// Trava dura: no máximo UMA reciclagem por boot da máquina, persistida. Se a
// reciclagem não resolver, não insiste — a falha é outra coisa e um loop de
// `pm2 kill` seria muito pior que o problema.
let _haEverUp = false;
const LOCALPERM_FILE = path.join(DATA_DIR, 'localperm-heal.json');
const LOCALPERM_SUSTAIN_MS = +(process.env.LOCALPERM_SUSTAIN_MIN || 4) * 60_000;
function _bootMs() { return Math.round(Date.now() - require('os').uptime() * 1000); }
function _healedThisBoot() {
  try {
    const j = JSON.parse(fs.readFileSync(LOCALPERM_FILE, 'utf8'));
    return Math.abs((j.boot_ms || 0) - _bootMs()) < 120_000;   // mesmo boot (±2min)
  } catch (_) { return false; }
}
function _markHealedThisBoot() {
  try { atomicWriteFileSync(LOCALPERM_FILE, JSON.stringify({ boot_ms: _bootMs(), at: Date.now() })); }
  catch (_) {}
}
function _checkLocalPermission() {
  if (_haStatus.up === true) {
    _haEverUp = true;
    // Carimba mesmo no caminho bom: `checked_at: 0` faria o vigia não saber
    // diferenciar "verificado e está tudo bem" de "nunca verificado".
    _localPerm = { lost: false, since_ms: null, ha_error: null, checked_at: Date.now() };
    return;
  }
  const err = String(_haStatus.error || '');
  // EHOSTUNREACH especificamente: ECONNREFUSED seria HA no ar sem escutar.
  const assinatura = _haStatus.up === false && /EHOSTUNREACH/.test(err) && !_haEverUp;
  const firing = _sustained('localperm', true, assinatura, LOCALPERM_SUSTAIN_MS);
  _alert('local_perm_lost', firing,
    'Bridge sem permissão de Rede Local',
    `TCP pra LAN dando EHOSTUNREACH desde que o processo subiu, e o HA nunca respondeu `
    + `nesta encarnação. É a permissão do daemon pm2, que some no reboot do Mac.`
    + (_healedThisBoot() ? ' Já reciclei uma vez neste boot — não vou insistir.'
                         : ' Reciclando o pm2 (kill+resurrect).'),
    'urgent', ['satellite', 'warning'], { fireDelay: 0, repeatEvery: 6 * 3600_000 });
  // O bridge NÃO conserta isso. Ele tentou em 02/09 e falhou: o `pm2 kill+resurrect`
  // sai daqui como filho do próprio daemon, e o macOS atribui o daemon novo ao
  // MESMO responsible process — nasce sem a permissão de novo. Quem consegue é um
  // processo de fora do pm2: o `servicos-vigia.sh`, que roda por launchd e já
  // alcança o HA. Aqui fica só o diagnóstico, exposto pra ele ler.
  _localPerm = { lost: firing, since_ms: firing ? (_sustain.get('localperm') || {}).since || null : null,
                 ha_error: firing ? err.slice(0, 180) : null, checked_at: Date.now() };
}
let _localPerm = { lost: false, since_ms: null, ha_error: null, checked_at: 0 };

function _checkAlerts() {
  const now = Date.now();

  // Mac dormiu/suspendeu: o setInterval pausa, então um gap grande entre ticks
  // delata o wake. Sem isso, qualquer alerta com firedAt setado antes do sleep
  // acorda com (now - firedAt) ≫ ALERT_FIRE_DELAY e notifica na 1ª amostra
  // pós-wake — mesmo já recuperado (foi o flood de falsos pushes). Reseta o
  // debounce dos alertas em curso e pula este ciclo pros pollers (SSD, gateway,
  // HA, DNS) reamostrarem o estado real antes de qualquer julgamento.
  if (_lastAlertTick > 0 && (now - _lastAlertTick) > WAKE_GAP_MS) {
    // Logar o gap em health_events pra permitir correlacionar com alertas
    // externos "Mac inalcançável" (HA do Sítio). Gap grande = Mac dormiu,
    // suspend/DarkWake ou processo bloqueado — bridge acorda sem contexto.
    const gapSec = Math.round((now - _lastAlertTick) / 1000);
    _recordHealthEvent('tick_gap', `Gap de ${gapSec}s no _checkAlerts (sleep/DarkWake?) — reset debounce`);
    for (const [id, st] of _alertState) if (st.firing) _alertState.set(id, { ...st, firedAt: now });
    _lastAlertTick = now;
    return;
  }
  _lastAlertTick = now;

  // 1. Bridge caindo em rajada (3+ QUEDAS em 1h). Restarts planejados (ajustes/
  // deploys, com marker de shutdown limpo) não contam — só quedas reais.
  const recentRestarts = _healthEvents.filter(e => e.type === 'restart' && !e.planned && e.ts > now - 3600_000).length;
  if (_lastRestartCount === 0) _lastRestartCount = recentRestarts;   // inicializa sem alertar no boot
  const newRestarts = recentRestarts > _lastRestartCount;
  _lastRestartCount = recentRestarts;
  if (newRestarts && recentRestarts >= 3)
    _alert('restarts', true, 'Bridge caindo muito', `${recentRestarts} quedas na última hora`, 'urgent', ['rotating_light']);
  else if (recentRestarts < 3)
    _alert('restarts', false, 'Bridge reiniciando muito', '');

  // 2. MQTT desconectado (2 ciclos consecutivos para evitar falso positivo no restart)
  const mqttOk = !!(mqttClient?.connected);
  if (mqttOk) _mqttDownCount = 0; else _mqttDownCount = (_mqttDownCount || 0) + 1;
  _alert('mqtt_down', _mqttDownCount >= 2, 'MQTT desconectado', 'Bridge perdeu conexao com o broker MQTT.', 'high', ['electric_plug']);

  // 3. MQTT latência alta (> 800ms)
  const mqttLat = _mqttPing.latency_ms;
  const mqttSlow = mqttLat != null && mqttLat > 800;
  _alert('mqtt_slow', mqttSlow, 'MQTT lento', `Latência ${mqttLat}ms (limite 800ms)`, 'default', ['snail']);

  // 4. Mosquitto broker ports
  const brokerPortDown = _mqttBrokerStatus.checked_at > 0 &&
    (!_mqttBrokerStatus.port1883 || !_mqttBrokerStatus.port1884 || !_mqttBrokerStatus.port8883) &&
    _mqttBrokerFailCount >= 2;
  const brokerMsg = [
    !_mqttBrokerStatus.port1883 ? '1883 down' : '',
    !_mqttBrokerStatus.port1884 ? '1884 down' : '',
    !_mqttBrokerStatus.port8883 ? '8883 down' : '',
    _mqttBrokerStatus.errors ? `(${_mqttBrokerStatus.errors})` : '',
  ].filter(Boolean).join(', ');
  // Guard "cegueira local": 3+ desses caindo juntos = processo isolado, não
  // outage real em sistemas independentes. Suprime os 4 individuais, dispara
  // 1 só, e tenta self-heal (ver função acima).
  const extForBlindCheck = _macStats.disk_ext;
  const localSignals = {
    mosquitto: brokerPortDown,
    ha:        _haStatus.up === false,
    gateway:   _gwStatus.up === false,
    ssd:       extForBlindCheck ? extForBlindCheck.mounted === false : false,
  };
  const localBlindCount = Object.values(localSignals).filter(Boolean).length;
  const localBlind = localBlindCount >= 3;
  if (localBlind) {
    const downList = Object.entries(localSignals).filter(([, v]) => v).map(([k]) => k).join(', ');
    // Push desativado — HA do trabalho agora decide o alerta a partir de
    // /api/infra-status (centraliza pra não duplicar/dessincronizar cooldowns).
    _alert('local_blind', true, 'Bridge cego localmente',
      `${downList} caíram juntos — provável processo isolado (rede/FD), não outage real. Self-heal disparado.`,
      'urgent', ['satellite', 'warning'], { silent: true });
    _selfHealPm2();
  } else {
    _alert('local_blind', false, 'Bridge cego localmente', '', 'default', [], { silent: true });
  }

  _alert('broker_ports', brokerPortDown && !localBlind, 'Mosquitto porta inacessivel', brokerMsg, 'high', ['electric_plug'], { silent: true });

  // 5. Home Assistant down
  _alert('ha_down', _haStatus.up === false && !localBlind, 'Home Assistant offline', _haStatus.error || `Sem resposta em ${process.env.HA_URL || '192.168.1.30:8123'}`, 'high', ['house'], { silent: true });

  // 5. Tailscale não Running
  const tsDown = _tsStatus.backend !== null && _tsStatus.backend !== 'Running';
  _checkLocalPermission();
  _alert('ts_down', tsDown, 'Tailscale fora', `Backend: ${_tsStatus.backend || _tsStatus.error}`, 'high', ['satellite']);

  // 6. DuckDNS divergente
  // Saiu do `silent`. Ele sabia que o carro estava inalcançável e não falava:
  // em 02/09 o IP mudou às 17:37 e eu só descobri abrindo a página, horas depois.
  // Alerta que detecta e cala é pior que alerta que não existe.
  //
  // Sustentação de 10min porque o net-failover alterna Ethernet↔WiFi e o DuckDNS
  // tem TTL: divergência de um ciclo é propagação, não problema. E o corpo diz a
  // CONSEQUÊNCIA — quem lê no celular precisa saber o que quebrou, não só que dois
  // IPs diferem.
  _alert('dns_mismatch',
    _sustained('dns_mismatch', _netStatus.match !== null, _netStatus.match === false, DNS_MISMATCH_SUSTAIN_MS),
    'Carro sem caminho de volta',
    `mqttrafael.duckdns.org aponta pra ${_netStatus.duckdns_ip} e o IP público agora é `
    + `${_netStatus.public_ip} (há ${_sustainedFor('dns_mismatch')}min). O APK do carro chega por `
    + `esse hostname, então enquanto divergir ele não publica. Atualize o DuckDNS — `
    + `nada faz isso sozinho. Se você está em link CGNAT (Starlink/4G), entrada não `
    + `atravessa e atualizar o DNS não resolve.`,
    'default', ['globe_with_meridians'], { repeatEvery: 12 * 3600_000 });

  // 7. Memória alta (RSS > 450MB)
  const rss = Math.round(process.memoryUsage().rss / 1048576);
  _alert('mem_high', rss > 450, 'Memória alta no bridge', `RSS ${rss}MB (limite 450MB)`, 'high', ['warning']);

  // 8. Gateway LAN down
  _alert('gw_down', _gwStatus.up === false && !localBlind, 'Gateway LAN offline',
    `Ping para 192.168.1.1 falhou (${_gwStatus.error || '?'}).`, 'urgent', ['sos'], { silent: true });

  // 9. Funnel ingress down
  _alert('funnel_down', _funnelStatus.up === false && _funnelStatus.checked_at > 0,
    'Funnel ingress down',
    _funnelStatus.error || `Portas falhas: ${_funnelStatus.failed?.join(', ') || '?'} (${_funnelStatus.ip || FUNNEL_HOST})`,
    'high', ['satellite']);

  // 10. Certificado TLS expirando (< 21 dias)
  if (_certStatus.days_left != null)
    _alert('cert_expiry', _certStatus.days_left < 21, 'Certificado TLS expirando',
      `Expira em ${_certStatus.days_left} dias`, _certStatus.days_left < 7 ? 'urgent' : 'default', ['lock']);

  // 11. SSD externo desmontado (segura o bundle HAOS — HA morre sem ele)
  const ext = _macStats.disk_ext;
  if (ext) {
    _alert('ssd_unmounted', ext.mounted === false && !localBlind, 'SSD externo desmontado',
      `${ext.path} não está montado (${ext.error || '?'}) — Home Assistant pode cair.`, 'urgent', ['floppy_disk'], { silent: true });
    if (ext.mounted && ext.avail_gb != null)
      _alert('ssd_full', ext.avail_gb < 5, 'SSD externo quase cheio',
        `${ext.avail_gb}GB livres em ${ext.path} (limite 5GB)`, 'high', ['floppy_disk']);
  }

  // 12. Disco interno quase cheio (< 8GB)
  if (_macStats.disk?.avail_gb != null)
    _alert('disk_full', _macStats.disk.avail_gb < 8, 'Disco interno quase cheio',
      `${_macStats.disk.avail_gb}GB livres em / (limite 8GB)`, 'high', ['floppy_disk']);

  // 13. Backup velho (passou do max_age_h da fonte). Repete no máx 1x/dia — não
  // adianta spammar push de algo que muda devagar.
  for (const b of _backups) {
    const stale = b.ok === false;
    _alert(`backup_${b.name.split(' ')[0].toLowerCase()}`, stale, `Backup atrasado: ${b.name}`,
      b.error ? b.error : `${b.age_hours}h desde o último (limite ${b.max_age_h}h)`, 'high', ['package'],
      { repeatEvery: 24 * 3600_000 });
  }

  // 14. Cert TLS do broker MQTT expirando (< 21 dias)
  if (_certBrokerStatus.days_left != null)
    _alert('cert_broker_expiry', _certBrokerStatus.days_left < 21, 'Cert do broker MQTT expirando',
      `Expira em ${_certBrokerStatus.days_left} dias (carro/OBD param de conectar)`,
      _certBrokerStatus.days_left < 7 ? 'urgent' : 'default', ['lock']);

  // 15. PREDITIVO: disco/SSD vai encher em < 10 dias (regressão de tendência)
  // Gate de piso absoluto: a ETA linear não vale pra consumo purgeable/serrilhado
  // (snapshots APFS do Time Machine, cache iCloud evictável que o macOS reclama
  // sob pressão). Com dezenas de GB livres a projeção é ruído — só alerta quando
  // já está num patamar baixo E ainda caindo, dando lead time sobre o piso duro.
  const tdi = _trend.disk_int, tde = _trend.disk_ext;
  if (tdi?.eta_days != null)
    _alert('disk_int_eta', tdi.eta_days < 10 && tdi.current < 20, 'Disco interno vai encher',
      `~${tdi.eta_days} dias até <8GB (${tdi.current}GB, ${tdi.slope_per_day}GB/dia)`, 'high', ['chart_with_downwards_trend'],
      { repeatEvery: 24 * 3600_000 });
  if (tde?.eta_days != null)
    _alert('disk_ext_eta', tde.eta_days < 10 && tde.current < 15, 'SSD externo vai encher',
      `~${tde.eta_days} dias até <5GB (${tde.current}GB, ${tde.slope_per_day}GB/dia)`, 'high', ['chart_with_downwards_trend'],
      { repeatEvery: 24 * 3600_000 });

  // 16. PREDITIVO: memory leak no bridge (RSS subindo de forma sustentada)
  const trss = _trend.rss;
  const leaking = trss != null && trss.span_h >= 6 && trss.slope_per_day > 60;
  if (trss != null)
    _alert('rss_leak', leaking, 'Possível memory leak no bridge',
      `RSS +${trss.slope_per_day}MB/dia sob ${trss.span_h}h (atual ${trss.current}MB)`, 'default', ['chart_with_upwards_trend'],
      { repeatEvery: 12 * 3600_000 });

  // 17. iCloud: backup local não subiu (offsite em risco)
  if (_icloudSync.checked_at > 0 && !_icloudSync.error) {
    const pend = _icloudSync.pending > 0;
    // Em 30 dias disparou 6 vezes, SEMPRE entre 00:05 e 00:17 (quando o backup
    // roda), e SEMPRE se resolveu sozinho — pior caso 2,0h, mediana 0,8h. Ou
    // seja: 6 pushes de madrugada pra avisar de fila que ia esvaziar sozinha.
    // Só interessa o backup que NÃO terminou; a sustentação passa do pior
    // autocorrigido com folga.
    _alert('icloud_pending', _sustained('icloud_pending', true, pend, ICLOUD_SUSTAIN_MS),
      'Backup iCloud travado',
      `${_icloudSync.pending}/${_icloudSync.total} arquivos ainda não subiram depois de `
      + `${Math.round(_sustainedFor('icloud_pending') / 60)}h. Não se resolveu sozinho.`,
      'high', ['cloud'], { repeatEvery: 12 * 3600_000 });
  }

  // 18. APNs: tokens de Live Activity morrendo (atrito → LA para de entregar)
  // Morte de push-to-start token é ESPERADA em cada update do app (TestFlight):
  // o iOS rotaciona o token e o antigo vira BadDeviceToken/410 até o re-registro.
  // Com deploys frequentes isso dava alerta diário falso. Só é problema de verdade
  // se, ALÉM das mortes, a entrega parou — ou seja, nenhum push 200 nas últimas 6h.
  const apns = apnsLive.getStatus();
  const apnsDeliveryStalled = (apns.last_ok_ms || 0) < (Date.now() - 6 * 3600_000);
  if (apns.enabled)
    _alert('apns_attrition', (apns.dead_24h || 0) >= 3 && apnsDeliveryStalled, 'Tokens APNs morrendo',
      `${apns.dead_24h} tokens invalidados em 24h sem entrega OK há 6h+ (start=${apns.start_tokens} update=${apns.update_tokens})`,
      'default', ['iphone'], { repeatEvery: 12 * 3600_000 });

  // APK executor (Shizuku) morto/mudo: comandos publicados mas o carro não muda
  // estado. Sinal indireto — automações repetidas sem efeito. Se ≥2 seguidas
  // falharem no verify2, provavelmente Shizuku travou / permissão caiu.
  // Só alerta se a última falha foi RECENTE (1h) — com o carro desligado a
  // streak fica pendurada sem comando novo e não deve re-notificar.
  const apkX = _apkExecutorHealth();
  const apkFailFresh = apkX.fail_streak >= 2 && (Date.now() - (apkX.last_fail_ms || 0)) < 3600_000;
  _alert('apk_executor_dead', apkFailFresh, 'APK/Shizuku sem executar',
    `${apkX.fail_streak} comandos seguidos sem confirmação (24h: ${apkX.ok_24h} ok / ${apkX.fail_24h} fail). Cheque Shizuku no head-unit.`,
    'high', ['warning'], { repeatEvery: 4 * 3600_000 });

  // 19. Monitor externo (HA do Sítio) parado — dead-man's-switch. HA bate a cada
  // 60s; 5min de silêncio = parado. Só avalia após já ter recebido ≥1 heartbeat
  // (deploy novo sem beat ainda não alerta). O beat persiste em disco, então
  // restart do bridge com HA já caído ainda dispara.
  if (_extMonitorLastBeat != null) {
    const silentMin = Math.round((now - _extMonitorLastBeat) / 60_000);
    _alert('ext_monitor_down', (now - _extMonitorLastBeat) > EXT_MONITOR_TIMEOUT,
      'Monitor externo parado',
      `HA do Sítio sem heartbeat há ${silentMin}min — o Mac está sendo monitorado às cegas.`,
      'high', ['satellite', 'warning'], { repeatEvery: 6 * 3600_000, fireDelay: 0 });
  }
}

// Aguarda 60s no boot antes de começar a checar (deixa os pollers inicializarem).
//
// Armado de dentro do `server.listen`, NÃO no topo: `_checkAlerts` lê `mqttClient`,
// que é `const` lá pelo fim do arquivo. Armando aqui em cima, existia uma janela
// em que o timer disparava antes da linha do `const` ter sido avaliada — e `const`
// em TDZ LANÇA em vez de devolver undefined, derrubando o processo com
// "Cannot access 'mqttClient' before initialization" (14/09, 2 vezes seguidas).
// O callback do listen só roda com o módulo inteiro avaliado, então a ordem
// passa a ser garantida em vez de provável.
function _armaChecagemDeAlertas() {
  setTimeout(() => {
    _lastRestartCount = _healthEvents.filter(e => e.type === 'restart' && !e.planned && e.ts > Date.now() - 3600_000).length;
    _checkAlerts();
    setInterval(_checkAlerts, 60_000);
  }, 60_000);
}

// Registra o boot desta instância. `planned` = o processo anterior saiu por sinal
// (pm2 restart/stop = ajuste/deploy) e deixou o marker; senão foi queda (crash).
const _planned = _wasPlannedRestart();
_recordHealthEvent('restart',
  `Bridge iniciado (PID ${process.pid}, Node ${process.version}) — ${_planned ? 'ajuste/deploy' : 'queda'}`,
  { planned: _planned });

// Série temporal de memória (último 1h a cada 30s, ~120 pontos — só em memória).
const _memSeries = [];
setInterval(() => {
  const m = process.memoryUsage();
  _memSeries.push({ ts: Date.now(), rss: Math.round(m.rss / 1048576), heap: Math.round(m.heapUsed / 1048576) });
  if (_memSeries.length > 120) _memSeries.shift();
}, 30_000);

process.on('unhandledRejection', (reason) => {
  const msg = reason && reason.stack || String(reason);
  console.error('[unhandledRejection]', msg);
  _recordHealthEvent('unhandledRejection', msg);
});
process.on('uncaughtException', (err) => {
  const msg = err && err.stack || String(err);
  console.error('[uncaughtException]', msg);
  _recordHealthEvent('uncaughtException', msg);
});

// Write atômico: grava em tmp + rename (rename é atômico no mesmo FS). Sem isto,
// um writeFileSync interrompido (kill/queda de energia no meio) deixava o arquivo
// truncado — em .env/state isso = bridge não sobe. rename garante "tudo ou nada".
function atomicWriteFileSync(file, data, enc) {
  const tmp = file + '.tmp-' + process.pid;
  require('fs').writeFileSync(tmp, data, enc);
  require('fs').renameSync(tmp, file);
}

