// ── Tombstones (IDs explicitamente deletados pelo usuário) ────────────────
// Sem isso, o APK reenviaria via MQTT (trips/history, charging/history) e o
// bridge re-aceitaria. Tombstone bloqueia o re-insert. Mantém últimos 2000
// por categoria pra não crescer infinito.
let deletedIds = { autotrips: [], charges: [], refuels: [], rules: [] };
// Sets paralelos pra lookup O(1) — array continua sendo a fonte de verdade
// (mantém ordem de inserção e serializa direto pro JSON).
let deletedIdsSets = { autotrips: new Set(), charges: new Set(), refuels: new Set(), rules: new Set() };
try {
  if (fs.existsSync(DELETED_IDS_FILE)) {
    const loaded = JSON.parse(fs.readFileSync(DELETED_IDS_FILE, 'utf8'));
    deletedIds = { autotrips: [], charges: [], refuels: [], rules: [], ...loaded };
  }
  for (const k of ['autotrips', 'charges', 'refuels', 'rules']) {
    deletedIdsSets[k] = new Set((deletedIds[k] || []).map(String));
  }
  const total = deletedIds.autotrips.length + deletedIds.charges.length + deletedIds.refuels.length;
  if (total > 0) console.log(`✓ Tombstones: ${deletedIds.autotrips.length} viagens, ${deletedIds.charges.length} recargas, ${deletedIds.refuels.length} abastecimentos`);
} catch (e) { console.error('Aviso deleted_ids:', e.message); }

function saveDeletedIds() {
  try { atomicWriteFileSync(DELETED_IDS_FILE, JSON.stringify(deletedIds, null, 2)); } catch (_) {}
}
function markDeleted(kind, id) {
  const key = String(id);
  if (!deletedIds[kind]) { deletedIds[kind] = []; deletedIdsSets[kind] = new Set(); }
  if (!deletedIdsSets[kind].has(key)) {
    deletedIds[kind].push(key);
    deletedIdsSets[kind].add(key);
    if (deletedIds[kind].length > 2000) {
      deletedIds[kind] = deletedIds[kind].slice(-2000);
      deletedIdsSets[kind] = new Set(deletedIds[kind]);
    }
    saveDeletedIds();
  }
}
function isDeleted(kind, id) {
  return deletedIdsSets[kind]?.has(String(id)) || false;
}

// ── Abastecimentos ──────────────────────────────────────────────────────────
// Cada registro tem `liters_added`, opcionalmente `price_per_liter` (vazio =
// pendente, aguardando preenchimento). `fuel_l_before`/`fuel_l_after` capturam
// o estado do tanque no momento do abastecimento. `tank_avg_after` é o preço
// médio ponderado do tanque resultante (mix do que tinha + o que entrou).
let refuels = [];
try {
  if (fs.existsSync(REFUELS_FILE)) refuels = JSON.parse(fs.readFileSync(REFUELS_FILE, 'utf8')) || [];
  console.log(`✓ Abastecimentos: ${refuels.length}`);
} catch (e) { console.error('Aviso refuels.json:', e.message); }

function saveRefuels() {
  try { atomicWriteFileSync(REFUELS_FILE, JSON.stringify(refuels, null, 2)); } catch (_) {}
}

// Preços de referência (seed) usados quando não há histórico próprio.
// Também valoram o combustível/energia já presente antes do primeiro registro:
// no mix do primeiro abastecimento real, o que estava no tanque conta a SEED_*.
const SEED_GAS_PRICE_PER_L = 6.50;
const SEED_KWH_PRICE       = 0.55;

// Recalcula o preço médio do tanque iterando pelos refuels em ordem cronológica.
// Lógica de mix ponderado: ao abastecer, mistura o R$/L do que sobrou com o novo.
function recomputeTankAvgPrice() {
  // Ordena por ts crescente
  const ordered = [...refuels].sort((a, b) => (a.timestamp_ms || 0) - (b.timestamp_ms || 0));
  let avgPrice = SEED_GAS_PRICE_PER_L;  // R$/L médio inicial = seed
  let lastAfter = 0;    // litros no tanque após último abastecimento processado
  for (const r of ordered) {
    if (!(r.price_per_liter > 0)) {
      // Pendente — pula no cálculo do médio. Mantém o avg anterior.
      lastAfter = +r.fuel_l_after || lastAfter;
      continue;
    }
    const before  = +r.fuel_l_before || 0;
    const after   = +r.fuel_l_after  || (before + (+r.liters_added || 0));
    const added   = +r.liters_added  || Math.max(0, after - before);
    const oldL    = Math.max(0, Math.min(before, lastAfter > 0 ? lastAfter : before));
    const total   = oldL + added;
    if (total > 0.1) avgPrice = (oldL * avgPrice + added * r.price_per_liter) / total;
    lastAfter = after;
    // Persiste no registro o snapshot
    r.tank_avg_after = +avgPrice.toFixed(3);
  }
  state.tank_avg_price_per_l = +avgPrice.toFixed(3);
  // Sempre escreve no global — quando não há refuels, avgPrice é o seed.
  state.price_gas_per_l = +avgPrice.toFixed(3);
  saveRefuels();
  publishPricesToCar();
  return avgPrice;
}

// Snapshot do tanque ao desligar o motor — usado pra detectar abastecimento ao religar.
// PERSISTIDO em disco: ficava só em memória e todo restart do bridge zerava. Como o
// detector exige `_fuelLAtPark > 0`, qualquer restart entre estacionar e religar fazia
// o abastecimento passar em branco, sem log. Foi o que aconteceu em 09/08 (restart
// 14:24 durante deploy) e comeu um tanque de 44,36 L.
const FUELPARK_FILE = path.join(DATA_DIR, 'fuel-park.json');
let _fuelLAtPark = 0;
let _fuelParkTs  = 0;
try {
  if (fs.existsSync(FUELPARK_FILE)) {
    const d = JSON.parse(fs.readFileSync(FUELPARK_FILE, 'utf8')) || {};
    _fuelLAtPark = +d.fuel_l || 0;
    _fuelParkTs  = +d.ts     || 0;
    if (_fuelLAtPark > 0) console.log(`✓ Snapshot do tanque: ${_fuelLAtPark}L`);
  }
} catch (e) { console.error('Aviso fuel-park.json:', e.message); }
function _saveFuelPark() {
  try { atomicWriteFileSync(FUELPARK_FILE, JSON.stringify({ fuel_l: _fuelLAtPark, ts: _fuelParkTs })); } catch (_) {}
}

// ── AC esquecido ligado com carro parado (velocidade = 0 por X min) ──────────
let _acParkedTimer   = null;   // setTimeout handle
let _acParkedSentAt  = 0;      // ts do último push para evitar re-envio imediato

function _cancelAcParkedTimer() {
  if (_acParkedTimer) { clearTimeout(_acParkedTimer); _acParkedTimer = null; }
}

function _scheduleAcParkedAlert() {
  _cancelAcParkedTimer();
  if (!notifPrefs.ac_on_parked) return;
  const mins = Math.max(1, +(notifPrefs.ac_on_parked_min) || 10);
  _acParkedTimer = setTimeout(() => {
    _acParkedTimer = null;
    if ((+state.speed_kmh || 0) > 0) return;             // carro se moveu
    const fan = parseInt(state.hvac_fan_speed, 10) || 0;
    if (fan <= 0) return;                                 // AC desligado (0) ou inválido (-1, carro dormindo)
    if (Date.now() - _acParkedSentAt < 30 * 60_000) return; // re-envio mín 30 min
    _acParkedSentAt = Date.now();
    sendPush('❄️ AC ligado com carro parado',
      `Ventilação ${fan}/7 há mais de ${mins} min. Lembre de desligar.`, 'ac_on_parked');
  }, mins * 60_000);
}

// ── Vidros esquecidos abertos após motor desligar ─────────────────────────────
let _windowForgottenTimer  = null;
let _windowForgottenSentAt = 0;

function _cancelWindowForgottenTimer() {
  if (_windowForgottenTimer) { clearTimeout(_windowForgottenTimer); _windowForgottenTimer = null; }
}

function _scheduleWindowForgottenAlert() {
  _cancelWindowForgottenTimer();
  // Usa o menor delay entre os devices com a notif ativa (ou global default)
  const minsArr = pushSubs
    .map(s => getPrefsForDevice(s.device_id))
    .filter(p => p.window_forgotten)
    .map(p => Math.max(1, +(p.window_forgotten_min) || 10));
  if (!minsArr.length) return;   // nenhum device ativou — não agenda
  const mins = Math.min(...minsArr);
  _windowForgottenTimer = setTimeout(() => {
    _windowForgottenTimer = null;
    if (state.engine_state !== '0') return;                          // motor voltou
    const openNames = ['fl','fr','rl','rr']
      .filter(s => state[`window_${s}`] === 'on')
      .map(s => WINDOW_NAMES[s] || s.toUpperCase());
    if (!openNames.length) return;                                    // tudo fechado
    if (Date.now() - _windowForgottenSentAt < 30 * 60_000) return;  // cooldown 30 min
    _windowForgottenSentAt = Date.now();
    sendPush('🪟 Vidro aberto com carro desligado',
      `${openNames.join(', ')} há mais de ${mins} min.`, 'window_forgotten');
  }, mins * 60_000);
}

// ── Carro destravado após motor desligar ──────────────────────────────────────
let _lockForgottenTimer  = null;
let _lockForgottenSentAt = 0;

function _cancelLockForgottenTimer() {
  if (_lockForgottenTimer) { clearTimeout(_lockForgottenTimer); _lockForgottenTimer = null; }
}

function _scheduleLockForgottenAlert() {
  _cancelLockForgottenTimer();
  const minsArr = pushSubs
    .map(s => getPrefsForDevice(s.device_id))
    .filter(p => p.lock_forgotten)
    .map(p => Math.max(1, +(p.lock_forgotten_min) || 5));
  if (!minsArr.length) return;
  const mins = Math.min(...minsArr);
  _lockForgottenTimer = setTimeout(() => {
    _lockForgottenTimer = null;
    if (state.engine_state !== '0') return;        // motor voltou
    if (state.lock_state !== 'on') return;          // foi trancado
    if (Date.now() - _lockForgottenSentAt < 30 * 60_000) return;
    _lockForgottenSentAt = Date.now();
    sendPush('🔓 Carro destravado com motor desligado',
      `Carro continua destrancado há mais de ${mins} min.`, 'lock_forgotten');
  }, mins * 60_000);
}

// ── Porta-malas esquecida aberta após motor desligar ──────────────────────────
let _trunkForgottenTimer  = null;
let _trunkForgottenSentAt = 0;

function _cancelTrunkForgottenTimer() {
  if (_trunkForgottenTimer) { clearTimeout(_trunkForgottenTimer); _trunkForgottenTimer = null; }
}

function _scheduleTrunkForgottenAlert() {
  _cancelTrunkForgottenTimer();
  if (state.door_trunk !== 'on') return;  // porta-malas já fechada
  const minsArr = pushSubs
    .map(s => getPrefsForDevice(s.device_id))
    .filter(p => p.trunk_forgotten)
    .map(p => Math.max(1, +(p.trunk_forgotten_min) || 10));
  if (!minsArr.length) return;
  const mins = Math.min(...minsArr);
  _trunkForgottenTimer = setTimeout(() => {
    _trunkForgottenTimer = null;
    if (state.engine_state !== '0') return;
    if (state.door_trunk !== 'on') return;
    if (Date.now() - _trunkForgottenSentAt < 30 * 60_000) return;
    _trunkForgottenSentAt = Date.now();
    sendPush('🧳 Porta-malas aberta com carro desligado',
      `Porta-malas continua aberta há mais de ${mins} min.`, 'trunk_forgotten');
  }, mins * 60_000);
}

// ── SOC baixo sem estar carregando ───────────────────────────────────────────
let _socLowIdleSentAt = 0;
const SOC_LOW_IDLE_COOLDOWN = 4 * 60 * 60_000; // 4h entre notifs

function checkSocLowIdle() {
  const minsArr = pushSubs
    .map(s => getPrefsForDevice(s.device_id))
    .filter(p => p.soc_low_idle);
  if (!minsArr.length) return;
  if (state.charging_state === 'Carregando') return;
  if (Date.now() - _socLowIdleSentAt < SOC_LOW_IDLE_COOLDOWN) return;
  const soc = +state.soc_pct || 0;
  if (!soc) return;
  // Use the lowest threshold across enabled devices
  const thresholds = minsArr.map(p => Math.max(1, Math.min(100, +(p.soc_low_idle_pct) || 20)));
  const threshold = Math.max(...thresholds); // alert if below ANY device's threshold
  if (soc >= threshold) return;
  _socLowIdleSentAt = Date.now();
  sendPush('🔋 Bateria do EV baixa',
    `SOC em ${soc.toFixed(0)}% e carro não está carregando.`, 'soc_low_idle');
}

// ── SOC baixo ao chegar num local sem carregar ────────────────────────────────
const _socArrivalTimers = {};  // { [placeId]: timeoutHandle }

function _scheduleSocArrivalAlert(place) {
  if (_socArrivalTimers[place.id]) return;  // já agendado pra este local
  // Verifica se algum device tem esta notif + este local configurado
  const eligible = pushSubs
    .map(s => ({ prefs: getPrefsForDevice(s.device_id) }))
    .filter(({ prefs }) => {
      if (!prefs.soc_arrival) return false;
      const places = (prefs.soc_arrival_places || []).map(String);
      return places.length === 0 || places.includes(String(place.id));
    })
    .map(({ prefs }) => prefs);
  if (!eligible.length) return;
  const mins = Math.min(...eligible.map(p => Math.max(1, +(p.soc_arrival_min) || 5)));
  _socArrivalTimers[place.id] = setTimeout(() => {
    delete _socArrivalTimers[place.id];
    if (geofenceState[place.id] !== 'in') return;  // saiu antes do timer
    if (state.charging_state === 'Carregando') return;  // está carregando
    const soc = +state.soc_pct || 0;
    if (!soc) return;
    const threshold = Math.max(...eligible.map(p => Math.max(1, Math.min(100, +(p.soc_arrival_pct) || 30))));
    if (soc >= threshold) return;
    sendPush('🔌 Chegou em ' + place.name + ' — bateria baixa',
      `SOC em ${soc.toFixed(0)}% e carro não está carregando.`, 'soc_arrival');
  }, mins * 60_000);
}

// ── Bateria mantida cheia (>95%) por mais de 24h ──────────────────────────────
let _socFullTimer   = null;
let _socFullSentAt  = 0;
const SOC_FULL_THRESHOLD = 95;
const SOC_FULL_HOURS     = 24;

function _checkSocFullLong(soc) {
  const enabled = pushSubs.some(s => getPrefsForDevice(s.device_id).soc_full_long);
  if (!enabled) { _cancelSocFullTimer(); return; }
  if (soc < SOC_FULL_THRESHOLD) { _cancelSocFullTimer(); return; }
  if (_socFullTimer) return;  // já agendado
  _socFullTimer = setTimeout(() => {
    _socFullTimer = null;
    const curSoc = +state.soc_pct || 0;
    if (curSoc < SOC_FULL_THRESHOLD) return;  // caiu entre o agendamento e o disparo
    if (Date.now() - _socFullSentAt < SOC_FULL_HOURS * 60 * 60_000) return;
    _socFullSentAt = Date.now();
    sendPush('⚡ Bateria mantida cheia',
      `SOC acima de ${SOC_FULL_THRESHOLD}% há mais de ${SOC_FULL_HOURS}h. Considere descarregar um pouco para preservar a bateria.`,
      'soc_full_long');
  }, SOC_FULL_HOURS * 60 * 60_000);
}

function _cancelSocFullTimer() {
  if (_socFullTimer) { clearTimeout(_socFullTimer); _socFullTimer = null; }
}

// ── Corte de carga por software (alvo custom fora dos presets do carro) ────────
// Chamado a cada update de soc_pct. Quando carregando e o SOC atinge o alvo,
// freia setando o maior preset ESTRITAMENTE abaixo do SOC atual — o carro entende
// que já passou do alvo e encerra a carga. O preset (não o alvo) é o que para a
// carga; o alvo só define QUANDO. Dispara uma vez por sessão (_customCutoffFired).
function _checkCustomChargeCutoff(soc) {
  const target = +state.charge_custom_target || 0;
  if (!target) return;
  if (state.charging_state !== 'Carregando') return;
  if (_customCutoffFired) return;
  if (soc < target) return;
  const brake = [90, 80, 70, 60, 50].find(p => p < soc) || 50;
  _customCutoffFired = true;
  publishCmdWithRetry(`${MQTT_PREFIX}/cmd/charge_limit`, brake.toString(), { retain: true, qos: 1 })
    .then(() => console.log(`[charge-cutoff] alvo ${target}% atingido em ${soc.toFixed(0)}% → freia com preset ${brake}%`))
    .catch(e => console.warn('[charge-cutoff] falha ao frear:', e.message));
  sendPush('⚡ Carga interrompida', `Atingiu seu alvo de ${target}% (parou em ${soc.toFixed(0)}%).`, 'charge_target');
}

// ── Queda de pressão do pneu durante viagem ───────────────────────────────────
const TYRE_POSITIONS = ['fl', 'fr', 'rl', 'rr'];
let _tyreTripBaseline = {};    // { fl: psi, fr: psi, rl: psi, rr: psi }
let _tyreDropAlertSent = {};   // { fl: bool, ... }

function _resetTyreTrip() {
  _tyreTripBaseline = {};
  _tyreDropAlertSent = {};
}

function _captureTyreBaseline() {
  for (const pos of TYRE_POSITIONS) {
    const psi = +state[`tyre_pressure_${pos}`] || 0;
    if (psi > 5 && !_tyreTripBaseline[pos]) _tyreTripBaseline[pos] = psi;
  }
}

function checkTyreDrop(pos, currentPsi) {
  // Segurança: detecta SEMPRE (independe do toggle) pra destacar o pneu na LA de
  // Viagem. A notificação respeita a pref tyre_drop (default LIGADA).
  if ((+state.speed_kmh || 0) < 5) return;  // parado — não avalia
  if (!_tyreTripBaseline[pos]) { _captureTyreBaseline(); return; }
  if (_tyreDropAlertSent[pos]) return;
  const dropPsi = Math.max(1, +notifPrefs.tyre_drop_psi || 4);
  const drop = _tyreTripBaseline[pos] - currentPsi;
  if (drop < dropPsi) return;
  _tyreDropAlertSent[pos] = true;   // ← destaca o pneu na LA de Viagem
  const name = { fl: 'Dianteiro Esq.', fr: 'Dianteiro Dir.', rl: 'Traseiro Esq.', rr: 'Traseiro Dir.' }[pos] || pos.toUpperCase();
  sendPush('⚠️ Queda de pressão detectada',
    `${name}: ${currentPsi.toFixed(1)} PSI (era ${_tyreTripBaseline[pos].toFixed(1)} PSI, queda de ${drop.toFixed(1)} PSI)`,
    'tyre_drop');
}

// ── Bateria 12V baixa ────────────────────────────────────────────────────────
let _batt12LowSentAt = 0;
const BATT12_LOW_PCT = 50;       // threshold %
const BATT12_LOW_COOLDOWN = 60 * 60_000; // 1 hora entre notifs

function checkBatt12Low() {
  if (!notifPrefs.batt12_low) return;
  const pct = +state.batt_12v_pct || 0;
  if (pct <= 0 || pct > BATT12_LOW_PCT) return;
  if (Date.now() - _batt12LowSentAt < BATT12_LOW_COOLDOWN) return;
  _batt12LowSentAt = Date.now();
  sendPush('🔋 Bateria auxiliar baixa',
    `12V em ${pct.toFixed(0)}% · verifique se há dreno excessivo.`, 'batt12_low');
}

const REFUEL_MIN_LITERS = 5;          // threshold mínimo pra detectar abastecimento
const REFUEL_MIN_OFF_MS = 3 * 60_000; // motor precisa ter ficado desligado ≥3min
                                      // (abastecer leva no mínimo isso; on/off
                                      // rápido do APK bug não conta como parada)

function checkRefuelOnEngineOn() {
  // `state.fuel_l` é sempre a leitura do APK (garantido no handler de fuel_l, 04/08):
  // as duas fontes medem o tanque com diferença de ~1 L e o litro do carro é o que
  // vale. Importa aqui porque o abastecimento é a DIFERENÇA entre duas leituras —
  // misturar fontes entre o "antes" e o "depois" inventaria ou apagaria litros
  // sozinho, e com REFUEL_MIN_LITERS=5 uma divergência de 1 L não protege de nada.
  const fuelNow = +state.fuel_l || 0;
  if (_fuelLAtPark <= 0 || fuelNow <= 0) {
    console.log(`[refuel] sem baseline pra comparar (park=${_fuelLAtPark}L, agora=${fuelNow}L) — detecção pulada`);
    return;
  }
  const added = fuelNow - _fuelLAtPark;
  if (added < REFUEL_MIN_LITERS) return;
  // Guarda contra rajada de motor on/off (APK travado, ANR, etc): se ficou
  // desligado menos de 3min, não pode ter abastecido — a leitura do sensor
  // fuel_l só variou por ruído/reset ao religar. Sem isso, 20/07 gerou 93
  // refuels fantasmas em 40min de ciclos de ignição.
  const offMs = Date.now() - (_fuelParkTs || 0);
  if (_fuelParkTs && offMs < REFUEL_MIN_OFF_MS) {
    console.log(`[refuel] ignorado — motor ficou off só ${Math.round(offMs/1000)}s (mín=${REFUEL_MIN_OFF_MS/1000}s). added=${added.toFixed(1)}L`);
    return;
  }

  // NÃO cria mais registro (11/08, decisão do dono). A detecção compara duas leituras
  // do sensor do tanque e sempre errava os litros em relação à bomba, e ainda depende do
  // evento de motor ligado — que o bridge suprime como ruído de inicialização, então
  // metade dos abastecimentos passava batido. Agora só AVISA; quem registra é o botão
  // "Registrar abastecimento" no app, com o que a bomba mostrou.
  addEvent('refuel_detected', `⛽ Abastecimento de ~${added.toFixed(1)}L detectado`);
  sendPush(
    `⛽ Abastecimento detectado`,
    `~${added.toFixed(1)}L. Abra o app e registre os litros e o valor da bomba.`,
    'refuel_detected'
  );
  console.log(`[refuel] detectado +${added.toFixed(1)}L (${_fuelLAtPark.toFixed(1)} → ${fuelNow.toFixed(1)}) — só aviso, sem registro`);
  // Zera o baseline: sem isso o mesmo delta seria reavisado a cada religada.
  _fuelLAtPark = fuelNow; _fuelParkTs = Date.now(); _saveFuelPark();
}

// Idem pra bateria — itera por charges com preço e mixa com kWh estimado restante.
// kWh restante na bateria = SOC% × BATTERY_CAPACITY_KWH / 100.
let _chargesMudou = false;
function recomputeBatteryAvgPrice() {
  // chargesArr é o storage de recargas (carregado no boot via CHARGES_FILE).
  // Preço por sessão: cost_override.perKwh > 0 ou cost_override.total / energy.
  // Quando não há override, usa SEED_KWH_PRICE pra valorar a sessão.
  // Persiste `battery_avg_after` em cada recarga pra permitir reconstruir o
  // preço histórico (custo de viagens antigas com preço da época).
  const ordered = [...chargesArr].sort((a, b) => (a.timestamp_ms || 0) - (b.timestamp_ms || 0));
  let avgPrice = SEED_KWH_PRICE;  // R$/kWh médio inicial = seed
  for (const c of ordered) {
    // LÊ pelo valor efetivo (com `manual_overrides` aplicados), ESCREVE no registro
    // cru. Sem isto, corrigir um SOC errado pela tela de edição não chegava aqui: a
    // recarga de 31/07 continuou entrando com peso neutro e ostentando o selo de
    // incoerente mesmo depois de consertada, porque este laço lia `c.soc_start`
    // direto. A edição existia e não valia pra nada no custo.
    const eff = applyChargeOverrides(c);
    const energy = +eff.energy_kwh || 0;
    if (energy < 0.05) continue;
    const ovr = c.cost_override;
    // PREFERE total/energy_kwh atual em vez do perKwh salvo. Se energy_kwh
    // for corrigido após o user setar override, o perKwh fica defasado
    // mas (total / energy) sempre reflete a realidade da sessão.
    let pricePerKwh = ovr?.free === true ? 0
                    : ovr && +ovr.total  > 0 ? (+ovr.total / energy)
                    : ovr && +ovr.perKwh > 0 ? +ovr.perKwh
                    : SEED_KWH_PRICE;
    // Anti-outlier: R$/kWh > 5 indica erro de input ou energy_kwh parcial.
    // Cai pro SEED em vez de contaminar o avg.
    if (pricePerKwh > 5) {
      console.warn(`[charge] pricePerKwh anormal ts=${c.timestamp_ms}: R$ ${pricePerKwh.toFixed(2)}/kWh — usando SEED ${SEED_KWH_PRICE}`);
      pricePerKwh = SEED_KWH_PRICE;
    }
    // SOC coerente com a energia? `soc_start` é o PESO do histórico nesta conta —
    // com 0 a fórmula conclui "bateria vazia" e a sessão reescreve a média inteira.
    // Foi o que aconteceu em 31/07: uma recarga de 3,6 kWh marcada 0→97% levou a
    // média de 0,69 pra 1,54, e ela levou dias descendo. 0→97% exigiria ~33 kWh —
    // aquele zero era leitura falha, não bateria vazia.
    //
    // Critério: o ΔSOC declarado tem que explicar a energia, com folga de 2×. Fora
    // disso o SOC não é confiável e a sessão entra com peso pela ENERGIA (não zera
    // o histórico) — perde precisão, mas não destrói a série.
    const socStart = +eff.soc_start || 0;
    const socEnd   = +eff.soc_end   || 0;
    const dSoc = socEnd - socStart;
    const kwhEsperado = dSoc > 0 ? dSoc * BATTERY_CAPACITY_KWH / 100 : 0;
    const socConfiavel = socStart > 0 && kwhEsperado > 0
                         && energy <= kwhEsperado * 2 && energy >= kwhEsperado / 2;
    // ── Energia coerente com o ΔSOC? ────────────────────────────────────────
    // `energy / ΔSOC` é a capacidade que a sessão IMPLICA. Nas 72 sessões a mediana
    // é 35,2 e o corpo dos dados vive entre 31 e 42; fora de 28–42 o `energy_kwh`
    // não fecha com o SOC e um dos dois está errado. Marca o registro pra aparecer
    // na tela em vez de aceitar calado — foi o que deixou 11/08 sair com 16,3 kWh
    // para 64 pontos de SOC (capacidade implícita 25,4).
    const capImpl = dSoc > 0 ? +(energy / (dSoc / 100)).toFixed(1) : 0;
    const suspeita = dSoc >= 15 && capImpl > 0 && (capImpl < 28 || capImpl > 42);
    if (suspeita && !c._energia_suspeita) {
      c._energia_suspeita = true;
      c._cap_implicita = capImpl;
      _chargesMudou = true;
      console.warn(`[charge] energia suspeita ts=${c.timestamp_ms}: ${energy.toFixed(1)}kWh `
        + `para ΔSOC ${dSoc}% → capacidade implícita ${capImpl}kWh (esperado 28–42)`);
    } else if (!suspeita && c._energia_suspeita) {
      delete c._energia_suspeita; delete c._cap_implicita; _chargesMudou = true;
    }

    let kWhBefore;
    if (socConfiavel) {
      kWhBefore = socStart * BATTERY_CAPACITY_KWH / 100;
    } else {
      // Peso neutro: metade da capacidade. Mantém o histórico com influência
      // comparável à da sessão nova, em vez de zerá-lo ou de ignorar a sessão.
      kWhBefore = BATTERY_CAPACITY_KWH / 2;
      // Log UMA vez por registro: este recompute roda a cada poucos minutos e o
      // aviso enchia o log com a mesma recarga de 31/07 pra sempre.
      if (!c._soc_incoerente) {
        c._soc_incoerente = true; _chargesMudou = true;
        console.warn(`[charge] SOC incoerente ts=${c.timestamp_ms} (${socStart}→${socEnd}% para `
          + `${energy.toFixed(1)}kWh, esperado ~${kwhEsperado.toFixed(1)}) — peso neutro na média`);
      }
    }
    if (socConfiavel && c._soc_incoerente) { delete c._soc_incoerente; _chargesMudou = true; }
    const kWhAfter  = kWhBefore + energy;
    avgPrice = (kWhBefore * avgPrice + energy * pricePerKwh) / kWhAfter;
    c.battery_avg_after = +avgPrice.toFixed(4);   // snapshot pós-recarga
  }
  if (_chargesMudou) { _chargesMudou = false; scheduleChargesFlush(); }
  state.battery_avg_price_per_kwh = +avgPrice.toFixed(4);
  state.price_kwh = +avgPrice.toFixed(4);
  publishPricesToCar();
  return avgPrice;
}

// Retorna { kwhPrice, gasPrice } válidos no momento `targetMs`. Usa o
// `battery_avg_after`/`tank_avg_after` persistido na recarga/abastecimento
// IMEDIATAMENTE ANTERIOR a esse timestamp. Cai no SEED quando o histórico
// não cobre o período (viagem antes da primeira recarga).
function priceMixAtMs(targetMs) {
  // Bateria: pega o avg pós-recarga mais recente <= targetMs
  let kwhPrice = SEED_KWH_PRICE;
  const cBefore = chargesArr
    .filter(c => (c.timestamp_ms || 0) <= targetMs && c.battery_avg_after != null)
    .sort((a, b) => (b.timestamp_ms || 0) - (a.timestamp_ms || 0))[0];
  if (cBefore) kwhPrice = +cBefore.battery_avg_after || kwhPrice;
  // Tanque: idem com refuels
  let gasPrice = SEED_GAS_PRICE_PER_L;
  const rBefore = refuels
    .filter(r => (r.timestamp_ms || 0) <= targetMs && r.tank_avg_after != null)
    .sort((a, b) => (b.timestamp_ms || 0) - (a.timestamp_ms || 0))[0];
  if (rBefore) gasPrice = +rBefore.tank_avg_after || gasPrice;
  return { kwhPrice, gasPrice };
}

// Publica os preços médios atuais no MQTT (retained) pra o APK do carro guardar
// nas SharedPreferences e usar nos cálculos internos da tela de viagem.
let _lastPublishedGas = null, _lastPublishedKwh = null;
function publishPricesToCar() {
  // mqttClient é declarado depois do boot — protege contra TDZ no primeiro
  // recompute (que roda antes do mqtt.connect).
  let client;
  try { client = mqttClient; } catch (_) { return; }
  if (!client?.connected) return;
  const gas = +state.price_gas_per_l || 0;
  const kwh = +state.price_kwh || 0;
  if (gas > 0 && gas !== _lastPublishedGas) {
    client.publish(`${MQTT_PREFIX}/cmd/set_price_gas_per_l`, gas.toFixed(3),
      { qos: 1, retain: true });
    _lastPublishedGas = gas;
  }
  if (kwh > 0 && kwh !== _lastPublishedKwh) {
    client.publish(`${MQTT_PREFIX}/cmd/set_price_kwh`, kwh.toFixed(4),
      { qos: 1, retain: true });
    _lastPublishedKwh = kwh;
  }
}

// Estado de alerta já disparado por intervalo (evita re-notificar a cada km).
// Reseta automaticamente quando uma nova manutenção é registrada (ciclo novo).
// Persistido em maintenance.json como `_alerts: { type_id: 'soon'|'overdue' }`.
maintenance._alerts = maintenance._alerts || {};

// Compõe descrição "X km / Y dias" da condição que disparou o alerta
function _maintBody(it) {
  const parts = [];
  if (it.has_km && it.km_status !== 'ok') {
    const rk = it.remaining_km;
    parts.push(rk <= 0
      ? `${Math.round(Math.abs(rk)).toLocaleString('pt-BR')} km atrasada`
      : `${Math.round(rk).toLocaleString('pt-BR')} km restantes`);
  }
  if (it.has_time && it.time_status !== 'ok') {
    const rd = it.remaining_days;
    parts.push(rd <= 0
      ? `${Math.abs(rd)} dias atrasada`
      : `${rd} dias restantes`);
  }
  return parts.join(' · ') || `${Math.round(it.remaining_km).toLocaleString('pt-BR')} km`;
}

function checkMaintenanceAlerts() {
  const items = computeMaintenance();
  for (const it of items) {
    const prev = maintenance._alerts[it.id] || 'ok';
    if (it.status === prev) continue;  // sem mudança de severidade

    // Só notifica em transição pra estado MAIS severo (ok→soon, ok→overdue, soon→overdue)
    const order = { ok: 0, soon: 1, overdue: 2 };
    if (order[it.status] > order[prev]) {
      const body = _maintBody(it);
      if (it.status === 'soon') {
        sendPush(`${it.icon || '🔧'} ${it.label} se aproximando`, body, 'maintenance_soon');
        addEvent('maint_soon', `${it.icon || '🔧'} ${it.label}: ${body}`);
      } else if (it.status === 'overdue') {
        sendPush(`⚠️ ${it.label} atrasada`, body, 'maintenance_overdue');
        addEvent('maint_overdue', `⚠️ ${it.label}: ${body}`);
      }
    }
    maintenance._alerts[it.id] = it.status;
    saveMaintenance();
  }
}

// Verificação diária pros alertas por tempo (km já dispara em cada update do odo)
setInterval(checkMaintenanceAlerts, 60 * 60 * 1000);  // 1h

// ── Monitor do certificado TLS Let's Encrypt ─────────────────────────────────
// DuckDNS add-on renova sozinho, mas se quebrar (rate limit, bug, DNS) o cert
// expira em silêncio. Checamos 1×/dia (e 1× no boot) via handshake TLS na
// porta 8883 e parseamos o validTo. Alerta se faltar menos de 7 dias.
const CERT_HOST = (process.env.CAR_MQTT_HOST || 'mqttrafael.duckdns.org').replace(/^mqtts?:\/\//, '');
const CERT_PORT = parseInt(process.env.CAR_MQTT_PORT || '8883', 10);
let _certWarnNotifiedDay = '';   // 'YYYY-MM-DD' do último alerta — anti-spam diário
function _checkCertExpiry() {
  const tls = require('tls');
  const socket = tls.connect({ host: CERT_HOST, port: CERT_PORT, servername: CERT_HOST, rejectUnauthorized: false, timeout: 8000 }, () => {
    try {
      const cert = socket.getPeerCertificate();
      socket.end();
      if (!cert || !cert.valid_to) return;
      const expiry = new Date(cert.valid_to).getTime();
      const daysLeft = Math.floor((expiry - Date.now()) / 86_400_000);
      console.log(`[cert] ${CERT_HOST}:${CERT_PORT} valid until ${cert.valid_to} (${daysLeft}d restantes)`);
      const today = new Date().toISOString().slice(0, 10);
      if (daysLeft < 7 && _certWarnNotifiedDay !== today) {
        _certWarnNotifiedDay = today;
        sendPush('🔒 Certificado TLS próximo do vencimento',
          `Cert do broker expira em ${daysLeft} dia(s). Verifique o add-on DuckDNS no HA.`,
          'anomaly_detected', { renotify: true });
      }
    } catch (e) { console.warn('[cert] parse falhou:', e.message); }
  });
  socket.on('error', e => console.warn(`[cert] check falhou: ${e.code || e.message}`));
  socket.on('timeout', () => { console.warn('[cert] check timeout'); socket.destroy(); });
}
setTimeout(_checkCertExpiry, 30_000);          // 1ª verificação 30s após boot
setInterval(_checkCertExpiry, 24 * 60 * 60_000); // depois diário

// Watchdog do car_online: se não chega mensagem do carro há >30s, marca offline.
// Cobre o caso raro de queda silenciosa em que nem a LWT chegou.
// Também: detecta ping-pong online↔offline (padrão zumbi/collision) e alerta.
const _offlineTransitions = [];   // ms de cada transição online→offline (janela 5min)
let _lastZumbiAlertMs = 0;        // cooldown 30min entre alertas de zumbi
setInterval(() => {
  if (!state.car_online) return;
  const ageSec = (Date.now() - (state.last_update_ms || 0)) / 1000;
  if (ageSec > 30) {
    state.car_online = false;
    console.log(`[mqtt] watchdog: marcando carro offline (sem msg há ${Math.round(ageSec)}s)`);
    // Registra a transição. Se acumular ≥5 em 5min = APK em ping-pong (zumbi
    // pós-OTA ou client-id collision). Dispara push pro dono pra ele saber
    // que precisa força-parar o app — não deixa a viagem inteira sem saber.
    const now = Date.now();
    _offlineTransitions.push(now);
    while (_offlineTransitions.length && now - _offlineTransitions[0] > 5 * 60_000) {
      _offlineTransitions.shift();
    }
    if (_offlineTransitions.length >= 5 && now - _lastZumbiAlertMs > 30 * 60_000) {
      _lastZumbiAlertMs = now;
      // Reconexão NÃO é queda. O client-id do APK carrega o PID
      // (haval_ecotrip_<id>_p<PID>_b<n>): se ele não mudou, é o MESMO processo
      // reconectando — troca de rede, não crash. Em 09/08 o alerta acusou "caiu 5×"
      // com três IPs diferentes em 10min, PID idêntico e ZERO apk-death: o carro
      // trocou de rede, e o app estava vivo o tempo todo.
      //
      // A distinção importa porque o texto antigo mandava FORCE-PARAR o app — e
      // force-stop põe o Android em stopped state, bloqueando broadcasts e alarmes.
      // O "conserto" deixaria o app inerte até ser aberto na mão.
      const mortesRecentes = _apkDeaths.filter(d => now - new Date(d.at).getTime() < 5 * 60_000).length;
      if (mortesRecentes >= 2) {
        sendPush('⚠️ APK do carro em loop',
          `Ecotrip caiu ${mortesRecentes}× em 5min. Se persistir, abra o app no carro.`,
          'apk_zumbi_loop', { tag: 'apk_zumbi_loop' });
        console.warn(`[mqtt] crash loop real: ${mortesRecentes} mortes/5min`);
      } else {
        // Sem mortes: é instabilidade de REDE. Avisa com o diagnóstico certo, sem
        // mandar force-parar nada.
        sendPush('📶 Conexão do carro instável',
          `${_offlineTransitions.length} reconexões em 5min — provável troca de rede. O app segue rodando.`,
          'apk_rede_instavel', { tag: 'apk_rede_instavel' });
        console.warn(`[mqtt] ${_offlineTransitions.length} reconexões/5min sem morte de processo — instabilidade de rede`);
      }
    }
    // Carro caiu silencioso no meio da viagem (APK morre ao desligar sem publicar
    // engine_state='0'). Sem isso a LA de viagem ficava presa indefinidamente.
    if (_tripActive) _scheduleTripLAEnd();
  }
}, 10_000);

// Watchdog POR FONTE: detecta quando UMA das pernas (APK ou GWM) cai sozinha.
// Cenário que motivou: GWM Brasil parou de publicar mas o APK continuou — sem
// alerta visível, dados ficaram defasados (SOC). Agora, se uma fonte ficar >10min
// silenciosa enquanto a outra continua atualizando, notifica uma vez por hora.
//
// REGRA PRÁTICA: o APK só transmite quando o head unit do carro está ligado.
// Quando o carro está estacionado/dormindo (gear=P, sem carregar, sem driving_ready),
// é NORMAL o APK ficar silencioso — não dispara alerta. Já o GWM (HA Brasil) é
// polled pelo HA e DEVE continuar respondendo mesmo com carro dormindo — silêncio
// dele é sempre anomalia.
let _mqttLastConnectedAt = 0;  // timestamp da última conexão MQTT — grace period pós-reconexão
let _lastCarAwakeMs = 0;       // última vez que _carIsAwake() retornou true
const SOURCE_STALL_MS = 20 * 60_000;           // 20 min de silêncio = stalled
const CAR_AWAKE_WINDOW = 30 * 60_000;          // "foi visto ativo" nos últimos 30min

/** True quando há sinal de que o carro está "em uso" — em movimento, com
 *  motor pronto, ou carregando. Nesses casos o APK DEVE estar publicando.
 *
 *  IMPORTANTE: só confia em state.gear/driving_ready/speed se a FONTE que
 *  publicou esses campos ainda está VIVA. Se APK silente E GWM também stale,
 *  tudo no state é antigo — não dá pra saber. Trata como "carro dormindo"
 *  (não-acordado) e evita falso-positivo de notificação. */
function _carIsAwake() {
  const now    = Date.now();
  const apkAge = now - (state.last_apk_ms || 0);
  const gwmAge = now - (state.last_gwm_ms || 0);
  // Se NENHUMA fonte publicou recentemente, state está stale —
  // não há como saber se o carro está em uso. Assume dormindo.
  const apkFresh = state.last_apk_ms && apkAge < 90_000;          // APK publica a cada poucos segundos
  const gwmFresh = state.last_gwm_ms && gwmAge < 5 * 60_000;      // GWM é polled a cada 30s-2min
  if (!apkFresh && !gwmFresh) return false;
  // NB: charging não conta como "acordado" aqui. Carro carregando parado na
  // garagem com APK zumbi cutucava de hora em hora — e os alertas de recarga
  // vêm da GWM, não do APK, então o silêncio do app não quebra nada nesse caso.
  //
  // gear/driving_ready/speed/power vêm do APK (CAN via Shizuku). Quando o carro
  // estaciona e hiberna, ele MATA o app — esses campos ficam CONGELADOS no
  // último estado (que pode ser "acordado": ready=1, gear=D). Confiar neles com
  // o APK silente gerava o falso "App do carro silente". Só os considera se o
  // APK ainda está fresco.
  if (apkFresh) {
    const gear   = String(state.gear || 'P').toUpperCase();
    const ready  = state.driving_ready === 1 || state.driving_ready === true;
    const speed  = +state.speed_kmh || 0;
    const power  = state.power_mode != null && +state.power_mode > 0;
    if (ready || speed > 1 || power || (gear !== 'P' && gear !== 'N')) return true;
  }
  // Com o APK silente, o único sinal confiável de "acordado" é o motor ligado
  // pela GWM (hyengsts), que segue sendo polled mesmo com o app morto. Mas
  // só conta se o último snapshot do APK NÃO mostrava carro claramente parado
  // (gear=P + speed~0 + driving_ready falso) — evita falso-positivo quando o
  // carro estava estacionado quando o APK silenciou.
  if (gwmFresh && _fieldSource['engine_state'] === 'gwm' &&
      (state.engine_state === '1' || state.engine_state === 1)) {
    const lastGear  = String(state.gear || 'P').toUpperCase();
    const lastSpeed = +state.speed_kmh || 0;
    const lastReady = state.driving_ready === 1 || state.driving_ready === true;
    if (!(lastGear === 'P' && lastSpeed < 1 && !lastReady)) return true;
  }
  return false;
}

// ── Zonas de silêncio esperado ───────────────────────────────────────────────
// Lugares onde o carro comprovadamente fica sem rede (subsolo de garagem, por
// exemplo). Lá o APK silenciar é o comportamento normal, não anomalia, e alertar
// só ensina o dono a ignorar alerta — que é o pior estrago possível num alarme.
//
// A posição usada é a ÚLTIMA CONHECIDA: `gps_lat/lng` vêm só do APK, então quando
// ele emudece a coordenada congela exatamente onde o carro entrou. É o dado certo
// pra esta decisão, e é o único que existe enquanto o silêncio dura.
const SILENCE_ZONES_FILE = path.join(DATA_DIR, 'silence_zones.json');
let _silenceZones = [];
let _zonaSilencioAtual = null;   // pra logar só a transição, não a cada minuto
/// Posição de quando a velocidade ainda era > 0 — base do alerta car_can_frozen.
let _canAncora = null;
/// Último `cmd/restart_app` enviado — cooldown do conserto automático.
let _ultimoRestartApk = 0;
try { _silenceZones = JSON.parse(fs.readFileSync(SILENCE_ZONES_FILE, 'utf8')) || []; } catch (_) {}
function _saveSilenceZones() {
  try { atomicWriteFileSync(SILENCE_ZONES_FILE, JSON.stringify(_silenceZones, null, 2)); }
  catch (e) { console.warn('[zona-silencio] falha ao salvar:', e.message); }
}

/** Zona que contém a última posição conhecida do carro, ou null. */
function _zonaDeSilencio() {
  const lat = +state.gps_lat, lng = +state.gps_lng;
  if (!lat || !lng) return null;
  for (const z of _silenceZones) {
    if (!(z.lat && z.lng)) continue;
    if (haversineM(lat, lng, z.lat, z.lng) <= (+z.radiusM || 250)) return z;
  }
  return null;
}

setInterval(() => {
  const now    = Date.now();
  const apkMs  = state.last_apk_ms || 0;
  const gwmMs  = state.last_gwm_ms || 0;

  // Atualiza janela "carro foi visto ativo" antes de qualquer early-return.
  if (_carIsAwake()) _lastCarAwakeMs = now;

  // Só faz sentido comparar quando AMBAS fontes já produziram algo nesta sessão.
  if (apkMs === 0 || gwmMs === 0) return;
  // Grace period pós-reconexão MQTT: retained GWM chega imediatamente mas o APK
  // precisa de tempo para reconectar. Sem isso, qualquer queda de Starlink dispara
  // falso-positivo de "APK silente" logo que o GWM retorna via retained.
  if ((now - _mqttLastConnectedAt) < SOURCE_STALL_MS) return;

  const apkAge = now - apkMs;
  const gwmAge = now - gwmMs;

  // Zona de silêncio esperado: lá o APK mudo é o normal. Logado na TRANSIÇÃO — um
  // alerta que some sem explicação é tão ruim quanto um alerta falso.
  const zona = _zonaDeSilencio();
  if (!!zona !== !!_zonaSilencioAtual) {
    _zonaSilencioAtual = zona;
    console.log(zona
      ? `[zona-silencio] carro na zona '${zona.name}' — alertas de silêncio suspensos`
      : '[zona-silencio] carro saiu da zona — alertas de silêncio normais');
  }

  // 1. APK silente mas GWM ativa — só alerta com carro acordado (dormir = normal).
  _alert('car_apk_stall',
    apkAge > SOURCE_STALL_MS && gwmAge < SOURCE_STALL_MS && _carIsAwake() && !zona,
    'App do carro silente',
    `Sem dados do APK há ${Math.round(apkAge / 60_000)}min (GWM continua ativa).`,
    'high', ['car']);

  // 1a. CAN congelado com o carro ANDANDO.
  //
  // O modo de falha que nenhum alerta pegava: o APK continua publicando (timestamp
  // fresco a cada 2s) mas os valores do barramento não mexem. Aconteceu em 18/09 e
  // de novo em 22/09 — nas duas vezes o dono descobriu pelo app mudo, dirigindo.
  //
  // Por que ESTE sinal e não o ping do Shizuku: de fora, binder morto e APK travado
  // são idênticos. Em 22/09 eu apostei em Shizuku e era o app travado; o ping teria
  // respondido e o alerta ficaria calado. O que não mente é a contradição — GPS do
  // head unit andando (prova que o APK está vivo E o carro se move) com velocidade
  // parada em 0 (prova que o barramento não chega).
  //
  // Âncora: posição de quando a velocidade foi vista pela última vez acima de zero.
  // Enquanto ela ficar em 0, mede quanto o carro andou desde então.
  {
    const vel = +state.speed_kmh || 0;
    const lat = +state.gps_lat, lng = +state.gps_lng;
    const temGps = Number.isFinite(lat) && Number.isFinite(lng) && (lat || lng);
    if (vel > 0.5 || !temGps) {
      _canAncora = temGps ? { lat, lng, ms: now, odo: +state.odometer_km || 0 } : null;
    } else if (!_canAncora) {
      _canAncora = { lat, lng, ms: now, odo: +state.odometer_km || 0 };
    }
    const andou = _canAncora ? haversineM(_canAncora.lat, _canAncora.lng, lat, lng) : 0;
    const odoDelta = _canAncora ? (+state.odometer_km || 0) - _canAncora.odo : 0;
    // 600 m OU 1 km de odômetro: abaixo disso é deriva de GPS parado. E 2 min de
    // duração pra não disparar num semáforo com GPS pulando.
    const tempo = _canAncora ? now - _canAncora.ms : 0;
    const canCongelado = !!_canAncora && vel <= 0.5 && tempo > 120_000
      && (andou > 600 || odoDelta >= 1) && (now - apkMs) < 60_000;
    // Guarda A JANELA, não só o alerta. Quando a viagem finalmente abrir, o
    // `_completaInicioComCelular` precisa saber desde quando o carro andava — e
    // `_engine_on_ms` não serve: o reinício da multimídia (que é a receita de
    // recuperação) reescreve ele segundos antes da viagem começar, e o portão de
    // 3 min do completar-início nunca abre. Foi o que aconteceu em 22/09: motor
    // "ligado" 07:15:22, viagem 07:15:06, e ~10 min de trajeto sem registro.
    if (canCongelado && _canAncora) {
      state._can_mudo_desde_ms = _canAncora.ms;
      state._can_mudo_lat = _canAncora.lat; state._can_mudo_lng = _canAncora.lng;
      scheduleStateSave();

      // ── Conserto automático ────────────────────────────────────────────────
      //
      // Só avisar não basta: em 22/09 isto aconteceu TRÊS vezes, e nas três quem
      // resolveu foi o dono reiniciando na mão, dirigindo, depois de perceber o
      // painel mudo. O app não morre — ele continua publicando com o barramento
      // congelado —, então nada se auto-recupera.
      //
      // 3 min de condição sustentada antes de agir: tempo de descartar semáforo
      // longo e GPS pulando, e ainda assim menos que o dono levaria pra notar.
      // Cooldown de 20 min do lado de cá, e o AppRestart tem 15 min do lado de lá —
      // duas travas porque reinício em laço deixaria o carro inutilizável, o que é
      // pior que cego.
      const mudoMs = now - _canAncora.ms;
      if (mudoMs > 180_000 && (now - _ultimoRestartApk) > 20 * 60_000) {
        _ultimoRestartApk = now;
        publishCmdWithRetry(`${MQTT_PREFIX}/cmd/restart_app`,
          `CAN congelado ha ${Math.round(mudoMs / 60000)}min com o carro andando`,
          { retain: false, qos: 1 })
          .then(() => {
            console.log(`[can-frozen] restart_app enviado (mudo ha ${Math.round(mudoMs / 60000)}min)`);
            addEvent('apk_restart_auto', 'App do carro reiniciado automaticamente');
            sendPush('🔄 Reiniciei o app do carro',
              'O painel estava congelado com o carro andando. Deve voltar a marcar em ~1 min.',
              'car_apk_restart');
          })
          .catch(e => console.warn('[can-frozen] restart_app falhou:', e.message));
      }
    }
    _alert('car_can_frozen',
      canCongelado,
      'Carro andando e o painel não vê',
      `O app do carro está publicando, mas a leitura do barramento está parada `
      + `(velocidade 0 com ${(andou / 1000).toFixed(1)} km percorridos). `
      + `Viagem não está sendo gravada — reiniciar a multimídia recupera.`,
      'high', ['car']);
  }

  // 1b. Shizuku caído. É ele que sustenta leitura do CAN e comando de vidro/teto;
  // sem ele o APK segue vivo e "funcionando", só que cego e sem braço — por isso
  // não cai em nenhum dos alertas de silêncio acima. Em 18/09 caiu no meio de uma
  // viagem e a única pista foi o comportamento. Só alerta com carro acordado:
  // dormindo, binder morto é o normal.
  _alert('car_shizuku_dead',
    state.shizuku === 'dead' && _carIsAwake(),
    'Shizuku caiu no carro',
    'O APK está vivo mas sem acesso ao CAN — leitura e comandos param. '
    + 'Reiniciar a multimídia recupera.',
    'high', ['car']);

  // 2. GWM silente mas APK ativo — HA é polled, silêncio é sempre anomalia.
  _alert('car_gwm_stall',
    gwmAge > SOURCE_STALL_MS && apkAge < SOURCE_STALL_MS,
    'Integração GWM silente',
    `Sem dados da GWM há ${Math.round(gwmAge / 60_000)}min (APK ativo).`,
    'high', ['satellite']);

  // 3. Silêncio total: ambas fontes sumidas + carro foi visto ativo recentemente.
  // Cobre quedas de infra que silenciam tudo ao mesmo tempo (Starlink, HA + MQTT).
  // NB: ha_down / mqtt_down já cobrem a causa raiz; este alerta foca na perspectiva
  // do carro — "não tenho dados do veículo há Xmin".
  const bothSilent    = apkAge > SOURCE_STALL_MS && gwmAge > SOURCE_STALL_MS;
  const recentlyAwake = _lastCarAwakeMs > 0 && (now - _lastCarAwakeMs) < CAR_AWAKE_WINDOW;
  _alert('car_total_silence',
    bothSilent && recentlyAwake && !zona,
    'Carro sem comunicação',
    `APK ${Math.round(apkAge / 60_000)}min + GWM ${Math.round(gwmAge / 60_000)}min sem dados. Ativo há ${Math.round((now - _lastCarAwakeMs) / 60_000)}min.`,
    'high', ['sos']);
}, 60_000);

// Fallback do endereço: a GWM publica endereco_atual (geocode da nuvem). Sem ela
// (4G out), o APK ainda manda gps_lat/gps_lng via WiFi — então geocodamos local
// (Nominatim, mesma fonte do auto-share) pra manter current_address atualizado.
// Volta pra GWM sozinho quando ela revive. Throttle por coordenada (cache 1000m).
let _lastAddrGeocodeKey = '';
setInterval(async () => {
  const now = Date.now();
  if (_gwmAlive(now)) return;                                 // GWM viva → ela cuida do endereço
  if (!state.last_apk_ms || (now - state.last_apk_ms) > 90_000) return; // APK precisa estar vivo
  const lat = +state.gps_lat, lng = +state.gps_lng;
  if (!lat || !lng) return;
  const key = _geocodeMemKey(lat, lng);
  if (key === _lastAddrGeocodeKey) return;                    // não move → não re-geocoda
  _lastAddrGeocodeKey = key;
  try {
    const g = await _reverseGeocode(lat, lng);
    const addr = [g.suburb, g.city].filter(Boolean).join(', ');
    if (addr) { state.current_address = addr; _fieldSource['current_address'] = 'apk'; }
  } catch (_) {}
}, 60_000);

// ── Detecção de anomalia preventiva ────────────────────────────────────────
// Mantém histórico de snapshots diários (telemetry_history.json) e dispara
// push notif quando uma métrica se desvia significativamente da média móvel
// dos últimos N dias. Não substitui sensores de defeito do carro — é um
// "olha esquisito" baseado em variações graduais.
let telemetryHistory = [];
try {
  if (fs.existsSync(TELEMETRY_LOG_FILE)) {
    telemetryHistory = JSON.parse(fs.readFileSync(TELEMETRY_LOG_FILE, 'utf8')) || [];
  }
  console.log(`✓ Snapshots de telemetria: ${telemetryHistory.length}`);
} catch (e) { console.error('Aviso telemetry_history:', e.message); }

function _todayKey() {
  return new Date().toISOString().slice(0, 10);  // YYYY-MM-DD
}

// Pressão é registrada só quando o pneu está "a frio" (≤ TYRE_COLD_C°C).
// Em movimento o pneu esquenta e a pressão sobe ~1 PSI a cada 10°C — incluir
// essas leituras na média histórica inflava o baseline e gerava falso "perdendo
// pressão" quando o carro voltava a esfriar. A captura mantém o pneu anterior
// (não sobrescreve com 0) quando a temperatura inviabiliza a leitura.
const TYRE_COLD_C = 28;

function _tyreColdPsi(pos) {
  const psi = +state[`tyre_pressure_${pos}`] || 0;
  const t   = +state[`tyre_temp_${pos}`]     || 0;
  // Sem leitura de PSI ou temperatura elevada: retorna null pra preservar
  // o valor anterior do snapshot do dia (não dilui a média com 0).
  if (psi <= 5) return null;
  if (t > TYRE_COLD_C) return null;
  return psi;
}

function captureTelemetrySnapshot() {
  const today = _todayKey();
  const idx = telemetryHistory.findIndex(s => s.date === today);
  const prev = idx >= 0 ? telemetryHistory[idx] : null;
  // Pneus: usa leitura a frio quando disponível; senão preserva o que tinha no
  // snapshot anterior do dia (ou 0 se primeira chamada do dia).
  const tyre = (pos) => {
    const cold = _tyreColdPsi(pos);
    if (cold != null) return cold;
    return prev ? (+prev[`tyre_${pos}`] || 0) : 0;
  };
  const snap = {
    date: today,
    ts: Date.now(),
    tyre_fl: tyre('fl'),
    tyre_fr: tyre('fr'),
    tyre_rl: tyre('rl'),
    tyre_rr: tyre('rr'),
    batt_12v: +state.batt_12v_pct || 0,
    autonomy_ice: +state.autonomy_ice_km || 0,
    autonomy_ev:  +state.autonomy_ev_km  || 0,
    fuel_l: +state.fuel_l || 0,
    soc_pct: +state.soc_pct || 0,
    odometer: +state.odometer_km || 0,
  };
  if (idx >= 0) telemetryHistory[idx] = snap;
  else telemetryHistory.push(snap);
  // Mantém só os últimos 90 dias
  if (telemetryHistory.length > 90) telemetryHistory = telemetryHistory.slice(-90);
  try { fs.writeFileSync(TELEMETRY_LOG_FILE, JSON.stringify(telemetryHistory, null, 2)); } catch (_) {}
}

// Detecta anomalias comparando o snapshot atual com a média dos últimos 14d.
// Evita re-alertar todo dia: mantém memória do dia de cada alerta disparado.
let _anomalyAlerted = {};  // { metric: 'YYYY-MM-DD' }
function checkAnomalies() {
  if (telemetryHistory.length < 7) return;  // amostra mínima
  const today = _todayKey();
  const last = telemetryHistory[telemetryHistory.length - 1];
  const window = telemetryHistory.slice(-15, -1);  // últimos 14 dias (excluindo hoje)
  if (window.length < 5) return;
  const avg = (key) => {
    const vals = window.map(s => +s[key] || 0).filter(v => v > 0);
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
  };

  const issues = [];

  // Pneus: cada um cai mais de 2 PSI da média
  for (const pos of ['fl', 'fr', 'rl', 'rr']) {
    const k = `tyre_${pos}`;
    const a = avg(k), cur = +last[k] || 0;
    if (a > 0 && cur > 0 && (a - cur) >= 2) {
      issues.push({
        metric: `tyre_${pos}_drop`,
        title: `🚗 Pneu ${pos.toUpperCase()} perdendo pressão`,
        body: `Atual ${cur.toFixed(1)} PSI · média 14d ${a.toFixed(1)} PSI (−${(a-cur).toFixed(1)})`,
      });
    }
  }

  // Bateria 12V abaixo de 75% e tendência caindo
  const v12 = avg('batt_12v'), cur12 = +last.batt_12v || 0;
  if (v12 > 0 && cur12 > 0 && cur12 < 75 && (v12 - cur12) >= 5) {
    issues.push({
      metric: 'batt_12v_low',
      title: '🔋 Bateria 12V baixa',
      body: `Atual ${cur12}% · média ${v12.toFixed(0)}%. Considere verificar.`,
    });
  }

  // Autonomia ICE caindo com tanque similar (pode indicar filtro/injeção)
  if (last.fuel_l > 5) {
    const recent = telemetryHistory.slice(-15).filter(s => Math.abs((s.fuel_l || 0) - last.fuel_l) < 3 && (s.autonomy_ice || 0) > 0);
    if (recent.length >= 5) {
      const sortedByDate = [...recent].sort((a, b) => a.ts - b.ts);
      const first3 = sortedByDate.slice(0, 3).map(s => s.autonomy_ice);
      const last3  = sortedByDate.slice(-3).map(s => s.autonomy_ice);
      const avgFirst = first3.reduce((a, b) => a + b, 0) / first3.length;
      const avgLast  = last3.reduce((a, b) => a + b, 0) / last3.length;
      if (avgFirst > 0 && (avgFirst - avgLast) / avgFirst > 0.10) {
        issues.push({
          metric: 'autonomy_ice_drop',
          title: '⛽ Autonomia (combustão) caindo',
          body: `Com tanque ~${last.fuel_l.toFixed(0)}L, estimativa caiu de ${avgFirst.toFixed(0)} km pra ${avgLast.toFixed(0)} km.`,
        });
      }
    }
  }

  // Dispara alertas — evita repetir o mesmo no mesmo dia
  for (const iss of issues) {
    if (_anomalyAlerted[iss.metric] === today) continue;
    _anomalyAlerted[iss.metric] = today;
    addEvent('anomaly', `${iss.title} — ${iss.body}`);
    sendPush(iss.title, iss.body, 'anomaly_detected');
  }
}

// Regressão linear do 12V sobre o histórico diário (até 90d). Base compartilhada
// pelo alerta preditivo (checkBatt12Trend) e pelo subscore de saúde. Retorna
// null sem amostra/janela mínima; senão { slope %/dia, curProj %, daysTo50, perWeek, spanDays, n }.
function batt12Regression() {
  const pts = telemetryHistory
    .filter(s => +s.batt_12v > 0 && +s.batt_12v <= 100 && s.ts)
    .map(s => ({ t: s.ts, v: +s.batt_12v }))
    .sort((a, b) => a.t - b.t);
  if (pts.length < 10) return null;                             // amostra mínima
  const spanDays = (pts[pts.length - 1].t - pts[0].t) / 86400000;
  if (spanDays < 14) return null;                               // janela mínima
  const t0 = pts[0].t;
  const xs = pts.map(p => (p.t - t0) / 86400000), ys = pts.map(p => p.v);
  const n = pts.length, sx = xs.reduce((a, b) => a + b, 0), sy = ys.reduce((a, b) => a + b, 0);
  const sxx = xs.reduce((a, x) => a + x * x, 0), sxy = xs.reduce((a, x, i) => a + x * ys[i], 0);
  const denom = n * sxx - sx * sx;
  if (Math.abs(denom) < 1e-6) return null;
  const slope = (n * sxy - sx * sy) / denom;                    // %/dia (negativo = caindo)
  const intercept = (sy - slope * sx) / n;
  const curProj = intercept + slope * xs[xs.length - 1];        // % projetado hoje
  const daysTo50 = slope < 0 ? (50 - curProj) / slope : null;   // dias até cruzar 50% (só se caindo)
  return { slope, curProj, daysTo50, perWeek: +(-slope * 7).toFixed(1), spanDays, n };
}

// Tendência preditiva do 12V: regressão linear sobre o histórico (até 90d) projeta
// QUANDO o 12V cruza o limite crítico (50%), alertando ANTES de chegar lá — diferente
// do batt12_low (threshold) e do checkAnomalies (diff dia-a-dia). Dispara no máx 1×/7d.
let _batt12TrendSentAt = 0;
const BATT12_TREND_COOLDOWN = 7 * 24 * 60 * 60 * 1000;
function checkBatt12Trend() {
  if (!notifPrefs.batt12_trend) return;
  if (Date.now() - _batt12TrendSentAt < BATT12_TREND_COOLDOWN) return;
  const reg = batt12Regression();
  if (!reg) return;
  const { slope, curProj, daysTo50 } = reg;
  if (slope >= -0.1) return;                                    // estável ou subindo
  if (curProj > 95) return;                                     // ainda cheio → ruído
  if (!(daysTo50 > 0 && daysTo50 <= 30)) return;                // só alerta se cruza 50% em ≤30d
  _batt12TrendSentAt = Date.now();
  const perWeek = reg.perWeek.toFixed(1);
  const title = '🔋 Bateria 12V em queda';
  const body = `12V caindo ~${perWeek}%/semana (atual ~${curProj.toFixed(0)}%). No ritmo, chega a 50% em ~${Math.round(daysTo50)} dias — verifique dreno/alternador.`;
  addEvent('anomaly', `${title} — ${body}`);
  sendPush(title, body, 'batt12_trend');
}

// Captura snapshot diário + check de anomalia 1×/dia (à meia-noite + boot)
function _runDailyTelemetry() {
  captureTelemetrySnapshot();
  checkAnomalies();
  checkBatt12Trend();
}
setTimeout(_runDailyTelemetry, 30 * 1000);                       // 30s após boot
setInterval(_runDailyTelemetry, 24 * 60 * 60 * 1000);            // 24h

// Computa o status de cada intervalo (próxima manutenção, km restantes, severidade)
// Média de km/dia dos últimos N dias (default 30) baseada em autotrips.
// Cai pra 0 se não houver viagens — UI trata como "sem ETA".
function avgDailyKm(daysWindow = 30) {
  const now = Date.now();
  const cutoff = now - daysWindow * 24 * 60 * 60 * 1000;
  let totalKm = 0, firstMs = now;
  for (const t of autoTripsArr) {
    if ((t.startMs || 0) < cutoff) continue;
    totalKm += +t.distKm || 0;
    if ((t.startMs || 0) < firstMs) firstMs = t.startMs;
  }
  const spanMs = Math.max(now - firstMs, 24 * 60 * 60 * 1000); // mín 1 dia
  return totalKm / (spanMs / (24 * 60 * 60 * 1000));
}

function computeMaintenance() {
  const odom = +state.odometer_km || 0;
  const now  = Date.now();
  const MS_PER_DAY = 24 * 60 * 60 * 1000;
  // km/dia médio dos últimos 30 dias — usado pra prever DATA do próximo
  // vencimento por km (até hoje só prevíamos por meses). Se < 1 km/dia,
  // ignora a previsão (carro parado ou recém-instalado).
  const dailyKm = avgDailyKm(30);
  return maintenance.intervals.map(itv => {
    // Pega registro mais recente pra essa manutenção — preferindo o de maior
    // odômetro (fallback: data mais recente se odômetro for igual/zero).
    const all = maintenance.history.filter(h => h.type_id === itv.id);
    const last = all.sort((a, b) => {
      const dk = (b.odometer_km || 0) - (a.odometer_km || 0);
      return dk !== 0 ? dk : (b.date_ms || 0) - (a.date_ms || 0);
    })[0];
    const lastKm   = last ? last.odometer_km : 0;
    const lastDate = last?.date_ms || null;

    // ── Componente km ──
    const everyKm    = +itv.every_km || 0;
    const alertKm    = +itv.alert_km || 500;
    const hasKm      = everyKm > 0;
    const nextKm     = hasKm ? lastKm + everyKm : 0;
    const remainKm   = hasKm ? (nextKm - odom) : Infinity;
    let kmStatus = 'ok';
    if (hasKm) {
      if (remainKm <= 0)        kmStatus = 'overdue';
      else if (remainKm <= alertKm) kmStatus = 'soon';
    }

    // ── Componente tempo (meses) ──
    const everyMonths = +itv.every_months || 0;
    const alertDays   = +itv.alert_days   || 15;
    const hasTime     = everyMonths > 0 && lastDate;
    let nextDate = null, remainDays = Infinity, timeStatus = 'ok';
    if (hasTime) {
      const d = new Date(lastDate);
      d.setMonth(d.getMonth() + everyMonths);
      nextDate = d.getTime();
      remainDays = Math.round((nextDate - now) / MS_PER_DAY);
      if (remainDays <= 0)              timeStatus = 'overdue';
      else if (remainDays <= alertDays) timeStatus = 'soon';
    }

    // Status final: o pior entre os dois (overdue > soon > ok)
    const order = { ok: 0, soon: 1, overdue: 2 };
    const status = order[kmStatus] >= order[timeStatus] ? kmStatus : timeStatus;

    // ── ETA por km/dia: estima quantos dias ainda faltam pro vencimento
    // por km, baseado no ritmo de uso recente. Se carro está parado
    // (dailyKm < 1) ou intervalo não usa km, ignora.
    let etaDaysFromKm = null, etaDateMsFromKm = null;
    if (hasKm && dailyKm >= 1 && remainKm > 0 && Number.isFinite(remainKm)) {
      etaDaysFromKm = Math.round(remainKm / dailyKm);
      etaDateMsFromKm = now + etaDaysFromKm * MS_PER_DAY;
    }

    return {
      ...itv,
      last_km: lastKm,
      last_date_ms: lastDate,
      next_km: nextKm,
      remaining_km: remainKm,
      next_date_ms: nextDate,
      remaining_days: hasTime ? remainDays : null,
      km_status: kmStatus,
      time_status: timeStatus,
      has_km: hasKm,
      has_time: hasTime,
      eta_days_from_km: etaDaysFromKm,     // dias previstos até vencer pelo km/dia
      eta_date_ms_from_km: etaDateMsFromKm, // timestamp previsto
      status,
    };
  });
}

// Retorna o local conhecido mais próximo dentro do raio do local, ou null
function matchKnownPlace(lat, lng, tol = 0) {
  if (!lat || !lng) return null;
  let best = null, bestDist = Infinity;
  for (const loc of knownPlaces) {
    if (!loc.lat || !loc.lng) continue;
    const d = haversineM(lat, lng, loc.lat, loc.lng);
    const r = (loc.radius_m || 200) + tol;   // tol extra absorve desvio de GPS em garagem/estacionamento
    if (d < r && d < bestDist) { best = loc; bestDist = d; }
  }
  return best;
}

// Destinos compartilhados do Waze/Maps (in-memory, últimos ~30). Usados pra nomear
// a viagem que terminar perto deles com o NOME digitado (ex.: "Shopping Flamboyant")
// em vez do bairro+cidade do reverse-geocode.
/// Destinos recentes. Persistidos porque um restart do bridge no meio da viagem
/// apagava o nome do destino e a viagem terminava batizada pelo bairro — mesma
/// falha da chegada zerar o ts, por outro caminho. 30 itens, arquivo minúsculo.
const NAV_DESTS_FILE = path.join(DATA_DIR, 'nav_dests.json');
const recentNavDests = [];
try {
  const _nd = JSON.parse(fs.readFileSync(NAV_DESTS_FILE, 'utf8'));
  if (Array.isArray(_nd)) recentNavDests.push(..._nd.filter(x => x && x.name && _validLatLng(x.lat, x.lng)));
} catch (_) {}
let _navDestsSaveTimer = null;
function _saveNavDestsSoon() {
  if (_navDestsSaveTimer) return;
  _navDestsSaveTimer = setTimeout(() => {
    _navDestsSaveTimer = null;
    try { fs.writeFileSync(NAV_DESTS_FILE, JSON.stringify(recentNavDests.slice(-30))); }
    catch (e) { console.warn('[nav_dest] falha ao salvar:', e.message); }
  }, 5_000);
}
// Dispositivos NavRelay online: alimentado por mensagens retidas em nav_devices/<id>.
// LWT esvazia retain ao desconectar — entry é apagada no handler do mqtt.
const _navDevices = {};
/// Espelha o destino no Waze do Android do carro (espelhamento/Android Auto).
///
/// Direção deliberada: o bridge manda pros DOIS, em vez de ler o Waze. O Waze não
/// expõe o destino atual — a notificação dele traz próxima manobra e ETA, não o
/// endereço — então capturar de lá exigiria ler a tela por acessibilidade, que
/// quebra a cada update. O deep link `waze://?ll=…&navigate=yes` é estável, e o
/// MacroDroid só executa o intent quando recebe o webhook.
///
/// Fica desligado sem WAZE_WEBHOOK_URL no .env. Falha nunca propaga: destino no
/// carro não pode depender do celular estar acordado.
const WAZE_WEBHOOK_URL = process.env.WAZE_WEBHOOK_URL || '';
function _espelhaDestinoNoWaze(lat, lng, name) {
  if (!WAZE_WEBHOOK_URL) return;
  const la = +lat, ln = +lng;
  if (!Number.isFinite(la) || !Number.isFinite(ln) || (!la && !ln)) return;
  const u = new URL(WAZE_WEBHOOK_URL);
  u.searchParams.set('lat', la.toFixed(6));
  u.searchParams.set('lng', ln.toFixed(6));
  if (name) u.searchParams.set('name', String(name).slice(0, 60));
  const ctl = new AbortController();
  const to = setTimeout(() => ctl.abort(), 8000);
  fetch(u.toString(), { signal: ctl.signal })
    .then(r => console.log(`[waze] destino '${name}' → MacroDroid HTTP ${r.status}`))
    .catch(e => console.warn('[waze] webhook falhou:', e.message))
    .finally(() => clearTimeout(to));
}

let _navDestRetained = false;   // há um nav_dest retido no broker? (pra limpar ao expirar)
/// Nome de onde a viagem ANTERIOR terminou, se esta começa no mesmo ponto.
///
/// Sem isto, sair de um lugar que só tinha nome por destino digitado (não é Local
/// Conhecido) produzia o bairro do reverse-geocode na partida: chegou em "New
/// Vikings Barbearia Moderna" e saiu de "Setor Bueno" (01/08). Se o carro não se
/// moveu entre as duas viagens, é o mesmo lugar e merece o mesmo nome.
///
/// Compara com a viagem imediatamente anterior e só herda se ela terminou PERTO —
/// herdar de uma mais antiga ignoraria o trecho que houve no meio.
function _nomeDaChegadaAnterior(lat, lng, startMs, tolM = 150) {
  if (!lat || !lng || !startMs) return null;
  let ant = null;
  for (const t of autoTripsArr) {
    if (!t.endMs || t.endMs > startMs || !t.endLat || !t.endLng) continue;
    if (!ant || t.endMs > ant.endMs) ant = t;
  }
  if (!ant) return null;
  if (haversineM(lat, lng, ant.endLat, ant.endLng) > tolM) return null;   // houve movimentação
  return ant.endKp || null;
}

function _navDestNameFor(lat, lng) {
  if (!lat || !lng) return null;
  const maxAgeMs = 12 * 3600 * 1000;   // só destinos das últimas 12h
  const now = Date.now();
  let best = null, bestDist = Infinity;
  for (const nd of recentNavDests) {
    if (now - nd.ts > maxAgeMs) continue;
    const d = haversineM(lat, lng, nd.lat, nd.lng);
    if (d < 300 && d < bestDist) { best = nd; bestDist = d; }   // ~300 m do ponto compartilhado
  }
  return best ? best.name : null;
}

// Reserva de bateria: o carro guarda os últimos 15% do SOC pro motor a combustão
// (não dá pra rodar 100% elétrico até 0). A autonomia EV exibida e todos os
// cálculos de alcance consideram só a energia ATÉ 15% de SOC.
const EV_RESERVE_PCT = 15;
let _rangeEvRaw = 0;   // valor cru do sensor (até ~0%), antes da reserva
function _applyEvReserve() {
  const soc = +state.soc_pct || 0;
  if (_rangeEvRaw <= 0) return;
  state.range_ev_km = soc > EV_RESERVE_PCT ? Math.round(_rangeEvRaw * (soc - EV_RESERVE_PCT) / soc) : 0;
}

// ── Geofence: detecta entrada/saída de locais conhecidos e dispara push ───
// Mantém estado por place {id → 'in'|'out'}. Histerese de 20% no raio pra evitar
// flapping na borda. Saída só notifica se motor ligado (evita ruído de
// reconexão GPS). Loga eventos `geofence_in` / `geofence_out` em events.json.
const geofenceState = {};  // { placeId: 'in' | 'out' }
// ── Heading do carro (orientação no mapa) ───────────────────────────────────
// Calculado do deslocamento GPS quando em movimento (>3 km/h e >5 m), guardado
// em state.car_heading (PERSISTIDO via scheduleStateSave). Assim o marcador do
// PWA acerta o rumo mesmo parado, ao abrir o app ou após restart do bridge —
// não depende de cada cliente recalcular. 0 = Norte.
let _headingPrevLat = null, _headingPrevLng = null;
function _maybeUpdateCarHeading() {
  const lat = +state.gps_lat, lng = +state.gps_lng;
  if (!lat || !lng) return;
  if (_headingPrevLat == null) { _headingPrevLat = lat; _headingPrevLng = lng; return; }
  if (haversineM(_headingPrevLat, _headingPrevLng, lat, lng) < 5) return;   // movimento mínimo (~5 m)
  if ((+state.speed_kmh || 0) > 1) {   // ≥1 km/h: atualiza rumo até em manobra lenta (5 m filtra jitter)
    const toRad = d => d * Math.PI / 180, toDeg = r => r * 180 / Math.PI;
    const f1 = toRad(_headingPrevLat), f2 = toRad(lat), dl = toRad(lng - _headingPrevLng);
    const y = Math.sin(dl) * Math.cos(f2);
    const x = Math.cos(f1) * Math.sin(f2) - Math.sin(f1) * Math.cos(f2) * Math.cos(dl);
    state.car_heading = Math.round((toDeg(Math.atan2(y, x)) + 360) % 360);
    scheduleStateSave();
  }
  _headingPrevLat = lat;
  _headingPrevLng = lng;
}

// Anti-furto: se o carro NÃO está em uso (não ready, motor desligado, parado) e
// mesmo assim o GPS se desloca >200 m, alerta (rebocado/movido). Baseline segue o
// carro enquanto está em uso; só dispara desligado. Debounce de 10 min.
// Pra filtrar jitter/deriva pontual do GPS, o deslocamento precisa SUSTENTAR
// >200 m por ≥3 amostras ao longo de ≥60 s antes de virar alerta.
let _theftBase = null, _theftAlertedMs = 0, _theftPending = null, _theftLastCheckMs = 0;
function checkTheft() {
  const lat = +state.gps_lat, lng = +state.gps_lng;
  if (!lat || !lng) return;
  const inUse = state.driving_ready === 1 || state.driving_ready === true
    || String(state.engine_state) === '1' || (+state.speed_kmh || 0) > 3;
  // Gap de telemetria: se passou >30s entre dois checks (APK MQTT travou e
  // retomou), o baseline anterior é stale — o carro pode ter chegado dirigindo
  // mas o bridge não viu as posições intermediárias. Refresca sem alertar.
  const now = Date.now();
  const gap = _theftLastCheckMs ? (now - _theftLastCheckMs) : 0;
  _theftLastCheckMs = now;
  if (gap > 30_000) { _theftBase = { lat, lng }; _theftPending = null; return; }
  if (inUse) { _theftBase = { lat, lng }; _theftPending = null; return; }   // em uso → acompanha, sem alerta
  if (!_theftBase) { _theftBase = { lat, lng }; return; }
  const moved = haversineM(_theftBase.lat, _theftBase.lng, lat, lng);
  if (moved <= 200) { _theftPending = null; return; }   // voltou perto → cancela pendência
  // Deslocamento candidato. Acumula até confirmar; se uma única amostra >200m
  // (jitter) aparecer isolada, a próxima volta perto e zera _theftPending.
  if (!_theftPending) {
    _theftPending = { firstMs: Date.now(), samples: 1 };
    return;
  }
  _theftPending.samples += 1;
  const sustainedSec = (Date.now() - _theftPending.firstMs) / 1000;
  if (_theftPending.samples >= 3 && sustainedSec >= 60
      && Date.now() - _theftAlertedMs > 10 * 60_000) {
    _theftAlertedMs = Date.now();
    _theftBase = { lat, lng };
    _theftPending = null;
    addEvent('theft_move', `Carro se moveu ${Math.round(moved)} m com o motor desligado`);
    sendPush('⚠️ Carro se moveu', `O Haval saiu do lugar (~${Math.round(moved)} m) com o motor desligado. Verifique.`, 'theft');
  }
}

// Janela de segurança (dias + faixa "HH:MM"). Vazio/inválido = sempre dentro.
function _inSecurityWindow(now = new Date()) {
  const days = Array.isArray(notifPrefs.security_days) ? notifPrefs.security_days.map(Number).filter(Number.isFinite) : [];
  if (days.length && !days.includes(now.getDay())) return false;
  const toMin = s => { const m = /^(\d{1,2}):(\d{2})$/.exec(String(s || '')); return m ? (+m[1]) * 60 + (+m[2]) : null; };
  const f = toMin(notifPrefs.security_from), t = toMin(notifPrefs.security_to);
  if (f == null || t == null) return true;            // sem faixa válida → só o filtro de dias conta
  const cur = now.getHours() * 60 + now.getMinutes();
  return f <= t ? (cur >= f && cur <= t) : (cur >= f || cur <= t);   // suporta virar meia-noite
}

function checkGeofence() {
  const lat = state.gps_lat, lng = state.gps_lng;
  if (!lat || !lng) return;
  const engineOn = String(state.engine_state) === '1' || state.engine_state === 1;
  for (const loc of knownPlaces) {
    if (!loc.lat || !loc.lng) continue;
    const r = loc.radius_m || 200;
    const d = haversineM(lat, lng, loc.lat, loc.lng);
    const prev = geofenceState[loc.id];
    const isInside = d < r;
    // Histerese: pra mudar IN → OUT precisa estar 20% além do raio
    const isOutside = d > r * 1.2;
    if (isInside && prev !== 'in') {
      geofenceState[loc.id] = 'in';
      if (prev === 'out') {  // só notifica se houve transição (não no boot)
        addEvent('geofence_in', `📍 Chegou em ${loc.name}`);
        // Filtro de places permanece global (todos devices reagem aos mesmos locais).
        // O on/off da categoria geofence_arrival fica por device dentro do sendPush.
        const arrPlaces = notifPrefs.geofence_arrival_places || [];
        if (arrPlaces.length === 0 || arrPlaces.includes(String(loc.id)))
          sendPush(`📍 Chegou em ${loc.name}`, `Veículo dentro da zona.`, 'geofence_arrival');
        _scheduleSocArrivalAlert(loc);
      }
    } else if (isOutside && prev !== 'out') {
      geofenceState[loc.id] = 'out';
      if (_socArrivalTimers[loc.id]) { clearTimeout(_socArrivalTimers[loc.id]); delete _socArrivalTimers[loc.id]; }
      // Segurança por janela: saída de local monitorado durante janela proibida →
      // alerta INDEPENDENTE do motor (cobre reboque/empurrão e furto com motor on).
      if (prev === 'in' && notifPrefs.security_departure && _inSecurityWindow()) {
        const secPlaces = notifPrefs.security_departure_places || [];
        if (secPlaces.length === 0 || secPlaces.map(String).includes(String(loc.id))) {
          addEvent('security_departure', `🚨 Carro saiu de ${loc.name} em horário monitorado`);
          sendPush('🚨 Saída suspeita', `O Haval deixou ${loc.name} dentro da janela de segurança. Verifique.`, 'security_departure');
        }
      }
      if (prev === 'in' && engineOn) {  // saída só com motor ligado
        addEvent('geofence_out', `🚗 Saiu de ${loc.name}`);
        const depPlaces = notifPrefs.geofence_departure_places || [];
        if (depPlaces.length === 0 || depPlaces.includes(String(loc.id)))
          sendPush(`🚗 Saiu de ${loc.name}`, `Veículo deixou a zona.`, 'geofence_departure');
      }
    }
  }
  // Monitor server-side das regras geofence-vidro: o APK executa; o bridge só observa
  // se o vidro atingiu o estado esperado e alerta se não (usa o mesmo GPS do carro).
  _evalGeofenceRules(lat, lng);
}

// Retorna o local conhecido mais próximo dentro de radiusM metros, ou null
function autoMatchLocation(lat, lng, radiusM = 200) {
  // Tenta known_places primeiro (raio por local); fallback para chargeLocations com raio fixo
  const kp = matchKnownPlace(lat, lng);
  if (kp) return kp;
  if (!lat || !lng) return null;
  let best = null, bestDist = Infinity;
  for (const loc of chargeLocations) {
    if (!loc.lat || !loc.lng) continue;
    const d = haversineM(lat, lng, loc.lat, loc.lng);
    if (d < radiusM && d < bestDist) { best = loc; bestDist = d; }
  }
  return best;
}

// ── Express + HTTP ────────────────────────────────────────────────────────────

const app    = express();
const server = http.createServer(app);

// ── HTTPS opcional — ativo quando cert.pem + key.pem existem no diretório ────
// Setup: brew install mkcert && mkcert -install
//        cd ~/haval-ecotrip/bridge
//        mkcert mac-mini.local localhost 127.0.0.1 <IP-LAN>
//        mv mac-mini.local+*.pem cert.pem; mv mac-mini.local+*-key.pem key.pem
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);
const _certFile  = path.join(DATA_DIR, 'cert.pem');
const _keyFile   = path.join(DATA_DIR, 'key.pem');
let httpsServer  = null;
if (fs.existsSync(_certFile) && fs.existsSync(_keyFile)) {
  try {
    httpsServer = require('https').createServer(
      { cert: fs.readFileSync(_certFile), key: fs.readFileSync(_keyFile) },
      app
    );
    console.log('✅  Certificado HTTPS encontrado — porta', HTTPS_PORT);
  } catch (e) {
    console.warn('⚠️  HTTPS: falha ao ler certificado —', e.message);
  }
}

// ── Proxy pra Ellevar Clockin (app de ponto separado em :3010) ─────────────
// /clockin/* passa direto, sem auth do Haval. App tem auth propria (PIN + WebAuthn).
const _clockinProxy = require('http-proxy').createProxyServer({ ws: true, xfwd: true });
_clockinProxy.on('error', (err, req, res) => {
  console.warn('[clockin] proxy erro:', err.message);
  if (res && res.writeHead && !res.headersSent) { res.writeHead(502); res.end('clockin offline'); }
});
function _isClockinPath(u) {
  return typeof u === 'string' && (u === '/clockin' || u.startsWith('/clockin/') || u.startsWith('/clockin?'));
}
app.use((req, res, next) => {
  if (_isClockinPath(req.url)) return _clockinProxy.web(req, res, { target: 'http://127.0.0.1:3010' });
  next();
});
server.on('upgrade', (req, socket, head) => {
  if (_isClockinPath(req.url)) _clockinProxy.ws(req, socket, head, { target: 'http://127.0.0.1:3010' });
});

// ── Contador de Host ─────────────────────────────────────────────────────────
// Quem ainda bate no hostname antigo? Sem isso, desligar o Funnel do Tailscale é
// adivinhação: um cliente esquecido (atalho, script, app não atualizado) só
// apareceria quando quebrasse. Conta por Host numa janela de 24h, com o último
// acesso e o user-agent — o suficiente pra identificar o retardatário.
//
// Persistido em disco: a janela de observação é de 48h e um restart do bridge
// (deploy, crash) zerava tudo — o contador mostraria 0 por ter perdido a memória,
// não por ninguém ter usado, e é justamente essa leitura que faria desligar o
// Funnel cedo demais.
const HOST_HITS_FILE = path.join(DATA_DIR, 'host-hits.json');
const _hostHits = new Map();   // host → { n, firstMs, lastMs, agents:Set, ips:Set, paths:Map }
const HOST_WINDOW_MS = 48 * 3600_000;
let _hostHitsResetMs = 0;      // declarado aqui: o GET abaixo lê antes do POST definir

function _loadHostHits() {
  try {
    const j = JSON.parse(fs.readFileSync(HOST_HITS_FILE, 'utf8'));
    _hostHitsResetMs = j.resetMs || 0;
    const now = Date.now();
    for (const [host, e] of Object.entries(j.hosts || {})) {
      if (now - (e.firstMs || 0) > HOST_WINDOW_MS) continue;   // fora da janela
      _hostHits.set(host, {
        n: e.n || 0, firstMs: e.firstMs || now, lastMs: e.lastMs || now,
        agents: new Set(e.agents || []), ips: new Set(e.ips || []),
        paths: new Map(Object.entries(e.paths || {})),
      });
    }
    if (_hostHits.size) console.log(`[host-hits] restaurados ${_hostHits.size} hosts do disco`);
  } catch (_) { /* primeira execução */ }
}

let _hostHitsSaveTimer = null;
function _saveHostHitsSoon() {
  if (_hostHitsSaveTimer) return;   // debounce: o middleware roda em TODA request
  _hostHitsSaveTimer = setTimeout(() => {
    _hostHitsSaveTimer = null;
    try {
      const hosts = {};
      for (const [host, e] of _hostHits) {
        hosts[host] = { n: e.n, firstMs: e.firstMs, lastMs: e.lastMs,
                        agents: [...e.agents], ips: [...(e.ips || [])],
                        paths: Object.fromEntries(e.paths || []) };
      }
      fs.writeFileSync(HOST_HITS_FILE, JSON.stringify({ resetMs: _hostHitsResetMs, hosts }));
    } catch (e) { console.warn('[host-hits] falha ao salvar:', e.message); }
  }, 20_000);
}
_loadHostHits();

// Só o Funnel do Tailscale bloqueia o desligamento. O DuckDNS NÃO entra: ele é
// acesso direto por porta aberta, não depende do Tailscale, e é justamente o
// fallback que o BridgeRouter do app usa quando o Cloudflare está mais lento.
// Contar o duckdns como "legado" dava falso alarme — o app iOS aparece lá por
// design, não por estar desatualizado.
function _isFunnelHost(h) { return /tailacc6e7|\.ts\.net$/.test(String(h || '')); }
app.use((req, _res, next) => {
  try {
    // Monitores do próprio Mac não contam: eles sondam o hostname antigo por
    // design (probe do bridge a cada 15s, watchdog do launchd a cada 120s) e
    // inflavam o número que decide se ainda tem CLIENTE real lá — chegaram a ser
    // ~59 acessos/h de puro auto-monitoramento.
    const _ua = req.headers['user-agent'] || '';
    // Diagnóstico do MacroDroid: o host-hits não guarda path pra host não-legacy,
    // então uma macro que erra a rota ou o token fica invisível — só aparece que
    // "bateu no bridge". Loga método, rota e status, pra fechar o diagnóstico do
    // lado do servidor sem depender de ler o Toast no celular.
    if (/macrodroid/i.test(_ua)) {
      // Mascara o token: só presença, prefixo e tamanho. Suficiente pra separar
      // "header não chegou" de "placeholder não foi trocado" sem vazar segredo no
      // log, que é lido em texto puro.
      const _a = req.headers['authorization'] || '';
      const _t = _a.startsWith('Bearer ') ? _a.slice(7).trim() : '';
      const _tinfo = !_a ? 'SEM header Authorization'
                   : !_t ? `header presente mas sem 'Bearer ' (${_a.slice(0, 12)}…)`
                   : `Bearer ${_t.slice(0, 4)}… (${_t.length} chars)`;
      _res.on('finish', () => console.log(
        `[macrodroid] ${req.method} ${req.originalUrl} → HTTP ${_res.statusCode} | auth: ${_tinfo}`));
    }
    if (_ua.startsWith('ecotrip-funnel-probe') || _ua.startsWith('funnel-watchdog')) return next();
    const h = String(req.headers.host || '?').toLowerCase().split(':')[0];
    const now = Date.now();
    let e = _hostHits.get(h);
    if (!e || now - e.firstMs > HOST_WINDOW_MS) {
      e = { n: 0, firstMs: now, lastMs: now, agents: new Set(), paths: new Map() };
    }
    e.n += 1; e.lastMs = now;
    const ua = (req.headers['user-agent'] || '').slice(0, 40);
    if (ua && e.agents.size < 6) e.agents.add(ua);
    // Path também: saber QUE endpoint o retardatário chama é o que diz onde
    // reconfigurar. Só nos hosts legados, pra não gastar memória com o normal.
    if (_isFunnelHost(h)) {
      const p = String(req.path || req.url || '').split('?')[0].slice(0, 60);
      if (e.paths.size < 40) e.paths.set(p, (e.paths.get(p) || 0) + 1);
      else if (e.paths.has(p)) e.paths.set(p, e.paths.get(p) + 1);
      // IP de origem: UA genérico ("curl/8.5.0") não diz de qual máquina veio, e
      // sem isso sobra adivinhar de qual dispositivo da tailnet é.
      e.ips = e.ips || new Set();
      const ip = (req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '?')
        .toString().split(',')[0].trim();
      if (e.ips.size < 8) e.ips.add(ip);
    }
    _hostHits.set(h, e);
    _saveHostHitsSoon();
  } catch (_) { /* contador não pode derrubar request */ }
  next();
});
// IPs "de casa": o público da residência e as faixas privadas. Serve pra separar
// cliente conhecido de scanner — o Funnel é público e bots varrem a internet
// (28/07: 172.184.247.1, Azure/Microsoft, pedindo /health.html). Sem separar, o
// ruído de scanner mascara a pergunta "ainda tem cliente MEU no host antigo?".
function _ipConhecido(ip) {
  const s = String(ip || '');
  if (!s || s === '?') return true;                       // sem dado: não acusa
  if (/^(127\.|::1|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.)/.test(s)) return true;
  return s === (_ddnsLastIp() || '');                     // IP público atual da casa
}
function _ddnsLastIp() {
  try { return fs.readFileSync(path.join(require('os').homedir(), '.cloudflared/ddns-last-ip'), 'utf8').trim(); }
  catch (_) { return ''; }
}

// User-agents dos NOSSOS clientes. Vale mais que o IP: eles rodam em 4G (carro,
// iPhone da Grasi) e o IP muda, então filtrar só por IP mascarava cliente real
// como se fosse scanner.
const UA_CLIENTES = [
  'HavalEcoTrip', 'BydRecarga', 'EllevarClockin',   // apps iOS
  'Dalvik',                                         // APK do carro / cluster
  'HomeAssistant', 'aiohttp',                       // HA de casa e do sítio
  'okhttp',                                         // libs Android
];
function _uaClienteConhecido(ua) {
  const s = String(ua || '');
  return UA_CLIENTES.some(m => s.includes(m));
}

// Qual fonte manda em cada chave disputada, e por quê. Sem isto, "por que o app
// mostra o carro ligado" só se responde lendo log.
app.get('/api/source-state', (_req, res) => {
  const now = Date.now();
  const out = {};
  // Itera os campos DISPUTADOS, não só MIGRATED_TO_HA: soc_pct, autonomy_* e
  // fuel_l são escritos pelas duas fontes sem estar no gate, e ficavam invisíveis
  // aqui — justamente os que apareceram velhos no app (SOC 88% vs 74% do CAN).
  for (const key of [..._camposDisputados].sort()) {
    const e = _srcChange[key] || {};
    out[key] = {
      valor_atual: state[key],
      fonte: _fieldSource[key] || null,
      gwm: e.gwm ? { valor: e.gwm.v, mudou_ha_s: Math.round((now - e.gwm.ms) / 1000) } : null,
      apk: e.apk ? { valor: e.apk.v, mudou_ha_s: Math.round((now - e.apk.ms) / 1000) } : null,
      // Os valores CRUS têm formatos diferentes por fonte (vidro do APK vem
      // '1:<ts>', sunroof da GWM é posição 0-3). Sem expor o normalizado, o
      // monitor mostra "discordam" justamente onde a decisão vê concordância.
      concordam: !!(e.gwm && e.apk) && _normCmp(key, e.gwm.v) === _normCmp(key, e.apk.v),
      gwm_congelada: !!(e.gwm && now - e.gwm.ms > GWM_VALUE_STALE_MS),
    };
  }
  res.json({ gwm_publicando: _gwmAlive(now),
             gwm_ultimo_pacote_s: state.last_gwm_ms ? Math.round((now - state.last_gwm_ms) / 1000) : null,
             // AO VIVO, não last_apk_ms: aquele é atualizado por retained e pela
             // re-injeção que o failover faz a cada mensagem bloqueada da GWM,
             // então marcava 0s com o carro dormindo — inútil pra diagnóstico.
             apk_ultimo_pacote_s: state.last_apk_live_ms ? Math.round((now - state.last_apk_live_ms) / 1000) : null,
             apk_bruto_s:         state.last_apk_ms      ? Math.round((now - state.last_apk_ms)      / 1000) : null,
             limites: { gwm_valor_parado_s: GWM_VALUE_STALE_MS / 1000,
                        apk_discordando_s:  APK_TAKEOVER_MIN_MS / 1000 },
             chaves: out });
});

app.get('/api/host-hits', (_req, res) => {
  const out = [...
    _hostHits.entries()].map(([host, e]) => ({
      host, hits: e.n, lastMs: e.lastMs, sinceMs: e.firstMs,
      agents: [...e.agents],
      ips: [...(e.ips || new Set())],
      paths: [...(e.paths || new Map())].sort((a, b) => b[1] - a[1]).slice(0, 8)
                                        .map(([p, n]) => ({ path: p, n })),
      legacy: _isFunnelHost(host),
      fallback: /duckdns/.test(host),   // acesso direto, não bloqueia o desligamento
      // "Externo" = scanner/bot, que não deve travar o desligamento do Funnel.
      //
      // Classifica por USER-AGENT e não por IP: o app do sogro (BydRecarga) roda
      // no 4G dele, com IP que não é o da casa, e o filtro só-por-IP o marcava
      // como scanner — escondendo um cliente real ainda no ts.net.
      externo: !(e.agents && [...e.agents].some(a => _uaClienteConhecido(a)))
            && [...(e.ips || new Set())].length > 0
            && [...(e.ips || new Set())].every(ip => !_ipConhecido(ip)),
      // Quais UAs conhecidos ainda batem aqui. É ISTO que diz se o Funnel pode
      // cair — a contagem de hits do host mistura cliente e bot no mesmo número,
      // porque agents/paths são conjuntos por host e não dá pra atribuir cada hit.
      clientes: [...(e.agents || new Set())].filter(a => _uaClienteConhecido(a)),
    })).sort((a, b) => b.hits - a.hits);
  const legacy = out.filter(h => h.legacy);
  // O que DECIDE o desligamento é a lista de clientes conhecidos ainda batendo no
  // Funnel, não a contagem de hits: agents e paths são conjuntos por host, então
  // um único cliente conhecido fazia o host inteiro (bots incluídos) contar como
  // "seu" e inflava o número — 38 hits quando só o app do sogro importava.
  const clientesNoFunnel = [...new Set(legacy.flatMap(h => h.clientes || []))];
  res.json({ hosts: out, window_h: HOST_WINDOW_MS / 3600_000,
             legacy_hits:         legacy.filter(h => !h.externo).reduce((s, h) => s + h.hits, 0),
             legacy_hits_externo: legacy.filter(h =>  h.externo).reduce((s, h) => s + h.hits, 0),
             // Vazio = seguro desligar o Funnel.
             clientes_no_funnel:  clientesNoFunnel,
             reset_ms: _hostHitsResetMs });
});

// Zera a contagem. Serve pra marcar "corrigi um retardatário" e ver do zero se
// alguém volta a bater no host antigo — sem isso os hits de antes da correção
// mascaram os novos e não dá pra saber se resolveu.
app.post('/api/host-hits/reset', (_req, res) => {
  const antes = [...
    _hostHits.entries()].filter(([h]) => _isFunnelHost(h))
                        .reduce((s, [, e]) => s + e.n, 0);
  _hostHits.clear();
  _hostHitsResetMs = Date.now();
  console.log(`[host-hits] zerado (havia ${antes} acessos em host legado)`);
  res.json({ ok: true, cleared_legacy: antes, reset_ms: _hostHitsResetMs });
});

app.use(require('compression')());  // gzip — backup de 11MB cai pra ~1.5MB
app.use(express.json({ limit: '200mb' }));  // /api/restore carrega o backup completo (autotrips+samples) — já ~38MB e cresce até o cap de 2000 trips. Auth-gated; express.json só bufferiza o que chega (não pré-aloca).
app.use((req, res, next) => {
  // Sem isso, o URLSession (iOS) pode cachear por heurística respostas de sync
  // (sem Cache-Control) e servir corpo antigo. Boa prática pra APIs dinâmicas.
  if (req.path.startsWith('/api')) res.setHeader('Cache-Control', 'no-store, must-revalidate');
  next();
});
// Basic auth no HTML do monitor. Navegação de browser NÃO manda header
// Authorization: Bearer, então não dá pra reusar o token do jeito que as /api/*
// fazem — o Basic é o único esquema que o browser negocia sozinho (pede uma vez
// e guarda na sessão).
//
// Por que fechar: o HTML aberto entregava a estrutura do monitor (nomes de
// endpoint, ids dos cards) a qualquer scanner. Não era vazamento de dado — o
// conteúdo vem das /api/*, que exigem token — mas era reconhecimento de graça.
// Um bot da Azure pediu /health.html em 28/07.
//
// Senha = o token do bridge (usuário: qualquer coisa). HEALTH_HTML_OPEN=1 no .env
// volta ao comportamento aberto.
function requireHealthHtmlAuth(req, res, next) {
  if (process.env.HEALTH_HTML_OPEN === '1' || !BRIDGE_TOKEN_HASH) return next();
  const h = req.headers.authorization || '';
  if (h.startsWith('Basic ')) {
    const pw = Buffer.from(h.slice(6), 'base64').toString('utf8').split(':').slice(1).join(':');
    if (safeStrEqual(pw, BRIDGE_TOKEN_HASH) || safeStrEqual(sha256hex(pw), BRIDGE_TOKEN_HASH)) return next();
  }
  // Sessão admin também abre (senha + 2FA já provaram identidade).
  const sid = (req.headers['x-admin-session'] || '').toString().trim();
  if (sid && adminAuth.validSession(sid)) return next();
  res.set('WWW-Authenticate', 'Basic realm="Bridge Health", charset="UTF-8"');
  return res.status(401).send('auth necessária');
}

app.get('/health.html', requireHealthHtmlAuth, (_req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  res.sendFile(path.join(__dirname, 'public', 'health.html'));
});

// Raiz por hostname: bridge.* é o nome do SERVIDOR, então abre o monitor; a PWA
// do carro fica no carro.*, que é o nome do Haval/Grasi. Mesmo processo, mesma
// porta — só a porta de entrada muda de significado.
//
// Redirect (302) em vez de servir o health direto, pra URL na barra refletir
// onde a pessoa está. HEAD passa igual, então o probe do Funnel e a corrida do
// BridgeRouter (que fazem HEAD em '/') continuam validando: 302 < 500.
const _monitorHosts = new Set(
  [process.env.BRIDGE_PUBLIC_URL || 'https://bridge.malha.dev']
    .map(u => { try { return new URL(u).hostname.toLowerCase(); } catch (_) { return ''; } })
    .filter(Boolean));
app.get('/', (req, res, next) => {
  const h = String(req.headers.host || '').toLowerCase().split(':')[0];
  if (_monitorHosts.has(h)) return res.redirect(302, '/health.html');
  next();
});

app.use(express.static(path.join(__dirname, 'public')));

// ── Viewer 3D (Haval-H6-3D, de netseek) servido pro iPad ─────────────────────
// O app do carro é, na prática, uma página: Three.js num WebView. Servir aqui e
// abrir num WKWebView do app iOS evita portar 13 mil linhas de casca Java que só
// fazem sentido no head unit (troca de tarefa, acessibilidade, launcher).
//
// O index é servido com o shim INJETADO em vez de editado: o arquivo do autor
// fica intacto na árvore, e atualizar a cópia dele não conflita com nada nosso.
const WEB3D_DIR = path.join(__dirname, 'web3d');
if (fs.existsSync(path.join(WEB3D_DIR, 'index.html'))) {
  // SEM a barra final, `assets/x.glb` no HTML resolve pra /assets/x.glb em vez de
  // /3d/assets/x.glb e nada carrega — o viewer sobe com o DOM cru, placeholders
  // de template à mostra. Mesma armadilha de path aninhado do Assinador.
  app.get(['/3d', '/3d/'], (req, res) => {
    // O Express casa os dois caminhos na MESMA rota (strict routing desligado),
    // então redirecionar por rota separada vira loop. O teste é a URL crua.
    const cru = req.originalUrl.split('?')[0];
    // `?android` é flag DELES e aqui é a melhor configuração pro iPad, não um
    // disfarce: (1) pula o auto-connect em ws://127.0.0.1:8888, que no iPad nunca
    // existe e reconectaria a cada 3s pra sempre — numa tela que fica horas aberta
    // isso é bateria à toa; (2) liga o tier _perfMobile, que por comentário do
    // próprio autor "não muda o que o carro parece"; (3) só abre mão do GLTFExporter,
    // que é recurso de desktop. O shim é quem entrega os dados no lugar do WS deles.
    // `?hq=1` desliga o modo mobile pra comparar qualidade × fluidez no iPad.
    // ATENÇÃO à direção: `?android` NÃO reduz fps, ele AUMENTA — é o tier de
    // performance. Entre outras coisas ele deixa `preserveDrawingBuffer` falso, e
    // o comentário do autor explica que preservá-lo "derrota o caminho rápido de
    // descarte que GPUs móveis usam" e é "custo puro por quadro" ali. Em hq o
    // desenho ganha alguns detalhes que o autor descreve como invisíveis à
    // distância de visão, e o custo por quadro sobe. Quem julga é o olho no iPad.
    const hq = req.query.hq === '1';
    if (!cru.endsWith('/') || (!hq && req.query.android === undefined)) {
      const q = new URLSearchParams(req.query);
      if (!hq) q.set('android', '1'); else q.delete('android');
      return res.redirect(302, '/3d/?' + q.toString());
    }
    try {
      // `?token=` é opcional e serve pra abrir direto no Safari. No app iOS o
      // token entra por WKUserScript (não passa pela URL, que vaza em log e
      // histórico) — por isso a injeção aqui só acontece se vier e for válido.
      const t = String(req.query.token || '');
      const ok = t && (!BRIDGE_TOKEN_HASH || t === BRIDGE_TOKEN_HASH || sha256hex(t) === BRIDGE_TOKEN_HASH);
      let cfg = ok ? `<script>window.__ECOTRIP_TOKEN__=${JSON.stringify(t)};</script>` : '';
      // `?native=1`: o hospedeiro nativo alimenta o viewer e o shim fica só como
      // receptor. Injetado pelo SERVIDOR e não por WKUserScript porque aqui a ordem
      // é garantida — o shim lê esta global na primeira linha que executa, e
      // qualquer injeção do lado do app corre com o carregamento da página.
      if (req.query.native === '1') cfg += '<script>window.__ECOTRIP_NATIVE__=true;</script>';
      // Sem `?android`, o telemetryClient deles volta a tentar ws://127.0.0.1:8888
      // — endereço do carro, inexistente aqui — e reconecta a cada 3s pra sempre.
      // Neutralizo só ESSE endereço, antes de qualquer script rodar; todo o resto
      // (inclusive o WS do shim) segue normal.
      if (hq) cfg += '<script>(function(){var W=window.WebSocket;window.WebSocket='
        + 'function(u,p){if(String(u).indexOf("127.0.0.1:8888")>=0){return {close:function(){},'
        + 'send:function(){},readyState:3,addEventListener:function(){}};}return new W(u,p);};'
        + 'window.WebSocket.prototype=W.prototype;})();</script>';
      const html = fs.readFileSync(path.join(WEB3D_DIR, 'index.html'), 'utf8')
        .replace('</body>', cfg + '<script src="/ecotrip-3d-shim.js"></script></body>');
      res.type('html').set('Cache-Control', 'no-store').send(html);
    } catch (e) { res.status(500).send('viewer indisponível: ' + e.message); }
  });
  // Assets são ~92MB e imutáveis entre atualizações — cache longo é o que torna
  // a segunda abertura instantânea no iPad.
  // 1 ano + immutable: o conteúdo só muda quando a cópia local muda, e é isso que
  // faz o app do iPad baixar UMA vez e reusar. Sem isso, cada abertura revalidaria
  // 255 arquivos e a tela demoraria a pintar fora de casa.
  app.use('/3d', express.static(WEB3D_DIR, { maxAge: '365d', immutable: true }));
  console.log('✓ Viewer 3D servido em /3d');
}

// ── Autenticação ──────────────────────────────────────────────────────────────
// O cliente envia SHA-256(senha) no header Authorization: Bearer <hash>
// O servidor compara com BRIDGE_TOKEN_HASH armazenado no .env
// Comparação em tempo constante (evita timing oracle no token). Strings de
// tamanhos diferentes → false sem vazar onde diferiu.
function safeStrEqual(a, b) {
  const ba = Buffer.from(String(a)), bb = Buffer.from(String(b));
  if (ba.length !== bb.length) return false;
  try { return require('crypto').timingSafeEqual(ba, bb); } catch (_) { return false; }
}
// Tokens emitidos pelo painel admin (nome + escopo + revogação individual). O
// token legado do .env continua valendo e equivale a escopo admin — trocar tudo
// de uma vez arriscaria derrubar app, cluster, OBD e atalhos juntos.
const { AdminAuth } = require('./admin-auth');
const adminAuth = new AdminAuth(DATA_DIR);

function requireAuth(req, res, next) {
  if (!BRIDGE_TOKEN_HASH) {
    if (ALLOW_NO_AUTH) return next();      // dev local explícito
    return res.status(503).json({ error: 'auth_not_configured' });
  }
  const auth  = req.headers['authorization'] || '';
  const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
  // Aceita SHA-256(senha) [HTTPS] ou texto puro [HTTP — fallback quando crypto.subtle indisponível]
  const valid = safeStrEqual(token, BRIDGE_TOKEN_HASH) || safeStrEqual(sha256hex(token), BRIDGE_TOKEN_HASH);
  if (valid) { req.authScope = 'admin'; req.authSource = 'legacy'; return next(); }
  // Token emitido no painel: além de existir, o escopo tem que permitir o método.
  const issued = adminAuth.match(token);
  if (issued) {
    if (!AdminAuth.scopeAllows(issued.scope, req.method)) {
      return res.status(403).json({ error: 'forbidden_scope', scope: issued.scope, need: req.method });
    }
    req.authScope  = issued.scope;
    req.authSource = 'issued';
    req.authToken  = { id: issued.id, name: issued.name };
    return next();
  }
  return res.status(401).json({ error: 'unauthorized' });
}

// ── Painel admin: senha + TOTP, e emissão de tokens ──────────────────────────
// A área não herda a sessão do monitor: exige senha + código na hora, porque o
// health.html está público em bridge.malha.dev e emitir credencial a partir dele
// concentra risco.
function _adminIp(req) {
  return (req.headers['cf-connecting-ip'] || req.headers['x-forwarded-for'] || req.ip || '')
    .toString().split(',')[0].trim();
}
function requireAdmin(req, res, next) {
  const sid = (req.headers['x-admin-session'] || '').toString().trim();
  const s = adminAuth.validSession(sid);
  if (!s) return res.status(401).json({ error: 'admin_session_invalida' });
  req.adminSession = s;
  next();
}

app.get('/api/admin/state', (req, res) => {
  const sid = (req.headers['x-admin-session'] || '').toString().trim();
  res.json({
    configured: adminAuth.configured,
    totpPending: !!adminAuth.state.totpPending,
    session: !!adminAuth.validSession(sid),
    scopes: AdminAuth.SCOPES,
  });
});

// Primeiro acesso: define a senha. Só permitido enquanto NÃO há senha — depois
// disso a troca exige sessão válida (rota abaixo), senão qualquer um na
// internet redefiniria o admin.
app.post('/api/admin/setup-password', (req, res) => {
  if (adminAuth.state.password) return res.status(409).json({ error: 'ja_configurada' });
  const r = adminAuth.setPassword(req.body?.password);
  res.status(r.ok ? 200 : 400).json(r);
});

app.post('/api/admin/change-password', requireAdmin, (req, res) => {
  if (!adminAuth.verifyPassword(req.body?.current)) return res.status(401).json({ error: 'senha_atual_invalida' });
  const r = adminAuth.setPassword(req.body?.password);
  res.status(r.ok ? 200 : 400).json(r);
});

// TOTP: begin devolve o segredo/QR; confirm só liga o 2FA depois de um código
// bater. Enquanto não há senha, nem começa.
app.post('/api/admin/totp/begin', (req, res) => {
  if (!adminAuth.state.password) return res.status(409).json({ error: 'defina_a_senha_primeiro' });
  // Se já existe TOTP ativo, exigir sessão pra regerar (evita reset remoto).
  if (adminAuth.state.totp) {
    const s = adminAuth.validSession((req.headers['x-admin-session'] || '').toString().trim());
    if (!s) return res.status(401).json({ error: 'admin_session_invalida' });
  } else if (!adminAuth.verifyPassword(req.body?.password)) {
    return res.status(401).json({ error: 'senha_invalida' });
  }
  res.json(adminAuth.beginTotpSetup('malha.dev'));
});

// QR do setup em andamento. Monta do segredo PENDENTE guardado no servidor —
// receber o URI por query o colocaria em log de acesso e no histórico do proxy,
// e o URI carrega o segredo inteiro. Só serve enquanto há setup em curso.
app.get('/api/admin/totp/qr', async (_req, res) => {
  const p = adminAuth.state.totpPending;
  if (!p) return res.status(404).json({ error: 'sem_setup_pendente' });
  try {
    const { authenticator } = require('otplib');
    const uri = authenticator.keyuri('admin', 'Bridge malha.dev', p.secret);
    const png = await require('qrcode').toBuffer(uri, { width: 360, margin: 1 });
    res.set('Cache-Control', 'no-store').type('png').send(png);
  } catch (e) {
    res.status(500).json({ error: 'qr_falhou', detail: String(e.message).slice(0, 80) });
  }
});

app.post('/api/admin/totp/confirm', (req, res) => {
  const r = adminAuth.confirmTotpSetup(req.body?.code);
  res.status(r.ok ? 200 : 400).json(r);
});

app.post('/api/admin/login', (req, res) => {
  const ip = _adminIp(req);
  if (adminAuth.blocked(ip)) return res.status(429).json({ error: 'muitas_tentativas' });
  if (!adminAuth.configured) return res.status(409).json({ error: 'admin_nao_configurado' });
  const okPw = adminAuth.verifyPassword(req.body?.password);
  const okTt = adminAuth.verifyTotp(req.body?.code);
  if (!okPw || !okTt) {
    adminAuth.noteFail(ip);
    // Resposta única pra não revelar qual dos dois falhou.
    return res.status(401).json({ error: 'credenciais_invalidas' });
  }
  // Só agora o código é gasto: consumir antes faria uma senha errada queimar o
  // TOTP do dono e viraria vetor de negação de acesso.
  adminAuth.consumeTotp(req.body?.code);
  adminAuth.clearFails(ip);
  const s = adminAuth.createSession(ip);
  console.log(`[admin] login OK ip=${ip || '?'} — sessão até ${new Date(s.expiresMs).toLocaleTimeString('pt-BR')}`);
  res.json({ ok: true, session: s.sid, expiresMs: s.expiresMs });
});

app.post('/api/admin/logout', requireAdmin, (req, res) => {
  adminAuth.dropSession((req.headers['x-admin-session'] || '').toString().trim());
  res.json({ ok: true });
});

app.get('/api/admin/tokens', requireAdmin, (_req, res) => res.json({ tokens: adminAuth.list() }));

app.post('/api/admin/tokens', requireAdmin, (req, res) => {
  const r = adminAuth.issueToken({ name: req.body?.name, scope: req.body?.scope });
  if (!r.ok) return res.status(400).json(r);
  console.log(`[admin] token emitido "${r.record.name}" escopo=${r.record.scope} id=${r.record.id}`);
  res.json(r);   // `token` em claro só nesta resposta
});

app.post('/api/admin/tokens/:id/revoke', requireAdmin, (req, res) => {
  const r = adminAuth.revokeToken(req.params.id);
  if (r.ok) console.log(`[admin] token revogado id=${req.params.id}`);
  res.status(r.ok ? 200 : 404).json(r);
});

app.delete('/api/admin/tokens/:id', requireAdmin, (req, res) => {
  const r = adminAuth.deleteToken(req.params.id);
  res.status(r.ok ? 200 : 404).json(r);
});
// Ping público — sem auth, útil para verificar se o servidor está online
app.get('/ping', (_req, res) => res.json({ ok: true, ts: Date.now() }));

// Status do broker MQTT — público (só booleano, sem segredos). Monitor externo
// (HA do Sítio) checa via 443/Funnel; a 8883 não é funnelada e exige peering.
app.get('/api/mqtt-status', (_req, res) =>
  res.json({ ok: !!(mqttClient && mqttClient.connected), ts: Date.now() }));

// Status agregado da infra local — público (só booleanos, sem IP/path/erro).
// HA do Sítio consome isso pra decidir os pushes (guard 3+ juntos = 1 alerta),
// substituindo os alertas que o bridge disparava sozinho pra essas mesmas checagens.
app.get('/api/infra-status', (_req, res) => res.json({
  // Precisa do mesmo debounce (fail_count >= 2) que local_ha_ok/gateway_ok já tinham —
  // sem isso, 1 timeout isolado de probe (broker ocupado por 1 ciclo) já reportava
  // down pro HA do Sítio. Causa raiz real (achada via alert_diag.log pós-fix,
  // 2026-07-01): não é lag/boot-race do bridge — é um cliente MQTT.js em
  // 192.168.1.30 (user rafael_haval, provável Node-RED com reconnect quebrado)
  // fazendo connect/disconnect em rajada só na porta 1884, a cada ~3min, por
  // 5-65s cada vez. O debounce filtra essas rajadas (nunca passam de ~65s =
  // 13 ciclos de 5s); só alertaria de verdade se a porta ficasse presa >150s
  // contínuos, que é o threshold real do guard "Mosquitto Local" no HA (2min30).
  // Corrigir na raiz = achar e consertar o reconnect loop no lado do HA VM.
  mosquitto_ok: !(_mqttBrokerStatus.checked_at > 0 &&
    (!_mqttBrokerStatus.port1883 || !_mqttBrokerStatus.port1884 || !_mqttBrokerStatus.port8883) &&
    _mqttBrokerStatus.fail_count >= 2),
  local_ha_ok: _haStatus.up !== false,
  gateway_ok: _gwStatus.up !== false,
  ssd_ok: !_macStats.disk_ext || _macStats.disk_ext.mounted !== false,
  dns_ok: _netStatus.match !== false,
  // backup_ok: TODOS os 5 backups (Lari, Haval, SSD, MQTT, Clockin) dentro da
  // idade máxima esperada. Automação do HA do Sítio pode usar ISSO em vez de
  // heurística temporal ("se hora=04 e não vi backup") que dá falso positivo.
  backup_ok: !_backups.length || _backups.every(b => b.ok !== false),
  ts: Date.now(),
}));

// GET /api/departure-configs — retorna as configs de Saídas monitoradas
// parseadas dos _group das automation_rules. Consumido pelo iOS pra saber quando
// mostrar a LA "Indo pra <dest>?" ao ligar o carro em uma origem monitorada.
app.get('/api/departure-configs', (_req, res) => {
  const byGroup = {};
  for (const r of (automationRules || [])) {
    const g = r._group || '';
    if (!g.startsWith('departure_share:')) continue;
    (byGroup[g] = byGroup[g] || []).push(r);
  }
  const out = Object.entries(byGroup).map(([g, rules]) => {
    const exit = rules.find(r => (r.trigger || {}).edge === 'exit');
    const enter = rules.find(r => (r.trigger || {}).edge === 'enter');
    if (!exit) return null;
    const cond = (((exit.conditions || {}).items) || []).find(i => i.type === 'time') || {};
    const a = exit.action || {};
    return {
      config_id: g.replace('departure_share:', ''),
      enabled: exit.enabled !== false,
      subject: a.subject || 'Rafael',
      source: { lat: exit.trigger.lat, lng: exit.trigger.lng, radius_m: exit.trigger.radius_m, name: (a.from || {}).name || 'Origem' },
      dest:   { lat: (a.to || {}).lat, lng: (a.to || {}).lng, radius_m: (enter && enter.trigger && enter.trigger.radius_m) || 50, name: (a.to || {}).name || 'Destino' },
      days: cond.days || [],
      from_hhmm: cond.from_hhmm ?? 0,
      until_hhmm: cond.to_hhmm ?? 1439,
    };
  }).filter(Boolean);
  res.json(out);
});

// ── Sugestão de destino a partir do próximo compromisso ────────────────────
// A agenda não vive aqui: a Mari cria planos de pré-clima com `eventStartMs` +
// `destName`/`destLat` a partir do calendário, e é por esses planos que o compromisso
// chega ao bridge. Uso a mesma fonte em vez de inventar um segundo canal de agenda.
const SUGESTAO_JANELA_MS = 3 * 3600_000;   // compromisso nas próximas 3h

/** Próximo compromisso COM destino dentro da janela, ou null. */
function _proximoCompromisso() {
  const agora = Date.now();
  const cands = (preclimat.schedules || []).filter(x =>
    x && x.enabled !== false
    && +x.eventStartMs > agora
    && +x.eventStartMs - agora < SUGESTAO_JANELA_MS
    && ((x.destName && String(x.destName).trim()) || +x.destLat || +x.destLng));
  if (!cands.length) return null;
  cands.sort((a, b) => (+a.eventStartMs) - (+b.eventStartMs));
  const c = cands[0];
  return {
    id: c.id, nome: String(c.destName || '').trim(),
    lat: +c.destLat || 0, lng: +c.destLng || 0,
    eventStartMs: +c.eventStartMs,
    label: String(c.label || '').trim(),
  };
}

/** Publica a sugestão pro carro. `retain:false`: é convite pontual, não estado —
 *  retido reapareceria a cada reconexão do APK e viraria popup fantasma. */
function _sugereDestinoNoCarro(motivo) {
  const c = _proximoCompromisso();
  if (!c) { console.log(`[sugestao] ${motivo}: nenhum compromisso com destino na janela`); return false; }
  // Já tem rota? Não atropela decisão do dono.
  if (state.route && Array.isArray(state.route.wps) && state.route.wps.length) {
    console.log(`[sugestao] ${motivo}: rota já definida (${state.route.wps[0].name}) — não sugere`);
    return false;
  }
  const jaSugerido = _sugestaoFeita[c.id];
  if (jaSugerido && Date.now() - jaSugerido < 2 * 3600_000) {
    console.log(`[sugestao] ${motivo}: já sugerido há ${Math.round((Date.now() - jaSugerido) / 60000)}min — pula`);
    return false;
  }
  _sugestaoFeita[c.id] = Date.now();
  const hhmm = new Date(c.eventStartMs).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  mqttClient.publish(`${MQTT_PREFIX}/cmd/sugestao_destino`, JSON.stringify({
    id: c.id, nome: c.nome, lat: c.lat, lng: c.lng, hhmm,
    label: c.label, eventStartMs: c.eventStartMs, ts: Date.now(),
  }), { qos: 1, retain: false });
  console.log(`[sugestao] ${motivo}: sugerido "${c.nome}" às ${hhmm} (id=${c.id})`);
  return true;
}
let _sugestaoFeita = {};

// POST /api/destino-sugerido/accept  { id }
// O dono tocou "Sim" no popup do carro. Mesma orquestração do departure/accept:
// grava a rota, publica o nav_dest retido e ESPELHA NO WAZE — que é o "o Waze puxa
// automaticamente" que o dono pediu.
app.post('/api/destino-sugerido/accept', (req, res) => {
  const id = String((req.body || {}).id || '');
  const c = _proximoCompromisso();
  if (!c || (id && c.id !== id)) return res.status(404).json({ error: 'sugestão não encontrada ou expirada' });
  if (!(c.lat && c.lng)) return res.status(422).json({ error: 'compromisso sem coordenada' });
  try {
    const nome = c.nome || 'Compromisso';
    mqttClient.publish(`${MQTT_PREFIX}/cmd/nav_dest`,
      JSON.stringify({ lat: c.lat, lng: c.lng, name: nome }), { qos: 1, retain: true });
    // state.route JUNTO do tópico: sem isso o `_maybeComputeArrival` vê retained sem
    // rota em memória, conclui "rota órfã" e apaga o destino em segundos — foi o que
    // aconteceu no caminho da Live Activity em 04/08.
    state.route = { wps: [{ lat: c.lat, lng: c.lng, name: nome, isFinal: true }],
                    completedIdx: -1, undo: null, ts: Date.now() };
    _navDestRetained = true;
    scheduleStateSave();
    _espelhaDestinoNoWaze(c.lat, c.lng, nome);
    recentNavDests.push({ name: nome, lat: c.lat, lng: c.lng, ts: Date.now() });
    _registraRecente(nome, c.lat, c.lng);
    if (recentNavDests.length > 30) recentNavDests.shift();
    _saveNavDestsSoon();
    console.log(`[sugestao] ACEITA: "${nome}" (${c.lat},${c.lng}) — rota gravada e espelhada no Waze`);
    res.json({ ok: true, nome, lat: c.lat, lng: c.lng });
  } catch (e) {
    console.warn('[sugestao] accept falhou:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// POST /api/destino-sugerido/enviar — força a sugestão agora (teste e botão do app).
app.post('/api/destino-sugerido/enviar', (req, res) => {
  // `forcar` ignora o anti-repetição de 2h, pra testar sem esperar.
  if ((req.body || {}).forcar) _sugestaoFeita = {};
  const ok = _sugereDestinoNoCarro('manual');
  res.json({ ok, proximo: _proximoCompromisso() });
});

// GET /api/destino-sugerido — o que seria sugerido agora (diagnóstico e uso do app).
app.get('/api/destino-sugerido', (_req, res) => res.json({ proximo: _proximoCompromisso() }));

// POST /api/departure/accept  { config_id }
// O usuário tocou "Sim" na LA "Indo pra <dest>?" — orquestra: seta nav_dest no
// carro (MQTT retido) + cria share role=grasi + inicia SharedTripLA no iPhone
// da Grasi. iOS termina a LA de decisão localmente.
app.post('/api/departure/accept', async (req, res) => {
  const cfgId = (req.body || {}).config_id;
  if (!cfgId) return res.status(400).json({ error: 'config_id obrigatório' });
  const rule = (automationRules || []).find(r => (r._group || '') === `departure_share:${cfgId}` && (r.trigger || {}).edge === 'exit');
  if (!rule) return res.status(404).json({ error: 'config não encontrada' });
  const a = rule.action || {};
  const to = a.to || {};
  const destName = to.name || 'Casa';
  // 1. nav_dest pro carro (retido — se estiver acordado, painel abre a Chegada)
  try {
    const payload = JSON.stringify({ lat: to.lat, lng: to.lng, name: destName });
    mqttClient.publish(`${MQTT_PREFIX}/cmd/nav_dest`, payload, { qos: 1, retain: true });
    // state.route JUNTO, não só o tópico. `_maybeComputeArrival` roda em tick e, se
    // encontra retained no broker sem rota em memória, conclui "rota órfã" e limpa —
    // apagando o destino que o dono acabou de aceitar. Em 04/08 durou 13s: publicado
    // 17:18:19, limpo 17:18:32, e só funcionou quando ele repetiu pelo botão
    // flutuante (aquele caminho já setava a rota). O comentário no handler de nav_to
    // avisa exatamente disso; este caminho, o da Live Activity, ficou de fora.
    state.route = { wps: [{ lat: to.lat, lng: to.lng, name: destName, isFinal: true }],
                    completedIdx: -1, undo: null, ts: Date.now() };
    _navDestRetained = true;
    scheduleStateSave();
    _espelhaDestinoNoWaze(to.lat, to.lng, destName);
    recentNavDests.push({ name: destName, lat: to.lat, lng: to.lng, ts: Date.now() });
    _registraRecente(destName, to.lat, to.lng);
    if (recentNavDests.length > 30) recentNavDests.shift();
    _saveNavDestsSoon();
  } catch (e) { console.warn('[departure/accept] nav_dest falhou:', e.message); }
  // 2. share pra Grasi
  let share = null;
  try {
    share = _createShareToken(180, { recipientName: 'Grasi', recipientRole: 'grasi', destName });
  } catch (e) { console.warn('[departure/accept] share falhou:', e.message); }
  // 3. LA na Grasi
  if (share && apnsLive.enabled) {
    _startSharedTripLA(share.token, a.subject || 'Rafael').catch(() => {});
  }
  res.json({ ok: true, share_token: share ? share.token : null, dest: destName });
});

// POST /api/departure/dismiss  { config_id }   — "não hoje".
//
// A marca do dia já foi gravada em _evalDepartureAsk ANTES do push, então não
// perguntar mais hoje é o padrão e aqui só registramos. Fica explícito no log
// pra diferenciar de "ignorou a LA", que tem o mesmo efeito prático.
app.post('/api/departure/dismiss', (req, res) => {
  console.log(`[departure] dismiss (não hoje) config=${(req.body || {}).config_id}`);
  res.json({ ok: true, until: 'proxima_janela' });
});

// POST /api/departure/snooze  { config_id }  — "me lembra na próxima partida".
//
// Caso de uso: ligar o carro só pra manobrar no pátio da empresa. Não é uma
// saída, mas a pergunta já apareceu — e como a marca do dia foi gravada antes do
// push, sem isto a pergunta não voltaria hoje e a saída de verdade passaria
// batida.
//
// Apagar a marca faz _evalDepartureAsk perguntar de novo no PRÓXIMO engine on
// (é ele o gatilho, nos dois caminhos: GWM e APK), desde que ainda esteja na
// janela de horário e no raio da origem.
app.post('/api/departure/snooze', (req, res) => {
  const cfgId = (req.body || {}).config_id;
  if (!cfgId) return res.status(400).json({ error: 'config_id obrigatório' });
  const now = new Date();
  const today = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  const key = `${cfgId}_${today}`;
  const havia = !!_departureAsked[key];
  delete _departureAsked[key];
  _saveDepartureAsked();
  console.log(`[departure] snooze config=${cfgId} — pergunta de novo na próxima partida (marca ${havia ? 'removida' : 'não existia'})`);
  res.json({ ok: true, until: 'proxima_partida' });
});

// GET /api/bluetti-status — estado das duas EL100V2 (Casa + Sítio). Fonte
// PRIMÁRIA: integração própria com a nuvem Bluetti (bluetti-cloud.js, sem HA no
// caminho). O HA fica como fallback automático enquanto a nuvem não tem token/
// bootstrap — assim a troca não abre janela cega. `source` no payload diz de onde
// o dado veio. Consumido pelo health.html do monitor externo.
// BLUETTI_SOURCE=cloud|ha|auto (default auto = cloud com fallback pro HA).
const _BLUETTI = {
  casa:  { id: 'el100v22541111662131', sn: 'EL100V22541111662131', label: 'Casa',  feeds: 'Mac Mini + Roteador' },
  sitio: { id: 'el100v22541111602913', sn: 'EL100V22541111602913', label: 'Sítio', feeds: 'Starlink' },
};
const _BLUETTI_SOURCE = (process.env.BLUETTI_SOURCE || 'auto').toLowerCase();
let _bluettiCache = { data: null, ts: 0 };

// SN por estação: .env manda (BLUETTI_SN_CASA/BLUETTI_SN_SITIO), senão o default
// derivado das entity ids que o HA já usava (model+SN).
function _bluettiSn(key) {
  return (process.env[`BLUETTI_SN_${key.toUpperCase()}`] || _BLUETTI[key].sn).toUpperCase();
}

// Monta o payload normalizado a partir do snapshot da nuvem. Mesmo shape do HA
// (battery_pct/ac_out_w/.../reachable) — o watchdog e o health.html não mudam.
const BLUETTI_STALE_MS = 5 * 60_000;   // sem poll bem-sucedido há 5min = dado velho
function _bluettiFromCloud() {
  const snap = bluettiCloud.snapshot();
  if (!snap.ready) return null;
  // Dado velho não vale como verdade: em `auto` cai pro HA, em `cloud` o alerta
  // bluetti_cloud_stale acende. Sem isso o watchdog julgaria estado congelado.
  if (!snap.ts || Date.now() - snap.ts > BLUETTI_STALE_MS) return null;
  const out = { ts: Date.now(), source: 'cloud', ws: snap.ws, needs_reauth: snap.needs_reauth };
  let hit = 0;
  for (const key of ['casa', 'sitio']) {
    const d = snap.devices[_bluettiSn(key)];
    if (d) hit++;
    out[key] = {
      ..._BLUETTI[key],
      battery_pct:      d?.battery_pct ?? null,
      ac_out_w:         d?.ac_out_w ?? null,
      dc_out_w:         d?.dc_out_w ?? null,
      grid_in_w:        d?.grid_in_w ?? null,
      pv_in_w:          d?.pv_in_w ?? null,
      battery_time_min: d?.battery_time_min ?? null,
      full_charge_min:  d?.full_charge_min ?? null,
      ac_on:            d?.ac_on ?? null,
      ac_eco_on:        d?.ac_eco_on ?? null,
      dc_on:            d?.dc_on ?? null,
      dc_eco_on:        d?.dc_eco_on ?? null,
      working_mode:     d?.working_mode ?? null,
      inv_state:        d?.inv_state ?? null,
      reachable:        !!d?.reachable,
      // stale_zeros: nuvem diz online mas mandou tudo zerado = estação sem
      // comunicação de verdade (vira unreachable, não apagão).
      stale_zeros:      !!d?.stale_zeros,
      cloud_name:       d?.name ?? null,
    };
  }
  // Nenhum dos 2 SNs bateu → SN errado no .env. Não devolve "tudo offline" (isso
  // dispararia unreachable falso); deixa o HA responder e loga o que a nuvem viu.
  if (!hit) {
    console.warn('[bluetti] SNs não bateram com a nuvem. Cloud tem:', Object.keys(snap.devices).join(', '));
    return null;
  }
  return out;
}

async function _fetchBluettiStatusHA() {
  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return null;
  try {
    const r = await fetch(`${url}/api/states`, {
      headers: { Authorization: `Bearer ${tok}` },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return null;
    const arr = await r.json();
    const parse = (id) => {
      const num = (suffix) => {
        const s = arr.find(x => x.entity_id === `sensor.${id}_${suffix}`);
        if (!s || s.state === 'unknown' || s.state === 'unavailable') return null;
        const n = +s.state; return Number.isFinite(n) ? n : null;
      };
      const bool = (suffix) => {
        const s = arr.find(x => x.entity_id === `switch.${id}_${suffix}`);
        if (!s) return null;
        if (s.state === 'unknown' || s.state === 'unavailable') return null;
        return s.state === 'on';
      };
      const str = (domain, suffix) => {
        const s = arr.find(x => x.entity_id === `${domain}.${id}_${suffix}`);
        return s && s.state !== 'unknown' && s.state !== 'unavailable' ? s.state : null;
      };
      const batt   = num('battery_level');
      const gridIn = num('grid_input_power');
      const acOn   = bool('ac');
      const acOut  = num('alternating_current_out_power');
      const dcOut  = num('direct_current_out_power');
      const pv     = num('photovoltaics_input_power');
      // Reachable = pelo menos um campo veio; se todos null, HA/dispositivo offline
      const reachable = [batt, gridIn, acOut, dcOut, pv].some(v => v != null);
      return {
        battery_pct:      batt,
        ac_out_w:         acOut,
        dc_out_w:         dcOut,
        grid_in_w:        gridIn,
        pv_in_w:          pv,
        battery_time_min: num('battery_time_in_minutes'),
        full_charge_min:  num('full_charge_time_in_minutes'),
        ac_on:            acOn,
        ac_eco_on:        bool('ac_eco'),
        dc_on:            bool('dc'),
        dc_eco_on:        bool('dc_eco'),
        working_mode:     str('select', 'working_mode'),
        reachable,
      };
    };
    return {
      casa:  { ..._BLUETTI.casa,  ...parse(_BLUETTI.casa.id) },
      sitio: { ..._BLUETTI.sitio, ...parse(_BLUETTI.sitio.id) },
      ts: Date.now(),
      source: 'ha',
    };
  } catch (e) { return null; }
}

// Fonte efetiva: cloud primeiro (é o dado sem intermediário), HA como rede de
// segurança. Com BLUETTI_SOURCE=cloud não cai pro HA nunca (útil pra validar que
// a integração própria está de pé sozinha); com =ha volta ao comportamento antigo.
async function _fetchBluettiStatus() {
  if (_BLUETTI_SOURCE !== 'ha') {
    const c = _bluettiFromCloud();
    if (c) return c;
    if (_BLUETTI_SOURCE === 'cloud') return null;
  }
  return _fetchBluettiStatusHA();
}
// Poll servidor-side a cada 30s: 1 fetch pra alimentar UI + watchdog. Endpoint
// e alertas ambos leem `_bluettiState` mais recente sem hammer no HA.
let _bluettiState = null;
async function _bluettiTick() {
  const d = await _fetchBluettiStatus();
  if (d) { _marcaBuracoDePotencia(d); _bluettiState = d; _bluettiCache = { data: d, ts: Date.now() }; }
  _evalBluettiAlerts();
}
setInterval(() => { _bluettiTick().catch(() => {}); }, 30_000);
setTimeout(() => { _bluettiTick().catch(() => {}); }, 5_000);

// ── Integração própria com a nuvem Bluetti (substitui o caminho via HA) ───────
// start() cuida sozinho de: bootstrap (devices + bind), poll de fundo, WS STOMP
// de push e refresh do OAuth. onUpdate = push chegou → reavalia alerta na hora,
// sem esperar o tick de 30s. Throttle de 3s pra rajada de push não virar loop.
let _bluettiPushAt = 0;
bluettiCloud.start({
  dataDir: DATA_DIR,
  log: (...a) => console.log('[bluetti-cloud]', ...a),
  onUpdate: () => {
    const now = Date.now();
    if (now - _bluettiPushAt < 3000) return;
    _bluettiPushAt = now;
    _bluettiTick().catch(() => {});
  },
});

// ── Watchdog: interpreta o estado das estações e dispara alertas via _alert() ─
// Cada estação tem 4 alertas escopados: ac_off (dispositivos apagados agora),
// offgrid (rodando bateria — pré-alarme), battery_low (≤30% sem grid), battery_critical
// (≤10% sem grid). unreachable = HA/Bluetti offline. Histerese via debounce/recovery
// do próprio _alert(). Rotula "🏠 Casa" e "🌱 Sítio" pra ntfy ficar autoexplicativo.
// Histórico curto de battery_pct por estação pra confirmar offgrid real (evita
// falso positivo se grid_in_w oscilar em 0 momentaneamente sem ser queda de rede).
// Só considero "offgrid confirmado" se grid=0 E (bateria caiu ≥1% em ≥3 leituras
// OU bateria ≤ 99% mesmo — a passthrough real em UPS+bateria cheia mantém 100%).
const _bluettiHist = { casa: [], sitio: [] };   // últimos N battery_pct
function _pushBluettiHist(key, pct) {
  if (pct == null) return;
  const arr = _bluettiHist[key]; arr.push(pct);
  if (arr.length > 6) arr.shift();
}
// A Casa para de reportar POTÊNCIA por minutos e volta (visto em 16/09/2026:
// 0 W por 3 min, depois 49 W — o consumo real do Mac Mini + roteador). O
// `stale_zeros` do módulo não pega isso porque exige TUDO zerado, e a bateria
// segue mandando 100%: sinal de vida existe, medição é que sumiu.
//
// Zero é uma afirmação ("não está consumindo nada"); buraco de telemetria não é.
// Aqui a diferença fica registrada: guarda a última leitura não-zero e há quanto
// tempo. Quem desenha decide mostrar o último valor com idade em vez de 0.
const _bluettiUltPot = {};    // key -> { grid_in_w, ac_out_w, dc_out_w, pv_in_w, ts }
function _marcaBuracoDePotencia(d) {
  for (const key of ['casa', 'sitio']) {
    const b = d[key];
    if (!b) continue;
    const campos = ['grid_in_w', 'ac_out_w', 'dc_out_w', 'pv_in_w'];
    const algum = campos.some(k => (b[k] ?? 0) > 0);
    if (algum) {
      _bluettiUltPot[key] = { ts: Date.now() };
      for (const k of campos) _bluettiUltPot[key][k] = b[k];
      b.power_stale_ms = 0;
    } else {
      const u = _bluettiUltPot[key];
      b.power_stale_ms = u ? Date.now() - u.ts : null;
      b.ultima_potencia = u || null;
    }
  }
}

function _bluettiOffgridConfirmed(key, gridW, batt) {
  if (gridW !== 0) return false;
  const arr = _bluettiHist[key];
  if (arr.length < 3) return false;                   // insuficiente pra decidir
  // Caiu ≥1% nas últimas 3 leituras?
  const dropping = arr[arr.length - 1] < arr[arr.length - 3];
  // Ou está abaixo de 100 E mantém grid=0 há ≥3 ticks (não está passthrough)
  const belowFull = batt != null && batt < 100;
  return dropping || belowFull;
}

function _evalBluettiAlerts() {
  // OAuth da nuvem morreu (refresh_token recusado) → só login manual religa. Fora
  // do guard abaixo de propósito: precisa gritar mesmo sem nenhum estado ainda.
  // O grant da Bluetti morre 31 dias depois do login manual: o refresh renova o
  // access_token DENTRO da janela mas não move o vencimento (o servidor devolve o
  // tempo restante, não 31 dias novos). Então o login mensal é inevitável — o que
  // dá pra fazer é avisar com folga e num toque. Um alerta só, com dois gatilhos:
  // refresh quebrado OU janela acabando; repete 1x/dia até religar.
  const _bDays = bluettiCloud.status().token_expires_in_days;
  _alert('bluetti_cloud_reauth',
    bluettiCloud.hasToken() && ((bluettiCloud.needsReauth() && _bDays != null && _bDays < 7) || (_bDays != null && _bDays < 7)),
    'Bluetti: refazer login',
    `O acesso à nuvem Bluetti vence em ${_bDays} dia(s)` +
    `${bluettiCloud.needsReauth() ? ' e o refresh automático está falhando' : ''}. ` +
    `Toque pra religar: ${_bluettiReauthLink()}`,
    'high', ['key', 'warning'], { repeatEvery: 86400_000 });
  // Integração própria parada (token ok, mas sem poll há >5min: internet, nuvem
  // Bluetti fora ou WS/poll travado). Em modo `ha` não interessa.
  const cs = bluettiCloud.status();
  _alert('bluetti_cloud_stale',
    _BLUETTI_SOURCE !== 'ha' && cs.has_token && !cs.needs_reauth &&
      cs.last_poll_age_s != null && cs.last_poll_age_s > 300,
    'Bluetti: integração sem dados',
    `A nuvem Bluetti não responde há ${cs.last_poll_age_s}s (ws=${cs.ws_connected ? 'on' : 'off'}). ` +
    `Último erro: ${cs.last_error || '—'}.`,
    'high', ['warning', 'cloud']);
  if (!_bluettiState) return;
  for (const key of ['casa', 'sitio']) {
    const s = _bluettiState[key]; if (!s) continue;
    _pushBluettiHist(key, s.battery_pct);
    const emoji = key === 'casa' ? '🏠 Casa' : '🌱 Sítio';
    const feeds = s.feeds || (key === 'casa' ? 'Mac Mini + Roteador' : 'Starlink');
    const unreachable = !s.reachable;
    // A nuvem Bluetti fala por WebSocket STOMP; quedinha de socket é comum e
    // reconecta sozinha. Sustentação evita o push por reconexão de 1 ciclo.
    const unreachKey = `bluetti_${key}_unreachable`;
    const unreachSustained = _sustained(unreachKey, true, unreachable, BLUETTI_SUSTAIN_MS);
    // 1. Unreachable — Bluetti/HA sem comunicação. Silencia demais alertas.
    _alert(unreachKey, unreachSustained,
      `Bluetti ${emoji} sem comunicação`,
      `Sem dados do EL100V2 (HA/BLE offline). Ver conexão da estação.`,
      'high', ['battery.0', 'signal_strength']);
    if (unreachable) {
      // Suprime os outros pra não gritar múltiplas vezes por causa da mesma causa
      _alert(`bluetti_${key}_ac_off`, false, '', '', 'default', []);
      _alert(`bluetti_${key}_offgrid`, false, '', '', 'default', []);
      _alert(`bluetti_${key}_battery_low`, false, '', '', 'default', []);
      _alert(`bluetti_${key}_battery_critical`, false, '', '', 'default', []);
      continue;
    }
    const grid = s.grid_in_w ?? 0;
    const batt = s.battery_pct ?? 100;
    const acOff = s.ac_on === false;
    // "Offgrid CONFIRMADO" = grid=0 E (bateria caindo em histórico ≥3 leituras
    // OU battery<100). Isso elimina falso positivo de flap momentâneo de grid=0
    // com bateria cheia em passthrough perfeito.
    const offgrid = _bluettiOffgridConfirmed(key, grid, batt);
    // Grava no estado: `/api/bluetti-status`, `/api/wall` e a página de health
    // têm que ler o MESMO veredito. Cada um recalculando é como divergem.
    s.offgrid = (_bluettiHist[key]?.length || 0) < 3 ? null : offgrid;
    // 2. AC desligado — dispositivos ligados apagaram agora. Urgentíssimo.
    _alert(`bluetti_${key}_ac_off`, acOff,
      `${emoji} — AC DESLIGADO`,
      `Saída AC off. ${feeds} sem energia AGORA. Religa a saída AC na estação.`,
      'urgent', ['warning', 'electric_plug']);
    // 3. Bateria crítica (offgrid confirmado + ≤10%): apagão iminente
    _alert(`bluetti_${key}_battery_critical`, offgrid && batt <= 10 && !acOff,
      `${emoji} — bateria CRÍTICA ${batt}%`,
      `Sem rede e bateria ≤10%. ${feeds} vão apagar em minutos. Autonomia: ${_fmtMin(s.battery_time_min)}.`,
      'urgent', ['warning', 'battery.0']);
    // 4. Bateria baixa (offgrid confirmado + ≤30%): pré-alarme
    _alert(`bluetti_${key}_battery_low`, offgrid && batt > 10 && batt <= 30 && !acOff,
      `${emoji} — bateria baixa ${batt}%`,
      `Sem rede e bateria ≤30%. Autonomia estimada: ${_fmtMin(s.battery_time_min)}.`,
      'high', ['battery.25']);
    // 5. Offgrid confirmado (rodando na bateria, ainda tem folga): observação
    _alert(`bluetti_${key}_offgrid`, offgrid && batt > 30 && !acOff,
      `${emoji} — sem energia da rede`,
      `Rodando na bateria (${batt}%, autonomia ${_fmtMin(s.battery_time_min)}). ${feeds}.`,
      'default', ['battery.75', 'electric_plug']);
  }
}
function _fmtMin(m) {
  if (m == null) return 'desconhecida';
  const h = Math.floor(m / 60), r = m % 60;
  return h > 0 ? `${h}h${String(r).padStart(2, '0')}min` : `${m}min`;
}
app.get('/api/bluetti-status', async (req, res) => {
  const now = Date.now();
  if (!_bluettiCache.data || (now - _bluettiCache.ts) > 30_000) {
    const d = await _fetchBluettiStatus();
    if (d) _bluettiCache = { data: d, ts: now };
  }
  if (!_bluettiCache.data) return res.status(502).json({ error: 'bluetti indisponível' });
  // Bloco de auth pro banner do health: dias restantes e se precisa religar. O LINK
  // só vai pra quem apresenta o token do bridge — esta rota é registrada antes do
  // gate global de /api, então responde sem auth, e link de login vazando daria
  // pra um estranho plugar a NOSSA instância na conta Bluetti dele.
  const cs = bluettiCloud.status();
  const days = cs.token_expires_in_days;
  const auth = {
    has_token: cs.has_token,
    expires_at: cs.token_expires_at,
    expires_in_days: days,
    needs_reauth: cs.needs_reauth,
    // 7 dias é onde o alerta acende: o refresh renova o access_token mas NÃO move
    // o vencimento do grant (a nuvem devolve o tempo restante), então o login
    // manual mensal é obrigatório.
    needs_login: !cs.has_token || (days != null && days < 7),
  };
  if (_bridgeTokenOk(req)) auth.reauth_url = _bluettiReauthLink();
  // Quem decide "está na bateria" é aqui, com a MESMA regra dos alertas
  // (_bluettiOffgridConfirmed). grid_in_w=0 sozinho não prova descarga: em
  // passthrough com a bateria cheia a estação reporta 0 em todos os medidores, e
  // a página — que tinha regra própria — lia isso como "na bateria" com a rede
  // ligada e a Casa em 100% (13/09). null = histórico ainda curto pra afirmar.
  const out = { ..._bluettiCache.data, auth };
  for (const key of ['casa', 'sitio']) {
    const s = out[key];
    if (!s || !s.reachable) continue;
    out[key] = { ...s, offgrid: (_bluettiHist[key]?.length || 0) < 3
      ? null
      : _bluettiOffgridConfirmed(key, s.grid_in_w ?? 0, s.battery_pct) };
  }
  res.json(out);
});

// ── OAuth da nuvem Bluetti ───────────────────────────────────────────────────
// Fluxo authorization_code padrão. /start só é alcançável com ADMIN_TOKEN na
// query (é navegação de browser, não dá pra usar o header x-admin-session), e o
// callback é protegido pelo `state` de uso único com validade de 10min.
const _bluettiStates = new Map();   // state → expiresMs
// Link de reautorização: o alerta vai pro ntfy/celular, então NÃO pode carregar o
// ADMIN_TOKEN (o tópico ntfy vale como segredo fraco). Em vez disso um token
// dedicado, com validade e escopo de uma coisa só: iniciar o OAuth da Bluetti.
// Sobrevive a restart (em disco) e é rotacionado a cada login bem-sucedido.
const BLUETTI_REAUTH_FILE = path.join(DATA_DIR, 'bluetti_reauth.json');
let _bluettiReauth = null;
try { _bluettiReauth = JSON.parse(fs.readFileSync(BLUETTI_REAUTH_FILE, 'utf8')); } catch (_) {}
function _bluettiReauthToken() {
  const now = Date.now();
  if (!_bluettiReauth || !_bluettiReauth.token || (_bluettiReauth.expires || 0) < now) {
    _bluettiReauth = { token: require('crypto').randomBytes(24).toString('base64url'), created: now, expires: now + 45 * 86400_000 };
    try { atomicWriteFileSync(BLUETTI_REAUTH_FILE, JSON.stringify(_bluettiReauth)); } catch (_) {}
  }
  return _bluettiReauth.token;
}
function _bluettiReauthLink() {
  const base = (process.env.BRIDGE_PUBLIC_URL || '').replace(/\/$/, '');
  return `${base}/api/bluetti/oauth/start?rt=${_bluettiReauthToken()}`;
}
// Mesmo esquema do requireAuth: aceita o token cru ou o sha256 dele.
function _bridgeTokenOk(req) {
  const raw = (req.headers.authorization || '').replace(/^Bearer\s+/i, '').trim() ||
              (req.query.token || '').toString();
  if (!raw || !BRIDGE_TOKEN_HASH) return false;
  return safeStrEqual(raw, BRIDGE_TOKEN_HASH) || safeStrEqual(sha256hex(raw), BRIDGE_TOKEN_HASH);
}
function _bluettiAdminOk(req) {
  const t = (req.query.token || req.headers['x-admin-token'] || '').toString();
  if (process.env.ADMIN_TOKEN && t === process.env.ADMIN_TOKEN) return true;
  const rt = (req.query.rt || '').toString();
  return !!(rt && _bluettiReauth && rt === _bluettiReauth.token && (_bluettiReauth.expires || 0) > Date.now());
}
app.get('/api/bluetti/oauth/start', (req, res) => {
  if (!_bluettiAdminOk(req)) return res.status(401).send('token inválido');
  const state = require('crypto').randomBytes(16).toString('hex');
  for (const [k, exp] of _bluettiStates) if (exp < Date.now()) _bluettiStates.delete(k);
  _bluettiStates.set(state, Date.now() + 600_000);
  const url = bluettiCloud.authUrl(state);
  console.log(`[bluetti] oauth start → redirect_uri=${bluettiCloud.redirectUri()}`);
  res.redirect(url);
});
// Atende os dois paths: o nosso e o do HA (/auth/external/callback), caso o SSO
// da Bluetti valide redirect_uri por whitelist. Trocar via BLUETTI_REDIRECT_PATH.
app.get(['/api/bluetti/oauth/callback', '/auth/external/callback'], async (req, res) => {
  const { code, state, error, error_description: desc } = req.query;
  if (error) return res.status(400).send(`<h2>Bluetti recusou</h2><pre>${error}: ${desc || ''}</pre>`);
  const exp = _bluettiStates.get(String(state));
  if (!exp || exp < Date.now()) return res.status(400).send('<h2>state inválido/expirado</h2>Refaça em /api/bluetti/oauth/start');
  _bluettiStates.delete(String(state));
  if (!code) return res.status(400).send('<h2>sem code</h2>');
  try {
    await bluettiCloud.exchangeCode(String(code));
    _bluettiReauth = null; _bluettiReauthToken();      // queima o link usado
    const st = bluettiCloud.status();
    _bluettiTick().catch(() => {});
    // Esta página é o fim do popup aberto pelo health. Ela se fecha sozinha; o
    // health detecta pelo /api/bluetti-status que o token chegou, não pelo
    // fechamento da janela. Se alguém abriu o link direto (fora do popup),
    // window.close() não faz nada e a mensagem fica na tela — por isso o texto
    // precisa se sustentar sozinho, sem o JSON de diagnóstico que estava aqui.
    res.set('Content-Type', 'text/html; charset=utf-8').send(`<!doctype html>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bluetti autorizada</title>
<style>:root{color-scheme:dark light}body{margin:0;min-height:100vh;display:grid;
place-items:center;background:#0d0d0d;color:#ececea;
font:14px/1.6 -apple-system,system-ui,sans-serif;text-align:center;padding:24px}
@media(prefers-color-scheme:light){body{background:#e6e5e4;color:#201e1d}}
h1{font-size:17px;font-weight:800;margin:0 0 6px}
p{margin:0;color:#a3a39d}@media(prefers-color-scheme:light){p{color:#565452}}
b{color:#9ad34a}@media(prefers-color-scheme:light){b{color:#356210}}</style>
<div>
  <h1>Bluetti autorizada</h1>
  <p><b>${st.devices.length}</b> ${st.devices.length === 1 ? 'estação' : 'estações'} conectada${st.devices.length === 1 ? '' : 's'}.
     Login vale ${st.token_expires_in_days} dias, com renovação automática.</p>
  <p id="f" style="margin-top:14px">Fechando…</p>
</div>
<script>
setTimeout(() => {
  window.close();
  // Não fechou = não é popup. Diz o que fazer em vez de deixar a pessoa parada.
  document.getElementById('f').textContent = 'Pode fechar esta aba — o monitor já atualizou.';
}, 1200);
</script>`);
  } catch (e) {
    console.warn('[bluetti] callback falhou:', e.message);
    res.status(502).send(`<h2>Falhou</h2><pre>${e.message}</pre>`);
  }
});
// Diagnóstico da integração (token, ws, poll, SNs vistos na nuvem).
app.get('/api/bluetti/cloud-status', (req, res) => {
  const admin = _bluettiAdminOk(req) || !!adminAuth.validSession((req.headers['x-admin-session'] || '').toString().trim());
  if (!admin) return res.status(401).json({ error: 'unauthorized' });
  res.json({ source_mode: _BLUETTI_SOURCE, expected_sns: { casa: _bluettiSn('casa'), sitio: _bluettiSn('sitio') },
             ...bluettiCloud.status(), snapshot: bluettiCloud.snapshot() });
});
// Força um refresh do OAuth agora (o automático roda com 7 dias de folga). Serve
// pra testar o caminho de renovação sem esperar o mês passar.
app.post('/api/bluetti/refresh', async (req, res) => {
  const admin = _bluettiAdminOk(req) || !!adminAuth.validSession((req.headers['x-admin-session'] || '').toString().trim());
  if (!admin) return res.status(401).json({ error: 'unauthorized' });
  const before = bluettiCloud.status();
  const ok = await bluettiCloud.refreshNow();
  const after = bluettiCloud.status();
  res.json({ ok, before: { expires_at: before.token_expires_at, days: before.token_expires_in_days },
             after:  { expires_at: after.token_expires_at,  days: after.token_expires_in_days },
             needs_reauth: after.needs_reauth, last_error: after.last_error });
});
// Controle direto (AC/DC/ECO/working mode) sem passar pelo HA.
// body: { key: 'casa'|'sitio' } ou { sn }, + { fnCode, value }
app.post('/api/bluetti/control', requireAdmin, async (req, res) => {
  const { key, sn, fnCode, value } = req.body || {};
  const target = sn || (key ? _bluettiSn(key) : null);
  if (!target || !fnCode) return res.status(400).json({ error: 'sn/key e fnCode obrigatórios' });
  try {
    await bluettiCloud.controlDevice(target, fnCode, value);
    await bluettiCloud.poll([target]);
    await _bluettiTick();
    res.json({ ok: true, state: bluettiCloud.snapshot().devices[String(target).toUpperCase()] || null });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// ── Starlink do Sítio (via HA de lá, pelo túnel Cloudflare) ─────────────────
// Fonte: starlink-sitio.js (pull no sitio.malha.dev). Aqui só ficam o endpoint,
// os alertas e a histerese — mesmo desenho do Bluetti.
starlink.start({
  dataDir: DATA_DIR,
  log: (...a) => console.log('[starlink]', ...a),
  onUpdate: () => { try { _evalStarlinkAlerts(); } catch (_) {} },
});

// Histerese: ping e drop oscilam por natureza num link de satélite. Só alerto com
// 3 leituras ruins seguidas (≈3min), senão isso viraria máquina de falso positivo.
const _slHist = { ping: [], drop: [] };
let _slLastRestart = null;
function _pushSl(arr, v) { if (v == null) return; arr.push(v); if (arr.length > 3) arr.shift(); }
const _slAllAbove = (arr, lim) => arr.length === 3 && arr.every(v => v > lim);

function _evalStarlinkAlerts() {
  const st = starlink.status();
  if (!st.configured) return;
  const snap = starlink.snapshot();
  const d = snap.data;
  // Antes da 1ª leitura boa não existe "sem dados": o bridge acabou de subir. Só
  // considero queda depois de 3 falhas seguidas (≈3min) ou 5min sem leitura.
  const stale = st.last_ok_at ? st.stale_s > 300 : st.fail_streak >= 3;

  // 1. Sem dados: o caminho passa pela própria Starlink, então isso É a queda do
  // link (ou do HA, ou do túnel — não dá pra desempatar daqui). Último estado
  // conhecido vai no corpo pra dar contexto de qual das três é mais provável.
  const lastSeen = st.last_ok_at ? new Date(st.last_ok_at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : 'nunca';
  _alert('starlink_no_data', stale,
    '🛰️ Sítio sem dados',
    `Sem leitura da Starlink há ${st.stale_s == null ? '—' : Math.round(st.stale_s / 60) + 'min'} (última ${lastSeen}). ` +
    `Último estado: ${d ? (d.online ? 'online, ping ' + Math.round(d.ping_ms || 0) + 'ms' : 'offline') : 'desconhecido'}. ` +
    `Pode ser link, HA do sítio ou o túnel — o dado vem pelo próprio link. Erro: ${st.last_error || '—'}`,
    'high', ['satellite', 'warning']);
  if (stale || !d) {
    for (const id of ['starlink_offline', 'starlink_integration_down', 'starlink_stowed',
                      'starlink_obstructed', 'starlink_thermal', 'starlink_hw',
                      'starlink_ping_drop', 'starlink_latency'])
      _alert(id, false, '', '', 'default', []);
    return;
  }

  // 2. HA responde mas as entidades estão unavailable = dish não responde ao gRPC.
  _alert('starlink_integration_down', d.integration_ok === false,
    '🛰️ Starlink sem resposta',
    'O HA do sítio responde, mas a integração está sem dados do dish (gRPC 192.168.100.1 sem resposta). Dish desligado, cabo ou roteador.',
    'high', ['satellite']);

  // 3. Antena recolhida = sem link de propósito (ou por acidente).
  _alert('starlink_stowed', d.stowed === true,
    '🛰️ Antena recolhida (stowed)',
    'A Starlink do sítio está recolhida — sem link enquanto ficar assim.',
    'urgent', ['warning']);

  // 4. Conectividade caída com HA vivo: dá pra afirmar que é o dish, não o caminho.
  _alert('starlink_offline', d.conn === false && d.integration_ok !== false && d.stowed !== true,
    '🛰️ Starlink offline',
    `Dish sem conectividade${d.obstructed ? ' e obstruído' : ''}. Uptime ${d.uptime_h ?? '?'}h · quedas hoje ${d.drops_today ?? '?'}.`,
    'urgent', ['satellite', 'warning']);

  _alert('starlink_obstructed', d.obstructed === true,
    '🛰️ Starlink obstruída',
    `Dish reportando obstrução${d.online ? ' (ainda conectado)' : ' e sem conexão'}. Ver vegetação/estrutura na linha de visada.`,
    'high', ['satellite']);

  _alert('starlink_thermal', d.thermal === true,
    '🛰️ Starlink em throttle térmico',
    `Dish reduzindo desempenho por temperatura. Consumo atual ${Math.round(d.power_w || 0)}W.`,
    'high', ['thermometer']);

  // 5. Hardware: mastro, motores, local inesperado, ethernet. Um alerta só,
  // listando o que está acusando — são coisas que exigem ir lá olhar.
  const hw = (d.problems || []).filter(p => !['obstructed', 'thermal'].includes(p));
  const hwNames = { mast: 'mastro fora da vertical', motors: 'motores presos', unexpected_loc: 'localização inesperada', eth: 'velocidade ethernet' };
  _alert('starlink_hw', hw.length > 0,
    '🛰️ Starlink com aviso de hardware',
    `Acusando: ${hw.map(h => hwNames[h] || h).join(', ')}. Precisa de inspeção física no sítio.`,
    'default', ['wrench']);

  // 6. Qualidade: 3 leituras seguidas ruins. Drop de pacote sustentado é o que
  // realmente derruba chamada/VPN; latência alta só degrada.
  _pushSl(_slHist.drop, d.ping_drop);
  _pushSl(_slHist.ping, d.ping_ms);
  _alert('starlink_ping_drop', _slAllAbove(_slHist.drop, 5),
    '🛰️ Starlink perdendo pacote',
    `Ping drop acima de 5% nas últimas 3 leituras (agora ${d.ping_drop}%). Link instável.`,
    'high', ['satellite']);
  _alert('starlink_latency', _slAllAbove(_slHist.ping, 150),
    '🛰️ Starlink com latência alta',
    `Ping acima de 150ms nas últimas 3 leituras (agora ${Math.round(d.ping_ms)}ms).`,
    'default', ['satellite']);

  // 7. Reboot do dish: evento, não alerta contínuo. Baseline vem da 1ª leitura,
  // então restart do bridge não gera evento falso.
  if (d.last_restart) {
    if (_slLastRestart && d.last_restart !== _slLastRestart) {
      _recordHealthEvent('starlink_rebooted',
        `Starlink do sítio reiniciou (${new Date(d.last_restart).toLocaleString('pt-BR')})`);
    }
    _slLastRestart = d.last_restart;
  }
}
setInterval(() => { try { _evalStarlinkAlerts(); } catch (_) {} }, 60_000);

// GET /api/starlink-history?hours=24&every=1 — série temporal (NDJSON em disco,
// janela de STARLINK_HIST_DAYS). Sobrevive a restart do bridge.
app.get('/api/starlink-history', (req, res) => {
  const hours = Math.min(Math.max(+req.query.hours || 24, 1), 24 * 45);
  const every = Math.min(Math.max(+req.query.every || 1, 1), 60);
  const rows = starlink.history({ hours, every });
  res.json({ hours, every, count: rows.length, rows });
});

// POST /api/starlink/reset-counters — marco de corte dos agregados 7d/30d.
// Não purga o recorder do HA (o histórico do trabalho fica lá pra comparação):
// só passa a contar daqui pra frente e arquiva a nossa série temporal.
// Exige token do bridge ou sessão admin — é ação que muda número na cara do dono.
app.post('/api/starlink/reset-counters', async (req, res) => {
  const admin = _bridgeTokenOk(req) || !!adminAuth.validSession((req.headers['x-admin-session'] || '').toString().trim());
  if (!admin) return res.status(403).json({ error: 'somente com token do bridge ou sessão admin' });
  try {
    const r = await starlink.resetCounters();
    _slHist.ping.length = 0; _slHist.drop.length = 0;   // histerese recomeça também
    _recordHealthEvent('starlink_counters_reset',
      `Contadores da Starlink zerados${r.archived ? ' · histórico arquivado em ' + r.archived : ''}`);
    res.json({ ok: true, ...r });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/starlink-status — consumido pelo card do health.
app.get('/api/starlink-status', (req, res) => {
  const snap = starlink.snapshot();
  const st = starlink.status();
  if (!st.configured) return res.status(503).json({ error: 'ha_sitio_nao_configurado' });
  // A URL do HA só pra quem tem o token do bridge (rota registrada antes do gate
  // global de /api, igual a do Bluetti).
  const meta = { ...st };
  if (!_bridgeTokenOk(req)) delete meta.url;
  res.json({ ...snap, meta });
});

// ── Solar (SAJ Clean Master Ambiental — Catalão) ─────────────────────────────
// Planta com 2 inversores R6-10K-S3-18 (3 strings cada). Fetch via HA REST +
// cache 60s. Watchdog dispara alertas: plant_offline (sem comm com cloud SAJ),
// inverter_alarm, temperature_high, generation_lost_daytime, stale_upload.
const _SAJ = {
  plant_slug: 'clean_master_ambiental',
  invs: [
    { label: 'Inv A', slug: 'inverter_r6l3103j2422e30214', short: '30214' },
    { label: 'Inv B', slug: 'inverter_r6l3103j2425e37763', short: '37763' },
  ],
};
let _solarState = null;
let _solarCache = { data: null, ts: 0 };
async function _fetchSolarStatus() {
  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return null;
  try {
    const r = await fetch(`${url}/api/states`, {
      headers: { Authorization: `Bearer ${tok}` },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return null;
    const arr = await r.json();
    const num = (id) => {
      const s = arr.find(x => x.entity_id === id);
      if (!s || s.state === 'unknown' || s.state === 'unavailable') return null;
      const n = +s.state; return Number.isFinite(n) ? n : null;
    };
    const str = (id) => {
      const s = arr.find(x => x.entity_id === id);
      return s && s.state !== 'unknown' && s.state !== 'unavailable' ? s.state : null;
    };
    // Planta
    const p = _SAJ.plant_slug;
    const plantP = `sensor.plant_${p}`;
    const plant = {
      online:            str(`sensor.${p}_device_online`) === 'online',
      // status da PLANTA (Normal/Offline/Alarm). O sensor `${p}_inverter_status`
      // é do inversor e vive cravado em "alarm" no cloud SAJ mesmo após evento
      // passar — não serve pra decidir alerta.
      status:            str(`${plantP}_status`),
      inverter_status:   str(`sensor.${p}_inverter_status`),      // legado — sticky
      pv_power:          num(`sensor.${p}_pv_power`),              // W (geração agora)
      pv_direction:      str(`sensor.${p}_pv_direction`),          // exporting/importing/standby
      grid_power:        num(`sensor.${p}_grid_power`),            // W (sinal indica direção)
      load_power:        num(`sensor.${p}_load_power`),
      self_use_rate:     num(`sensor.${p}_self_use_rate`),         // % (auto-consumo)
      co2_kg_today:      (num(`sensor.${p}_co2_reduction_today`) ?? 0) * 1000,
      trees_today:       num(`sensor.${p}_trees_planted_today`),
      energy_today:      num(`${plantP}_energy_today`),            // kWh
      energy_month:      num(`${plantP}_energy_month`),
      energy_year:       num(`${plantP}_energy_year`),
      energy_total:      num(`${plantP}_energy_total`),
      peak_power_today:  num(`${plantP}_peak_power`),
      hours_equivalent:  num(`${plantP}_today_equivalent_hours`),
      last_upload_iso:   str(`${plantP}_last_upload_time`),
    };
    // Inversores
    const invs = _SAJ.invs.map(inv => {
      const s = `sensor.${inv.slug}`;
      const strings = [1, 2, 3].map(i => ({
        pv_v:  num(`${s}_pv${i}`),
        watts: num(`${s}_string_${i}_power`),
      }));
      return {
        label: inv.label, short: inv.short,
        power:         num(`${s}_power`),
        peak_today:    num(`${s}_peak_power`),
        energy_today:  num(`${s}_energy_today`),
        energy_month:  num(`${s}_energy_month`),
        energy_total:  num(`${s}_energy_total`),
        temperature:   num(`${s}_temperature`),
        grid_power:    num(`${s}_grid_power`),
        grid_v:        num(`${s}_gv1r`),
        alarm_count:   num(`${s}_today_alarm_num`),
        strings,
      };
    });
    // Freshness da última comunicação com o cloud SAJ
    let stale_min = null;
    if (plant.last_upload_iso) {
      const t = Date.parse(plant.last_upload_iso);
      if (!isNaN(t)) stale_min = Math.round((Date.now() - t) / 60_000);
    }
    return { plant, invs, stale_min, ts: Date.now(), fonte: 'ha' };
  } catch (e) { return null; }
}

/**
 * Catalão com a nuvem SAJ como fonte PRIMÁRIA e o HA como reserva.
 *
 * Existe porque em 15/09/2026 a usina ficou ~3h invisível sem ter nada de errado:
 * a SAJ passou a bloquear o User-Agent do `requests` e a integração comunitária
 * do HA parou inteira. Cada campo vem da melhor fonte disponível, e a falta de
 * uma NÃO apaga a outra:
 *   · potência / energia / online  → SAJ (direto, sem intermediário)
 *   · temperatura e strings        → HA (a SAJ não expõe: `invTemp` vem vazio)
 * Sem nenhuma das duas, o campo é null — nunca 0, que seria afirmar geração zero.
 */
async function _fetchSolarCombinado() {
  const [ha, cloud] = await Promise.all([
    _fetchSolarStatus(),
    sajCloud.lePlanta().catch(() => null),
  ]);
  if (!cloud) return ha;                      // nuvem fora: segue como sempre foi
  if (!ha) {
    // Sem HA: serve o que a SAJ tem, e temperatura fica null (o desenho mostra
    // "—", não zero). Melhor meia leitura verdadeira que nenhuma.
    return {
      plant: { online: cloud.online, pv_power: cloud.pv_power, energy_today: cloud.energy_today,
               energy_month: cloud.energy_month, energy_total: cloud.energy_total, status: null,
               inverter_status: null, last_upload_iso: null },
      invs: cloud.invs.map((i, n) => ({ label: `Inv ${String.fromCharCode(65 + n)}`,
        short: i.sn.slice(-5), power: i.power, temperature: null,
        energy_today: i.energy_today, status: i.status, strings: [] })),
      stale_min: null, ts: cloud.ts, fonte: 'saj-cloud',
      invs_reporting: cloud.invs_reportando, invs_total: cloud.invs_total,
    };
  }
  // As duas vivas: SAJ manda nos números, HA completa o que ela não dá. O casamento
  // é pelo final do serial, que é o que os dois lados têm em comum.
  const porSn = new Map(cloud.invs.map(i => [String(i.sn).slice(-5).toUpperCase(), i]));
  const invs = ha.invs.map((h) => {
    const c = porSn.get(String(h.short || '').toUpperCase());
    return c ? { ...h, power: c.power, energy_today: c.energy_today, status: c.status ?? h.status } : h;
  });
  return {
    ...ha,
    plant: { ...ha.plant, online: cloud.online, pv_power: cloud.pv_power,
             energy_today: cloud.energy_today, energy_month: cloud.energy_month,
             energy_total: cloud.energy_total },
    invs,
    fonte: 'saj-cloud+ha',
    invs_reporting: cloud.invs_reportando, invs_total: cloud.invs_total,
  };
}
async function _solarTick() {
  const d = await _fetchSolarCombinado();
  if (d) {
    const sun = await _fetchCatalaoSun();
    d.sunrise_ms = sun.sunrise_ms || null;
    d.sunset_ms  = sun.sunset_ms  || null;
    d.expected   = _expectedNow('catalao');   // mediana da hora atual (histórico)
    _solarState = d; _solarCache = { data: d, ts: Date.now() };
  }
  _evalSolarAlerts().catch(() => {});
}
// 1 minuto. Explícito em env pra não ficar escondido num literal: é este tique
// que fala com a nuvem SAJ desde 15/09/2026, não só com o HA.
const SOLAR_POLL_MS = +(process.env.SOLAR_POLL_MS || 60_000);
setInterval(() => { _solarTick().catch(() => {}); }, SOLAR_POLL_MS);
setTimeout(() => { _solarTick().catch(() => {}); }, 7_000);

// Alertas do solar. Prioriza clareza: planta offline > inversor alarm >
// geração perdida em pleno dia > temperatura alta > dados velhos.
// Sunrise/sunset por localização via OpenWeather. Cache 12h por lat/lng —
// sunrise/sunset varia <2min/dia. Fallback pra janela fixa 7-18h se API off.
// Margem de 15min antes/depois pra cobrir a franja de geração fraca no
// alvorecer/entardecer (evita alerta na fronteira).
const SUN_COORDS = {
  catalao:   { lat: -18.189331, lng: -47.937741 },   // SAJ Clean Master
  goiania:   { lat: -16.686900, lng: -49.264800 },   // Ivonei
  palmeiras: { lat: -16.800300, lng: -49.925600 },   // Palmeiras de Goiás
};
const _sunCache = {};   // { locKey: { sunrise_ms, sunset_ms, cachedAt } }
async function _fetchSunTimes(locKey) {
  const c = SUN_COORDS[locKey];
  if (!c) return { sunrise_ms: 0, sunset_ms: 0 };
  const cur = _sunCache[locKey];
  const now = Date.now();
  if (cur && cur.cachedAt && (now - cur.cachedAt) < 12 * 3600_000) return cur;
  const key = process.env.OPENWEATHER_API_KEY;
  if (!key) return cur || { sunrise_ms: 0, sunset_ms: 0 };
  try {
    const u = `https://api.openweathermap.org/data/2.5/weather?lat=${c.lat}&lon=${c.lng}&appid=${key}`;
    const j = await (await fetch(u, { signal: AbortSignal.timeout(5000) })).json();
    if (j.sys && j.sys.sunrise && j.sys.sunset) {
      _sunCache[locKey] = { sunrise_ms: j.sys.sunrise * 1000, sunset_ms: j.sys.sunset * 1000, cachedAt: now };
    }
  } catch (_) {}
  return _sunCache[locKey] || { sunrise_ms: 0, sunset_ms: 0 };
}
// Compat: _fetchCatalaoSun continua funcionando (SAJ Catalão).
async function _fetchCatalaoSun() { return _fetchSunTimes('catalao'); }
async function _isDaytimeAt(locKey) {
  const s = await _fetchSunTimes(locKey);
  if (!s.sunrise_ms || !s.sunset_ms) {
    const h = new Date().getHours();
    return h >= 7 && h < 18;
  }
  const marginMs = 15 * 60_000;
  const now = Date.now();
  return now >= (s.sunrise_ms - marginMs) && now <= (s.sunset_ms + marginMs);
}
// Janela em que inversor DEVE estar reportando ao coletor. Sunrise "oficial"
