// Tomada WiFi do ventilador do Ivonei. É `switch.bluetti_1` por acidente de
// nome do fabricante — o friendly_name é "Ventilador Socket 1" e nada tem a ver
// com a bateria Bluetti de casa.
const VENT_IVONEI = process.env.VENT_IVONEI_ENTITY || 'switch.bluetti_1';
const _SOLIS = {
  ivonei: {
    label: 'Ivonei (Goiânia)',
    invs: [
      { label: 'Inv 1', slug: 'energia_solar_ivonei',   strings: [1, 2] },
      { label: 'Inv 2', slug: 'energia_solar_ivonei_2', strings: [1, 2] },
    ],
  },
  palmeiras: {
    label: 'Palmeiras (Palmeiras de Goiás)',
    invs: [
      { label: 'Inv',   slug: 'energia_solar_palmeiras', strings: [1, 2, 3] },
    ],
  },
};
let _solisState = null;
let _solisCache = { data: null, ts: 0 };
async function _fetchSolisStatus() {
  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return null;
  try {
    const r = await fetch(`${url}/api/states`, {
      headers: { Authorization: `Bearer ${tok}` },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return null;
    const arr = await r.json();
    const num = (id) => {
      const s = arr.find(x => x.entity_id === id);
      if (!s || s.state === 'unknown' || s.state === 'unavailable') return null;
      const n = +s.state; return Number.isFinite(n) ? n : null;
    };
    const str = (id) => {
      const s = arr.find(x => x.entity_id === id);
      return s && s.state !== 'unknown' && s.state !== 'unavailable' ? s.state : null;
    };
    // Quando a leitura chegou. Sem isso não dá pra afirmar nada sobre a
    // temperatura fora do horário: o cloud Solis para de atualizar com o
    // inversor dormindo e o último valor passaria por atual.
    const tsOf = (id) => {
      const s = arr.find(x => x.entity_id === id);
      return s ? (Date.parse(s.last_updated || s.last_changed || '') || null) : null;
    };
    const readInv = (inv) => {
      const p = `sensor.${inv.slug}`;
      return {
        label: inv.label,
        temp_ms:           tsOf(`${p}_inverter_temperature`),
        ac_power_w:        num(`${p}_inverter_ac_power`),
        dc_power_w:        num(`${p}_inverter_dc_power`),
        gen_today_kwh:     num(`${p}_inverter_generation_today`),
        gen_month_kwh:     num(`${p}_inverter_generation_this_month`),
        gen_total_kwh:     num(`${p}_inverter_generation_total`),
        temperature_c:     num(`${p}_inverter_temperature`),
        grid_v:            num(`${p}_grid_l1_voltage`),
        grid_a:            num(`${p}_grid_l1_current`),
        grid_freq_hz:      num(`${p}_grid_frequency`),
        grid_export_today: num(`${p}_grid_export_today`),
        runtime_today_h:   num(`${p}_inverter_runtime_today`),
        collector:         str(`${p}_collector_state`),   // online/offline
        status:            str(`${p}_inverter_status`),   // generating/alarm/offline
        strings: inv.strings.map(n => ({
          n,
          v: num(`${p}_pv_string_${n}_voltage`),
          a: num(`${p}_pv_string_${n}_current`),
          w: num(`${p}_pv_string_${n}_power`),
        })),
      };
    };
    // Agrega por sistema (soma potência/energia hoje)
    const buildSystem = (cfg, key) => {
      const invs = cfg.invs.map(readInv);
      // `?? 0` transformava "sem dado" em "gerando 0 W". Zero é uma afirmação:
      // com o datalogger mudo a planta aparecia zerada na tela enquanto o app
      // Solis mostrava geração normal (Palmeiras, 13/09). Agora: ninguém
      // reportou → null; parcial → soma o que veio.
      const sum = (k) => {
        const v = invs.map(i => i[k]).filter(x => x != null);
        return v.length ? v.reduce((a, x) => a + x, 0) : null;
      };
      // Se algum inversor não trouxe gen_today (Solis manda `unavailable`
      // esporadicamente), soma vai vir subestimada. Deriva a partir de
      // gen_month_kwh - snapshot_do_inicio_do_dia (monotônico até virar mês).
      const someMissing = invs.some(i => i.gen_today_kwh == null);
      const genMonth = sum('gen_month_kwh');
      if (genMonth != null) _ensureDayStart(key, genMonth);
      let genToday = sum('gen_today_kwh');
      let genTodaySource = 'inverter_field';
      // Fallback A: deriva de gen_month_kwh - snapshot_do_inicio_do_dia
      if (someMissing || !genToday) {
        const start = _dayStartMonthKwh(key);
        if (start != null && genMonth != null && genMonth >= start) {
          const derived = +(genMonth - start).toFixed(2);
          if (genToday == null || derived > genToday) { genToday = derived; genTodaySource = 'derived_month_delta'; }
        }
      }
      // Fallback B: monotonic clamp — última leitura BOA persistida hoje
      // sempre vence uma leitura pior (Solis manda unavailable → 0 e depois
      // volta). Usa `_solarHistory[key]` que já é atualizado pelo _recordSolarSnap.
      if (someMissing || !genToday) {
        const today = _todayDateStr();
        const persisted = (_solarHistory[key] || []).find(d => d.date === today);
        if (persisted && (persisted.kwh || 0) > (genToday ?? 0)) {
          genToday = +persisted.kwh.toFixed(2);
          genTodaySource = 'persisted_max';
        }
      }
      // Quantos inversores REALMENTE reportaram potência. Uma planta de 2 com 1
      // mudo soma metade, e sem dizer isso a tela mostra uma queda de 50% que
      // não existe — e pior, compara essa metade contra a mediana da planta
      // inteira. Quem desenha precisa saber que a soma está incompleta.
      const reporting = invs.filter(i => i.ac_power_w != null).length;
      return {
        label: cfg.label,
        ac_power_w:      sum('ac_power_w'),
        invs_reporting:  reporting,
        invs_total:      invs.length,
        gen_today_kwh:   genToday,
        gen_today_src:   genTodaySource,
        gen_month_kwh:   genMonth,
        gen_total_kwh:   sum('gen_total_kwh'),
        invs,
      };
    };
    // Ventilador do Ivonei: tomada WiFi que o HA liga quando o inversor passa
    // de 50°C por 5min e desliga abaixo de 45°C por 15min (e às 18h, de todo
    // jeito). Fica aqui junto da planta porque é dela que ele cuida.
    const vent = (() => {
      const e = arr.find(x => x.entity_id === VENT_IVONEI);
      if (!e || e.state === 'unavailable' || e.state === 'unknown') {
        return { ligado: null, erro: e ? e.state : 'sem entidade' };
      }
      const w = num('sensor.potencia_tomada_wifi');
      return {
        ligado: e.state === 'on',
        // `last_changed` é quando LIGOU ou DESLIGOU — é o "desde quando".
        // `last_updated` não serve: muda a cada atualização de atributo.
        desde_ms: Date.parse(e.last_changed || e.last_updated || '') || null,
        watts: w,
        // Tomada ligada com consumo ~0 = ventilador parado (queimado, cabo
        // solto). O socket dizer "on" não prova que o ar está se movendo.
        girando: w == null ? null : w > 5,
      };
    })();
    const ivonei = buildSystem(_SOLIS.ivonei, 'ivonei');
    ivonei.ventilador = vent;
    return {
      ivonei,
      palmeiras: buildSystem(_SOLIS.palmeiras, 'palmeiras'),
      ts: Date.now(),
    };
  } catch (e) { return null; }
}
async function _solisTick() {
  const d = await _fetchSolisStatus();
  if (d) {
    // Sunrise/sunset ESPECÍFICO por sistema: Ivonei usa Goiânia, Palmeiras
    // usa Palmeiras de Goiás. ~30min de diferença no oeste (Palmeiras).
    const sunGYN = await _fetchSunTimes('goiania');
    const sunPGO = await _fetchSunTimes('palmeiras');
    if (d.ivonei)    { d.ivonei.sunrise_ms    = sunGYN.sunrise_ms || null; d.ivonei.sunset_ms    = sunGYN.sunset_ms || null; d.ivonei.expected    = _expectedNow('ivonei'); }
    if (d.palmeiras) { d.palmeiras.sunrise_ms = sunPGO.sunrise_ms || null; d.palmeiras.sunset_ms = sunPGO.sunset_ms || null; d.palmeiras.expected = _expectedNow('palmeiras'); }
    _solisState = d; _solisCache = { data: d, ts: Date.now() };
  }
  _evalSolisAlerts().catch(() => {});
}
setInterval(() => { _solisTick().catch(() => {}); }, 60_000);
setTimeout(() => { _solisTick().catch(() => {}); }, 9_000);

// ── Ventilador dos inversores do Ivonei ──────────────────────────────────────
// Tomada Tuya no HA. O entity_id carrega o slug `bluetti` porque o device foi
// reaproveitado e renomeado — NÃO deduzir a entidade pelo nome, vem do .env.
// Confere o friendly_name no boot só pra avisar se a tomada trocou de dono.
const FAN_IV_SWITCH = process.env.FAN_IVONEI_ENTITY       || 'switch.bluetti_1';
const FAN_IV_POWER  = process.env.FAN_IVONEI_POWER_ENTITY || 'sensor.bluetti_potencia';
const FAN_IV_NO_LOAD_W  = +(process.env.FAN_IVONEI_NO_LOAD_W || 5);      // abaixo disso não está girando
const FAN_IV_NO_LOAD_MS = +(process.env.FAN_IVONEI_NO_LOAD_MIN || 5) * 60_000;
// Supervisão da automação do HA: acima de 55°C em qualquer inversor o ventilador
// tem que estar ligado; abaixo, desligado. Quem executa é o HA — o bridge só
// confere o EFEITO, igual ao _monitorRuleAction do carro.
// Gatilhos da automação do HA, lidos de lá (liga_ventilador_ivonei /
// desliga_ventilador_ivonei): liga acima de 55, desliga abaixo de 50. A
// histerese de verdade é essa — entre 50 e 55 o ventilador pode legitimamente
// estar nos dois estados, depende de por onde a temperatura entrou na faixa.
const FAN_IV_TEMP_ON_C   = +(process.env.FAN_IVONEI_TEMP_ON_C  || 55);
const FAN_IV_TEMP_OFF_C  = +(process.env.FAN_IVONEI_TEMP_OFF_C || 50);
// Carência = o `for:` da própria automação + folga. Ela espera 5min acima de 55
// pra ligar e 15min abaixo de 50 pra desligar; cobrar antes disso seria alertar
// de algo que ainda nem estava previsto acontecer. A folga cobre o poll do
// cloud Solis (~5min), que é o relógio real dessas temperaturas.
const FAN_IV_GRACE_ON_MS  = +(process.env.FAN_IVONEI_GRACE_ON_MIN  || 10) * 60_000;
const FAN_IV_GRACE_OFF_MS = +(process.env.FAN_IVONEI_GRACE_OFF_MIN || 25) * 60_000;
// A planta inteira parou de reportar (inversor dormindo) — aí nenhum veredito se
// sustenta. NÃO é filtro por inversor: o cloud Solis atualiza cada um no seu
// ritmo (o Inv 1 fica 20-30min no mesmo valor) e descartar o atrasado
// transformava "o mais quente dos dois" em "o único que sobrou".
const FAN_IV_TEMP_AGE_MS = +(process.env.FAN_IVONEI_TEMP_MAX_AGE_MIN || 45) * 60_000;
// A janela vale só pro "devia estar LIGADO" — fora dela ninguém cobra o
// ventilador de ligar. "Devia estar DESLIGADO" não tem hora: abaixo de 55 ele
// tem que estar parado, inclusive de madrugada.
const FAN_IV_WIN_FROM_H  = +(process.env.FAN_IVONEI_WINDOW_FROM_H || 10);
const FAN_IV_WIN_TO_H    = +(process.env.FAN_IVONEI_WINDOW_TO_H   || 17);
let _fanIvonei = null;

function _localHourBR(d = new Date()) {
  const p = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false,
  }).formatToParts(d).find(x => x.type === 'hour');
  return (+(p?.value ?? 0)) % 24;
}

async function _haState(entity) {
  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return null;
  try {
    const r = await fetch(`${url}/api/states/${encodeURIComponent(entity)}`, {
      headers: { Authorization: `Bearer ${tok}` },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return null;
    return await r.json();
  } catch (_) { return null; }
}

async function _fanIvoneiTick() {
  const sw = await _haState(FAN_IV_SWITCH);
  const now = Date.now();
  if (!sw) {                                   // HA mudo: mantém o último conhecido
    _fanIvoneiForget();
    if (_fanIvonei) _fanIvonei = { ..._fanIvonei, available: false, mismatch: false, ts: now };
    return;
  }
  const raw = String(sw.state || '').toLowerCase();
  const known = raw === 'on' || raw === 'off';
  if (!known) {                                // unavailable/unknown não é transição
    _fanIvoneiForget();
    if (_fanIvonei) _fanIvonei = { ..._fanIvonei, available: false, mismatch: false, ts: now };
    else _fanIvonei = { on: null, since_ms: null, available: false, ts: now };
    return;
  }
  const on = raw === 'on';
  const haSince = Date.parse(sw.last_changed || '') || now;
  // `last_changed` zera quando o HA reinicia. Se o estado NÃO mudou, o "desde"
  // mais antigo é o verdadeiro — é o que faz a contagem sobreviver ao restart
  // do HA (mesmo motivo do _alertState persistido do probe).
  const prev = state._fan_ivonei;
  let since = haSince;
  if (prev && prev.on === on && prev.since_ms) since = Math.min(prev.since_ms, haSince);
  if (!prev || prev.on !== on || prev.since_ms !== since) {
    state._fan_ivonei = { on, since_ms: since };
    scheduleStateSave();
  }
  const pw = await _haState(FAN_IV_POWER);
  const powerW = pw && Number.isFinite(+pw.state) ? +pw.state : null;
  // Chave ligada e tomada sem consumo = ventilador não está girando (desplugado,
  // motor travado). Só depois de FAN_IV_NO_LOAD_MS ligado, senão o próprio
  // arranque do motor viraria alarme.
  const noLoad = !!(on && powerW != null && powerW < FAN_IV_NO_LOAD_W
                    && (now - since) > FAN_IV_NO_LOAD_MS);
  _fanIvonei = {
    on, since_ms: since, since_age_ms: now - since,
    power_w: powerW, no_load: noLoad,
    entity: FAN_IV_SWITCH, name: sw.attributes?.friendly_name || null,
    available: true, ts: now,
    ..._fanIvoneiCheck(on, now),
  };
}

// Confere se a automação do HA fez o que devia. Devolve um veredito ou, quando
// não dá pra afirmar nada (sem temperatura fresca, banda morta, HA mudo), o
// motivo — silêncio explicado vale mais que alerta chutado.
// Sem estado do ventilador não há divergência que se sustente: esquece o relógio
// em vez de deixá-lo correndo por baixo.
function _fanIvoneiForget() {
  if (state._fan_iv_mismatch) { state._fan_iv_mismatch = null; scheduleStateSave(); }
}
function _fanIvoneiCheck(on, now) {
  const hour = _localHourBR();
  const inWindow = hour >= FAN_IV_WIN_FROM_H && hour < FAN_IV_WIN_TO_H;
  const base = { max_temp_c: null, expected: null, check_skip: null, in_window: inWindow,
                 mismatch: false, mismatch_kind: null, mismatch_since_ms: null, mismatch_age_ms: null };
  // Todo caminho SEM veredito zera o relógio. A carência mede divergência
  // CONTÍNUA; sem isto o relógio latchava e o primeiro instante de divergência
  // depois de qualquer pausa já nascia vencido.
  const quiet = (why, extra = {}) => {
    if (state._fan_iv_mismatch) { state._fan_iv_mismatch = null; scheduleStateSave(); }
    return { ...base, ...extra, check_skip: why };
  };

  // Sem _solisState ainda (boot, ou o fetch do Solis falhou) é "não sei", não
  // "inversor sem leitura" — e não zera o relógio, porque nada foi observado.
  const invs = _solisState?.ivonei?.invs;
  if (!invs) return { ...base, check_skip: 'aguardando leitura do Solis' };
  const temps = invs.map(i => i.temperature_c).filter(t => Number.isFinite(t));
  // Mesma visão da automação: ela lê states(), que devolve o último valor
  // conhecido sem olhar idade, e só falha em unavailable. Se um inversor não tem
  // leitura, a condição do HA não fecha e o bridge também não pode cobrar.
  if (!invs.length || temps.length !== invs.length) return quiet('inversor sem leitura');   // aqui SIM é observação
  const freshest = Math.min(...invs.map(i => i.temp_ms ? now - i.temp_ms : Infinity));
  if (!(freshest < FAN_IV_TEMP_AGE_MS)) return quiet('planta sem reportar');
  const maxT = Math.max(...temps);
  // Comparação estrita nos dois lados, igual ao numeric_state do HA (`above: 55`
  // e `below: 50` não disparam no valor exato).
  const hot  = maxT > FAN_IV_TEMP_ON_C;
  const cold = maxT < FAN_IV_TEMP_OFF_C;

  let expected = null;
  if (hot)  expected = 'on';
  else if (cold) expected = 'off';
  if (!expected) return quiet(`histerese ${FAN_IV_TEMP_OFF_C}-${FAN_IV_TEMP_ON_C}°C`, { max_temp_c: maxT });
  // Cobrar que LIGUE só na janela; que DESLIGUE, a qualquer hora.
  if (expected === 'on' && !inWindow) return quiet('fora da janela', { max_temp_c: maxT, expected });

  const bad  = (expected === 'on') !== on;
  const kind = bad ? (expected === 'on' ? 'deveria_ligar' : 'deveria_desligar') : null;
  const prev = state._fan_iv_mismatch;
  let since = null;
  if (bad) {
    since = (prev && prev.kind === kind && prev.since_ms) ? prev.since_ms : now;
    if (!prev || prev.kind !== kind || prev.since_ms !== since) {
      state._fan_iv_mismatch = { kind, since_ms: since }; scheduleStateSave();
    }
  } else if (prev) {
    state._fan_iv_mismatch = null; scheduleStateSave();
  }
  // `mismatch` só vira true depois da carência: é o MESMO campo que alimenta o
  // alerta e a página, pra não existirem dois limiares pro mesmo fato.
  const age   = since ? now - since : null;
  const grace = expected === 'on' ? FAN_IV_GRACE_ON_MS : FAN_IV_GRACE_OFF_MS;
  return { ...base, max_temp_c: maxT, expected, grace_ms: grace,
           mismatch: !!(bad && age >= grace),
           mismatch_kind: kind, mismatch_since_ms: since, mismatch_age_ms: age };
}

function _evalFanIvoneiAlerts() {
  const f = _fanIvonei;
  const on = f?.mismatch === true;
  const t  = f?.max_temp_c != null ? `${f.max_temp_c.toFixed(1)}°C` : '?';
  const min = f?.mismatch_age_ms ? Math.round(f.mismatch_age_ms / 60_000) : 0;
  _alert('fan_ivonei_off_when_hot', on && f.mismatch_kind === 'deveria_ligar',
    '🌀 Ventilador do Ivonei desligado com inversor quente',
    `Inversor a ${t} (liga acima de ${FAN_IV_TEMP_ON_C}°C) e o ventilador está desligado há ${min}min, `
    + `dentro da janela ${FAN_IV_WIN_FROM_H}h-${FAN_IV_WIN_TO_H}h. A automação do HA não ligou.`,
    'high', ['fan', 'thermometer.sun'], { fireDelay: 0 });
  _alert('fan_ivonei_on_when_cold', on && f.mismatch_kind === 'deveria_desligar',
    '🌀 Ventilador do Ivonei ligado com inversor frio',
    `Inversor a ${t} (desliga abaixo de ${FAN_IV_TEMP_OFF_C}°C) e o ventilador segue ligado há ${min}min. `
    + `A automação do HA não desligou.`,
    'default', ['fan', 'snowflake'], { fireDelay: 0 });
}
// Engolir a exceção aqui escondeu por horas um alerta que não conseguia limpar.
const _fanIvoneiCycle = () => _fanIvoneiTick().then(_evalFanIvoneiAlerts)
  .catch(e => console.warn('[fan-ivonei]', e && e.stack || e));
setInterval(_fanIvoneiCycle, 30_000);
setTimeout(_fanIvoneiCycle, 11_000);

async function _evalSolisAlerts() {
  if (!_solisState) return;
  const daytimeGYN = await _isDaytimeAt('goiania');
  const daytimePGO = await _isDaytimeAt('palmeiras');
  const invHoursGYN = await _isInverterActiveHours('goiania');
  const invHoursPGO = await _isInverterActiveHours('palmeiras');
  for (const [key, sys, daytime, invHours] of [
    ['ivonei',    _solisState.ivonei,    daytimeGYN, invHoursGYN],
    ['palmeiras', _solisState.palmeiras, daytimePGO, invHoursPGO],
  ]) {
    if (!sys) continue;
    // Collector offline em qualquer inv = cloud Solis não recebe. Só alerta na
    // janela ATIVA do inversor (sunrise+45min → sunset-30min); daytime é
    // permissivo demais (dispara 06:29 antes do inversor acordar).
    // ANY → ALL. Cada inversor tem seu próprio datalogger; um mudo com o outro
    // online é telemetria parcial, não planta cega — e o inversor segue gerando.
    // Com `some()` isso virava alerta 'high' de "monitoramento cego" enquanto a
    // planta produzia normal. É o mesmo erro de ANY-em-vez-de-ALL que já apareceu
    // no desligamento do ventilador.
    // `unavailable` no HA vira null em str(), e null não contava como offline: o
    // alerta ficava mudo EXATAMENTE quando a planta cegou de vez (a entidade
    // some em vez de reportar 'offline'). Sem telemetria nenhuma — nem coletor,
    // nem potência, nem temperatura — é cego.
    const invBlind = (i) => i.collector ? i.collector !== 'online'
                                        : (i.ac_power_w == null && i.temperature_c == null);
    const collsOff = sys.invs.filter(invBlind).length;
    const collOff  = collsOff > 0;                       // ainda usado pra suprimir o alarme
    const plantBlind = collsOff === sys.invs.length;
    // Mediana de 1min nos últimos 14 dias: stick reconecta sozinho. Só é problema
    // se ficar mudo de verdade.
    const blindKey = `solis_${key}_collector_offline`;
    _alert(blindKey,
      _sustained(blindKey, invHours, plantBlind && invHours, COLLECTOR_SUSTAIN_MS),
      `☀️ ${sys.label} — planta cega`,
      `Todos os dataloggers sem comunicação com a cloud há ${_sustainedFor(blindKey)}min. `
      + `Os inversores podem estar gerando normal, mas não há como saber.`,
      'high', ['warning', 'sun.max'], { repeatEvery: 6 * 3600_000 });
    // Inverter status != generating (durante o dia)
    const badStatus = sys.invs.find(i => i.status && !['generating','正常'].includes(String(i.status).toLowerCase()) && i.status !== 'online');
    _alert(`solis_${key}_alarm`, !!badStatus && daytime && !collOff,
      `☀️ ${sys.label} — inversor em ALARME`,
      `Status: "${badStatus?.status}". Ver app Solis Cloud pra detalhes.`,
      'urgent', ['warning', 'exclamationmark.circle.fill']);
    // Temperatura alta (>80°C — S6-GR1P6K tem limite 85°C)
    for (const inv of sys.invs) {
      const _tId = key + '_' + inv.label.toLowerCase().replace(/[^a-z0-9]/g,'');
      const kT2 = `solis_${_tId}_temp_high`;
      const tEval = daytime && inv.temperature_c != null;
      _alert(kT2, _sustained(kT2, tEval, tEval && inv.temperature_c > 80, SOLAR_TEMP_SUSTAIN_MS),
        `☀️ ${sys.label} · ${inv.label} — temperatura alta ${inv.temperature_c}°C`,
        `Acima de 80°C. Pode entrar em derating. Ver ventilação/insolação direta.`,
        'high', ['thermometer.sun', 'flame']);
    }
    // Ivonei tem 2 inversores — se 1 estiver em 0W enquanto o outro gera >500W
    // (10h-14h), problema local
    if (sys.invs.length === 2) {
      const now = new Date(), h = now.getHours();
      const midday = h >= 10 && h <= 14;
      const [a, b] = sys.invs;
      // Com `?? 0` o inversor mudo virava "em 0W" e o outro gerando confirmava
      // um problema local que não existe. Comparação exige os DOIS lados.
      const pair  = a.ac_power_w != null && b.ac_power_w != null;
      const aDown = pair && a.ac_power_w < 100, bDown = pair && b.ac_power_w < 100;
      const aUp   = pair && a.ac_power_w > 500, bUp   = pair && b.ac_power_w > 500;
      const kS1 = `solis_${key}_inv1_solo_down`;
      _alert(kS1, _sustained(kS1, midday && pair, aDown && bUp && midday, SOLAR_SOLO_SUSTAIN_MS),
        `☀️ ${sys.label} — ${a.label} parou`,
        `${a.label} em 0W enquanto ${b.label} gera ${b.ac_power_w}W. Problema local (string/disjuntor/CC).`,
        'high', ['bolt.slash']);
      const kS2 = `solis_${key}_inv2_solo_down`;
      _alert(kS2, _sustained(kS2, midday && pair, bDown && aUp && midday, SOLAR_SOLO_SUSTAIN_MS),
        `☀️ ${sys.label} — ${b.label} parou`,
        `${b.label} em 0W enquanto ${a.label} gera ${a.ac_power_w}W. Problema local (string/disjuntor/CC).`,
        'high', ['bolt.slash']);
    }
    // Geração perdida ao meio-dia (10-14h) — sistema inteiro em <10% do esperado
    const now2 = new Date();
    const midday2 = now2.getHours() >= 10 && now2.getHours() <= 14;
    const kG = `solis_${key}_generation_lost`;
    const genEval = midday2 && sys.ac_power_w != null;   // sem leitura, congela
    _alert(kG, _sustained(kG, genEval, genEval && sys.ac_power_w < 500, SOLAR_GEN_SUSTAIN_MS),
      `☀️ ${sys.label} — sem geração ao meio-dia`,
      `Potência ${sys.ac_power_w}W entre 10-14h. Nublado extremo, disjuntor ou coletor caído.`,
      'high', ['sun.max.trianglebadge.exclamationmark']);
    // Anomalias comuns: queda súbita + dia baixo vs histórico
    const sunLoc = key === 'ivonei' ? 'goiania' : 'palmeiras';
    await _evalSolarAnomalies(key, sunLoc, sys.ac_power_w, sys.gen_today_kwh, daytime);
  }
}

app.get('/api/solis-status', async (_req, res) => {
  const now = Date.now();
  if (!_solisCache.data || (now - _solisCache.ts) > 60_000) {
    const d = await _fetchSolisStatus();
    if (d) _solisCache = { data: d, ts: now };
  }
  if (!_solisCache.data) return res.status(502).json({ error: 'solis indisponível' });
  res.json(_solisCache.data);
});
// Endpoints separados por sistema — matching o padrão do /api/solar-status
// (Catalão). Cada um retorna 1 sistema + sunrise/sunset local.
// ── Cloudflare Tunnel ────────────────────────────────────────────────────────
// Substituiu o Funnel do Tailscale como porta de entrada de tudo que é HTTP.
// Se ele cai, os links compartilhados, o app e o HA remoto caem juntos — então
// vale a mesma vigilância que as usinas têm.
//
// Duas fontes independentes, porque cada uma mente de um jeito diferente:
//  • processo local vivo (launchd) — mas pode estar vivo e desconectado
//  • a API da Cloudflare, que devolve o status oficial e as conexões de edge
// homedir() inline: HOME_DIR só é declarado bem mais abaixo no arquivo e um
// const em TDZ aqui derrubaria o boot.
const CF_DIR         = path.join(require('os').homedir(), '.cloudflared');
const CF_CONFIG      = path.join(CF_DIR, 'malha.yml');
const CF_TOKEN_FILE  = path.join(CF_DIR, 'cf-api-token');
const CF_ACCOUNT_ID  = process.env.CF_ACCOUNT_ID || '2aff246feca922d7d668f8c9ef9e6f8c';
const CF_CACHE_MS    = 45_000;
let _cfCache = { ts: 0, data: null };

function _cfTunnelIdFromConfig() {
  try {
    const m = fs.readFileSync(CF_CONFIG, 'utf8').match(/^tunnel:\s*([0-9a-f-]{36})/m);
    return m ? m[1] : null;
  } catch (_) { return null; }
}

// Hostnames que o túnel serve, lidos da própria config — sem lista duplicada
// aqui que sairia de sincronia quando o ingress mudar.
function _cfHostnames() {
  try {
    return [...fs.readFileSync(CF_CONFIG, 'utf8').matchAll(/^\s*-\s*hostname:\s*(\S+)/gm)].map(m => m[1]);
  } catch (_) { return []; }
}

function _cfProcess() {
  try {
    const { execFileSync } = require('child_process');
    const out = execFileSync('pgrep', ['-f', 'cloudflared.*malha.yml'], { encoding: 'utf8', timeout: 3000 }).trim();
    const pid = parseInt(out.split('\n')[0], 10);
    if (!pid) return { running: false };
    let etime = null;
    try {
      etime = execFileSync('ps', ['-o', 'etime=', '-p', String(pid)], { encoding: 'utf8', timeout: 3000 }).trim();
    } catch (_) {}
    return { running: true, pid, uptime: etime };
  } catch (_) { return { running: false }; }
}

async function _cfApiTunnel(tunnelId) {
  let token = '';
  try { token = fs.readFileSync(CF_TOKEN_FILE, 'utf8').trim(); } catch (_) {}
  if (!token || !tunnelId) return null;
  try {
    const r = await fetch(`https://api.cloudflare.com/client/v4/accounts/${CF_ACCOUNT_ID}/cfd_tunnel/${tunnelId}`,
                          { headers: { Authorization: `Bearer ${token}` }, signal: AbortSignal.timeout(8000) });
    const j = await r.json();
    if (!j.success) return { error: (j.errors || []).map(e => e.code).join(',') || 'api falhou' };
    const t = j.result || {};
    return {
      name: t.name || null,
      status: t.status || null,              // healthy | degraded | down | inactive
      connections: (t.connections || []).length,
      // Onde os túneis estão ancorados: útil pra ver rota ruim (ex. saiu de gru).
      colos: [...new Set((t.connections || []).map(c => c.colo_name).filter(Boolean))],
    };
  } catch (e) { return { error: String(e.message || e).slice(0, 80) }; }
}

app.get('/api/cloudflare-status', async (_req, res) => {
  const now = Date.now();
  if (_cfCache.data && (now - _cfCache.ts) < CF_CACHE_MS) return res.json(_cfCache.data);
  const tunnelId = _cfTunnelIdFromConfig();
  const [proc, api] = [_cfProcess(), await _cfApiTunnel(tunnelId)];
  const data = {
    tunnel_id: tunnelId,
    process: proc,
    api,
    hostnames: _cfHostnames(),
    // Aqui é o card do SERVIDOR no monitor, então mostra o nome do servidor —
    // _shareBaseUrl() devolveria carro.malha.dev, que é o dos links de trajeto.
    public_url: (process.env.BRIDGE_PUBLIC_URL || 'https://bridge.malha.dev').replace(/\/+$/, ''),
    car_url: _shareBaseUrl(),
    ts: now,
  };
  _cfCache = { ts: now, data };
  res.json(data);
});

// ── GET /api/monitor-glance — o resumo que cabe num widget ───────────────────
// /api/health tem 117 KB e a página o busca a cada 5s: serve pra tela, não pra
// widget no celular (bateria, 4G, e o iOS orça tempo de execução do timeline).
// Aqui saem só os números do relance, < 1 KB.
//
// A severidade NÃO é recalculada: vem dos alertas que o bridge já mantém. A
// triagem da página é rollup de cor no cliente; duplicar aquele critério aqui
// criaria a terceira régua pro mesmo fato, que é o erro que essa base já cometeu
// Totais de uma usina, seja qual for o formato. Catalão (SAJ) guarda o agregado
// em `.plant` e as Solis guardam na raiz — ler só a raiz devolvia null pro
// Catalão, e o `?? 0` pintava 0,00 kW com os inversores em 16,9 kW (13/09).
// null aqui significa "sem leitura", e quem desenha tem que dizer isso, não 0.
function _plantTotals(p) {
  if (!p) return null;
  const a = p.plant || p;
  const w = a.pv_power ?? a.ac_power_w ?? null;
  return { kw:  w == null ? null : w / 1000,
           kwh: a.energy_today ?? a.gen_today_kwh ?? null,
           online: a.online };
}
// várias vezes.
app.get('/api/monitor-glance', requireAuth, (_req, res) => {
  const now = Date.now();
  const firing = [];
  for (const [id, v] of _alertState) {
    if (!v || !v.firing) continue;
    const agentOwned = AGENT_OWNED.has(id);
    // urgent/high = vermelho. AGENT_OWNED cai pra amarelo mesmo em high: o agente
    // ainda vai verificar ao vivo antes de afirmar, e é assim que o push já trata.
    const sev = (!agentOwned && (v.priority === 'urgent' || v.priority === 'high')) ? 'crit' : 'warn';
    firing.push({ id, title: v.title || id, sev, agent_owned: agentOwned, since_ms: v.firedAt || null });
  }
  firing.sort((a, b) => (a.sev === b.sev ? (a.since_ms || 0) - (b.since_ms || 0) : a.sev === 'crit' ? -1 : 1));
  const crit = firing.filter(f => f.sev === 'crit').length;
  const warn = firing.length - crit;

  const tot  = [_solarState, _solisState?.ivonei, _solisState?.palmeiras].map(_plantTotals).filter(Boolean);
  const some = (k) => { const v = tot.map(t => t[k]).filter(x => x != null);
                        return v.length ? v.reduce((a, x) => a + x, 0) : null; };
  const kw = some('kw'), kwh = some('kwh');

  res.json({
    ts: now,
    state: crit ? 'crit' : warn ? 'warn' : 'ok',
    crit, warn,
    worst: firing[0] ? { title: firing[0].title, sev: firing[0].sev, since_ms: firing[0].since_ms } : null,
    alerts: firing.slice(0, 5),
    solar: { kw: kw == null ? null : +kw.toFixed(1),
             kwh_today: kwh == null ? null : +kwh.toFixed(1), plants: tot.length },
    car: { awake: _carIsAwake(), apk_age_ms: state.last_apk_ms ? now - state.last_apk_ms : null },
    bridge: { uptime_sec: Math.round(process.uptime()) },
  });
});

let _spAddr = { key: null, txt: null };   // endereço da Song Pro, resolvido em background

// ── GET /api/wall/detail — o número da parede, aberto ────────────────────────
// A parede mostra UM número por coisa. Este endpoint responde "de onde saiu?":
// devolve as leituras cruas que produziram aquele número, com unidade e idade.
// Existe pra o clique não virar um dump de JSON de 117KB nem uma segunda página
// que precisa ser mantida em paralelo.
app.get('/api/wall/detail', requireAuth, (req, res) => {
  const k = String(req.query.k || '');
  const now = Date.now();
  const idade = (ts) => ts ? Math.round((now - ts) / 60000) + ' min' : 'sem registro';
  const R = [];
  const add = (rot, val, nota) => R.push({ k: rot, v: val == null ? '—' : String(val), n: nota || null });

  const [tipo, alvo] = k.split(':');

  if (tipo === 'plant') {
    const cfgs = {
      catalao:   { t: 'Catalão (SAJ)',  p: _solarState, agg: (p) => p.plant || {}, tk: 'temperature' },
      ivonei:    { t: 'Ivonei (Solis)', p: _solisState?.ivonei,    agg: (p) => p, tk: 'temperature_c' },
      palmeiras: { t: 'Palmeiras (Solis)', p: _solisState?.palmeiras, agg: (p) => p, tk: 'temperature_c' },
    };
    const c = cfgs[alvo];
    if (!c || !c.p) return res.status(404).json({ error: 'usina desconhecida' });
    const a = c.agg(c.p);
    // Somas de float acumulam cauda (1040.3000000000002): arredonda na saída.
    const kwh = (v, d = 1) => v == null ? null : `${(+v).toFixed(d)} kWh`;
    add('Potência agora', (a.pv_power ?? a.ac_power_w) != null ? `${Math.round(a.pv_power ?? a.ac_power_w)} W` : null);
    add('Gerado hoje',  kwh(a.energy_today ?? a.gen_today_kwh),
        c.p.gen_today_src ? `fonte: ${c.p.gen_today_src}` : null);
    // Catalão (SAJ) chama de energy_month/energy_total; Solis, de gen_*_kwh.
    add('Gerado no mês', kwh(a.energy_month ?? a.gen_month_kwh));
    add('Acumulado', kwh(a.energy_total ?? a.gen_total_kwh, 0));
    const exp = c.p.expected;
    add('Esperado nesta hora', exp?.median_power != null ? `${exp.median_power} W` : null,
        exp ? `mediana de ${exp.samples} dias` : 'histórico insuficiente');
    if (c.p.invs_total != null)
      add('Inversores reportando', `${c.p.invs_reporting} de ${c.p.invs_total}`);
    // Ventilador (só o Ivonei). Três linhas porque são três perguntas
    // diferentes: está ligado, desde quando, e está realmente girando.
    const v = c.p.ventilador;
    if (v) {
      const desde = v.desde_ms
        ? `${new Date(v.desde_ms).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit',
            hour: '2-digit', minute: '2-digit' })} · há ${idade(v.desde_ms)}`
        : null;
      add('Ventilador', v.ligado == null ? 'sem leitura' : (v.ligado ? 'ligado' : 'desligado'),
          v.ligado == null ? (v.erro || null) : desde);
      if (v.ligado) {
        // A tomada dizer "on" não prova que o ar está se movendo: o motor pode
        // ter queimado com o socket ligado. O consumo é que prova.
        add('Consumo do ventilador', v.watts != null ? `${v.watts.toFixed(0)} W` : null,
            v.watts == null ? 'tomada sem medição agora'
            : v.girando ? 'girando' : 'LIGADO SEM CONSUMO — ventilador parado');
      }
      add('Regra', 'liga >50 °C por 5min · desliga <45 °C por 15min',
          'e desliga às 18h de todo jeito');
    }
    for (const i of (c.p.invs || [])) {
      add(i.label, [
        // SAJ chama de `power`, Solis de `ac_power_w`.
        (i.ac_power_w ?? i.power) != null ? `${i.ac_power_w ?? i.power} W` : 'sem leitura',
        i[c.tk] != null ? `${(+i[c.tk]).toFixed(1)} °C` : null,
        i.gen_today_kwh != null ? `${(+i.gen_today_kwh).toFixed(1)} kWh` : null,
      ].filter(Boolean).join(' · '), [i.collector, i.status].filter(Boolean).join(' / ') || null);
    }
    add('Leitura de', idade(c.p.ts || _solarState?.ts));
    return res.json({ title: c.t, rows: R });
  }

  if (tipo === 'bat') {
    const b = _bluettiState?.[alvo];
    if (!b) return res.status(404).json({ error: 'estação desconhecida' });
    add('Bateria', b.battery_pct != null ? `${b.battery_pct} %` : null);
    add('Na bateria?', b.offgrid == null ? 'ainda medindo' : (b.offgrid ? 'SIM — descarregando' : 'não'),
        'grid=0 só conta com bateria caindo ou <100%');
    add('Entrada da rede', b.grid_in_w != null ? `${b.grid_in_w} W` : null);
    add('Entrada solar', b.pv_in_w != null ? `${b.pv_in_w} W` : null);
    add('Saída AC', `${b.ac_out_w ?? '—'} W`, b.ac_on === false ? 'DESLIGADA' : null);
    add('Saída DC', `${b.dc_out_w ?? '—'} W`, b.dc_on === false ? 'desligada' : null);
    add('Autonomia', b.battery_time_min ? `${b.battery_time_min} min` : null,
        b.offgrid ? null : 'só significa algo descarregando');
    add('Modo', b.working_mode);
    add('Comunicação', b.reachable ? 'ok' : 'sem comunicação');
    return res.json({ title: `Bluetti ${b.label || alvo}`, rows: R });
  }

  if (tipo === 'car') {
    if (alvo === 'songpro') {
      const sp = songProStatus();
      add('Bateria', sp.soc != null ? `${sp.soc} %` : null);
      add('Carregando', sp.charging ? 'sim' : 'não');
      if (sp.charging) {
        add('Potência', `${sp.powerKw} kW`);
        add('Nesta sessão', `${sp.sessionKwh} kWh`);
        add('Falta', `${sp.remainingMin} min`);
      }
      if (sp.finished) add('Última recarga', `${sp.finishedKwh} kWh → ${sp.finishedSoc}%`, idade(sp.finishedAtMs));
      const pt = _songProTrail[_songProTrail.length - 1];
      add('Onde está', _spAddr.txt || (pt ? 'resolvendo endereço…' : null),
          pt ? `${pt.lat.toFixed(5)}, ${pt.lng.toFixed(5)}` : null);
      add('Leitura de', idade(sp.updatedAtMs));
      return res.json({ title: 'BYD Song Pro (Grasi)', rows: R });
    }
    add('Bateria', state.soc_pct != null ? `${state.soc_pct} %` : null);
    add('Carregando', state.charging_state === 'Carregando' ? 'sim' : (state.charging_state || 'não'));
    add('Potência de recarga', state.charge_power_kw != null ? `${state.charge_power_kw} kW` : null);
    add('Acordado', _carIsAwake() ? 'sim' : 'não');
    add('Onde está', String(state.current_address || '').replace(/,\s*\d{5}-?\d{3}\s*$/, '') || null,
        (state.gps_lat != null && state.gps_lng != null)
          ? `${(+state.gps_lat).toFixed(5)}, ${(+state.gps_lng).toFixed(5)}` : null);
    add('Última publicação do APK', idade(state.last_apk_ms));
    add('Última leitura da GWM', idade(state.last_gwm_ms));
    return res.json({ title: 'Haval H6 GT', rows: R });
  }

  if (tipo === 'ocorrencias') {
    // "15x Catalão sem comunicação" só vira acionável com os HORÁRIOS: é o
    // padrão (madrugada? sempre na mesma hora?) que diz o que investigar.
    const corte = now - 7 * 86400_000;
    const quais = _healthEvents.filter(e => e.type === alvo && e.ts >= corte).reverse();
    for (const e of quais.slice(0, 60)) {
      const d = new Date(e.ts);
      add(d.toLocaleString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit',
                                      hour: '2-digit', minute: '2-digit' }),
          String(e.msg || '').split(':').slice(1).join(':').trim().slice(0, 110) || '—');
    }
    if (!quais.length) add('sem registro', 'nada nos últimos 7 dias');
    const titulo = (_alertState.get(alvo)?.title) || alvo;
    return res.json({ title: `${titulo} · ${quais.length}x em 7 dias`, rows: R });
  }

  if (tipo === 'eventos') {
    // Log dos últimos 7 dias, agrupando repetição consecutiva do mesmo tipo.
    // Só sob demanda: no payload do ciclo isto seriam dezenas de KB a cada 2s.
    const corte = now - 7 * 86400_000;
    const linhas = [];
    for (const e of _healthEvents.slice().reverse()) {
      if (e.ts < corte) break;
      const ult = linhas[linhas.length - 1];
      if (ult && ult.tipo === e.type) { ult.n++; continue; }
      linhas.push({ tipo: e.type, ts: e.ts, n: 1,
                    msg: String(e.msg || '').split('\n')[0].slice(0, 120) });
      if (linhas.length >= 120) break;
    }
    for (const l of linhas) {
      const d = new Date(l.ts);
      add(d.toLocaleString('pt-BR', { day: '2-digit', month: '2-digit',
                                      hour: '2-digit', minute: '2-digit' }),
          l.msg, l.n > 1 ? `${l.n}x` : null);
    }
    if (!linhas.length) add('sem eventos', 'nada registrado em 7 dias');
    return res.json({ title: `Eventos · 7 dias (${linhas.length})`, rows: R });
  }

  if (tipo === 'host') {
    const m = _macStats || {};
    const gb = (v) => v == null ? null : `${Math.round(v)} GB`;
    add('No ar há', m.uptime_sec ? `${Math.floor(m.uptime_sec / 86400)}d ${Math.round(m.uptime_sec % 86400 / 3600)}h` : null);
    if (m.disk) add('Disco interno', `${gb(m.disk.total_gb - m.disk.avail_gb)} de ${gb(m.disk.total_gb)}`,
                    `${gb(m.disk.avail_gb)} livres`);
    if (m.disk_ext) add('SSD externo', m.disk_ext.mounted
      ? `${gb(m.disk_ext.total_gb - m.disk_ext.avail_gb)} de ${gb(m.disk_ext.total_gb)}` : 'NÃO MONTADO',
      m.disk_ext.mounted ? `${gb(m.disk_ext.avail_gb)} livres · ${m.disk_ext.path}` : null);
    if (m.mem) add('Memória', `${(m.mem.total_gb - m.mem.avail_gb).toFixed(1)} de ${m.mem.total_gb} GB`,
                   `${m.mem.avail_gb} GB livres`);
    add('Bridge (RSS)', process.memoryUsage ? `${Math.round(process.memoryUsage().rss / 1048576)} MB` : null);
    if (_netBw) add('Rede', `↓${_netBw.rx_kbps} ↑${_netBw.tx_kbps} kbps`,
                    `${_netBw.link_type} ${_netBw.link_mbps} Mbps`);
    add('IP público', _netStatus?.public_ip, _netStatus?.match === false ? 'DNS divergente' : null);
    add('Certificado', _certStatus?.days_left != null ? `${_certStatus.days_left} dias` : null);
    // Quem está comendo memória: é a pergunta seguinte quando a barra sobe.
    for (const t of (m.top_mem || []).slice(0, 4)) add(t.name, `${t.mb} MB`);
    return res.json({ title: 'Mac Mini', rows: R });
  }

  if (tipo === 'svc') {
    const nome = alvo;
    if (/^Delega/.test(nome)) {
      for (const d of _delega) add(d.label, d.up ? 'no ar' : 'fora',
        d.open_tasks != null ? `${d.open_tasks} abertas` : d.url);
    } else if (/^Assist/.test(nome)) {
      for (const l of _lari) add(l.user || '?',
        l.up ? (l.connected === false ? 'no ar, WhatsApp DESCONECTADO' : 'no ar e conectada') : 'fora',
        l.url || null);
    } else if (/^Gastos/.test(nome)) {
      for (const x of _pixbot) add(x.label, x.up ? 'no ar' : 'fora', x.url || null);
    } else if (/^Recados/.test(nome)) {
      // Uma seção por instância: dois números, e o detalhe precisa dizer de
      // QUAL deles se está falando.
      for (const r of _recadosLista) {
        const w = r.wa || {};
        const pre = _recadosLista.length > 1 ? `${r.rotulo || '?'} · ` : '';
        add(`${pre}Serviço`, r.up ? 'no ar' : 'fora', r.error || null);
        add(`${pre}WhatsApp`, w.conectado ? 'pareado' : 'DESPAREADO',
            w.numero || w.erro || 'reparear no painel');
        add(`${pre}Contatos`, r.contatos ?? null,
            r.contatos ? null : 'sincroniza no pareamento');
        add(`${pre}Agendados`, r.agendados ?? 0,
            r.proximo_ms ? 'próximo ' + new Date(r.proximo_ms).toLocaleString('pt-BR',
              { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : null);
        // Atrasado e repetindo só aparecem quando existem: linha zerada ocupa
        // espaço na parede sem dizer nada.
        if (r.atrasados) add(`${pre}Atrasados`, r.atrasados, 'passaram da hora e não saíram');
        if (r.repetindo) add(`${pre}Repetindo`, r.repetindo, 'tentando de novo');
        add(`${pre}Últimos 7 dias`, `${r.enviados_7d ?? 0} enviados`,
            r.nao_entregues_7d ? `${r.nao_entregues_7d} não entregues` : null);
      }
      // Janela de entrega foi removida em 20/09/2026: recado sai na hora marcada.
    } else if (/Driver Cred/.test(nome)) {
      add('Estado', _credito?.up ? 'no ar' : 'fora', _credito?.url || null);
      const vg = _credito?.vigia, fl = vg && vg.fila;
      if (vg?.erro) add('Resumo do vigia', 'indisponível', vg.erro);
      if (fl) {
        add('Fila de envio', `${fl.pendentes} pendente${fl.pendentes === 1 ? '' : 's'}`,
            fl.ficam ? `${fl.ficam} não fecham hoje` : 'fecham hoje');
        add('Espera do mais antigo', fl.espera_min != null
          ? (fl.espera_min >= 60 ? `${Math.floor(fl.espera_min / 60)}h${String(fl.espera_min % 60).padStart(2, '0')}` : `${fl.espera_min} min`)
          : null);
        add('Enviadas hoje', `${fl.enviadas} de ${fl.teto}`, `ritmo ${fl.ritmo}/h`);
        // A API oficial saiu de operação (banida); quem entrega é o canal
        // alternativo, então é o estado dele que se mostra.
        add('Canal de envio', fl.ligado ? 'alternativo, ligado' : 'alternativo DESLIGADO',
            fl.silencio ? 'em janela de silêncio' : null);
        if (fl.gargalo) add('Gargalo', fl.gargalo === 'teto' ? 'teto diário' : 'tempo até o silêncio');
      }
      for (const a of (vg?.achados || [])) add(a.urgente ? '⚠️ pendência' : 'pendência', a.titulo);
    } else if (/Home Assistant/.test(nome)) {
      add('Estado', _haStatus.up ? 'no ar' : 'fora', _haStatus.error || null);
      add('Latência', _haStatus.latency_ms != null ? `${_haStatus.latency_ms} ms` : null);
      add('Verificado', idade(_haStatus.checked_at));
    } else if (/MQTT/.test(nome)) {
      add('Cliente do bridge', mqttClient?.connected ? 'conectado' : 'desconectado');
      for (const [porta, ok] of [[1883, _mqttBrokerStatus.port1883], [1884, _mqttBrokerStatus.port1884], [8883, _mqttBrokerStatus.port8883]])
        add(`Porta ${porta}`, ok == null ? null : (ok ? 'escutando' : 'fechada'));
    } else if (/Outros/.test(nome)) {
      const ja = new Set(['bridge','assinador','gwm-bridge','ellevar-clockin','ecotrip-gateway',
        'credito','delega','delega-deivid','pixbot-renan','pixbot-rafael','pixbot-teste']);
      for (const p of _processes.filter(p => !ja.has(p.name)))
        add(p.name, p.status, `${p.mem_mb} MB · ${p.restarts} restarts`);
    } else {
      const p = _processes.find(x => new RegExp(nome.split(' ')[0], 'i').test(x.name));
      if (p) { add('Processo', p.name); add('Estado', p.status);
               add('Memória', `${p.mem_mb} MB`); add('Restarts', p.restarts);
               add('No ar há', Math.round(p.uptime_sec / 3600) + ' h'); }
      else add('Estado', 'sem detalhe adicional');
    }
    return res.json({ title: nome, rows: R });
  }

  res.status(400).json({ error: 'chave desconhecida' });
});

// ── GET /api/wall — o que a tela de parede precisa ───────────────────────────
// Separado do /api/monitor-glance (191B, orçado pro widget do iOS) e do
// /api/health (117KB, pra investigação). Aqui é o meio: o suficiente pra encher
// uma tela vista de longe, sem carregar o payload inteiro a cada 2s.
//
// `pulse_ms` existe pra animação ser HONESTA: a tela só pulsa quando um desses
// timestamps muda, ou seja, um pulso = uma publicação real observada. Animação em
// loop numa tela de monitoramento é mentira bonita — dá sensação de vida com o
// sistema morto, que é exatamente o oposto do que a página serve.
app.get('/api/wall', requireAuth, (_req, res) => {
  const now = Date.now();
  const firing = [];
  for (const [id, v] of _alertState) {
    if (!v || !v.firing) continue;
    const ao = AGENT_OWNED.has(id);
    // Alerta que TEM ação carrega o link: aviso sem o que fazer só transfere o
    // trabalho. O reauth da Bluetti era o caso — dizia "refazer login" e o botão
    // vivia escondido dentro de um bloco recolhido do health.
    const acao = id === 'bluetti_cloud_reauth' ? _bluettiReauthLink() : null;
    firing.push({ id, title: v.title || id,
                  sev: (!ao && (v.priority === 'urgent' || v.priority === 'high')) ? 'crit' : 'warn',
                  since_ms: v.firedAt || null, url: acao });
  }
  firing.sort((a, b) => (a.sev === b.sev ? (a.since_ms || 0) - (b.since_ms || 0) : a.sev === 'crit' ? -1 : 1));
  const crit = firing.filter(f => f.sev === 'crit').length;

  // Limiar de temperatura é POR FABRICANTE: SAJ avisa em 65 e é crítico em 80;
  // Solis avisa em 80 e é crítico em 85 (S6-GR1P6K tem limite 85). A parede
  // usava 65 pra todas e pintava o Ivonei a 67°C de âmbar sendo normal — é a
  // página inventando severidade que o bridge já sabe.
  const tempState = (t, marca) => {
    if (t == null) return null;
    const [w, c] = marca === 'saj' ? [65, 80] : [80, 85];
    return t > c ? 'crit' : t > w ? 'warn' : 'ok';
  };
  // Mediana do ACUMULADO desta hora nos dias anteriores, por usina. É contra
  // isso que "% do normal" tem que comparar: potência instantânea balança com
  // qualquer nuvem passageira, e uma nuvem em cima do tick não diz nada sobre
  // como foi a manhã. `snaps[h].kwh` é o acumulado do dia naquela hora.
  const paceDe = (chave) => {
    const h = new Date().getHours(), hoje = _todayDateStr();
    const vals = (_solarHistory[chave] || [])
      .filter(d => d.date !== hoje)
      .map(d => d.snaps && d.snaps[h] && d.snaps[h].kwh)
      .filter(v => v > 0).sort((a, b) => a - b);
    return vals.length < 3 ? null : +vals[Math.floor(vals.length / 2)].toFixed(1);
  };
  const plant = (p, label, tempKey, marca, chave) => {
    const t = _plantTotals(p);
    if (!t) return null;
    const temps = (p.invs || []).map(i => i[tempKey]).filter(v => v != null);
    // Mediana desta HORA nos últimos 14 dias (null com <3 amostras). É o que
    // transforma "17 kW" em "17 kW é bom?" — a pergunta que a parede responde.
    const exp = p.expected?.median_power;
    // Soma incompleta não se compara com a mediana da planta inteira: seria
    // dizer "58% do normal" de uma planta que está gerando normal.
    const rep = p.invs_reporting, tot = p.invs_total;
    const partial = (rep != null && tot != null && rep > 0 && rep < tot) ? [rep, tot] : null;
    const pace = partial ? null : paceDe(chave);
    return { label, key: chave,
             kw:   t.kw  == null ? null : +t.kw.toFixed(2),
             kwh:  t.kwh == null ? null : +t.kwh.toFixed(1),
             exp_kw: (exp && !partial) ? +(exp / 1000).toFixed(2) : null,
             pace_kwh: pace,
             // Faixa do ritmo, no servidor: a mesma régua vale pra parede, pro
             // widget e pra qualquer outra tela. Cedo no dia o quociente é
             // instável (0,3 vs 0,2 kWh = 150%), então só classifica com massa
             // suficiente — abaixo disso é `null` e ninguém pinta nada.
             pace_state: (() => {
               const k = t.kwh, m = pace;
               if (k == null || !m || m < 2 || k < 2) return null;
               const r = k / m;
               // Faixa "normal" larga de propósito: um dia com nuvens fecha em
               // 85% sem nada de errado, e pintar isso de âmbar todo dia
               // nublado treina a ignorar a cor. Âmbar só quando está mesmo
               // ficando pra trás.
               if (r >= 1.05) return 'acima';
               if (r >= 0.80) return 'normal';
               return r >= 0.55 ? 'abaixo' : 'ruim';
             })(),
             partial,
             temp: temps.length ? Math.max(...temps) : null,
             temp_state: tempState(temps.length ? Math.max(...temps) : null, marca),
             // Só o Ivonei tem ventilador. `undefined` nas outras some do JSON.
             ventilador: p.ventilador || undefined };
  };

  // Endereço da Song Pro: a trilha dá lat/lng, mas o reverse-geocode é async e
  // esta rota é síncrona. Resolve em segundo plano e serve o último conhecido —
  // carro parado não muda de lugar, então o valor "velho" continua certo, e o
  // `_familyGeoMem` evita bater no Nominatim a cada ciclo. O Haval não precisa
  // disso: ele já publica `current_address` pronto.
  const semCep = (a) => a ? String(a).replace(/,\s*\d{5}-?\d{3}\s*$/, '') : null;
  const spEndereco = () => {
    const pt = _songProTrail[_songProTrail.length - 1];
    if (!pt || pt.lat == null || pt.lng == null) return null;
    const k = `${pt.lat.toFixed(4)},${pt.lng.toFixed(4)}`;
    if (k !== _spAddr.key) {
      _spAddr.key = k;                    // mantém o texto anterior enquanto o novo vem
      _reverseGeocodeFamily(pt.lat, pt.lng, null)
        .then(g => { if (_spAddr.key === k) _spAddr.txt = g.label || null; })
        .catch(() => {});
    }
    return _spAddr.txt;
  };

  // Arrays fora do literal: os vereditos de cada nó do desenho derivam deles.
  const plantsArr = [plant(_solarState, 'Catalão', 'temperature', 'saj', 'catalao'),
                     plant(_solisState?.ivonei, 'Ivonei', 'temperature_c', 'solis', 'ivonei'),
                     plant(_solisState?.palmeiras, 'Palmeiras', 'temperature_c', 'solis', 'palmeiras')].filter(Boolean);
  // SOC de carro parado não deriva, então leitura velha continua VERDADEIRA —
  // diferente de potência solar, onde o valor antigo já não descreve o agora.
  // Por isso não vira "—": vai o valor com a idade, e quem desenha diz de quando.
  const carsArr = [
    { key: 'haval', label: 'Haval',
      soc: state.soc_pct != null ? Math.round(+state.soc_pct) : null,
      charging: state.charging_state === 'Carregando',
      power_kw: +state.charge_power_kw || 0,
      awake: _carIsAwake(),
      addr: semCep(state.current_address),
      ts: Math.max(state.last_apk_ms || 0, state.last_gwm_ms || 0) || null },
    (() => {
      const sp = songProStatus();          // BYD Song Pro (Grasi)
      if (!sp.hasData) return null;
      return { key: 'songpro', label: 'Song Pro',
               soc: sp.soc != null ? Math.round(sp.soc) : null,
               charging: !!sp.charging, power_kw: +sp.powerKw || 0,
               awake: null, addr: spEndereco(), ts: sp.updatedAtMs || null };
    })(),
  ].filter(Boolean);
  // Percentual é grandeza LIMITADA (0-100) e vira arco. Autonomia só significa
  // algo descarregando — com a rede presente é número bonito e vazio.
  const batArr = ['casa', 'sitio'].map(k => {
    const b = _bluettiState?.[k];
    if (!b) return null;
    return { key: k, label: b.label || k, pct: b.battery_pct ?? null,
             offgrid: b.offgrid ?? null, grid_w: b.grid_in_w ?? null,
             autonomy_min: b.battery_time_min ?? null,
             reachable: !!b.reachable,
             // Buraco de telemetria: potência toda zerada depois de ter medido.
             sem_potencia_ms: b.power_stale_ms ?? null,
             ultima_potencia: b.ultima_potencia || null };
  }).filter(Boolean);

  const svc = [];
  const push = (nome, ok, det) => svc.push({ nome, ok, det });
  // Família com várias instâncias vira UMA linha enquanto todas concordam, e se
  // separa sozinha assim que uma divergir — nada de informação se perde, e a
  // lista para de gastar 3 linhas pra dizer "os três estão bem".
  const familia = (nome, itens, okDe, detDe) => {
    const arr = itens.filter(Boolean);
    if (!arr.length) return;
    const oks = arr.map(okDe);
    if (arr.length > 1 && oks.every(o => o === oks[0])) {
      const dets = arr.map(detDe).filter(v => v != null);
      const soma = dets.length === arr.length
        ? dets.reduce((a, v) => a + (+v || 0), 0) : null;
      return push(`${nome} ×${arr.length}`, oks[0], soma != null ? `${soma}` : null);
    }
    arr.forEach((x, i) => push(`${nome} ${x.__lbl || i + 1}`, oks[i], detDe(x)));
  };

  push('Home Assistant', _haStatus.up === true, null);
  push('MQTT', !!(mqttClient && mqttClient.connected), null);
  // O status do túnel vive no cache do /api/cloudflare-status; sem leitura ainda,
  // não afirmo que está ruim — ausência de dado não é falha.
  const cf = _cfCache && _cfCache.data;
  push('Cloudflare', cf ? (cf.tunnel_healthy !== false && cf.healthy !== false) : true, null);
  push('Gateway', _gwStatus.up !== false, null);

  familia('Delega', _delega.map(d => ({ ...d, __lbl: d.label })),
          d => !!d.up, d => d.open_tasks ?? null);
  familia('Assist.', _lari.map(l => ({ ...l, __lbl: l.user || '?' })),
          l => !!(l.up && l.connected !== false), () => null);
  // "teste" é instância de desenvolvimento — não é serviço de ninguém.
  familia('Gastos', _pixbot.filter(x => !/teste/i.test(x.label || ''))
                           .map(x => ({ ...x, __lbl: x.label })),
          x => !!x.up, () => null);
  if (_recadosLista.length) {
    // O ponto é "está no ar?", mas há duas falhas que o up/down não pega:
    // serviço vivo com o WhatsApp despareado, e recado que passou da hora e não
    // saiu. As duas fazem o recado de segunda não chegar, então as duas pintam
    // o nó — com DUAS instâncias, basta uma ruim pra tirar o verde.
    const estado = (r) => !r.up ? 'fora'
      : r.wa?.conectado === false ? 'WhatsApp despareado'
      : r.atrasados ? `${r.atrasados} atrasado${r.atrasados > 1 ? 's' : ''}`
      : r.agendados ? `${r.agendados} agendado${r.agendados > 1 ? 's' : ''}` : null;
    const bom = (r) => !!r.up && r.wa?.conectado !== false && !r.atrasados;
    const partes = _recadosLista.map((r) => {
      const e = estado(r);
      return _recadosLista.length > 1 ? `${r.rotulo}: ${e || 'ok'}` : e;
    }).filter(Boolean);
    push('Recados', _recadosLista.every(bom), partes.join(' · ') || null);
  }
  if (_credito) {
    // O ponto continua sendo "está no ar?" — pendência de operação é outro eixo e
    // não pode pintar o serviço de vermelho. Ela vai no detalhe da linha, onde
    // "13 na fila" e "WA bloqueada" respondem o que o up/down não responde.
    // Nada de alerta novo aqui: quem notifica é o próprio app (vigia-saude).
    // `fila.bloqueado` (conta da API oficial da Meta) NÃO entra: a API foi
    // abandonada depois do banimento, então o campo fica `true` pra sempre e
    // avisar disso todo ciclo é ruído, não notícia. O canal em uso é o
    // alternativo — é o estado DELE que vale espaço aqui.
    const vg = _credito.vigia, fl = vg && vg.fila;
    const partes = [];
    if (fl && fl.ligado === false) partes.push('canal alt desligado');
    if (fl?.pendentes)         partes.push(`${fl.pendentes} na fila`);
    if (vg?.achados?.length)   partes.push(`${vg.achados.length} pendência${vg.achados.length > 1 ? 's' : ''}`);
    push('Driver Cred', !!_credito.up, partes.join(' · ') || null);
  }

  // Processos que existem no pm2 e não apareciam em lugar nenhum da parede.
  const proc = (nome, rotulo) => {
    const p = _processes.find(x => x.name === nome);
    if (p) push(rotulo, p.status === 'online', null);
  };
  proc('assinador', 'Assinador');
  proc('gwm-bridge', 'GWM');
  if (_appHealth.clockin?.up != null)
    push('Clockin', _appHealth.clockin.up === true && _appHealth.clockin.healthy !== false, null);
  // Resto do pm2 num rolo só: o que interessa é "algum caiu?", não o nome de
  // cada um. Os já listados acima saem da conta pra não contar duas vezes.
  const jaListados = new Set(['bridge', 'assinador', 'gwm-bridge', 'ellevar-clockin',
    'ecotrip-gateway', 'credito', 'delega', 'delega-deivid',
    'pixbot-renan', 'pixbot-rafael', 'pixbot-teste']);
  const resto = _processes.filter(p => !jaListados.has(p.name));
  if (resto.length) {
    const on = resto.filter(p => p.status === 'online').length;
    push('Outros (pm2)', on === resto.length, `${on}/${resto.length}`);
  }

  // ── nós do desenho: VEREDITO, não estado ────────────────────────────────────
  // "CARRO: dormindo" era tecnicamente certo (_carIsAwake significa EM USO —
  // ignição/marcha; recarga de propósito não conta) e mesmo assim enganava: o
  // Haval estava carregando a 6,2 kW e publicando em tempo real, e quem lia de
  // longe entendia "sem comunicação". Cada nó passa a responder "tem problema
  // aqui?" — e o que cada coisa está fazendo vai no detalhe, onde cabe.
  const idadeMin = (ts) => ts ? Math.round((now - ts) / 60000) : null;
  const quando = (ts) => { const m = idadeMin(ts);
    return m == null ? 'sem registro' : m < 1 ? 'agora' : `há ${m} min`; };
  const nodeDe = (re, det) => {
    const fs = firing.filter(f => re.test(f.id));
    const pior = fs.find(f => f.sev === 'crit') || fs[0];
    return { txt: pior ? pior.title : 'ok',
             sev: pior ? pior.sev : 'ok', n: fs.length, det };
  };
  // O mapa tem que ser EXAUSTIVO: com 5 nós, 22 alertas (starlink, disk, ssd,
  // mem, rss, restarts, backup, icloud) não caíam em nenhum — um problema neles
  // contava no veredito do hub e não acendia nada no desenho, que é justamente
  // onde se olha primeiro. SÍTIO saiu de dentro de CASA (misturava as duas
  // pontas) e MAC entrou pro host, que é onde tudo roda.
  const bat1 = (k) => batArr.find(b => b.key === k);
  const linhaBat = (b) => !b ? null : `${b.label} · ${b.pct == null ? '—' : b.pct + '%'} · ` +
    (!b.reachable ? 'sem comunicação' : b.offgrid === true ? 'na bateria'
     : b.grid_w > 0 ? `${b.grid_w} W da rede` : 'em espera');
  const pctDe = (u, t) => (u && t) ? Math.round(u / t * 100) + '%' : '—';
  const m = _macStats || {};
  const nodes = {
    carro: nodeDe(/^(car|apk)_/, carsArr.flatMap(c => [
      `${c.label} · ${c.soc == null ? '—' : c.soc + '%'} · ` +
      (c.charging ? `carregando ${c.power_kw.toFixed(1).replace(".", ",")} kW`
                  : c.awake === true ? 'em uso' : 'parado') +
      ` · leitura ${quando(c.ts)}`,
      c.addr ? `↳ ${c.addr}` : null,
    ].filter(Boolean))),
    solar: nodeDe(/^(solar|solis|fan)_/, plantsArr.map(p =>
      `${p.label} · ${p.kw == null ? 'sem leitura' : p.kw + ' kW'}` +
      (p.kwh != null ? ` · ${p.kwh} kWh hoje` : '') +
      (p.partial ? ` · parcial (${p.partial[0]}/${p.partial[1]} inv)` : ''))),
    casa: nodeDe(/^(bluetti_casa|ha_down)/, [
      linhaBat(bat1('casa')),
      `Home Assistant · ${_haStatus.up ? 'no ar' : 'fora'}`,
    ].filter(Boolean)),
    // ext_monitor_down é o dead-man's-switch do HA do SÍTIO (ele bate a cada
    // 60s), não um alerta de rede — estava caindo em REDE por causa do prefixo.
    sitio: nodeDe(/^(starlink|bluetti_sitio|ext_monitor)/, (() => {
      const st = starlink.status(), sn = starlink.snapshot();
      const beat = _extMonitorLastBeat
        ? Math.round((Date.now() - _extMonitorLastBeat) / 60000) : null;
      return [
        linhaBat(bat1('sitio')),
        !st.configured ? 'Starlink · não configurado'
          : `Starlink · ${sn.ok ? 'respondendo' : 'sem resposta'}` +
            (st.stale_s != null ? ` · leitura há ${Math.round(st.stale_s / 60)} min` : ''),
        // Batida do HA do sítio: é ele quem prova que o sítio inteiro está vivo.
        beat == null ? 'HA do sítio · nunca bateu'
          : `HA do sítio · batida ${beat < 1 ? 'agora' : 'há ' + beat + ' min'}`,
      ].filter(Boolean);
    })()),
    mac: nodeDe(/^(disk|ssd|mem_|rss|restarts|backup|icloud)/, [
      m.disk ? `Disco · ${pctDe(m.disk.total_gb - m.disk.avail_gb, m.disk.total_gb)} · ${Math.round(m.disk.avail_gb)} GB livres` : null,
      m.disk_ext ? `SSD 1TB · ${m.disk_ext.mounted ? pctDe(m.disk_ext.total_gb - m.disk_ext.avail_gb, m.disk_ext.total_gb) : 'NÃO MONTADO'}` : null,
      m.mem ? `Memória · ${pctDe(m.mem.total_gb - m.mem.avail_gb, m.mem.total_gb)}` : null,
      `Backups · ${(_backups || []).filter(b => b.ok !== false).length}/${(_backups || []).length} em dia`,
      m.uptime_sec ? `No ar há ${Math.floor(m.uptime_sec / 86400)}d` : null,
    ].filter(Boolean)),
    apps: nodeDe(/^(delega|lari|pixbot|credito|apns|recados)/,
      // Ancorado: /Assist/ solto casava com 'Home Assistant'.
      svc.filter(x => /^(Delega|Assist\.|Gastos|Driver Cred|Clockin|Recados)/.test(x.nome))
         .map(x => `${x.nome} · ${x.ok ? 'no ar' : 'FORA'}${x.det ? ' · ' + x.det : ''}`)),
    rede: nodeDe(/^(mqtt|cf|dns|funnel|gw_|ts_|local_|broker|cert)/,
      svc.filter(x => /Home Assistant|MQTT|Cloudflare|Gateway/.test(x.nome))
         .map(x => `${x.nome} · ${x.ok ? 'ok' : 'FORA'}`)),
  };

  res.json({
    ts: now,
    state: crit ? 'crit' : firing.length ? 'warn' : 'ok',
    crit, warn: firing.length - crit,
    alerts: firing.slice(0, 4),
    plants: plantsArr,
    car: { awake: _carIsAwake(),
           soc: state.soc_pct != null ? +state.soc_pct : null,
           charging: state.charging_state === 'Carregando',
           power_kw: state.charge_power_kw != null ? +state.charge_power_kw : null,
           apk_ms: state.last_apk_live_ms || state.last_apk_ms || null,
           gwm_ms: state.last_gwm_ms || null },
    cars: carsArr,
    bat: batArr,
    nodes,
    // Curva de hoje por usina: 1 amostra por hora, que é o que _solarHistory já
    // guarda. Não é gráfico de precisão — é pra enxergar a forma do dia de longe.
    // Curva de hoje: POTÊNCIA (linha) e ENERGIA DA HORA (barras) juntas.
    //
    // Só a potência não bastava: `snaps[h]` é UMA amostra, tirada no começo da
    // hora. Uma nuvem às 11:00 em ponto derruba a barra da hora inteira e parece
    // queda de geração. E só a energia também engana: a hora corrente está pela
    // metade e sempre aparece menor que a anterior — foi o que se viu às 11:15.
    //
    // Energia DA hora h = acumulado no início de h+1 menos o do início de h. Na
    // hora corrente não existe "próxima", então usa o total de agora e marca
    // `parcial` — quem desenha tem que dizer que ela ainda não fechou.
    // Por usina E somado: a parede abre no total, e clicar numa usina no rodapé
    // filtra os dois gráficos pra ela. Mesma função pros dois casos — série de
    // uma usina é só a série de uma lista de uma usina só.
    spark: (() => {
      const hoje = _todayDateStr();
      const serie = (chaves) => {
        const porHora = {};
        for (const k of chaves) {
          const dia = (_solarHistory[k] || []).find(d => d.date === hoje);
          for (const [hs, sn] of Object.entries(dia?.snaps || {})) {
            const h = +hs;
            if (!porHora[h]) porHora[h] = { kw: 0, cum: 0 };
            porHora[h].kw  += (sn.p || 0) / 1000;
            porHora[h].cum += (sn.kwh || 0);
          }
        }
        const alvo = plantsArr.filter(p => chaves.includes(p.key));
        const totalAgora = alvo.reduce((a, p) => a + (p.kwh || 0), 0);
        const kwAgora    = alvo.reduce((a, p) => a + (p.kw  || 0), 0);
        const hs = Object.keys(porHora).map(Number).sort((a, b) => a - b);
        return hs.map((h, i) => {
          const ultima = i === hs.length - 1;
          const prox = ultima ? totalAgora : porHora[hs[i + 1]].cum;
          return { h,
                   // Na hora corrente a potência do início já é velha: vale a de agora.
                   kw: +(ultima ? kwAgora : porHora[h].kw).toFixed(2),
                   kwh: Math.max(0, +(prox - porHora[h].cum).toFixed(2)),
                   parcial: ultima };
        });
      };
      const todas = ['catalao', 'ivonei', 'palmeiras'];
      return Object.fromEntries([['total', serie(todas)], ...todas.map(k => [k, serie([k])])]);
    })(),
    // Últimos 14 dias, somando as 3 usinas por data. O "121% do normal" de hoje
    // só quer dizer algo contra a série — e um dia ruim isolado vira nuvem, três
    // seguidos viram problema. Dia sem registro de alguma usina soma o que há.
    daily: (() => {
      const serie = (chaves) => {
        const acc = {};
        for (const k of chaves)
          for (const dia of (_solarHistory[k] || []).slice(-31))
            acc[dia.date] = (acc[dia.date] || 0) + (dia.kwh || 0);
        return Object.keys(acc).sort().slice(-30)
                 .map(date => ({ date, kwh: +acc[date].toFixed(1) }));
      };
      const todas = ['catalao', 'ivonei', 'palmeiras'];
      return Object.fromEntries([['total', serie(todas)], ...todas.map(k => [k, serie([k])])]);
    })(),
    // O Mac Mini é onde TUDO roda e não aparecia em lugar nenhum da parede. Disco
    // interno em 89% não dispara alerta ainda, mas é exatamente o tipo de coisa
    // que só se nota tarde — um painel ambiente existe pra isso.
    host: {
      uptime_sec: _macStats?.uptime_sec ?? null,
      mem:      _macStats?.mem      ? { usado: +(_macStats.mem.total_gb - _macStats.mem.avail_gb).toFixed(1),
                                        total: _macStats.mem.total_gb } : null,
      disco:    _macStats?.disk     ? { usado: +(_macStats.disk.total_gb - _macStats.disk.avail_gb).toFixed(0),
                                        total: _macStats.disk.total_gb } : null,
      ssd:      _macStats?.disk_ext?.mounted
                  ? { usado: +(_macStats.disk_ext.total_gb - _macStats.disk_ext.avail_gb).toFixed(0),
                      total: _macStats.disk_ext.total_gb } : null,
      rx_kbps:  _netBw?.rx_kbps ?? null,
      tx_kbps:  _netBw?.tx_kbps ?? null,
      link:     _netBw?.link_type ?? null,
      cert_dias: _certStatus?.days_left ?? null,
    },
    // Backup é a falha mais silenciosa que existe: some e ninguém percebe até
    // precisar. Cada um tem o próprio prazo (`max_age_h`), então a régua é essa,
    // não um número fixo.
    backups: (_backups || []).map(b => ({
      nome: b.name, ok: b.ok !== false,
      horas: b.age_hours != null ? +b.age_hours.toFixed(1) : null,
      limite: b.max_age_h ?? null,
    })),
    // Ritmo do dia. Comparar o dia PELA METADE com a mediana do dia INTEIRO dá
    // ~40% às 11h e assusta à toa — o dia não acabou. A comparação honesta é
    // contra a mediana ACUMULADA NESTA MESMA HORA nos dias anteriores, que é
    // exatamente o que `snaps[h].kwh` guarda. null com menos de 3 amostras.
    pace: (() => {
      const h = new Date().getHours(), hoje = _todayDateStr(), porDia = {};
      for (const k of ['catalao', 'ivonei', 'palmeiras'])
        for (const d of (_solarHistory[k] || []).slice(-31)) {
          const sn = d.snaps && d.snaps[h];
          if (sn && sn.kwh > 0) porDia[d.date] = (porDia[d.date] || 0) + sn.kwh;
        }
      const passados = Object.entries(porDia).filter(([dt]) => dt !== hoje)
                         .map(([, v]) => v).sort((a, b) => a - b);
      if (passados.length < 3) return null;
      return { hour: h, samples: passados.length,
               median_kwh: +passados[Math.floor(passados.length / 2)].toFixed(1) };
    })(),
    // O que deu trabalho na SEMANA. Um painel de estado atual responde "está
    // tudo bem agora?"; isto responde "o que anda quebrando?", que é outra
    // pergunta e não aparece em lugar nenhum hoje. Recuperações e restarts ficam
    // de fora: o que interessa é quantas vezes o problema ACONTECEU.
    // Faixa das últimas 24h por família: uma célula por hora, cor = pior coisa
    // que aconteceu naquela hora. Responde "estava tudo bem enquanto eu não
    // olhava?" sem um único número — que é o que a lista de eventos respondia
    // gastando vinte linhas.
    faixa24: (() => {
      // "Apps" é genérico demais numa parede: saber que "um app" caiu às 3h não
      // diz nada. Cada app vira sua PRÓPRIA linha, e só as que tiveram evento
      // aparecem — senão seriam seis linhas vazias todo dia.
      const APPS = [
        ['delega',  /^delega/,  'Delega'],
        ['lari',    /^lari/,    'Assistentes'],
        ['pixbot',  /^pixbot/,  'Gastos'],
        ['credito', /^credito/, 'Driver Cred'],
        ['apns',    /^apns/,    'APNs'],
        ['recados', /^recados/, 'Recados'],
      ];
      const FAM = [
        ['carro', /^(car|apk)_/, 'Carro'], ['solar', /^(solar|solis|fan)_/, 'Solar'],
        ['casa', /^(bluetti_casa|ha_down)/, 'Casa'],
        ['sitio', /^(starlink|bluetti_sitio|ext_monitor)/, 'Sítio'],
        ['mac', /^(disk|ssd|mem_|rss|restarts|backup|icloud)/, 'Mac'],
        ...APPS,
        ['rede', /^(mqtt|cf|dns|funnel|gw_|ts_|local_|broker|cert)/, 'Rede'],
      ];
      const H = 24, agoraH = Math.floor(now / 3600_000);
      const grade = {}, detalhe = {};
      for (const [f] of FAM) grade[f] = new Array(H).fill(0);   // 0=quieto
      for (const e of _healthEvents) {
        const h = Math.floor(e.ts / 3600_000);
        const i = H - 1 - (agoraH - h);
        if (i < 0 || i >= H) continue;
        // `_recovery` é boa notícia e não pinta a hora; restart pinta, porque é
        // a coisa que passa despercebida e explica buraco em gráfico.
        if (/_recovery$/.test(e.type)) continue;
        const sev = /crit|urgent/i.test(e.msg || '') ? 2 : 1;
        for (const [f, re] of FAM) {
          if (re.test(e.type) || (f === 'mac' && e.type === 'restart')) {
            grade[f][i] = Math.max(grade[f][i], sev);
            // O QUE aconteteceu naquela hora. Sem isto o quadradinho só dizia
            // "algo aconteceu", que obriga a ir procurar no log — a faixa
            // apontava o problema e não contava qual era.
            const ch = `${f}|${i}`;
            (detalhe[ch] || (detalhe[ch] = [])).push({
              ts: e.ts, sev,
              // `title: body` — o título diz o que é, o corpo diz a causa.
              // Mantém os dois: são as duas perguntas que o hover responde.
              msg: String(e.msg || '').slice(0, 220),
            });
          }
        }
      }
      // Hora cheia de repetição (23 restarts) não cabe e não informa mais que
      // os primeiros: manda 4 e diz quantos ficaram de fora.
      for (const ch of Object.keys(detalhe)) {
        const tot = detalhe[ch].length;
        detalhe[ch].sort((a, b) => b.sev - a.sev || a.ts - b.ts);
        detalhe[ch] = { itens: detalhe[ch].slice(0, 4), total: tot };
      }
      // App sem nenhum evento em 24h não ganha linha. As 5 famílias fixas
      // ficam sempre — a ausência delas é informação ("o carro não deu trabalho").
      const fixas = new Set(['carro', 'solar', 'casa', 'sitio', 'mac', 'rede']);
      const linhas = FAM
        .filter(([f]) => fixas.has(f) || grade[f].some(v => v > 0))
        .map(([f, , rot]) => ({ key: f, rotulo: rot }));
      for (const f of Object.keys(grade)) if (!linhas.some(l => l.key === f)) delete grade[f];
      return { horas: H, ate_ms: now, fam: linhas, grade, detalhe };
    })(),
    top7d: (() => {
      const cut = now - 7 * 86400_000, c = {}, titulo = {};
      for (const e of _healthEvents) {
        if (e.ts < cut) continue;
        if (e.type === 'restart' || /_recovery$/.test(e.type)) continue;
        c[e.type] = (c[e.type] || 0) + 1;
        // O evento é gravado como `title + ': ' + body`, então o texto legível
        // (com emoji) está no próprio msg. `_alertState` só tem título enquanto
        // o alerta existe, e estes aqui já recuperaram — por isso vinha a chave
        // crua ("solar_plant_offline") em vez do nome.
        // Tira o parêntese de data do fim ("... (04/09/2026, 02:31)"): ele não
        // cabe na coluna e era cortado no meio, virando lixo visual.
        // Enxuga pro que cabe numa linha estreita: parênteses (cidade, data,
        // "(ainda)") e o prefixo do fabricante não dizem O QUE houve, que é a
        // única coisa que essa lista precisa responder.
        const t = String(e.msg || '').split(':')[0]
                    .replace(/\s*\([^)]*\)?/g, '')
                    .replace(/^(☀️|🌱|🏠)?\s*(Solar|SAJ)\s+/, '$1 ')
                    .replace(/\s+/g, ' ').trim();
        // Cair pra `e.type` mostrava a CHAVE crua na parede
        // ("recados_999111211_wa_off"), que não é nome de nada. Com os nomes de
        // instância o título passou de 46 caracteres e o defeito apareceu.
        // Agora: se é longo, abrevia em palavra inteira; chave crua nunca.
        if (t) titulo[e.type] = t.length <= 46
          ? t
          : (() => { const c = t.slice(0, 46), i = c.lastIndexOf(' ');
                     return (i > 24 ? c.slice(0, i) : c).trim() + '…'; })();
      }
      const arr = Object.entries(c).sort((a, b) => b[1] - a[1]).slice(0, 6);
      const max = arr.length ? arr[0][1] : 0;
      return arr.map(([type, n]) => ({
        tipo: type, label: titulo[type] || type,
        n, pct: max ? Math.round(n / max * 100) : 0,
      }));
    })(),
    // O que aconteceu enquanto ninguém olhava. Um alerta que subiu e desceu não
    // aparece em `alerts` (já não está firing) mas é exatamente o que responde
    // "estava tudo bem de manhã?".
    events: (() => {
      const out = [];
      // Repetição consecutiva do mesmo tipo vira UMA linha com contagem: sete
      // "Bridge iniciado" seguidos enchiam o card e diziam uma coisa só.
      for (const e of _healthEvents.slice().reverse()) {
        const last = out[out.length - 1];
        if (last && last.type === e.type) { last.n++; continue; }
        if (out.length >= 20) break;
        out.push({ ts: e.ts, type: e.type, n: 1,
          kind: e.type === 'restart' ? 'restart'
              : /_recovery$/.test(e.type) ? 'recovery' : 'alert',
          // 160 pra o hover da linha ter o que mostrar além do que já cabe nela.
          msg: String(e.msg || '').split('\n')[0].slice(0, 160) });
      }
      return out;
    })(),
    // Só timestamps: quem decide se houve pulso é o cliente, comparando com o que
    // viu no ciclo anterior.
    pulse_ms: [state.last_apk_live_ms, state.last_gwm_ms].filter(Boolean),
    // O carro PUBLICA (MQTT) e por isso pulsava sozinho; o resto o bridge
    // CONSULTA, e nada disso acendia — a tela parecia ter um nó vivo e seis
    // mortos. Aqui vai o carimbo da última MEDIÇÃO de cada nó: a página pulsa
    // quando o número muda de verdade.
    //
    // Carimbo de MEDIÇÃO, não de consulta. Se a fonte devolve o mesmo valor
    // velho, o timestamp não anda e o nó não pulsa — senão a animação viraria
    // "o bridge está consultando", que é justamente a mentira que o pulso
    // deveria evitar. Mesma regra de medicao_ms vs atividade.
    pulses: {
      solar: Math.max(_solisState?.ts || 0, _solarState?.ts || 0) || null,
      // A Bluetti carimba a coleta inteira, não cada aparelho. `reachable`
      // é o que separa "respondeu agora" de "está no objeto porque sempre
      // esteve": bateria fora do ar não pulsa.
      casa:  _bluettiState?.casa?.reachable  ? _bluettiState.ts : null,
      sitio: _bluettiState?.sitio?.reachable ? _bluettiState.ts : null,
      apps:  Math.max(..._pixbot.map(x => x.ts || 0),
                      ..._recadosLista.map(x => x.ts || 0),
                      _credito?.ts || 0) || null,
      // Mac e rede são MEDIDOS localmente a cada ciclo, então `checked_at`
      // aqui É o instante da medição — não há fonte remota pra ficar velha.
      mac:   _macStats?.checked_at || null,
      rede:  Math.max(_netBw?.checked_at || 0, _netStatus?.checked_at || 0) || null,
    },
    services: svc,
    bridge: { uptime_sec: Math.round(process.uptime()), checks: svc.length },
  });
});

// ── GET /api/series — histórico do recorder do HA, reamostrado ───────────────
// A página não fala com o HA (CORS + token), então o bridge faz de intermediário.
// Reamostra em baldes fixos: 30 dias de um sensor que atualiza a cada 5min são
// ~8600 pontos, e desenhar isso num SVG de 900px é jogar 90% fora no cliente.
// Cada balde leva média/mín/máx — o máx é o que importa em temperatura, e some
// se você só guardar a média.
const SERIES_RANGES = {
  day:   { ms: 24 * 3600_000,      buckets: 480, ttl:   60_000 },
  week:  { ms: 7 * 24 * 3600_000,  buckets: 672, ttl:  300_000 },
  month: { ms: 30 * 24 * 3600_000, buckets: 720, ttl: 1800_000 },
};
const SERIES_ALLOW = /^sensor\.(energia_solar_[a-z0-9_]+|inverter_[a-z0-9_]+)$/;
const _seriesCache = new Map();

app.get('/api/series', requireAuth, async (req, res) => {
  const rk = String(req.query.range || 'day');
  const R = SERIES_RANGES[rk];
  if (!R) return res.status(400).json({ error: 'range inválido' });
  const ents = String(req.query.entities || '').split(',').map(x => x.trim()).filter(Boolean).slice(0, 6);
  // Allowlist: este endpoint expõe o recorder do HA por HTTP. Sem ela, qualquer
  // entity_id (device_tracker de pessoa, câmera, sensor de porta) sairia por aqui.
  if (!ents.length || !ents.every(e => SERIES_ALLOW.test(e)))
    return res.status(400).json({ error: 'entidade não permitida' });

  const ck = rk + '|' + ents.join(',');
  const hit = _seriesCache.get(ck);
  if (hit && (Date.now() - hit.ts) < R.ttl) return res.json(hit.data);

  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return res.status(503).json({ error: 'HA não configurado' });
  const to = Date.now(), from = to - R.ms;
  // O + do offset vira espaço se não for encodado, e o HA responde "Invalid end_time".
  const iso = ms => encodeURIComponent(new Date(ms).toISOString());
  let raw;
  try {
    const r = await fetch(`${url}/api/history/period/${iso(from)}`
      + `?end_time=${iso(to)}&filter_entity_id=${encodeURIComponent(ents.join(','))}`
      + `&minimal_response&no_attributes`,
      { headers: { Authorization: `Bearer ${tok}` }, signal: AbortSignal.timeout(45_000) });
    if (!r.ok) return res.status(502).json({ error: 'HA history HTTP ' + r.status });
    raw = await r.json();
  } catch (e) { return res.status(502).json({ error: 'HA history: ' + e.message }); }

  const step = R.ms / R.buckets;
  const series = ents.map(eid => {
    const arr = (raw || []).find(a => a[0]?.entity_id === eid) || [];
    const buckets = new Array(R.buckets).fill(null);
    let last = null;
    for (const s of arr) {
      const t = Date.parse(s.last_changed || s.last_updated || '');
      const v = parseFloat(s.state);
      if (!Number.isFinite(t) || !Number.isFinite(v)) continue;
      const i = Math.floor((t - from) / step);
      if (i < 0 || i >= R.buckets) continue;
      const b = buckets[i] || (buckets[i] = { s: 0, n: 0, lo: v, hi: v });
      b.s += v; b.n++; b.lo = Math.min(b.lo, v); b.hi = Math.max(b.hi, v);
      last = v;
    }
    // [t, media, min, max] — null onde não houve leitura. NÃO preencho o vazio
    // com o último valor: reta plana onde não há dado é o mesmo erro do gráfico
    // de ontem, medição inventada.
    const points = buckets.map((b, i) => b
      ? [Math.round(from + i * step + step / 2), +(b.s / b.n).toFixed(2), +b.lo.toFixed(2), +b.hi.toFixed(2)]
      : null);
    const vals = buckets.filter(Boolean);
    return {
      entity: eid, points,
      peak: vals.length ? +Math.max(...vals.map(b => b.hi)).toFixed(1) : null,
      min:  vals.length ? +Math.min(...vals.map(b => b.lo)).toFixed(1) : null,
      avg:  vals.length ? +(vals.reduce((a, b) => a + b.s, 0) / vals.reduce((a, b) => a + b.n, 0)).toFixed(1) : null,
      last: last,
    };
  });
  const data = { range: rk, from, to, step_ms: Math.round(step), series };
  _seriesCache.set(ck, { ts: Date.now(), data });
  if (_seriesCache.size > 40) _seriesCache.delete(_seriesCache.keys().next().value);
  res.json(data);
});

app.get('/api/ivonei-status', async (_req, res) => {
  const now = Date.now();
  if (!_solisCache.data || (now - _solisCache.ts) > 60_000) {
    const d = await _fetchSolisStatus();
    if (d) _solisCache = { data: d, ts: now };
  }
  const d = _solisCache.data;
  if (!d || !d.ivonei) return res.status(502).json({ error: 'ivonei indisponível' });
  const sun = await _fetchSunTimes('goiania');
  res.json({ ...d.ivonei, sunrise_ms: sun.sunrise_ms || null, sunset_ms: sun.sunset_ms || null, expected: _expectedNow('ivonei'), fan: _fanIvonei, ts: d.ts });
});
app.get('/api/palmeiras-status', async (_req, res) => {
  const now = Date.now();
  if (!_solisCache.data || (now - _solisCache.ts) > 60_000) {
    const d = await _fetchSolisStatus();
    if (d) _solisCache = { data: d, ts: now };
  }
  const d = _solisCache.data;
  if (!d || !d.palmeiras) return res.status(502).json({ error: 'palmeiras indisponível' });
  const sun = await _fetchSunTimes('palmeiras');
  res.json({ ...d.palmeiras, sunrise_ms: sun.sunrise_ms || null, sunset_ms: sun.sunset_ms || null, expected: _expectedNow('palmeiras'), ts: d.ts });
});

// GET /api/baseline-status — status do scanner preditivo (habilitado?, entries,
// pares monitorados, custo do dia em USD).
app.get('/api/baseline-status', (_req, res) => {
  res.json({
    enabled: notifPrefs.baseline_predictive !== false,
    entries: Object.keys(_baselineMatrix).length,
    pairs: _bmUsefulPairs().length,
    cost_today: _baselineCostToday,
  });
});

// Heartbeat do monitor externo — o HA do Sítio faz POST periódico aqui. Se
// parar de chegar, /api/monitor-heartbeat detecta no _checkAlerts e alerta que o
// monitoramento externo do Mac está cego. GET também aceito (rest_command simples).
function _recordExtBeat(_req, res) {
  _extMonitorLastBeat = Date.now();
  try { atomicWriteFileSync(EXT_MONITOR_BEAT_FILE, JSON.stringify({ ts: _extMonitorLastBeat })); } catch (_) {}
  res.json({ ok: true, ts: _extMonitorLastBeat });
}
app.post('/api/monitor-heartbeat', _recordExtBeat);
app.get('/api/monitor-heartbeat', _recordExtBeat);

// Status do HA do Sítio — push periódico de services/guards/uptime7d, pra
// mostrar no /health.html (única forma de ver de fora, já que o HA tem IP
// dinâmico). Sem auth por padrão, mesmo modelo do /api/monitor-heartbeat
// (dado não sensível); HA_STATUS_TOKEN opcional se quiser exigir header.
const HA_STATUS_TOKEN = process.env.HA_STATUS_TOKEN || '';
app.post('/api/ha-status', (req, res) => {
  if (HA_STATUS_TOKEN && req.get('x-ha-status-token') !== HA_STATUS_TOKEN)
    return res.status(401).json({ ok: false, error: 'unauthorized' });
  const b = req.body || {};
  if (!b.services || typeof b.services !== 'object')
    return res.status(400).json({ ok: false, error: 'missing services' });
  const ts = Date.now();
  _recordHaWorkTransitions(_haWorkLatest && _haWorkLatest.services, b.services, ts);
  _haWorkLatest = { ts, services: b.services, guards: b.guards || {}, uptime7d: b.uptime7d || {} };
  try { atomicWriteFileSync(HA_WORK_FILE, JSON.stringify(_haWorkLatest)); } catch (_) {}
  _evalInfraLA(b.services, b.guards || {});
  res.json({ ok: true, ts });
});

// ── iCloud family locations ─────────────────────────────────────────────────
// Puxa localização dos iPhones da família a cada 10min via device_tracker do HA
// (integração iCloud), reverse-geocoda endereço e persiste. gps_accuracy do HA
// vira "raio de confiança": <50m alta, 50-200m média, >200m baixa (potencial
// falso positivo). Só iPhones — iPad/MacBook fora. Endpoint auth-gated.
const _FAMILY_MEMBERS = [
  { key: 'grasielle', name: 'Grasielle',       device: 'iPhone 16 Pro Max',
    tracker: 'device_tracker.iphone_de_grasielle', battery: 'sensor.iphone_de_grasielle_bateria' },
  { key: 'vitoria',   name: 'Vitória',         device: 'iPhone 14 Pro Max',
    tracker: 'device_tracker.vitoria',             battery: 'sensor.vitoria_bateria' },
  { key: 'rodrigo',   name: 'Rodrigo Machado', device: 'iPhone 13 Pro',
    tracker: 'device_tracker.rodrigo_machado_2',   battery: 'sensor.rodrigo_machado_2_bateria' },
  { key: 'ivone',     name: 'Ivone',           device: 'iPhone 14 Pro Max',
    tracker: 'device_tracker.iphone_de_ivone_2',   battery: 'sensor.iphone_de_ivone_2_bateria' },
  { key: 'eduardo',   name: 'Eduardo',         device: 'iPhone 17e',
    tracker: 'device_tracker.eduardo_2',           battery: 'sensor.eduardo_2_bateria' },
];
const FAMILY_FILE = path.join(DATA_DIR, 'icloud_family.json');
let _familyLocations = {};
try { _familyLocations = JSON.parse(fs.readFileSync(FAMILY_FILE, 'utf8')) || {}; } catch (_) {}
function _saveFamilyLocations() {
  try { atomicWriteFileSync(FAMILY_FILE, JSON.stringify(_familyLocations)); } catch (_) {}
}
// Reverse geocode rico (rua + número + bairro + POI) só pra família. Cache
// próprio arredondado a ~11m (4 casas decimais). Zoom 18 pra buscar POI.
// namedetails=1 traz nome de estabelecimento quando lat/lng cai num prédio
// cadastrado no OSM. Se Nominatim não trouxe POI, faz fallback Overpass num
// raio ao redor pra pegar shopping/restaurante/mercado/hospital/etc próximo.
const _familyGeoMem = new Map();
// Overpass: busca POI (shop, amenity, tourism, leisure, office, healthcare)
// mais próximo com nome. Radius = accuracy do GPS ou 60m (o que for maior).
// Só chama quando Nominatim não trouxe POI. Timeout curto, fail-open.
const _OVERPASS_HOSTS = [
  'https://overpass-api.de/api/interpreter',
  'https://overpass.osm.ch/api/interpreter',
];
async function _nearbyPOI(lat, lng, radius) {
  const r = Math.max(30, Math.min(200, Math.round(radius || 60)));
  const q = `[out:json][timeout:4];(` +
    `nwr(around:${r},${lat},${lng})["name"]["shop"];` +
    `nwr(around:${r},${lat},${lng})["name"]["amenity"];` +
    `nwr(around:${r},${lat},${lng})["name"]["tourism"];` +
    `nwr(around:${r},${lat},${lng})["name"]["leisure"];` +
    `nwr(around:${r},${lat},${lng})["name"]["office"];` +
    `nwr(around:${r},${lat},${lng})["name"]["healthcare"];` +
    `);out center tags 8;`;
  let j = null;
  for (const host of _OVERPASS_HOSTS) {
    try {
      const resp = await fetch(host, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'User-Agent': 'ecotrip-bridge/1.0 (https://github.com/rafaelcs28/haval-ecotrip)',
        },
        body: 'data=' + encodeURIComponent(q),
        signal: AbortSignal.timeout(5000),
      });
      if (!resp.ok) continue;   // 429/500 → tenta próximo host
      j = await resp.json();
      break;
    } catch (_) { /* tenta próximo host */ }
  }
  if (!j) return '';
  try {
    const els = j.elements || [];
    if (!els.length) return '';
    // Score: preferir shop/amenity food-adjacent, e o mais próximo.
    const scored = els.map(e => {
      const c = e.center || e;
      const d = (c.lat && c.lon) ? haversineM(lat, lng, c.lat, c.lon) : 9999;
      const t = e.tags || {};
      let bonus = 0;
      if (t.shop === 'mall' || t.amenity === 'marketplace') bonus += 40;
      if (t.shop || t.amenity === 'restaurant' || t.amenity === 'cafe' || t.amenity === 'fast_food' || t.amenity === 'bar') bonus += 20;
      if (t.tourism || t.leisure) bonus += 10;
      if (t.healthcare || t.amenity === 'hospital' || t.amenity === 'clinic') bonus += 25;
      return { name: t.name, tags: t, dist: d, score: bonus - d };
    }).filter(x => x.name).sort((a,b) => b.score - a.score);
    return scored.length ? scored[0].name : '';
  } catch (_) { return ''; }
}
async function _reverseGeocodeFamily(lat, lng, accuracy) {
  const k = (Math.round(lat * 10000) / 10000) + ',' + (Math.round(lng * 10000) / 10000);
  if (_familyGeoMem.has(k)) return _familyGeoMem.get(k);
  try {
    const r = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=18&namedetails=1&addressdetails=1&accept-language=pt-BR`, {
      headers: {
        'Accept': 'application/json',
        'Accept-Language': 'pt-BR,pt;q=0.9',
        'User-Agent': 'ecotrip-bridge/1.0 (https://github.com/rafaelcs28/haval-ecotrip)',
      },
    });
    const j = await r.json();
    const a = j.address || {};
    let poi = j.name || (j.namedetails && j.namedetails.name) || '';
    const road   = a.road || a.pedestrian || a.footway || '';
    const num    = a.house_number || '';
    const bairro = a.suburb || a.neighbourhood || a.quarter || a.city_district || '';
    const city   = a.city || a.town || a.village || a.municipality || a.county || '';
    if (poi && (poi === road || poi === city)) poi = '';
    // Fallback Overpass: se Nominatim não achou POI nomeado, procura
    // estabelecimento próximo. Serve quando lat/lng cai na rua ao lado do
    // shopping/restaurante em vez de cair exato no polígono.
    if (!poi) {
      poi = await _nearbyPOI(lat, lng, accuracy);
    }
    const parts = [];
    if (poi)                        parts.push(poi);
    if (road)                       parts.push(num ? `${road}, ${num}` : road);
    if (bairro && bairro !== road)  parts.push(bairro);
    if (city && city !== bairro)    parts.push(city);
    const label = parts.length ? parts.join(' · ') : (j.display_name || '');
    const result = { label, city, bairro, road, num, poi };
    _familyGeoMem.set(k, result);
    return result;
  } catch (_) {
    const empty = { label: '', city: '', bairro: '', road: '', num: '', poi: '' };
    _familyGeoMem.set(k, empty);
    return empty;
  }
}
// ── Refresh forçado do iCloud (o que o app Buscar faz ao abrir) ──────────────
// A integração `icloud` do HA atualiza TODOS os devices num lote só, a cada ~20-30min:
// medido 22min de idade em todos os 5 ao mesmo tempo, e a Ivone ainda marcava "PFH"
// depois de já ter saído — dado velho E errado. O serviço icloud.update força a
// busca na Apple: 22min → 0,2min em 12s.
// Cadência é deliberadamente contida: cada refresh ACORDA os iPhones, e hoje tem
// gente em 10% e 18% de bateria. Então: lote de fundo espaçado + on-demand quando
// alguém realmente olha, com cooldown. É o mesmo comportamento do app.
const FAMILY_FORCE_GAP_MS = +(process.env.FAMILY_FORCE_GAP_S || 90) * 1000;
const FAMILY_BG_FORCE_MS  = +(process.env.FAMILY_BG_FORCE_MIN || 15) * 60_000;
const FAMILY_STALE_MS     = +(process.env.FAMILY_STALE_MIN || 5) * 60_000;
let _familyForcedAt = 0;

async function _forceIcloudRefresh() {
  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return false;
  const now = Date.now();
  if (now - _familyForcedAt < FAMILY_FORCE_GAP_MS) return false;   // cooldown
  _familyForcedAt = now;
  try {
    const r = await fetch(`${url}/api/services/icloud/update`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${tok}`, 'Content-Type': 'application/json' },
      body: '{}',
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) { console.warn('[family] icloud.update HTTP ' + r.status); return false; }
    return true;
  } catch (e) { console.warn('[family] icloud.update falhou:', e.message); return false; }
}

// Idade do dado mais novo que temos guardado.
function _familyFreshestAgeMs() {
  let newest = 0;
  for (const m of _FAMILY_MEMBERS) {
    const t = _familyLocations[m.key]?.ha_reported_ms || 0;
    if (t > newest) newest = t;
  }
  return newest ? Date.now() - newest : Infinity;
}

async function _fetchFamilyLocations(force = false) {
  const tok = process.env.HA_TOKEN;
  const url = (process.env.HA_URL || '').replace(/\/$/, '');
  if (!tok || !url) return;
  // Pede a atualização e dá tempo do HA receber a resposta da Apple antes de ler.
  if (force && await _forceIcloudRefresh()) await new Promise(r => setTimeout(r, 9000));
  let arr;
  try {
    const r = await fetch(`${url}/api/states`, {
      headers: { Authorization: `Bearer ${tok}` },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return;
    arr = await r.json();
  } catch (_) { return; }
  const now = Date.now();
  for (const m of _FAMILY_MEMBERS) {
    const t = arr.find(x => x.entity_id === m.tracker);
    if (!t) continue;
    const attr = t.attributes || {};
    const lat = Number.isFinite(+attr.latitude) ? +attr.latitude : null;
    const lng = Number.isFinite(+attr.longitude) ? +attr.longitude : null;
    const acc = Number.isFinite(+attr.gps_accuracy) ? +attr.gps_accuracy : null;
    const haReportedMs = Date.parse(t.last_updated || t.last_changed || '') || now;
    const zone = (t.state && t.state !== 'not_home' && t.state !== 'unknown' && t.state !== 'unavailable') ? t.state : null;
    let battery_pct = null;
    if (m.battery) {
      const b = arr.find(x => x.entity_id === m.battery);
      if (b && b.state !== 'unknown' && b.state !== 'unavailable') {
        const n = +b.state; if (Number.isFinite(n)) battery_pct = Math.round(n);
      }
    }
    const prev = _familyLocations[m.key] || {};
    let address = prev.address || null;
    if (lat != null && lng != null) {
      const moved = (prev.lat == null || prev.lng == null) ||
                    haversineM(prev.lat, prev.lng, lat, lng) > 50;
      if (moved || !prev.address) {
        try {
          const g = await _reverseGeocodeFamily(lat, lng, acc);
          if (g.label) address = g.label;
        } catch (_) {}
      }
    }
    // ── Frescor HONESTO ────────────────────────────────────────────────────────
    // `ha_reported_ms` é quando o HA GRAVOU o estado, ou seja quando a integração
    // buscou na Apple — NÃO quando o iPhone fixou a posição. Forçar o refresh deixa
    // a busca atual, mas se o aparelho está dormindo/parado/sem sinal a Apple
    // devolve a mesma coordenada antiga e o "8s" viraria mentira.
    // Nenhum atributo desta integração traz o timestamp real do fix (o icloud3, que
    // traria `last_located`, está com "Apple Login Failed"). Então derivo o que dá:
    //  - pos_since: desde quando a coordenada está IDÊNTICA (não distingue parado de
    //    velho, mas para de fingir frescor que não existe)
    //  - device_status/low_power: aparelho offline ou em baixo consumo = a posição da
    //    Apple é suspeita por definição
    const same = prev.lat != null && lat != null
      && Math.abs(prev.lat - lat) < 1e-6 && Math.abs(prev.lng - lng) < 1e-6;
    const next = {
      name: m.name,
      device: m.device,
      lat: lat != null ? lat : (prev.lat ?? null),
      lng: lng != null ? lng : (prev.lng ?? null),
      accuracy_m: acc,
      battery_pct,
      address,
      zone,
      ha_reported_ms: haReportedMs,
      updated_ms: now,
      pos_since: same ? (prev.pos_since || prev.ha_reported_ms || haReportedMs) : haReportedMs,
      device_status: attr.device_status || null,
      low_power: attr.low_power_mode === true,
      battery_status: attr.battery_status || null,
      fetch_interval_min: attr.account_fetch_interval ?? null,
    };
    // Detecta mudanca significativa (>=50m) pra fazer PUSH ao whats-assistant
    // (Marileuza). Bridge pushou = Mari pode reagir NA HORA sem esperar poll.
    if (prev.lat != null && next.lat != null
        && haversineM(prev.lat, prev.lng, next.lat, next.lng) >= 50) {
      _pushFamilyChange(m.key, next).catch(() => {});
    }
    _familyLocations[m.key] = next;
  }
  _saveFamilyLocations();
}
async function _pushFamilyChange(key, loc) {
  const url = process.env.MARI_PUSH_URL || 'http://127.0.0.1:3738/api/family-changed';
  const token = process.env.MARI_PUSH_TOKEN || process.env.HEALTH_TOKEN;
  if (!url || !token) return;
  try {
    await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Push-Token': token },
      body: JSON.stringify({ key, lat: loc.lat, lng: loc.lng, address: loc.address, ts: Date.now() }),
      signal: AbortSignal.timeout(4000),
    });
  } catch (_) { /* fail-open */ }
}
setTimeout(() => { _fetchFamilyLocations(true).catch(() => {}); }, 5_000);
setInterval(() => { _fetchFamilyLocations().catch(() => {}); }, 3 * 60_000);       // leitura barata
setInterval(() => { _fetchFamilyLocations(true).catch(() => {}); }, FAMILY_BG_FORCE_MS); // lote forçado

// `fresh=0` desliga o on-demand (pra quem só quer o cache). O default é: se o dado
// mais novo passou de 5min, força — respeitando o cooldown de 90s, então página
// atualizando de minuto em minuto não vira metralhadora de wake-up nos iPhones.
app.get('/api/family-locations', requireAuth, async (req, res) => {
  if (req.query.fresh !== '0' && _familyFreshestAgeMs() > FAMILY_STALE_MS) {
    try { await _fetchFamilyLocations(true); } catch (_) {}
  }
  const now = Date.now();
  const list = _FAMILY_MEMBERS.map(m => {
    const s = _familyLocations[m.key] || {};
    return {
      key: m.key,
      name: s.name || m.name,
      device: s.device || m.device,
      lat: s.lat ?? null,
      lng: s.lng ?? null,
      accuracy_m: s.accuracy_m ?? null,
      battery_pct: s.battery_pct ?? null,
      address: s.address || null,
      zone: s.zone || null,
      updated_ms: s.ha_reported_ms || null,
      // age_ms = idade da NOSSA cópia (quando a integração buscou).
      age_ms: s.ha_reported_ms ? (now - s.ha_reported_ms) : null,
      // pos_age_ms = há quanto tempo a coordenada não muda. É o número honesto:
      // "buscamos agora" não quer dizer "ele está aqui agora".
      pos_age_ms: s.pos_since ? (now - s.pos_since) : null,
      device_status: s.device_status || null,
      low_power: !!s.low_power,
      battery_status: s.battery_status || null,
      fetch_interval_min: s.fetch_interval_min ?? null,
    };
  });
  res.json({ ts: now, members: list });
});

// ── Stats do Mac (host) — memória/disco/uptime, cacheado (vm_stat é subprocess) ──
// os.freemem() no macOS conta só páginas livres (~0) e engana; usamos vm_stat
// pra "em uso" (active+wired+compressor) estilo Activity Monitor.
const SSD_EXT_PATH = process.env.SSD_EXT_PATH || '/Volumes/SSD1TB';
let _macStats = { uptime_sec: 0, mem: null, disk: null, disk_ext: null, checked_at: 0 };
function _pollMacStats() {
  const os = require('os');
  const total = os.totalmem();
  let disk = null, disk_ext = null;
  try {
    const s = require('fs').statfsSync('/');
    disk = { total_gb: +(s.blocks * s.bsize / 1e9).toFixed(1),
             avail_gb: +(s.bavail * s.bsize / 1e9).toFixed(1) };
  } catch (_) {}
  // SSD externo: segura o bundle HAOS (~60GB). Se desmontar ou encher, HA morre.
  try {
    const fsx = require('fs');
    if (fsx.existsSync(SSD_EXT_PATH)) {
      const s2 = fsx.statfsSync(SSD_EXT_PATH);
      disk_ext = { path: SSD_EXT_PATH, mounted: true,
                   total_gb: +(s2.blocks * s2.bsize / 1e9).toFixed(1),
                   avail_gb: +(s2.bavail * s2.bsize / 1e9).toFixed(1) };
    } else {
      disk_ext = { path: SSD_EXT_PATH, mounted: false, error: 'existsSync=false' };
    }
  } catch (e) {
    disk_ext = { path: SSD_EXT_PATH, mounted: false, error: e.message };
  }
  exec('vm_stat', { timeout: 4000 }, (err, stdout) => {
    let mem = { total_gb: +(total / 1e9).toFixed(1), used_gb: null, avail_gb: null };
    if (!err && stdout) {
      const pg = +(/page size of (\d+) bytes/.exec(stdout)?.[1] || 4096);
      const pages = k => +(new RegExp(k + ':\\s+(\\d+)').exec(stdout)?.[1] || 0);
      const used = (pages('Pages active') + pages('Pages wired down')
                    + pages('Pages occupied by compressor')) * pg;
      mem.used_gb  = +(used / 1e9).toFixed(1);
      mem.avail_gb = +((total - used) / 1e9).toFixed(1);
    }
    // Top 5 processos por RSS (rss em KB). Agrupa por nome de comando.
    exec('ps -Axo rss=,comm= -r', { timeout: 4000, maxBuffer: 4 * 1024 * 1024 }, (e2, s2) => {
      let top = [];
      if (!e2 && s2) {
        const agg = {};
        for (const line of s2.split('\n')) {
          const mm = /^\s*(\d+)\s+(.+)$/.exec(line);
          if (!mm) continue;
          const name = mm[2].split('/').pop().trim();
          agg[name] = (agg[name] || 0) + (+mm[1]) * 1024;
        }
        top = Object.entries(agg)
          .sort((a, b) => b[1] - a[1]).slice(0, 10)
          .map(([name, bytes]) => ({ name, mb: Math.round(bytes / 1048576) }));
      }
      _macStats = { uptime_sec: Math.floor(os.uptime()), mem, disk, disk_ext, top_mem: top, checked_at: Date.now() };
    });
  });
}
_pollMacStats();
setInterval(_pollMacStats, 20_000);

// Banda de rede: delta de bytes do netstat -ib na interface default, dividido
// pelo intervalo. rx/tx em kbps. Detecta a interface a cada tick (WiFi/Ethernet).
let _netBw = { rx_kbps: null, tx_kbps: null, iface: null, link_mbps: null, link_type: null, checked_at: 0 };
let _netPrev = null; // { rx, tx, ts }
let _netLink = { mbps: null, type: null }; // velocidade negociada do link local (WiFi/Ethernet)
function _pollLinkSpeed() {
  // Descobre a interface ATIVA da rota default antes de escolher o método:
  // Ethernet (en0/USB) → ifconfig media baseT. WiFi (en1) → Transmit Rate do
  // system_profiler. Antes assumia WiFi só porque o rádio estava associado
  // mesmo com Ethernet como default — reportava "WiFi" errado no card.
  exec("route -n get default 2>/dev/null | awk '/interface:/{print $2}'", { timeout: 3000 }, (e0, ifaceOut) => {
    const iface = (ifaceOut || '').trim() || 'en0';
    // en1 é WiFi no Mac Mini; qualquer outro (en0 built-in, en5-9 USB) é Ethernet
    const isWifi = iface === 'en1';
    if (isWifi) {
      exec('system_profiler SPAirPortDataType 2>/dev/null', { timeout: 20000, maxBuffer: 1 << 20 }, (e, out) => {
        const tx = /Transmit Rate:\s*(\d+)/.exec(out || '');
        _netLink = tx ? { mbps: +tx[1], type: 'WiFi' } : { mbps: null, type: 'WiFi' };
      });
    } else {
      exec(`ifconfig ${iface} 2>/dev/null`, { timeout: 3000 }, (e2, out2) => {
        const m = /media:.*?(\d+)base/i.exec(out2 || '');
        _netLink = m ? { mbps: +m[1], type: 'Ethernet' } : { mbps: null, type: 'Ethernet' };
      });
    }
  });
}
_pollLinkSpeed();
setInterval(_pollLinkSpeed, 60_000);
function _pollNetBw() {
  exec("route -n get default 2>/dev/null | awk '/interface:/{print $2}'", { timeout: 3000 }, (e0, ifaceOut) => {
    const iface = (ifaceOut || '').trim() || 'en0';
    exec(`netstat -ib -I ${iface}`, { timeout: 3000 }, (err, stdout) => {
      if (err || !stdout) return;
      const line = stdout.split('\n').find(l => new RegExp('^' + iface + '\\s').test(l));
      if (!line) return;
      const c = line.trim().split(/\s+/);
      const rx = +c[6], tx = +c[9]; // Ibytes, Obytes (col Link#)
      const now = Date.now();
      if (_netPrev && _netPrev.iface === iface && now > _netPrev.ts) {
        const dt = (now - _netPrev.ts) / 1000;
        _netBw = {
          rx_kbps: Math.max(0, Math.round((rx - _netPrev.rx) * 8 / 1000 / dt)),
          tx_kbps: Math.max(0, Math.round((tx - _netPrev.tx) * 8 / 1000 / dt)),
          iface, link_mbps: _netLink.mbps, link_type: _netLink.type, checked_at: now,
        };
      }
      _netPrev = { rx, tx, ts: now, iface };
    });
  });
}
_pollNetBw();
setInterval(_pollNetBw, 5_000);

// ── Processos pm2 (todos os apps do Mac Mini) ────────────────────────────────
const PM2_BIN = process.env.PM2_BIN || '/usr/local/bin/pm2';
let _processes = [];
function _pollProcesses() {
  exec(`${PM2_BIN} jlist`, { timeout: 6000, maxBuffer: 8 * 1024 * 1024 }, (err, stdout) => {
    if (err || !stdout) return;
    try {
      _processes = JSON.parse(stdout).map(p => ({
        name:        p.name,
        status:      p.pm2_env?.status || 'unknown',
        cpu:         p.monit?.cpu ?? null,
        mem_mb:      Math.round((p.monit?.memory || 0) / 1048576),
        restarts:    p.pm2_env?.restart_time ?? 0,
        uptime_sec:  p.pm2_env?.pm_uptime ? Math.floor((Date.now() - p.pm2_env.pm_uptime) / 1000) : null,
      })).sort((a, b) => a.name.localeCompare(b.name));
    } catch (_) {}
  });
}
_pollProcesses();
setInterval(_pollProcesses, 5_000);

// ── Recência de backups (Lari/Radicale, Haval tarball) ───────────────────────
// Cada fonte aponta pra um diretório; pega a entrada mais nova (file ou dir) por
// mtime e reporta a idade. Alerta se passar de max_age_h.
const _home = require('os').homedir();
const BACKUP_SOURCES = [
  { name: 'Lari (SQLite+Radicale)', dir: path.join(_home, 'whats-assistant', 'backups'), max_age_h: 30 },
  { name: 'Haval (tarball)', dir: path.join(_home, 'Library', 'Mobile Documents', 'com~apple~CloudDocs', '02. RAFAEL PESSOAL', 'Backup Haval EcoTrip', 'daily'), max_age_h: 30 },
  // 16h era a régua de quando o ssd-backup.sh rodava 2x/dia (01h e 13h). Em
  // 15/09/2026 passou a rodar 1x (01h) — com RETENTION_DAILY=14, duas execuções
  // guardavam só 7 dias de histórico. Mudar a cadência sem mudar a régua fez os
  // dois alertarem todo fim de tarde por um backup que estava em dia. 30h é a
  // mesma folga usada nos outros diários daqui.
  { name: 'SSD físico (diário)', dir: '/Volumes/SSD1TB/Backups/haval-ecotrip/daily', max_age_h: 30 },
  { name: 'MQTT (broker)', dir: '/Volumes/SSD1TB/Backups/mosquitto/daily', max_age_h: 30 },
  // bkp-OF-bkp: roda tarde (~17:39), a mais tardia do dia. Com cadência 24h e o
  // Mac podendo dormir/mirror atrasar, 30h dava alerta diário falso (só 6h de
  // folga). É cópia secundária — o primário + SSD físico + iCloud estão sempre
  // mais frescos —, então 48h só dispara se estiver 2 dias atrás de verdade.
  { name: 'Clockin bkp-of-bkp', dir: '/Volumes/SSD1TB/Backups/ellevar-clockin/backups-mirror', max_age_h: 48 },
];
let _backups = [];
function _pollBackups() {
  const fsx = require('fs');
  _backups = BACKUP_SOURCES.map((src) => {
    try {
      const entries = fsx.readdirSync(src.dir);
      if (!entries.length) return { name: src.name, ok: false, error: 'vazio', max_age_h: src.max_age_h };
      let newestMs = 0, newestName = null;
      for (const e of entries) {
        if (e.startsWith('.')) continue;
        const st = fsx.statSync(path.join(src.dir, e));
        if (st.mtimeMs > newestMs) { newestMs = st.mtimeMs; newestName = e; }
      }
      if (!newestName) return { name: src.name, ok: false, error: 'vazio', max_age_h: src.max_age_h };
      const ageH = (Date.now() - newestMs) / 3600000;
      return { name: src.name, ok: ageH <= src.max_age_h, newest: newestName,
               age_hours: Math.round(ageH * 10) / 10, max_age_h: src.max_age_h, checked_at: Date.now() };
    } catch (e) {
      return { name: src.name, ok: false, error: e.code === 'ENOENT' ? 'dir ausente' : e.message, max_age_h: src.max_age_h };
    }
  });
}
_pollBackups();
setInterval(_pollBackups, 10 * 60_000);

// ── Tendência preditiva: disco/SSD/RSS via regressão linear ──────────────────
// Guarda amostras (persistidas) e projeta: quantos dias até encher / detecta
// memory leak. Mais útil que o snapshot — avisa ANTES de bater no limite.
const TREND_FILE   = path.join(__dirname, '.trend_samples.json');
const TREND_MAX    = 1100;            // ~7,6 dias a 10min/amostra
const TREND_MIN_N  = 6;               // mínimo p/ projetar (≈1h de dados)
let _trendSamples = [];               // [{ ts, di, de, rss }]  (gb, gb, mb)
try { _trendSamples = JSON.parse(fs.readFileSync(TREND_FILE, 'utf8')) || []; } catch (_) {}
let _trend = { disk_int: null, disk_ext: null, rss: null, samples: 0 };

// Regressão linear y=a+bx sobre (horas, valor). Retorna slope/dia + ETA até `target`.
function _linfit(pts, perDayUnit) {
  const n = pts.length;
  if (n < TREND_MIN_N) return null;
  const x0 = pts[0].x;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  for (const p of pts) { const x = p.x - x0; sx += x; sy += p.y; sxx += x * x; sxy += x * p.y; }
  const d = n * sxx - sx * sx;
  if (d === 0) return null;
  const b = (n * sxy - sx * sy) / d;   // unidade por hora
  const spanH = pts[n - 1].x - pts[0].x;
  return { slope_per_day: +(b * 24).toFixed(2), current: +pts[n - 1].y.toFixed(2),
           span_h: +spanH.toFixed(1), unit: perDayUnit };
}
// ETA em dias até `current` cair a `floor` (recurso esgotando). null se subindo/estável.
function _etaToFloor(fit, floor) {
  if (!fit || fit.slope_per_day >= -0.001) return null;
  const days = (fit.current - floor) / (-fit.slope_per_day);
  return days > 0 ? +days.toFixed(1) : 0;
}
function _pollTrend() {
  const m  = _macStats;
  const di = m.disk?.avail_gb ?? null;
  const de = (m.disk_ext && m.disk_ext.mounted) ? (m.disk_ext.avail_gb ?? null) : null;
  const rss = Math.round(process.memoryUsage().rss / 1048576);
  _trendSamples.push({ ts: Date.now(), di, de, rss });
  if (_trendSamples.length > TREND_MAX) _trendSamples = _trendSamples.slice(-TREND_MAX);
  try { fs.writeFileSync(TREND_FILE, JSON.stringify(_trendSamples)); } catch (_) {}

  const toPts = (key) => _trendSamples
    .filter(s => s[key] != null)
    .map(s => ({ x: s.ts / 3600_000, y: s[key] }));
  const diFit  = _linfit(toPts('di'),  'gb');
  const deFit  = _linfit(toPts('de'),  'gb');
  const rssFit = _linfit(toPts('rss'), 'mb');
  _trend = {
    disk_int: diFit  ? { ...diFit,  eta_days: _etaToFloor(diFit, 8) } : null,
    disk_ext: deFit  ? { ...deFit,  eta_days: _etaToFloor(deFit, 5) } : null,
    rss:      rssFit ? { ...rssFit } : null,   // slope_per_day em MB/dia; >0 = subindo (leak)
    samples:  _trendSamples.length,
    checked_at: Date.now(),
  };
}
setTimeout(_pollTrend, 25_000);     // espera o 1º _pollMacStats popular
setInterval(_pollTrend, 10 * 60_000);

// ── iCloud: backup local ≠ offsite. Confere upload REAL via JXA ───────────────
// Lista o arquivo mais novo de cada produto no backup iCloud e pergunta ao
// NSURLUbiquitousItemIsUploadedKey se já subiu. Detecta backup "preso" local.
const ICLOUD_BACKUP_DIR = process.env.ICLOUD_BACKUP_DIR ||
  path.join(_home, 'Library', 'Mobile Documents', 'com~apple~CloudDocs', '02. RAFAEL PESSOAL', 'Backup Haval EcoTrip');
const ICLOUD_PROBE = path.join(__dirname, '..', 'scripts', 'icloud-upload-status.js');
let _icloudSync = { checked_at: 0, total: 0, uploaded: 0, pending: 0, errors: 0, files: [], error: null };
function _newestFileIn(dir) {
  try {
    const fsx = require('fs');
    let best = null, bestMs = 0;
    const walk = (d, depth) => {
      if (depth > 2) return;
      for (const e of fsx.readdirSync(d)) {
        if (e.startsWith('.')) continue;
        const fp = path.join(d, e);
        const st = fsx.statSync(fp);
        if (st.isDirectory()) walk(fp, depth + 1);
        else if (st.mtimeMs > bestMs) { bestMs = st.mtimeMs; best = fp; }
      }
    };
    walk(dir, 0);
    return best;
  } catch (_) { return null; }
}
function _pollIcloudSync() {
  const fsx = require('fs');
  const { execFile } = require('child_process');
  let roots;
  try { roots = fsx.readdirSync(ICLOUD_BACKUP_DIR).filter(e => !e.startsWith('.')); }
  catch (e) { _icloudSync = { checked_at: Date.now(), total: 0, uploaded: 0, pending: 0, errors: 0, files: [], error: e.code === 'ENOENT' ? 'dir ausente' : e.message }; return; }
  // 1 arquivo mais novo por produto (raiz ou subdir) — amostra representativa.
  const targets = [];
  for (const r of roots) {
    const rp = path.join(ICLOUD_BACKUP_DIR, r);
    let st; try { st = fsx.statSync(rp); } catch (_) { continue; }
    const f = st.isDirectory() ? _newestFileIn(rp) : rp;
    if (f) targets.push({ product: r, file: f });
  }
  if (!targets.length) { _icloudSync = { checked_at: Date.now(), total: 0, uploaded: 0, pending: 0, errors: 0, files: [], error: 'sem arquivos' }; return; }
  const args = ['-l', 'JavaScript', ICLOUD_PROBE, ...targets.map(t => t.file)];
  execFile('osascript', args, { timeout: 15000 }, (err, stdout) => {
    if (err) { _icloudSync = { ..._icloudSync, checked_at: Date.now(), error: 'osascript: ' + err.message }; return; }
    let arr; try { arr = JSON.parse(stdout); } catch (_) { _icloudSync = { ..._icloudSync, checked_at: Date.now(), error: 'parse' }; return; }
    let uploaded = 0, pending = 0, errors = 0;
    const files = targets.map((t, i) => {
      const s = arr[i] || {};
      if (s.uploaded) uploaded++; else pending++;
      if (s.error) errors++;
      return { product: t.product, name: path.basename(t.file), uploaded: !!s.uploaded, uploading: !!s.uploading, error: !!s.error };
    });
    _icloudSync = { checked_at: Date.now(), total: targets.length, uploaded, pending, errors, files, error: null };
  });
}
setTimeout(_pollIcloudSync, 30_000);
setInterval(_pollIcloudSync, 15 * 60_000);

// ── Health específico de apps vizinhos (Clockin etc.) ────────────────────────
const CLOCKIN_HEALTH_URL   = process.env.CLOCKIN_HEALTH_URL   || 'http://127.0.0.1:3010/clockin/api/health/full';
const CLOCKIN_HEALTH_TOKEN = process.env.CLOCKIN_HEALTH_TOKEN || '';
let _appHealth = { clockin: { up: null } };
async function _pollAppHealth() {
  const t0 = Date.now();
  try {
    const ctrl = new AbortController();
    const tm = setTimeout(() => ctrl.abort(), 3000);
    const r = await fetch(CLOCKIN_HEALTH_URL, { signal: ctrl.signal, headers: { 'x-health-token': CLOCKIN_HEALTH_TOKEN } });
    clearTimeout(tm);
    const j = await r.json().catch(() => ({}));
    _appHealth.clockin = {
      up:         r.ok,                       // HTTP respondeu
      healthy:    j.ok ?? null,               // health profundo (DB/backup/VAPID)
      version:    j.version || null,
      latency_ms: Date.now() - t0,
      issues:     j.issues  || [],
      metrics:    j.metrics || {},
    };
  } catch (e) {
    _appHealth.clockin = { up: false, error: e.name === 'AbortError' ? 'timeout' : e.message };
  }
}
_pollAppHealth();
setInterval(_pollAppHealth, 5_000);

function _evalLariAlerts() {
  // Diferente do pixbot: lá as 3 instâncias dividem UMA conexão e o alerta é do
  // grupo. Aqui cada assistente tem o SEU número (deivid 556292499830, rafael
  // 5562910006818), então o alerta é POR instância — uma caída é problema mesmo
  // com a outra de pé. Copiar a lógica do pixbot esconderia exatamente este caso.
  for (const l of _lari) {
    const nome = l.user || new URL(l.url).port;
    const kd = `lari_${nome}_down`;
    _alert(kd, _sustained(kd, true, !l.up, LARI_SUSTAIN_MS),
      `🤖 Assistente ${nome} fora do ar`,
      `Sem resposta em ${l.url} há ${_sustainedFor(kd)}min` + (l.error ? ` (${l.error})` : '') + '.',
      'high', ['bubble.left.and.bubble.right'], { repeatEvery: 6 * 3600_000 });
    // O que importa: processo vivo e WhatsApp caído. O app responde, o dono acha
    // que está tudo certo, e mensagem nenhuma entra ou sai. Só afirmo com o HTTP
    // no ar — se está fora, o alerta de cima já cobre e este não tem base.
    const kw = `lari_${nome}_wa_off`;
    _alert(kw, _sustained(kw, !!l.up, l.up && l.connected === false, LARI_SUSTAIN_MS),
      `🤖 Assistente ${nome} sem WhatsApp`,
      `O processo responde mas a sessão do WhatsApp está desconectada há `
      + `${_sustainedFor(kw)}min` + (l.me ? ` (número ${l.me})` : '') + '. '
      + (l.qr_pending ? 'Há QR pendente: precisa parear de novo pelo painel.'
                      : 'Sem QR pendente — costuma religar sozinho; se insistir, refazer o pareamento.'),
      'high', ['exclamationmark.bubble'], { repeatEvery: 12 * 3600_000 });
  }
}

// ── Delega (app de tarefas): 2 instâncias, uma por pessoa ────────────────────
// /api/health devolve { ok, seq, apns, open_tasks }. `seq` NÃO serve de sinal de
// vida: só anda quando alguém escreve, então dia quieto o deixa parado — quem
// prova que está de pé é o próprio HTTP responder.
//
// O que importa alertar num app de tarefas não é só "caiu": é `apns:false`. Sem
// APNs a tarefa continua lá e o lembrete simplesmente não chega — falha silenciosa,
// que é a pior categoria. Por isso ela tem alerta próprio.
const DELEGA_URLS = (process.env.DELEGA_HEALTH_URLS || '').split(',')
  .map(s => s.trim()).filter(Boolean);
let _delega = [];   // [{ label, url, up, ok, seq, apns, open_tasks, latency_ms, error }]

async function _pollDelega() {
  if (!DELEGA_URLS.length) return;
  _delega = await Promise.all(DELEGA_URLS.map(async spec => {
    // formato: "rótulo=url" (o rótulo entra no id do alerta e no card)
    const [label, url] = spec.includes('=') ? spec.split('=') : [new URL(spec).port, spec];
    const t0 = Date.now();
    try {
      const ctrl = new AbortController();
      const tm = setTimeout(() => ctrl.abort(), 4000);
      const r = await fetch(url, { signal: ctrl.signal });
      clearTimeout(tm);
      const j = await r.json().catch(() => ({}));
      return { label, url, up: r.ok, ok: j.ok ?? null, seq: j.seq ?? null,
               apns: j.apns ?? null, open_tasks: j.open_tasks ?? null,
               latency_ms: Date.now() - t0, ts: Date.now() };
    } catch (e) {
      return { label, url, up: false, ts: Date.now(),
               error: e.name === 'AbortError' ? 'timeout' : e.message };
    }
  }));
  _evalDelegaAlerts();
}

function _evalDelegaAlerts() {
  for (const d of _delega) {
    // Sustentação porque deploy reinicia o processo: o `delega` já acumulou 25
    // restarts, e cada um seria um push de "caiu" que se resolve em segundos.
    const kDown = `delega_${d.label}_down`;
    _alert(kDown, _sustained(kDown, true, !d.up, DELEGA_SUSTAIN_MS),
      `📋 Delega ${d.label} fora do ar`,
      `Sem resposta em ${d.url} há ${_sustainedFor(kDown)}min`
      + (d.error ? ` (${d.error})` : '') + '. Tarefas e lembretes param.',
      'high', ['checklist', 'exclamationmark.triangle'],
      { repeatEvery: 6 * 3600_000 });
    // APNs off: só afirmo quando a instância respondeu — se está fora do ar não
    // dá pra dizer nada sobre o push dela, e o alerta de cima já cobre.
    const kApns = `delega_${d.label}_apns_off`;
    _alert(kApns, _sustained(kApns, !!d.up, d.up && d.apns === false, DELEGA_SUSTAIN_MS),
      `📋 Delega ${d.label} sem APNs`,
      `A instância responde mas o APNs está desligado há ${_sustainedFor(kApns)}min: `
      + `as tarefas seguem lá e os lembretes não chegam no iPhone.`,
      'high', ['bell.slash'], { repeatEvery: 12 * 3600_000 });
  }
}
_pollDelega();
setInterval(() => { _pollDelega().catch(e => console.warn('[delega]', e.message)); }, 20_000);

// ── Pixbot (assistente financeiro) e Driver Cred ─────────────────────────────
// Pixbot: 3 instâncias que dividem UMA conexão de WhatsApp. Quem segura o Baileys
// tem `wa:true`; as outras recebem por relay e ficam `wa:false` — que é o estado
// NORMAL delas, não falha. E `relay` no /health é só `!!WA_RELAY_URL`, presença de
// variável: não diz se o relay funciona. Então o alerta não pode ser por instância.
// O que importa é: existe ALGUMA porta de entrada pro WhatsApp? Se nenhuma
// instância tem `wa:true`, ninguém recebe mensagem e o bot fica mudo sem cair.
//
// Atenção ao caminho: no pixbot, `/api/health` devolve o HTML da SPA (catch-all) e
// responde 200. Sondar ali daria "no ar" pra sempre, inclusive com o app quebrado.
// O endpoint de verdade é `/health`.
const PIXBOT_URLS  = (process.env.PIXBOT_HEALTH_URLS  || '').split(',').map(x => x.trim()).filter(Boolean);
const CREDITO_URL  = process.env.CREDITO_HEALTH_URL   || '';
// Resumo operacional (fila de envio + achados do vigia do próprio app). O
// /api/health de lá só diz "no ar"; isto diz O QUE está pendente. Read-only e
// cacheado 60s do lado de lá — o app continua sendo quem NOTIFICA, aqui só mostra.
const CREDITO_VIGIA_URL   = process.env.CREDITO_VIGIA_URL   || '';
const CREDITO_VIGIA_TOKEN = process.env.CREDITO_VIGIA_TOKEN || '';
const MINIAPP_SUSTAIN_MS = +(process.env.MINIAPP_SUSTAIN_MIN || 3) * 60_000;
let _pixbot = [];
let _credito = null;
// Recados (WhatsApp agendado). Monitorar aqui porque o valor dele é justamente
// não depender de eu lembrar: se a sessão cair, o recado de segunda não sai e
// ninguém descobre até alguém cobrar.
// Duas instâncias de Recados (números diferentes). Uma lista, não uma URL:
// vigiar só a primeira deixaria a segunda cair em silêncio.
const RECADOS_ALVOS = (process.env.RECADOS_HEALTH_URLS
  || 'Empresa|http://127.0.0.1:3060/api/saude,Pessoal|http://127.0.0.1:3061/api/saude')
  .split(',').map((par) => {
    const [rotulo, url] = par.split('|');
    return { rotulo: (rotulo || '').trim(), url: (url || '').trim() };
  }).filter((a) => a.url);
let _recados = null;
let _recadosLista = [];
let _creditoVigia = null;   // resumo operacional, atualizado fora do caminho do poller

async function _getJson(url, ms = 5000, headers = null) {
  const ctrl = new AbortController();
  const tm = setTimeout(() => ctrl.abort(), ms);
  try {
    const r = await fetch(url, { signal: ctrl.signal, ...(headers ? { headers } : {}) });
    const ct = (r.headers.get('content-type') || '');
    if (!r.ok) return { _err: 'HTTP ' + r.status };
    // Guarda contra o catch-all de SPA: HTML com 200 não é health.
    if (!/json/i.test(ct)) return { _err: 'resposta não-JSON (catch-all de SPA?)' };
    return await r.json();
  } catch (e) {
    return { _err: e.name === 'AbortError' ? 'timeout' : e.message };
  } finally { clearTimeout(tm); }
}

async function _pollMiniApps() {
  if (PIXBOT_URLS.length) {
    _pixbot = await Promise.all(PIXBOT_URLS.map(async spec => {
      const [label, url] = spec.includes('=') ? spec.split('=') : [new URL(spec).port, spec];
      const t0 = Date.now();
      const j = await _getJson(url);
      if (j._err) return { label, url, up: false, error: j._err, ts: Date.now() };
      return { label, url, up: true, tenant: j.tenant ?? null, wa: j.wa ?? null,
               relay_configured: j.relay ?? null, pending: j.pending ?? null,
               bills_open: j.bills_open ?? null, latency_ms: Date.now() - t0, ts: Date.now() };
    }));
  }
  if (CREDITO_URL) {
    const t0 = Date.now();
    const j = await _getJson(CREDITO_URL);
    _credito = j._err
      ? { up: false, error: j._err, ts: Date.now() }
      : { up: true, ok: j.ok ?? null, chave_pix: j.chave_pix ?? null, pin: j.pin ?? null,
          latency_ms: Date.now() - t0, ts: Date.now() };
    // Resumo operacional: falha aqui não derruba o `up` — o app pode estar no ar
    // com o resumo indisponível, e dizer "fora" por causa disso seria mentira.
    // Sem `await`: no cache miss o lado de lá roda uma checagem que bate na API
    // do Inter e pode levar 12s. Esperar isso travaria o poller inteiro toda vez
    // que o cache de 60s virasse. Atualiza quando chegar; até lá vale o anterior.
    if (_credito.up && CREDITO_VIGIA_URL) {
      const antes = _creditoVigia;
      _getJson(CREDITO_VIGIA_URL, 20000,
               CREDITO_VIGIA_TOKEN ? { 'X-Vigia-Token': CREDITO_VIGIA_TOKEN } : null)
        .then(v => {
          _creditoVigia = v._err
            ? { ...(antes || {}), erro: v._err, ts: Date.now() }   // mantém o último bom
            : { ok: v.ok, achados: v.achados || [], fila: v.fila || null, ts: Date.now() };
        })
        .catch(() => {});
    }
    _credito.vigia = _creditoVigia;
  }
  _recadosLista = [];
  for (const alvo of RECADOS_ALVOS) {
    const j = await _getJson(alvo.url, 8000,
      BRIDGE_TOKEN_HASH ? { Authorization: 'Bearer ' + BRIDGE_TOKEN_HASH } : null);
    _recadosLista.push(j._err
      ? { rotulo: alvo.rotulo, up: false, error: j._err, ts: Date.now() }
      : { rotulo: alvo.rotulo, up: true, ...j, ts: Date.now() });
  }
  _recados = _recadosLista[0] || null;   // compatibilidade com quem lê o singular
  _evalMiniAppAlerts();
}

function _evalMiniAppAlerts() {
  // Duas falhas diferentes: o serviço fora do ar, e o serviço no ar com o
  // WhatsApp despareado. A segunda é a traiçoeira — tudo "verde" e o recado
  // agendado simplesmente não sai na segunda de manhã.
  for (const r of _recadosLista) {
    const suf = r.rotulo ? `_${r.rotulo.replace(/\W+/g, '')}` : '';
    const nome = r.nome || (r.rotulo ? `Recados ${r.rotulo}` : 'Recados');
    _alert(`recados${suf}_down`, r.up === false,
      `💬 ${nome} fora do ar`,
      `O agendador não responde (${r.error || 'sem detalhe'}). Recado marcado não sai.`,
      'high', ['bubble.left.and.bubble.right']);
    const semSessao = r.up === true && r.wa && r.wa.conectado === false;
    _alert(`recados${suf}_wa_off`, semSessao,
      `💬 ${nome} — WhatsApp despareado`,
      `A sessão caiu${r.agendados ? ` e há ${r.agendados} recado(s) agendado(s)` : ''}. `
      + `Reparear em ${r.url_painel || 'recados.malha.dev'}.`,
      r.agendados ? 'high' : 'default', ['link.badge.plus']);
    // Atraso: passou da hora e não saiu. O próprio serviço já tenta de novo e
    // avisa quando esgota; aqui é a segunda rede — se o PROCESSO morrer, ele
    // não avisa ninguém, e é a parede que tem que denunciar.
    _alert(`recados${suf}_atrasado`, r.up === true && !!r.atrasados,
      `💬 ${nome} — recado atrasado`,
      `${r.atrasados} recado(s) passaram da hora e não saíram.`,
      'high', ['clock.badge.exclamationmark']);
  }
  // Pixbot, por instância: só "fora do ar". Nada de julgar `wa` aqui — ver acima.
  for (const p of _pixbot) {
    const k = `pixbot_${p.label}_down`;
    _alert(k, _sustained(k, true, !p.up, MINIAPP_SUSTAIN_MS),
      `💸 Gastos ${p.label} fora do ar`,
      `Sem resposta em ${p.url} há ${_sustainedFor(k)}min`
      + (p.error ? ` (${p.error})` : '') + '.',
      'high', ['dollarsign.circle'], { repeatEvery: 6 * 3600_000 });
  }
  // WhatsApp do grupo: só afirma se ALGUMA instância respondeu — se todas estão
  // fora, o alerta de cima já cobre e este não tem base pra opinar.
  const vivas = _pixbot.filter(p => p.up);
  const semWa = vivas.length > 0 && !vivas.some(p => p.wa === true);
  _alert('pixbot_wa_down', _sustained('pixbot_wa', vivas.length > 0, semWa, MINIAPP_SUSTAIN_MS),
    '💸 Gastos sem WhatsApp',
    `Nenhuma das ${vivas.length} instâncias tem conexão de WhatsApp há ${_sustainedFor('pixbot_wa')}min. `
    + `As instâncias respondem, mas mensagem nova não entra — pode ser sessão Baileys caída (QR).`,
    'high', ['exclamationmark.bubble'], { repeatEvery: 6 * 3600_000 });

  if (_credito) {
    const c = _credito;
    _alert('credito_down', _sustained('credito_down', true, !c.up, MINIAPP_SUSTAIN_MS),
      '🚗 Driver Cred fora do ar',
      `Sem resposta há ${_sustainedFor('credito_down')}min` + (c.error ? ` (${c.error})` : '') + '.',
      'high', ['car'], { repeatEvery: 6 * 3600_000 });
    // Chave PIX ausente é falha silenciosa: o app abre, o kit aparece e o cliente
    // não tem como pagar. Só afirmo com o app no ar.
    _alert('credito_sem_pix', _sustained('credito_pix', !!c.up, c.up && c.chave_pix === false, MINIAPP_SUSTAIN_MS),
      '🚗 Driver Cred sem chave PIX',
      `O app responde mas está sem chave PIX configurada há ${_sustainedFor('credito_pix')}min: `
      + `o cliente vê o kit e não consegue pagar.`,
      'high', ['creditcard.trianglebadge.exclamationmark'], { repeatEvery: 12 * 3600_000 });
  }
}
_pollMiniApps();
setInterval(() => { _pollMiniApps().catch(e => console.warn('[miniapps]', e.message)); }, 20_000);

// ── Lari (whats-assistant): 2 tenants (deivid/rafael), web server próprio ────
const LARI_HEALTH_TOKEN = process.env.LARI_HEALTH_TOKEN || '';
const LARI_HEALTH_URLS  = (process.env.LARI_HEALTH_URLS || '').split(',').map(s => s.trim()).filter(Boolean);
let _lari = []; // [{ url, up, user, connected, me, qr_pending, uptime_sec, latency_ms, pid, mem_mb, cpu, error }]
async function _pollLari() {
  if (!LARI_HEALTH_URLS.length) return;
  const arr = await Promise.all(LARI_HEALTH_URLS.map(async url => {
    const t0 = Date.now();
    try {
      const ctrl = new AbortController();
      const tm = setTimeout(() => ctrl.abort(), 3000);
      const r = await fetch(url, { signal: ctrl.signal, headers: { 'x-health-token': LARI_HEALTH_TOKEN } });
      clearTimeout(tm);
      const j = await r.json().catch(() => ({}));
      return { url, up: r.ok, user: j.user || null, connected: !!j.connected, me: j.me || null,
               qr_pending: !!j.qr_pending, uptime_sec: j.uptime_sec ?? null, latency_ms: Date.now() - t0,
               pid: j.pid || null, mem_mb: null, cpu: null };
    } catch (e) {
      return { url, up: false, error: e.name === 'AbortError' ? 'timeout' : e.message };
    }
  }));
  // mem/cpu via ps (mesma metrica do card Processos): RSS em KB, %cpu.
  const pids = arr.filter(l => l.pid).map(l => l.pid);
  if (pids.length) {
    await new Promise(resolve => {
      exec(`ps -o pid=,rss=,%cpu= -p ${pids.join(',')}`, { timeout: 3000 }, (err, stdout) => {
        if (!err && stdout) {
          for (const line of stdout.trim().split('\n')) {
            const m = /^\s*(\d+)\s+(\d+)\s+([\d.]+)/.exec(line);
            if (!m) continue;
            const ent = arr.find(l => l.pid === +m[1]);
            if (ent) { ent.mem_mb = Math.round(+m[2] / 1024); ent.cpu = +m[3]; }
          }
        }
        resolve();
      });
    });
  }
  _lari = arr;
  _evalLariAlerts();
}
_pollLari();
setInterval(_pollLari, 5_000);

