// Aceita token de escrita OU sessão admin. Motivo: o monitor roda com token de
// escopo `read` (privilégio mínimo — se o localStorage do browser vazar, ninguém
// comanda o carro), e aí o POST tomava 403 e o botão "limpar eventos" não fazia
// nada. Ação de escrita na página de leitura tem que se autenticar por outro
// caminho, e a sessão admin do card Tokens é exatamente isso.
function requireWriteOrAdmin(req, res, next) {
  const sid = (req.headers['x-admin-session'] || '').toString().trim();
  if (sid && adminAuth.validSession(sid)) { req.authScope = 'admin'; req.authSource = 'admin-session'; return next(); }
  return requireAuth(req, res, next);
}

app.post('/api/health/events/clear', (_req, res) => {
  _healthEvents = [];
  _saveHealthEvents();
  res.json({ ok: true });
});

// Lista top-30 processos do sistema (CPU/mem) — Activity Monitor estilo.
// macOS não expõe GPU per-process sem sudo (powermetrics), então só CPU+mem.
app.get('/api/proc-list', requireAuth, (_req, res) => {
  exec('LC_ALL=C ps -axo pid,pcpu,pmem,rss,user,comm -r', { maxBuffer: 4 * 1024 * 1024, timeout: 4000 }, (err, stdout) => {
    if (err) return res.json({ ok: false, error: err.message, list: [] });
    const lines = stdout.split('\n').slice(1).filter(Boolean).slice(0, 60);
    const list = [];
    for (const l of lines) {
      const m = l.trim().match(/^(\d+)\s+([\d.]+)\s+([\d.]+)\s+(\d+)\s+(\S+)\s+(.+)$/);
      if (!m) continue;
      const name = m[6].trim().split('/').pop();
      list.push({ pid: +m[1], cpu: +m[2], mem: +m[3], rssMb: Math.round(+m[4] / 1024), user: m[5], name });
    }
    res.json({ ok: true, ts: Date.now(), list: list.slice(0, 30) });
  });
});

// ── /api/auth/* — rotas de autenticação (públicas e privadas) ────────────────
// Rate limit simples por IP pra /api/auth/login: 5 tentativas/min, 15min de
// bloqueio após 10 falhas consecutivas. Hash da senha NUNCA volta no response.
const _loginAttempts = new Map();   // ip → { count, firstMs, blockedUntilMs }
// Purga entradas que já passaram da janela de bloqueio (evita crescimento indefinido).
setInterval(() => {
  const now = Date.now();
  for (const [ip, s] of _loginAttempts)
    if (s.blockedUntilMs < now && now - s.firstMs > 60_000) _loginAttempts.delete(ip);
}, 10 * 60_000);
function _checkRateLimit(ip) {
  const now = Date.now();
  let s = _loginAttempts.get(ip);
  if (!s) { s = { count: 0, firstMs: now, blockedUntilMs: 0 }; _loginAttempts.set(ip, s); }
  if (s.blockedUntilMs > now) return { ok: false, retryAfterSec: Math.ceil((s.blockedUntilMs - now) / 1000) };
  if (now - s.firstMs > 60_000) { s.count = 0; s.firstMs = now; }  // janela de 1min
  return { ok: true, state: s };
}
function _registerFailure(s) {
  s.count++;
  if (s.count >= 10) s.blockedUntilMs = Date.now() + 15 * 60_000;   // bloqueio 15min
}
function _registerSuccess(ip) { _loginAttempts.delete(ip); }

// POST /api/auth/login — { password_hash, totp_code? } → { ok, token? }
app.post('/api/auth/login', (req, res) => {
  const ip = req.ip || req.connection?.remoteAddress || 'unknown';
  const rl = _checkRateLimit(ip);
  if (!rl.ok) return res.status(429).json({ error: 'rate_limited', retry_after_sec: rl.retryAfterSec });
  if (rl.state.count >= 5) return res.status(429).json({ error: 'too_many_attempts' });
  const { password_hash, totp_code } = req.body || {};
  // Sem hash configurado: só aceita login em dev explícito; senão trancado.
  if (!BRIDGE_TOKEN_HASH) {
    if (ALLOW_NO_AUTH) return res.json({ ok: true, token: '' });
    return res.status(503).json({ error: 'auth_not_configured' });
  }
  const passwordValid = safeStrEqual(password_hash, BRIDGE_TOKEN_HASH) ||
                        (password_hash && safeStrEqual(sha256hex(password_hash), BRIDGE_TOKEN_HASH));
  if (!passwordValid) {
    _registerFailure(rl.state);
    return res.status(401).json({ error: 'invalid_password' });
  }
  // Senha ok. Se 2FA está ativo, exige o código.
  if (is2faEnabled()) {
    if (!totp_code) return res.status(401).json({ error: 'totp_required', requires_2fa: true });
    if (!verifyTotpOrBackup(totp_code)) {
      _registerFailure(rl.state);
      return res.status(401).json({ error: 'invalid_totp' });
    }
  }
  _registerSuccess(ip);
  res.json({ ok: true, token: BRIDGE_TOKEN_HASH });
});

// GET /api/auth/2fa/status — pública: PWA chama no início pra saber se precisa pedir código
app.get('/api/auth/2fa/status', (_req, res) => res.json({ enabled: is2faEnabled() }));

// ── Google Sign-In ────────────────────────────────────────────────────────────
const GOOGLE_OAUTH_CLIENT_ID = process.env.GOOGLE_OAUTH_CLIENT_ID || '';
// O app iOS usa um OAuth client iOS próprio → o ID token vem com aud = client iOS,
// diferente do client web. Aceitamos ambos como audiência válida.
const GOOGLE_IOS_CLIENT_ID   = process.env.GOOGLE_IOS_CLIENT_ID || '';
const GOOGLE_AUDIENCES = [GOOGLE_OAUTH_CLIENT_ID, GOOGLE_IOS_CLIENT_ID].filter(Boolean);
const GOOGLE_ALLOWED_EMAILS  = (process.env.GOOGLE_ALLOWED_EMAILS || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
let googleAuthClient = null;
if (GOOGLE_OAUTH_CLIENT_ID) {
  try {
    const { OAuth2Client } = require('google-auth-library');
    googleAuthClient = new OAuth2Client(GOOGLE_OAUTH_CLIENT_ID);
    console.log(`✓ Google Sign-In: client configurado · ${GOOGLE_ALLOWED_EMAILS.length} email(s) na whitelist`);
  } catch (e) { console.error('Falha google-auth-library:', e.message); }
}

// GET /api/auth/google/config — público. PWA usa pra saber se renderiza botão e qual client ID.
app.get('/api/auth/google/config', (_req, res) => res.json({
  enabled:    !!googleAuthClient,
  client_id:  GOOGLE_OAUTH_CLIENT_ID || null,
}));

// POST /api/auth/google/login — { credential (ID token), totp_code? } → { ok, token }
// Verifica o ID token (assinado pelo Google), checa email contra whitelist,
// aplica 2FA TOTP se ativo. Retorna o bearer (mesmo BRIDGE_TOKEN_HASH).
app.post('/api/auth/google/login', async (req, res) => {
  if (!googleAuthClient) return res.status(503).json({ error: 'google_login_disabled' });
  const ip = req.ip || req.connection?.remoteAddress || 'unknown';
  const rl = _checkRateLimit(ip);
  if (!rl.ok) return res.status(429).json({ error: 'rate_limited', retry_after_sec: rl.retryAfterSec });
  if (rl.state.count >= 5) return res.status(429).json({ error: 'too_many_attempts' });

  const { credential, totp_code } = req.body || {};
  if (!credential) return res.status(400).json({ error: 'missing_credential' });

  let payload;
  try {
    const ticket = await googleAuthClient.verifyIdToken({
      idToken:  credential,
      audience: GOOGLE_AUDIENCES,
    });
    payload = ticket.getPayload();
  } catch (e) {
    _registerFailure(rl.state);
    return res.status(401).json({ error: 'invalid_credential', detail: e.message });
  }

  const email = (payload?.email || '').toLowerCase();
  if (!email || !payload.email_verified) {
    _registerFailure(rl.state);
    return res.status(401).json({ error: 'email_not_verified' });
  }
  if (GOOGLE_ALLOWED_EMAILS.length > 0 && !GOOGLE_ALLOWED_EMAILS.includes(email)) {
    _registerFailure(rl.state);
    return res.status(403).json({ error: 'email_not_allowed', email });
  }

  // 2FA: se ativo, exige o código (igual ao login por senha)
  if (is2faEnabled()) {
    if (!totp_code) return res.status(401).json({ error: 'totp_required', requires_2fa: true, email });
    if (!verifyTotpOrBackup(totp_code)) {
      _registerFailure(rl.state);
      return res.status(401).json({ error: 'invalid_totp' });
    }
  }

  _registerSuccess(ip);
  console.log(`[auth] login Google OK · ${email}`);
  res.json({ ok: true, token: BRIDGE_TOKEN_HASH, email });
});

// ── Sign in with Apple ────────────────────────────────────────────────────
// aud do ID token nativo = o App ID (bundle). Verificamos a assinatura RS256 com
// as chaves públicas da Apple (JWKS) — Node converte JWK→chave nativamente.
const APPLE_CLIENT_IDS = (process.env.APPLE_CLIENT_ID || process.env.APNS_BUNDLE_ID || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const APPLE_ALLOWED_EMAILS = (process.env.APPLE_ALLOWED_EMAILS || process.env.GOOGLE_ALLOWED_EMAILS || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const APPLE_ENABLED = APPLE_CLIENT_IDS.length > 0;
if (APPLE_ENABLED) console.log(`✓ Sign in with Apple: aud=${APPLE_CLIENT_IDS.join(',')} · ${APPLE_ALLOWED_EMAILS.length} email(s) na whitelist`);

let _appleJwksCache = { keys: [], ts: 0 };
async function _appleJwks() {
  if (_appleJwksCache.keys.length && (Date.now() - _appleJwksCache.ts) < 3600_000) return _appleJwksCache.keys;
  const r = await fetch('https://appleid.apple.com/auth/keys');
  const d = await r.json();
  _appleJwksCache = { keys: d.keys || [], ts: Date.now() };
  return _appleJwksCache.keys;
}
async function _verifyAppleIdToken(idToken) {
  const crypto = require('crypto');
  const [h, p, s] = String(idToken).split('.');
  if (!h || !p || !s) throw new Error('token malformado');
  const header  = JSON.parse(Buffer.from(h, 'base64url').toString('utf8'));
  const jwk = (await _appleJwks()).find(k => k.kid === header.kid);
  if (!jwk) throw new Error('kid desconhecido');
  const pub = crypto.createPublicKey({ key: jwk, format: 'jwk' });
  const ok  = crypto.verify('RSA-SHA256', Buffer.from(`${h}.${p}`), pub, Buffer.from(s, 'base64url'));
  if (!ok) throw new Error('assinatura inválida');
  const payload = JSON.parse(Buffer.from(p, 'base64url').toString('utf8'));
  if (payload.iss !== 'https://appleid.apple.com') throw new Error('iss inválido');
  if (!APPLE_CLIENT_IDS.includes(payload.aud)) throw new Error('aud inválido (' + payload.aud + ')');
  if ((payload.exp || 0) * 1000 < Date.now()) throw new Error('expirado');
  return payload;
}

app.get('/api/auth/apple/config', (_req, res) => res.json({
  enabled: APPLE_ENABLED, client_id: APPLE_CLIENT_IDS[0] || null,
}));

// POST /api/auth/apple/login — { credential (ID token), totp_code? } → { ok, token }
app.post('/api/auth/apple/login', async (req, res) => {
  if (!APPLE_ENABLED) return res.status(503).json({ error: 'apple_login_disabled' });
  const ip = req.ip || req.connection?.remoteAddress || 'unknown';
  const rl = _checkRateLimit(ip);
  if (!rl.ok) return res.status(429).json({ error: 'rate_limited', retry_after_sec: rl.retryAfterSec });
  if (rl.state.count >= 5) return res.status(429).json({ error: 'too_many_attempts' });

  const { credential, totp_code } = req.body || {};
  if (!credential) return res.status(400).json({ error: 'missing_credential' });

  let payload;
  try { payload = await _verifyAppleIdToken(credential); }
  catch (e) { _registerFailure(rl.state); return res.status(401).json({ error: 'invalid_credential', detail: e.message }); }

  const email = (payload.email || '').toLowerCase();
  if (!email) {  // Apple só manda email se o usuário concedeu; sub é estável
    _registerFailure(rl.state);
    return res.status(401).json({ error: 'email_missing', sub: payload.sub });
  }
  if (APPLE_ALLOWED_EMAILS.length > 0 && !APPLE_ALLOWED_EMAILS.includes(email)) {
    _registerFailure(rl.state);
    console.warn(`[auth] login Apple NEGADO · email fora da whitelist: ${email}`);
    return res.status(403).json({ error: 'email_not_allowed', email });
  }
  if (is2faEnabled()) {
    if (!totp_code) return res.status(401).json({ error: 'totp_required', requires_2fa: true, email });
    if (!verifyTotpOrBackup(totp_code)) { _registerFailure(rl.state); return res.status(401).json({ error: 'invalid_totp' }); }
  }

  _registerSuccess(ip);
  console.log(`[auth] login Apple OK · ${email}`);
  res.json({ ok: true, token: BRIDGE_TOKEN_HASH, email });
});

// impulse-help: registrado ANTES do middleware blanket abaixo — rotas públicas
// (/status, /oauth/callback, /ask) ficam acessíveis; /oauth/start e /refresh já
// pegam requireAuth inline dentro do módulo.
impulseHelp.install(app, { requireAuth });
carHelp.install(app);

// requireAuth: aplica a toda a API exceto /api/push/* (SW não consegue enviar headers)
// e rotas de auth públicas (login, google, status).
app.use('/api', (req, res, next) => {
  if (req.path.startsWith('/push')) return next();        // push routes: sem auth
  if (req.path === '/auth/login' ||
      req.path === '/auth/2fa/status' ||
      req.path === '/auth/google/config' ||
      req.path === '/auth/google/login' ||
      req.path === '/auth/passkey/available' ||
      req.path === '/auth/passkey/login/begin' ||
      req.path === '/auth/passkey/login/finish' ||
      req.path === '/pair/redeem' ||
      req.path === '/mapkit/token') return next();   // mapkit/token: JWT só vale pra Apple Maps, não dá acesso a nada do bridge
  // Compartilhamento de status: páginas públicas validadas pelo token na própria URL.
  // `call` e `call/end`: a página share.html liga pro carro; o gate é o token do
  // share (+ cooldown/TTL/owner na própria rota), não o token do bridge.
  if (/^\/share\/[^/]+\/(state|eta|call|call\/end|message|message-audio)$/.test(req.path)) return next();
  // Áudio do recado: quem baixa é o MediaPlayer do carro, que não manda header
  // de Authorization. O gate é o id aleatório de 24 hex no path (+ TTL de 24h).
  if (/^\/voice\/[a-f0-9]{24}\.[a-z0-9]{2,4}$/.test(req.path)) return next();
  // Config de tiles: a página compartilhada é pública e precisa ler antes de
  // montar o mapa. Só expõe a chave de TILES (não a de Directions).
  if (req.path === '/maps-tiles-key' || req.path === '/maps-tiles-session') return next();
  // Trajeto compartilhado: /api/shared-trip/:token — token da URL faz o gate.
  if (/^\/shared-trip\/[^/]+$/.test(req.path)) return next();
  // Upload de gravação: o carro autentica com nonce de uso único (X-Rec-Token),
  // não com o token do bridge — a própria rota valida. Sem isso o requireAuth
  // devolvia 401 e o carro quebrava o stream (broken pipe) no meio do POST.
  if (req.path === '/rec/upload') return next();
  // Dois botões do monitor sem auth, por decisão explícita do dono: o monitor roda
  // com token `read` (privilégio mínimo) e esses POSTs tomavam 403 calado. São
  // ações de baixo impacto — zerar um contador de observação e limpar o log de
  // erros do próprio monitor. Não tocam em dado de negócio nem comandam o carro.
  // Ficam abertos em bridge.malha.dev, que é público: quem descobrir a URL pode
  // zerar essas duas coisas.
  if (req.path === '/host-hits/reset' || req.path === '/health/events/clear') return next();
  // Painel admin: tem autenticação PRÓPRIA (senha + TOTP, header
  // X-Admin-Session) e não pode exigir o token do bridge — é justamente de onde
  // se emite token novo quando não se tem nenhum. Cada rota /admin/* aplica
  // requireAdmin por conta, exceto as de bootstrap (state / setup-password /
  // totp / login), que são gateadas por senha e rate limit.
  if (req.path === '/admin/state' || req.path.startsWith('/admin/')) return next();
  requireAuth(req, res, next);
});

// POST /api/auth/2fa/setup — autenticado. Gera secret + QR + backup codes
// mas NÃO ativa ainda. Cliente precisa confirmar via /api/auth/2fa/activate.
let _pending2faSecret = null;   // { secret, generatedAt }
app.post('/api/auth/2fa/setup', async (req, res) => {
  const secret = otplib.authenticator.generateSecret();
  _pending2faSecret = { secret, generatedAt: Date.now() };
  const issuer = 'EcoTrip Impulse';
  const label  = 'bridge';
  const uri    = otplib.authenticator.keyuri(label, issuer, secret);
  const qrDataUrl = await QRCode.toDataURL(uri);
  res.json({ secret, qr: qrDataUrl, otpauth_uri: uri });
});

// POST /api/auth/2fa/activate — { code } confirma e persiste. Retorna backup codes.
app.post('/api/auth/2fa/activate', (req, res) => {
  const { code } = req.body || {};
  if (!_pending2faSecret) return res.status(400).json({ error: 'no_pending_setup' });
  if (Date.now() - _pending2faSecret.generatedAt > 10 * 60_000) {
    _pending2faSecret = null;
    return res.status(400).json({ error: 'setup_expired' });
  }
  if (!code || !otplib.authenticator.check(String(code).trim(), _pending2faSecret.secret)) {
    return res.status(401).json({ error: 'invalid_code' });
  }
  authConfig.totp_secret  = _pending2faSecret.secret;
  authConfig.backup_codes = genBackupCodes(10);
  saveAuthConfig();
  _pending2faSecret = null;
  res.json({ ok: true, backup_codes: authConfig.backup_codes });
});

// POST /api/auth/2fa/disable — autenticado + exige código TOTP atual
app.post('/api/auth/2fa/disable', (req, res) => {
  if (!is2faEnabled()) return res.json({ ok: true, already_disabled: true });
  const { code } = req.body || {};
  if (!verifyTotpOrBackup(code)) return res.status(401).json({ error: 'invalid_code' });
  authConfig = { totp_secret: '', backup_codes: [] };
  saveAuthConfig();
  res.json({ ok: true });
});

// GET /api/auth/2fa/backup-codes — lista códigos restantes (não regenera)
app.get('/api/auth/2fa/backup-codes', (_req, res) => {
  res.json({ enabled: is2faEnabled(), backup_codes: authConfig.backup_codes || [] });
});

// POST /api/auth/2fa/regenerate-backup — gera nova lista, descarta a antiga
app.post('/api/auth/2fa/regenerate-backup', (req, res) => {
  if (!is2faEnabled()) return res.status(400).json({ error: 'not_enabled' });
  const { code } = req.body || {};
  if (!verifyTotpOrBackup(code)) return res.status(401).json({ error: 'invalid_code' });
  authConfig.backup_codes = genBackupCodes(10);
  saveAuthConfig();
  res.json({ ok: true, backup_codes: authConfig.backup_codes });
});

// ── Passkeys (WebAuthn) ───────────────────────────────────────────────────────
// Login biométrico complementar (Face ID/Touch ID/fingerprint). O user PRIMEIRO
// faz login normal com senha+TOTP; daí registra a passkey nesse device. Próximas
// vezes pode entrar direto com biometria. O caminho senha+TOTP continua existindo
// como fallback se o device for perdido.
const PASSKEYS_FILE = path.join(DATA_DIR, 'passkeys.json');
let passkeys = [];
try {
  if (fs.existsSync(PASSKEYS_FILE)) {
    passkeys = JSON.parse(fs.readFileSync(PASSKEYS_FILE, 'utf8')).passkeys || [];
    console.log(`✓ Passkeys: ${passkeys.length} registrada(s)`);
  }
} catch (e) { console.error('Aviso passkeys.json:', e.message); }
function savePasskeys() {
  try {
    fs.writeFileSync(PASSKEYS_FILE, JSON.stringify({
      updatedAt: new Date().toISOString(),
      passkeys,
    }, null, 2));
  } catch (e) { console.error('Falha salvar passkeys:', e.message); }
}

// Challenges efêmeros — TTL 5min. Sem persistência: se o bridge cai no meio
// do registro/login, é só recomeçar.
const _passkeyChallenges = new Map();   // challenge → expiresMs
const _PASSKEY_CHALLENGE_TTL = 5 * 60 * 1000;
function _putChallenge(ch) { _passkeyChallenges.set(ch, Date.now() + _PASSKEY_CHALLENGE_TTL); }
function _takeChallenge(ch) {
  const exp = _passkeyChallenges.get(ch);
  if (!exp) return false;
  _passkeyChallenges.delete(ch);
  return exp > Date.now();
}
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of _passkeyChallenges) if (v < now) _passkeyChallenges.delete(k);
}, 10 * 60 * 1000).unref();

// Lazy import — só quando o primeiro endpoint é chamado, pra não atrasar boot.
let _swa = null;
function _swaLib() {
  if (!_swa) _swa = require('@simplewebauthn/server');
  return _swa;
}

// rpID é o domínio (sem protocolo nem porta). Pega do header Host pra suportar
// Tailscale Funnel sem hardcode. Origin é montado com https:// porque WebAuthn
// só funciona em HTTPS (ou localhost).
function _passkeyRpInfo(req) {
  const host = req.headers.host || 'localhost';
  const rpID = host.split(':')[0];
  const proto = (rpID === 'localhost' || rpID.startsWith('127.')) ? 'http' : 'https';
  const origin = `${proto}://${host}`;
  return { rpID, rpName: 'EcoTrip', origin };
}

// GET /api/auth/passkey — lista passkeys do user (autenticado)
app.get('/api/auth/passkey', (_req, res) => {
  res.json({
    passkeys: passkeys.map(p => ({
      id: p.id,
      device_name: p.device_name || 'Dispositivo',
      created_ms: p.created_ms,
      last_used_ms: p.last_used_ms || null,
    })),
  });
});

// POST /api/auth/passkey/register/begin — gera challenge de registro (autenticado)
app.post('/api/auth/passkey/register/begin', async (req, res) => {
  try {
    const { rpID, rpName } = _passkeyRpInfo(req);
    const opts = await _swaLib().generateRegistrationOptions({
      rpName, rpID,
      userID:    Buffer.from('ecotrip-user'),         // single-user
      userName:  'EcoTrip',
      attestationType: 'none',
      excludeCredentials: passkeys.map(p => ({
        id: p.id,
        transports: p.transports,
      })),
      authenticatorSelection: {
        residentKey: 'preferred',
        userVerification: 'preferred',                 // Face ID/Touch ID quando disponível
      },
    });
    _putChallenge(opts.challenge);
    res.json(opts);
  } catch (e) {
    console.error('passkey register/begin:', e);
    res.status(500).json({ error: e.message });
  }
});

// POST /api/auth/passkey/register/finish — valida e armazena a credential
app.post('/api/auth/passkey/register/finish', async (req, res) => {
  try {
    const { response, device_name } = req.body || {};
    if (!response) return res.status(400).json({ error: 'missing response' });
    const expectedChallenge = response.response?.clientDataJSON
      ? JSON.parse(Buffer.from(response.response.clientDataJSON, 'base64url').toString()).challenge
      : null;
    if (!expectedChallenge || !_takeChallenge(expectedChallenge)) {
      return res.status(400).json({ error: 'invalid_or_expired_challenge' });
    }
    const { rpID, origin } = _passkeyRpInfo(req);
    const verification = await _swaLib().verifyRegistrationResponse({
      response,
      expectedChallenge,
      expectedOrigin: origin,
      expectedRPID:   rpID,
    });
    if (!verification.verified || !verification.registrationInfo) {
      return res.status(400).json({ error: 'verification_failed' });
    }
    const reg = verification.registrationInfo;
    const cred = reg.credential || reg;       // v13 traz dentro de .credential
    const newPk = {
      id:           cred.id,
      publicKey:    Buffer.from(cred.publicKey).toString('base64url'),
      counter:      cred.counter || 0,
      transports:   cred.transports || response.response?.transports || [],
      device_name:  String(device_name || 'Dispositivo').slice(0, 60),
      created_ms:   Date.now(),
      last_used_ms: null,
    };
    passkeys.push(newPk);
    savePasskeys();
    console.log(`[passkey] registrada: ${newPk.device_name} (id=${newPk.id.slice(0, 12)}…)`);
    res.json({ ok: true, id: newPk.id });
  } catch (e) {
    console.error('passkey register/finish:', e);
    res.status(500).json({ error: e.message });
  }
});

// DELETE /api/auth/passkey/:id — remove passkey
app.delete('/api/auth/passkey/:id', (req, res) => {
  const id = String(req.params.id);
  const idx = passkeys.findIndex(p => p.id === id);
  if (idx < 0) return res.status(404).json({ error: 'not_found' });
  const [removed] = passkeys.splice(idx, 1);
  savePasskeys();
  console.log(`[passkey] removida: ${removed.device_name}`);
  res.json({ ok: true });
});

// POST /api/auth/passkey/login/begin — público. Gera challenge + lista de
// credentials permitidas. Sem rate limit aqui — o limit aplica ao /finish.
app.post('/api/auth/passkey/login/begin', async (req, res) => {
  try {
    if (!passkeys.length) return res.status(404).json({ error: 'no_passkeys_registered' });
    const { rpID } = _passkeyRpInfo(req);
    const opts = await _swaLib().generateAuthenticationOptions({
      rpID,
      allowCredentials: passkeys.map(p => ({
        id: p.id,
        transports: p.transports,
      })),
      userVerification: 'preferred',
    });
    _putChallenge(opts.challenge);
    res.json(opts);
  } catch (e) {
    console.error('passkey login/begin:', e);
    res.status(500).json({ error: e.message });
  }
});

// POST /api/auth/passkey/login/finish — valida assertion e emite o bearer
app.post('/api/auth/passkey/login/finish', async (req, res) => {
  const ip = req.ip || req.connection?.remoteAddress || 'unknown';
  const rl = _checkRateLimit(ip);
  if (!rl.ok) return res.status(429).json({ error: 'rate_limited', retry_after_sec: rl.retryAfterSec });
  if (rl.state.count >= 5) return res.status(429).json({ error: 'too_many_attempts' });
  try {
    const { response } = req.body || {};
    if (!response?.id) return res.status(400).json({ error: 'missing response' });
    const cred = passkeys.find(p => p.id === response.id);
    if (!cred) { _registerFailure(rl.state); return res.status(401).json({ error: 'unknown_credential' }); }
    const expectedChallenge = response.response?.clientDataJSON
      ? JSON.parse(Buffer.from(response.response.clientDataJSON, 'base64url').toString()).challenge
      : null;
    if (!expectedChallenge || !_takeChallenge(expectedChallenge)) {
      _registerFailure(rl.state);
      return res.status(400).json({ error: 'invalid_or_expired_challenge' });
    }
    const { rpID, origin } = _passkeyRpInfo(req);
    const verification = await _swaLib().verifyAuthenticationResponse({
      response,
      expectedChallenge,
      expectedOrigin: origin,
      expectedRPID:   rpID,
      credential: {
        id:        cred.id,
        publicKey: Buffer.from(cred.publicKey, 'base64url'),
        counter:   cred.counter || 0,
        transports: cred.transports,
      },
    });
    if (!verification.verified) {
      _registerFailure(rl.state);
      return res.status(401).json({ error: 'verification_failed' });
    }
    // Atualiza counter (anti-replay) + last_used
    cred.counter      = verification.authenticationInfo?.newCounter ?? cred.counter;
    cred.last_used_ms = Date.now();
    savePasskeys();
    _registerSuccess(ip);
    console.log(`[auth] login passkey OK · ${cred.device_name}`);
    res.json({ ok: true, token: BRIDGE_TOKEN_HASH });
  } catch (e) {
    console.error('passkey login/finish:', e);
    res.status(500).json({ error: e.message });
  }
});

// GET /api/auth/passkey/available — público, conta passkeys cadastradas
// (PWA usa pra decidir se mostra o botão "Entrar com biometria")
app.get('/api/auth/passkey/available', (_req, res) => {
  res.json({ count: passkeys.length, available: passkeys.length > 0 });
});

app.get('/api/state',  (_req, res) => res.json({
  ...state, _field_source: _fieldSource,
  // Idade REAL da medição, pro app não escrever "agora" sobre dado de horas atrás.
  medicao_ms: _ultimaMedicaoMs(),
  // Navegação do AA. Reavaliada NA LEITURA: o probe manda a cada ~7s, então um _nav
  // sem refresh há 45s significa que o carro parou de publicar (app fechado, MQTT
  // caído) — e aí não há ETA, em vez de um ETA congelado.
  // Inativo preserva `reason`/`apk`/`ms`: substituir por `{active:false}` seco jogava
  // fora justamente o diagnóstico que o probe manda ("sem rota ativa (updatedAtMs=0)",
  // "provider não respondeu"), e eu ficava sem saber de fora se era ausência de rota ou
  // probe morto — a mesma cegueira que o APK tinha até a 6.224.
  nav: (_nav.active && (Date.now() - (_nav.ms || 0)) < 45_000)
    ? _nav
    : { active: false, reason: _nav.reason || '', apk: _nav.apk || '',
        ms: _nav.ms || 0, idade_s: _nav.ms ? Math.round((Date.now() - _nav.ms) / 1000) : null },
  // O probe publica a cada troca de faixa e bate a cada 30s. 90s sem nada = o carro
  // parou de publicar (app fechado, MQTT caído), não "a música continua".
  // Exige PLAY ATIVO, não só ter faixa: pausado não é escutado. O probe bate a cada
  // 30s, então 90s sem amostra = o carro parou de publicar.
  media: (_media.playing && _media.title && (Date.now() - (_media.ms || 0)) < 90_000)
    ? _media : { playing: false },
  // ── Recarga ao vivo quando o APK está fora ────────────────────────────────
  // `charge_power_kw` e `charge_session_kwh` existem SÓ no APK. Com ele caído (19/08:
  // 17 mortes em 18/08 pela regressão do pool) o card mostrava "0,0 kW · +0,0 kWh"
  // carregando — zero medido e zero por ausência ficam indistinguíveis, e o zero
  // mentia. O SOC vem fresco da GWM, então a energia da sessão é derivável sem o APK.
  charge_power_confiavel: _campoConfiavel('charge_power_kw'),
  charge_session_kwh_est: (() => {
    if (state.charging_state !== 'Carregando') return null;
    const ini = +state.charge_start_soc_pct || 0;
    const agora = +state.soc_pct || 0;
    if (!(ini > 0) || !(agora > ini)) return null;
    return +(((agora - ini) / 100) * BATTERY_CAPACITY_KWH).toFixed(2);
  })(),
  // Idade POR CAMPO: quando cada chave foi confirmada ao vivo. A idade global não
  // servia pra decidir se "Motor ligado" pode ser afirmado — o carro publica dezenas
  // de campos, e um deles fresco fazia todos parecerem frescos.
  _field_seen: Object.fromEntries(
    Object.keys(_srcChange).map(k => [k, _fieldSeenMs(k)]).filter(([, v]) => v)),
}));
app.get('/api/counts', (_req, res) => res.json({
  trips:     0,                  // Trip A/B descontinuados
  autotrips: autoTripsArr.length,
  charges:   chargesArr.length,
}));
// /api/trips removido — Trip A/B descontinuados. Retorna 410 (Gone).
app.get('/api/trips', (_req, res) => res.status(410).json({ error: 'Trip A/B descontinuados' }));
app.delete('/api/trips/:tripId', (_req, res) => res.status(410).json({ error: 'Trip A/B descontinuados' }));
// Aplica edições manuais (manual_overrides) sobre os valores base do Android.
// Recalcula avg_power_kw quando energy_kwh ou duration_sec foram editados.
// Retorna um objeto novo (não muta o original em chargesArr).
function applyChargeOverrides(c) {
  if (!c || !c.manual_overrides || Object.keys(c.manual_overrides).length === 0) return c;
  const eff = { ...c, ...c.manual_overrides };
  // Recalcula potência média se energia ou duração foram editados
  const energy = +eff.energy_kwh;
  const dur    = +eff.duration_sec;
  if (energy > 0 && dur > 0) eff.avg_power_kw = (energy * 3600) / dur;
  // Sinaliza pra PWA quais campos vieram de edição
  eff._overridden_fields = Object.keys(c.manual_overrides);
  return eff;
}

// Cursor de sync incremental: ignora `since` no futuro. O relógio do carro/APK
// já publicou recargas com timestamp_ms adiantado; o cliente (SyncedList) avança
// o ponteiro pro maior campo visto e, com um valor futuro, fica preso — `?since=
// <futuro>` passa a retornar vazio pra sempre e dados novos somem. Clampa pra 0
// (full sync) quando o cursor está à frente do relógio do servidor.
function parseSince(req) {
  const s = parseInt(req.query.since || '0', 10);
  if (!Number.isFinite(s) || s <= 0) return 0;
  return s > Date.now() + 60_000 ? 0 : s;
}

// Watermark de sync: o cliente usa X-Sync-Ms (relógio do SERVIDOR no instante da
// resposta) como cursor do próximo ?since=. Sem isso o cliente adivinhava o cursor
// pelo maior timestamp dos itens — que vem do relógio do CARRO (adiantado) e
// travava o sync no futuro (bug do pull-to-refresh).
function setSyncWatermark(res) {
  // −1ms: o filtro do ?since= é `>` estrito — item ingerido no MESMO ms da
  // resposta seria perdido. Recuar 1ms só re-envia (upsert, inofensivo).
  res.setHeader('X-Sync-Ms', String(Date.now() - 1));
  res.setHeader('Access-Control-Expose-Headers', 'X-Tombstones, X-Sync-Ms');
}

app.get('/api/charges', (req, res) => {
  setSyncWatermark(res);
  const since = parseSince(req);
  // Retorna entradas novas (timestamp_ms > since) OU atualizadas (_updated_ms > since)
  const filtered = since > 0
    ? chargesArr.filter(c => (c.timestamp_ms || 0) > since || (c._updated_ms || 0) > since)
    : chargesArr;
  // Tombstones: PWA precisa saber quais IDs foram deletados pra remover do
  // cache local (sem isso, merge incremental mantinha entries fantasma após
  // delete/merge). Mandados via header pra preservar shape do body (array).
  if (Array.isArray(deletedIds.charges) && deletedIds.charges.length) {
    res.setHeader('X-Tombstones', deletedIds.charges.join(','));
    res.setHeader('Access-Control-Expose-Headers', 'X-Tombstones');
  }
  res.json(filtered.map(applyChargeOverrides));
});

app.delete('/api/charges/:ts', (req, res) => {
  const ts  = parseInt(req.params.ts, 10);
  const idx = chargesArr.findIndex(c => (c.timestamp_ms || 0) === ts);
  if (idx < 0) return res.status(404).json({ error: 'not found' });
  chargesArr.splice(idx, 1);
  scheduleChargesFlush();
  markDeleted('charges', ts);
  recomputeBatteryAvgPrice();
  console.log(`[delete] Charge ${ts} removida (tombstone gravado)`);
  res.json({ ok: true });
});

// ── Linha do tempo de recarga (amostras de potência/energia) ─────────────────
const CHARGE_TELEMETRY_DIR = path.join(DATA_DIR, 'charge_telemetry');
try { require('fs').mkdirSync(CHARGE_TELEMETRY_DIR, { recursive: true }); } catch (_) {}

app.post('/api/charges/:ts/samples', (req, res) => {
  const ts = parseInt(req.params.ts, 10);
  if (!ts) return res.status(400).json({ error: 'ts inválido' });
  const { samples, avgTempC } = req.body || {};
  if (!Array.isArray(samples)) return res.status(400).json({ error: 'samples deve ser array' });
  try {
    fs.writeFileSync(path.join(CHARGE_TELEMETRY_DIR, `${ts}.json`), JSON.stringify(samples));
    // Se Android enviou avgTempC junto, atualiza a recarga (preferência sobre cálculo bridge-side)
    if (typeof avgTempC === 'number' && !isNaN(avgTempC)) {
      const charge = chargesArr.find(c => (c.timestamp_ms || 0) === ts);
      if (charge) { charge.avg_temp_c = avgTempC; scheduleChargesFlush(); }
    }
    console.log(`✓ Amostras de recarga salvas: ts=${ts} (${samples.length} pontos)`);
    res.json({ ok: true, count: samples.length });
  } catch (e) {
    console.error('Erro ao salvar amostras de recarga:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/charges/:ts/samples', (req, res) => {
  const ts   = parseInt(req.params.ts, 10);
  const file = path.join(CHARGE_TELEMETRY_DIR, `${ts}.json`);
  try {
    res.json(fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : []);
  } catch (_) { res.json([]); }
});

// ── Unir recargas ─────────────────────────────────────────────────────────────
// POST /api/charges/merge  { tsA, tsB }
// Funde duas sessões de recarga em uma só.
// - timestamp_ms da sessão mais antiga é preservado (ID da sessão unificada)
// - duration_sec e energy_kwh são somados
// - soc_start = sessão mais antiga; soc_end = sessão mais nova
// - location, charger_kwh, cost_override, avg_temp_c: preservados do que existir
// - amostras de linha do tempo: concatenadas (late offset por duration da early)
// Reconstrói uma recarga que o bridge/APK perdeu (bridge morreu, APK offline,
// 4G caiu, força-parada no meio…). Body: { startMs, endMs, socStart, socEnd,
// avgPowerKw?, energyKwh?, location? }. Se energyKwh não vier, estima por
// SOC delta × capacidade nominal H6. Publish MQTT retained inclusive.
app.post('/api/charge-reconstruct', requireAuth, (req, res) => {
  try {
    const b = req.body || {};
    const startMs = parseInt(b.startMs, 10);
    const endMs   = parseInt(b.endMs, 10);
    const socStart = parseFloat(b.socStart);
    const socEnd   = parseFloat(b.socEnd);
    if (!startMs || !endMs || endMs <= startMs) return res.status(400).json({ error: 'startMs/endMs inválidos' });
    if (isNaN(socStart) || isNaN(socEnd) || socEnd <= socStart) return res.status(400).json({ error: 'socStart/socEnd inválidos (socEnd deve ser > socStart)' });
    const socDelta = socEnd - socStart;
    let energyKwh = parseFloat(b.energyKwh);
    if (!(energyKwh > 0)) energyKwh = +(socDelta / 100 * BATTERY_CAPACITY_KWH).toFixed(2);
    let avgPowerKw = parseFloat(b.avgPowerKw);
    // Duração efetiva DE CARGA (não tempo entre startMs/endMs — pode ter pausa).
    // Se veio avgPowerKw, calcula duration_sec = energy / power. Senão usa endMs-startMs.
    let durationSec;
    if (avgPowerKw > 0) {
      durationSec = Math.round(energyKwh / avgPowerKw * 3600);
    } else {
      durationSec = Math.round((endMs - startMs) / 1000);
      avgPowerKw  = durationSec > 0 ? +(energyKwh / (durationSec / 3600)).toFixed(2) : 0;
    }
    const rec = {
      timestamp: new Date(startMs - 3*3600_000).toISOString().slice(0,19),
      timestamp_ms: startMs,
      duration_sec: durationSec,
      energy_kwh: +energyKwh.toFixed(2),
      soc_start: Math.round(socStart),
      soc_end:   Math.round(socEnd),
      avg_power_kw: +avgPowerKw.toFixed(2),
      _updated_ms: Date.now(),
      _recovered: true,
    };
    if (b.location) {
      if (typeof b.location === 'string') rec.location_name = b.location;
      else { rec.location_name = b.location.name || ''; rec.location_lat = +b.location.lat || 0; rec.location_lng = +b.location.lng || 0; }
    }
    // Dedupe por startMs (5min de tolerância)
    let existingIdx = chargesArr.findIndex(c => Math.abs((c.timestamp_ms||0) - startMs) < 5*60_000);
    // Dedupe adicional contra registro PROMOVIDO do snapshot (`_recovered`). Quando o
    // bridge reinicia no meio de uma recarga, ele promove o snapshot a registro; ao
    // terminar, o APK manda o registro real e ficavam DOIS — foi o que duplicou em
    // 06/08 (14:37 promovido, 16:07 real, ambos soc_start 56%).
    //
    // O startMs não serve pra casar os dois: o promovido usa o início da sessão e o
    // real o momento do registro, e ali deu 90min de diferença. A identidade que
    // resiste é o SOC INICIAL no mesmo dia — uma sessão não recomeça do mesmo SOC.
    if (existingIdx < 0 && Number.isFinite(socStart)) {
      existingIdx = chargesArr.findIndex(c =>
        c._recovered === true
        && Math.abs((+c.soc_start || -99) - socStart) <= 2
        && Math.abs((c.timestamp_ms || 0) - startMs) < 12 * 3600_000);
      if (existingIdx >= 0) {
        const velho = chargesArr[existingIdx];
        console.log(`↩ recarga promovida do snapshot (ts=${velho.timestamp_ms}, SOC ${velho.soc_start}%) `
          + `substituída pelo registro real do carro (ts=${startMs})`);
        // A posição do promovido costuma ser a única que existe: ele nasceu com o
        // carro plugado e o GPS fresco. Não jogar fora.
        if (velho.location_lat != null && rec.location_lat == null) {
          rec.location_lat = velho.location_lat;
          rec.location_lng = velho.location_lng;
        }
        delete rec._recovered; delete rec._recovered_note;
      }
    }
    if (existingIdx >= 0) chargesArr[existingIdx] = { ...chargesArr[existingIdx], ...rec };
    else chargesArr.push(rec);
    chargesArr.sort((a,b) => (b.timestamp_ms||0) - (a.timestamp_ms||0));
    scheduleChargesFlush();
    // Republish MQTT retained pra iOS/PWA verem imediato.
    try {
      const publicArr = chargesArr.slice(0, 60).map(c => {
        const { _recovered, _recovered_note, _updated_ms, ...rest } = c;
        return rest;
      });
      if (mqttClient?.connected) {
        mqttClient.publish(`${MQTT_PREFIX}/charging/history`,
          JSON.stringify({ count: publicArr.length, charges: publicArr }),
          { qos: 1, retain: true });
      }
    } catch (e) { console.warn('[charge-reconstruct] republish MQTT falhou:', e.message); }
    console.log(`✓ [charge-reconstruct] ${existingIdx >= 0 ? 'atualizada' : 'inserida'}: ${rec.energy_kwh}kWh SOC ${rec.soc_start}→${rec.soc_end} @ ${rec.timestamp}`);
    res.json({ ok: true, charge: rec, updated: existingIdx >= 0 });
  } catch (e) {
    console.error('[charge-reconstruct] erro:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Funde duas recargas numa só. `cA`/`cB` em qualquer ordem — a cronológica é
// resolvida aqui. Faz os side effects (chargesArr, telemetria, tombstone da late,
// preço médio) e devolve o registro consolidado.
//
// Usada pelo merge manual (POST /api/charges/merge) e pelo automático
// (_autoMergeContiguousCharges), pra que os dois tratem cost_override, charger_kwh
// e amostras exatamente igual.
function _mergeChargePair(cA, cB) {
  {
    // Ordem cronológica
    const [early, late] = cA.timestamp_ms <= cB.timestamp_ms ? [cA, cB] : [cB, cA];

    // Campos numéricos — soma
    const mergedDurationSec = (early.duration_sec || 0) + (late.duration_sec  || 0);
    const mergedEnergyKwh   = parseFloat(((early.energy_kwh  || 0) + (late.energy_kwh  || 0)).toFixed(4));
    const mergedAvgPowerKw  = mergedDurationSec > 0
      ? parseFloat((mergedEnergyKwh / (mergedDurationSec / 3600)).toFixed(4)) : 0;

    // charger_kwh: soma se ambas têm; caso contrário usa o que existir
    let mergedChargerKwh = null;
    if (early.charger_kwh > 0 && late.charger_kwh > 0) {
      mergedChargerKwh = parseFloat(((early.charger_kwh || 0) + (late.charger_kwh || 0)).toFixed(4));
    } else if (early.charger_kwh > 0) {
      mergedChargerKwh = early.charger_kwh;
    } else if (late.charger_kwh > 0) {
      mergedChargerKwh = late.charger_kwh;
    }

    // cost_override: soma totais se ambas têm preço; se ambas grátis, mantém grátis;
    // se uma grátis e outra paga, conta só o pago.
    let mergedCostOverride = null;
    const eFree = early.cost_override?.free === true;
    const lFree = late.cost_override?.free  === true;
    if (eFree && lFree) {
      mergedCostOverride = { total: 0, perKwh: 0, free: true };
    } else if (eFree || lFree) {
      // Só uma é grátis — pega o total da paga
      const paid = eFree ? late.cost_override : early.cost_override;
      if (paid?.total > 0) {
        const perKwh = mergedEnergyKwh > 0 ? parseFloat((paid.total / mergedEnergyKwh).toFixed(4)) : 0;
        mergedCostOverride = { total: paid.total, perKwh };
      } else {
        mergedCostOverride = { total: 0, perKwh: 0, free: true };
      }
    } else if (early.cost_override?.total > 0 && late.cost_override?.total > 0) {
      const total     = parseFloat((early.cost_override.total + late.cost_override.total).toFixed(2));
      const perKwh    = mergedEnergyKwh > 0 ? parseFloat((total / mergedEnergyKwh).toFixed(4)) : 0;
      mergedCostOverride = { total, perKwh };
    } else {
      mergedCostOverride = early.cost_override || late.cost_override || null;
    }

    // avg_temp_c: média ponderada pela duração se ambas têm; caso contrário usa o que existir
    let mergedAvgTemp = null;
    if (early.avg_temp_c != null && late.avg_temp_c != null) {
      const totalSec = mergedDurationSec || 1;
      mergedAvgTemp  = parseFloat(
        ((early.avg_temp_c * (early.duration_sec || 0) + late.avg_temp_c * (late.duration_sec || 0)) / totalSec)
        .toFixed(1)
      );
    } else if (early.avg_temp_c != null) { mergedAvgTemp = early.avg_temp_c; }
    else if (late.avg_temp_c != null)    { mergedAvgTemp = late.avg_temp_c;  }

    // Location: prefere a mais antiga; fallback para a mais nova
    const locName  = early.location_name || late.location_name  || null;
    const locLat   = early.location_lat  != null ? early.location_lat  : (late.location_lat  || null);
    const locLng   = early.location_lng  != null ? early.location_lng  : (late.location_lng  || null);

    // Objeto final da recarga unificada
    const merged = {
      ...early,
      duration_sec: mergedDurationSec,
      energy_kwh:   mergedEnergyKwh,
      avg_power_kw: mergedAvgPowerKw,
      soc_start:    early.soc_start,
      soc_end:      late.soc_end,
      _updated_ms:  Date.now(),
      // Marca de quais ts originais a recarga foi consolidada — o handler
      // de charging/history (retained do APK) usa pra NÃO sobrescrever os
      // campos somados quando o APK reenvia o estado original da early.
      merged_from:  [...(early.merged_from || []), late.timestamp_ms],
    };
    // Nome só viaja junto da coordenada: propagar o nome sozinho fazia a recarga
    // nova nascer com o local da anterior e bloquear a detecção pelo GPS.
    if (locName != null && locLat != null)  merged.location_name  = locName;
    if (locLat  != null)           merged.location_lat   = locLat;
    if (locLng  != null)           merged.location_lng   = locLng;
    if (mergedChargerKwh != null)  merged.charger_kwh    = mergedChargerKwh;
    else                           delete merged.charger_kwh;
    if (mergedCostOverride != null) merged.cost_override = mergedCostOverride;
    else                            delete merged.cost_override;
    if (mergedAvgTemp != null)     merged.avg_temp_c     = mergedAvgTemp;
    else                           delete merged.avg_temp_c;

    // Amostras da linha do tempo: early + late com offset de t para continuar após a early
    const earlyFile = path.join(CHARGE_TELEMETRY_DIR, `${early.timestamp_ms}.json`);
    const lateFile  = path.join(CHARGE_TELEMETRY_DIR, `${late.timestamp_ms}.json`);
    let earlySamples = [], lateSamples = [];
    try { if (fs.existsSync(earlyFile)) earlySamples = JSON.parse(fs.readFileSync(earlyFile, 'utf8')); } catch (_) {}
    try { if (fs.existsSync(lateFile))  lateSamples  = JSON.parse(fs.readFileSync(lateFile,  'utf8')); } catch (_) {}
    if (earlySamples.length || lateSamples.length) {
      const offset   = early.duration_sec || 0;
      const lateOff  = lateSamples.map(s => ({ ...s, t: (s.t || 0) + offset }));
      const combined = [...earlySamples, ...lateOff];
      try { fs.writeFileSync(earlyFile, JSON.stringify(combined)); } catch (_) {}
      try { if (fs.existsSync(lateFile)) fs.unlinkSync(lateFile); } catch (_) {}
    }

    // Actualiza chargesArr: remove late, substitui early pelo merged
    chargesArr = chargesArr.filter(c => (c.timestamp_ms || 0) !== late.timestamp_ms);
    const earlyIdx = chargesArr.findIndex(c => (c.timestamp_ms || 0) === early.timestamp_ms);
    if (earlyIdx >= 0) chargesArr[earlyIdx] = merged;
    else chargesArr.unshift(merged);

    // Tombstone da `late` — sem isso, próximo charging/history retained do APK
    // re-adiciona a recarga (PWA "perde" a unificação ao dar refresh).
    markDeleted('charges', late.timestamp_ms);
    // Mix da bateria muda quando recargas fundem (cost_override pode mudar)
    recomputeBatteryAvgPrice();
    scheduleChargesFlush();
    console.log(`[merge-charges] ${early.timestamp_ms} + ${late.timestamp_ms} → ${early.timestamp_ms} (${mergedEnergyKwh} kWh, ${mergedDurationSec}s)`);
    return merged;
  }
}

// ── Consolidação automática de recargas fragmentadas ─────────────────────────
// O APK fecha a sessão e abre outra quando perde o fio no meio de uma carga
// (dorme, morre, MQTT cai). O carregador conta a carga INTEIRA, então cada
// fragmento comparado com o display do carregador parece ter perda absurda:
// em 27/07 um fragmento deu 21% contra 15,8% da carga somada.
//
// Assinatura de fragmentação: SOC contínuo (a nova começa onde a anterior
// parou), gap curto e mesmo local. Se o SOC caiu no meio, o carro rodou —
// são cargas distintas e não se unem.
const AUTO_MERGE_MAX_GAP_MS = 30 * 60_000;  // pausa maior que isso já é outra carga
const AUTO_MERGE_SOC_TOL    = 2;            // pontos de folga no encaixe do SOC
const AUTO_MERGE_MAX_DIST_M = 200;          // mesmo carregador

// `timestamp_ms` é o FIM da sessão (o APK usa System.currentTimeMillis() ao
// fechar), então o início é ts - duration.
function _chargeStartMs(c) {
  return (c.timestamp_ms || 0) - (c.duration_sec || 0) * 1000;
}

function _chargesAreContiguous(early, late) {
  const gapMs = _chargeStartMs(late) - (early.timestamp_ms || 0);
  if (!(gapMs >= 0 && gapMs <= AUTO_MERGE_MAX_GAP_MS)) return false;

  // SOC tem que existir nos dois lados; 0 aqui é leitura ausente, não bateria
  // vazia — unir com base nele inventaria continuidade.
  const eEnd = +early.soc_end, lStart = +late.soc_start;
  if (!(eEnd > 0) || !(lStart > 0)) return false;
  if (Math.abs(lStart - eEnd) > AUTO_MERGE_SOC_TOL) return false;

  // Progressão monotônica: a carga unida tem que subir.
  if (!(+late.soc_end > +early.soc_start)) return false;

  // Mesmo local. Se falta GPS em algum lado, o SOC contínuo + gap curto já
  // bastam (é o caso comum: o APK não anexa GPS em toda sessão).
  const hasBoth = early.location_lat != null && early.location_lng != null
               && late.location_lat  != null && late.location_lng  != null;
  if (hasBoth) {
    const d = haversineM(early.location_lat, early.location_lng, late.location_lat, late.location_lng);
    if (d > AUTO_MERGE_MAX_DIST_M) return false;
  }
  return true;
}

// Varre o histórico e une o que estiver fragmentado. Idempotente: a `late` de
// cada merge ganha tombstone, então o retained do APK não a traz de volta e uma
// segunda passada não encontra nada. Devolve os pares unidos.
function _autoMergeContiguousCharges() {
  const unidos = [];
  // Enquanto houver o que unir: cada merge muda os vizinhos, então reavalia.
  for (let volta = 0; volta < 20; volta++) {
    const ord = [...chargesArr]
      .filter(c => c.timestamp_ms)
      .sort((a, b) => a.timestamp_ms - b.timestamp_ms);
    let achou = false;
    for (let i = 0; i + 1 < ord.length; i++) {
      const early = ord[i], late = ord[i + 1];
      if (!_chargesAreContiguous(early, late)) continue;
      const antes = { e: early.energy_kwh, l: late.energy_kwh };
      const merged = _mergeChargePair(early, late);
      unidos.push({
        ts: merged.timestamp_ms,
        de: [early.timestamp_ms, late.timestamp_ms],
        energia: `${antes.e} + ${antes.l} → ${merged.energy_kwh} kWh`,
        soc: `${merged.soc_start}→${merged.soc_end}`,
      });
      achou = true;
      break;   // chargesArr mudou — reordena
    }
    if (!achou) break;
  }
  if (unidos.length) {
    console.log(`🔗 [auto-merge] ${unidos.length} recarga(s) fragmentada(s) consolidada(s)`);
    for (const u of unidos) console.log(`   ${u.de.join(' + ')} → ${u.ts}  ${u.energia}  SOC ${u.soc}`);
  }
  return unidos;
}

// Consolidação sob demanda — útil pra rodar no histórico já gravado.
// `?dry=1` só lista os pares que seriam unidos, sem tocar em nada.
app.post('/api/charges/auto-merge', (req, res) => {
  try {
    if (req.query.dry === '1' || req.body?.dry === true) {
      const ord = [...chargesArr].filter(c => c.timestamp_ms).sort((a, b) => a.timestamp_ms - b.timestamp_ms);
      const pares = [];
      for (let i = 0; i + 1 < ord.length; i++) {
        const e = ord[i], l = ord[i + 1];
        if (!_chargesAreContiguous(e, l)) continue;
        pares.push({
          early: { ts: e.timestamp_ms, quando: e.timestamp, kwh: e.energy_kwh, soc: `${e.soc_start}→${e.soc_end}`, local: e.location_name || null },
          late:  { ts: l.timestamp_ms, quando: l.timestamp, kwh: l.energy_kwh, soc: `${l.soc_start}→${l.soc_end}`, local: l.location_name || null },
          gap_min: +(((_chargeStartMs(l) - e.timestamp_ms) / 60000).toFixed(1)),
          resultado: { kwh: +(((+e.energy_kwh || 0) + (+l.energy_kwh || 0)).toFixed(2)), soc: `${e.soc_start}→${l.soc_end}` },
        });
      }
      return res.json({ ok: true, dry: true, would_merge: pares.length, pares });
    }
    const unidos = _autoMergeContiguousCharges();
    res.json({ ok: true, merged_count: unidos.length, merged: unidos });
  } catch (e) {
    console.error('[auto-merge]', e);
    res.status(500).json({ error: String(e.message) });
  }
});

app.post('/api/charges/merge', (req, res) => {
  try {
    const { tsA, tsB } = req.body;
    const numA = parseInt(tsA, 10), numB = parseInt(tsB, 10);
    if (!numA || !numB || numA === numB) return res.status(400).json({ error: 'tsA e tsB devem ser diferentes e válidos' });

    const idxA = chargesArr.findIndex(c => (c.timestamp_ms || 0) === numA);
    const idxB = chargesArr.findIndex(c => (c.timestamp_ms || 0) === numB);
    if (idxA < 0) return res.status(404).json({ error: `recarga não encontrada: ${numA}` });
    if (idxB < 0) return res.status(404).json({ error: `recarga não encontrada: ${numB}` });

    const merged = _mergeChargePair(chargesArr[idxA], chargesArr[idxB]);
    res.json({ ok: true, merged });
  } catch (e) {
    console.error('[merge-charges]', e);
    res.status(500).json({ error: String(e.message) });
  }
});

// ── Locais de recarga ─────────────────────────────────────────────────────────
app.get('/api/charge-locations', (_req, res) => res.json(chargeLocations));

app.post('/api/charge-locations', (req, res) => {
  const { name, lat, lng } = req.body || {};
  if (!name?.trim()) return res.status(400).json({ error: 'nome obrigatório' });
  // Evita duplicatas: mesmo nome ou GPS a < 100 m
  const dup = chargeLocations.find(l =>
    l.name === name.trim() ||
    (l.lat && l.lng && lat && lng && haversineM(l.lat, l.lng, lat, lng) < 100)
  );
  if (dup) return res.json(dup);
  const loc = { id: Date.now(), name: name.trim(), lat: lat ?? null, lng: lng ?? null };
  chargeLocations.push(loc);
  saveChargeLocations();
  res.json(loc);
});

app.delete('/api/charge-locations/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const idx = chargeLocations.findIndex(l => l.id === id);
  if (idx === -1) return res.status(404).json({ error: 'não encontrado' });
  chargeLocations.splice(idx, 1);
  saveChargeLocations();
  res.json({ ok: true });
});

// ── Automações (regras) ───────────────────────────────────────────────────────
// Fonte da verdade pra EDIÇÃO (sincroniza iPhone↔iPad via ?since=). A EXECUÇÃO é
// no carro: ao salvar, publica a lista completa em cmd/rules/set (retido) e o APK
// persiste + avalia sozinho. Ver AutomationManager no app.
let automationRules = [];
try {
  if (fs.existsSync(RULES_FILE)) automationRules = JSON.parse(fs.readFileSync(RULES_FILE, 'utf8'));
  if (!Array.isArray(automationRules)) automationRules = [];
  if (automationRules.length) console.log(`✓ Automações carregadas: ${automationRules.length}`);
} catch (_) { automationRules = []; }

// ── Executor server-side de regras (fallback do APK) ─────────────────────────
// Motivação: o APK adormece / Shizuku cai / GPS treme — regras de geofence
// que dependem do APK falham calado. O bridge executa em paralelo (idempotente),
// verifica o estado 3s depois e retenta 1× em caso de falha. Cada execução vai
// pro automation_events.json pra auditoria.
const AUTOMATION_EVENTS_FILE = path.join(DATA_DIR, 'automation_events.json');
const AUTOMATION_STATE_FILE  = path.join(DATA_DIR, 'automation_state.json');
const RULE_STABLE_MS      = 30_000;      // fallback quando carro parado
const RULE_STABLE_MOVING_MS = 1_500;    // se speed > 3, quase imediato (portaria dura ~3s)
const RULE_MOTION_MIN_KMH = 3;           // mínimo pra considerar "passando" (evita jitter estático)
const RULE_HYST_MULT      = 1.5;         // outside = d > radius * 1.5 (só zera enteredFired longe da zona)
const RULE_VERIFY_MS      = 3_000;       // intervalo entre verificar o estado do carro e re-publicar
const RULE_WATCHDOG_MS    = 120_000;     // bridge insiste (verify+re-publish) até confirmar ou estourar 2min — cobre o limbo WiFi-fraco/4G-ainda-não na chegada

let _autoEvents = [];
try { if (fs.existsSync(AUTOMATION_EVENTS_FILE)) _autoEvents = JSON.parse(fs.readFileSync(AUTOMATION_EVENTS_FILE, 'utf8')); } catch (_) {}
function _logAutoEvent(entry) {
  _autoEvents.push({ ts: Date.now(), ...entry });
  if (_autoEvents.length > 500) _autoEvents = _autoEvents.slice(-500);
  try { atomicWriteFileSync(AUTOMATION_EVENTS_FILE, JSON.stringify(_autoEvents)); } catch (_) {}
}

// Estado por regra: { entryTs, lastFireTs } — persistido pra sobreviver a restart.
let _ruleState = {};
try { if (fs.existsSync(AUTOMATION_STATE_FILE)) _ruleState = JSON.parse(fs.readFileSync(AUTOMATION_STATE_FILE, 'utf8')) || {}; } catch (_) {}
function _saveRuleState() {
  try { atomicWriteFileSync(AUTOMATION_STATE_FILE, JSON.stringify(_ruleState)); } catch (_) {}
}

// Mapa expected-state por action.status pra verificação pós-comando (windows).
// status 1=fechado, 2=aberto (APK). state.window_* : 1=fechado, 2=aberto.
function _expectedWindowState(status) { return status === 2 ? 'aberto' : 'fechado'; }
function _windowStateAt() {
  // state.window_* guarda 'on' (aberto) / 'off' (fechado). Null/undefined = desconhecido.
  const vals = [state.window_fl, state.window_fr, state.window_rl, state.window_rr];
  if (vals.every(v => v == null)) return 'desconhecido';
  if (vals.some(v => v === 'on')) return 'aberto';
  if (vals.every(v => v === 'off')) return 'fechado';
  return 'desconhecido';
}

// Verifica se o estado do carro reflete a ação executada.
// Table-driven: cada tipo de ação diz qual campo de `state` observar e o que esperar.
// `verifiable:false` = não há nada no carro pra observar (notify) ou não conheço o
// mapeamento (request de chave desconhecida) — melhor declarar que não sei do que
// inventar uma falha. `readable:false` = campo ainda não chegou / carro dormindo.
const LEVEL_TOLERANCE = 5;         // teto e cortina reportam 0..100 com folga
// Chaves de `request` com mapeamento de estado que eu confio. Fora daqui, não verifica:
// car.ev_setting.charge_soc_limit_config, por exemplo, é enum e não bate 1:1 com
// charge_limit_pct — chutar aqui geraria falha falsa.
const REQUEST_STATE_MAP = {
  'car.hvac.cycle_mode': () => state.hvac_cycle_mode,
};

function _verifyRuleAction(rule) {
  const a = rule.action || {};
  const numCmp = (expected, actual, tol) => ({
    verifiable: true,
    readable: actual != null && Number.isFinite(+actual),
    verified: actual != null && Math.abs(+actual - +expected) <= tol,
    expected: `${expected}`,
    actual: actual == null ? 'desconhecido' : `${actual}`,
  });

  if (a.type === 'window') {
    const expected = _expectedWindowState(a.status);
    const actual = _windowStateAt();
    return { verifiable: true, readable: actual !== 'desconhecido', verified: actual === expected, actual, expected };
  }
  if (a.type === 'skylight') return numCmp(a.level ?? 0, state.skylight_level, LEVEL_TOLERANCE);
  if (a.type === 'shade')    return numCmp(a.level ?? 0, state.shade_level, LEVEL_TOLERANCE);
  if (a.type === 'request') {
    const getter = REQUEST_STATE_MAP[a.key];
    if (!getter) return { verifiable: false, reason: `sem mapeamento de estado pra ${a.key}` };
    const actual = getter();
    return numCmp(a.value, actual, 0);
  }
  // notify: o efeito é um push, não um estado do carro.
  return { verifiable: false, reason: `ação ${a.type || '?'} não observável no carro` };
}

// O APK executa a regra de geofence-vidro localmente (imune ao limbo WiFi/4G da
// chegada). O bridge NÃO comanda — só MONITORA: observa se o vidro atinge o estado
// esperado e alerta se não atingir. Read-first: só confia com carro online E estado
// legível; offline/desconhecido não vira falso alarme, só espera. Alerta no fim da
// janela se leu e o vidro não mudou (APK não atuou), ou se o carro ficou ilegível.
// Um monitor por regra em vôo — regra que dispara em sequência não empilha timer.
const _monitorInFlight = new Set();

function _monitorRuleAction(rule, reason) {
  const probe = _verifyRuleAction(rule);
  // Ação sem estado observável (notify, request desconhecido): registra e sai. Não
  // conta como falha nem como sucesso — é ausência de veredito, e o painel diz isso.
  // Sai SEM registrar: 10 das 20 regras são `notify` e disparam várias vezes por dia.
  // Logar "não verificável" a cada disparo entupiria o log de auditoria e empurraria
  // pra fora o histórico que importa. Quem conta essa história é o card ("sem
  // confirmação de efeito"), não um evento por disparo.
  if (probe.verifiable === false) return;
  if (!_evalConditions(rule.conditions)) {
    _logAutoEvent({ rule_id: rule.id, name: rule.name, phase: 'monitor-skip', reason: 'conditions falharam' });
    return;
  }
  if (_monitorInFlight.has(rule.id)) return;
  _monitorInFlight.add(rule.id);
  _logAutoEvent({ rule_id: rule.id, name: rule.name, phase: 'monitor', trigger: reason,
                  action: `esperando efeito → ${probe.expected}` });
  const deadline = Date.now() + RULE_WATCHDOG_MS;
  let everReadable = false;
  const done = () => _monitorInFlight.delete(rule.id);
  const tick = () => {
    const v = _verifyRuleAction(rule);
    if (v.readable && state.car_online === true) everReadable = true;
    if (v.verified) { _logAutoEvent({ rule_id: rule.id, name: rule.name, phase: 'monitor-ok', ...v }); return done(); }
    if (Date.now() >= deadline) {
      // Carro que nunca ficou legível na janela não é falha da automação — é falta de
      // leitura. Antes isso virava push "não confirmou", que com cortina às 09h e
      // carro dormindo seria puro ruído. Agora fica no log, sem acordar ninguém.
      if (!everReadable) {
        _logAutoEvent({ rule_id: rule.id, name: rule.name, phase: 'monitor-skip',
                        reason: 'carro offline/ilegível na janela de verificação', ...v });
        return done();
      }
      _logAutoEvent({ rule_id: rule.id, name: rule.name, phase: 'monitor-fail', ...v, readable: true });
      sendPush('⚠️ Automação não confirmou',
        `${rule.name || 'Regra'}: esperava ${v.expected}, o carro reporta ${v.actual} após ${Math.round(RULE_WATCHDOG_MS / 1000)}s.`,
        'automation_fail');
      return done();
    }
    setTimeout(tick, RULE_VERIFY_MS);   // ainda não atingiu → só observa, nunca comanda
  };
  setTimeout(tick, RULE_VERIFY_MS);
}

// Chamado no loop de GPS (junto de checkGeofence). Avalia regras com
// trigger.type='geofence' e edge='enter'/'exit'. Estabilidade 30s antes de fire.
function _evalGeofenceRules(lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
  const now = Date.now();
  for (const rule of automationRules) {
    if (!rule.enabled) continue;
    const t = rule.trigger || {};
    if (t.type !== 'geofence') continue;
    if (!t.lat || !t.lng || !t.radius_m) continue;
    if (!['enter', 'exit'].includes(t.edge)) continue;
    // Execução é 100% do APK (autônoma, imune ao limbo WiFi/4G). O bridge só MONITORA
    // o vidro (único action verificável server-side); outros actions ficam sem monitor.
    if ((rule.action || {}).type !== 'window') continue;

    const d = haversineM(lat, lng, t.lat, t.lng);
    const inside = d <= t.radius_m;
    // Histerese: só considera "fora" quando >= 1.5× o raio (jitter pequeno não zera enteredFired).
    const clearlyOutside = d >= t.radius_m * RULE_HYST_MULT;
    const speed = +state.speed_kmh || 0;
    const moving = speed >= RULE_MOTION_MIN_KMH;
    // Estabilidade curta se está passando (portaria dura poucos segundos); longa se parado.
    const stableMs = moving ? RULE_STABLE_MOVING_MS : RULE_STABLE_MS;
    const st = _ruleState[rule.id] || {};
    const wantEnter = t.edge === 'enter';
    const wantExit  = t.edge === 'exit';

    if (wantEnter && inside) {
      if (!st.entryTs) { _ruleState[rule.id] = { ...st, entryTs: now }; _saveRuleState(); continue; }
      if (now - st.entryTs >= stableMs && !st.enteredFired) {
        _ruleState[rule.id] = { ...st, enteredFired: true };
        _saveRuleState();
        _monitorRuleAction(rule, `geofence enter (${Math.round(d)}m/${t.radius_m}m, speed=${speed.toFixed(1)}km/h, estável ${Math.round((now - st.entryTs)/1000)}s)`);
      }
    } else if (wantExit && !inside) {
      if (!st.exitTs) { _ruleState[rule.id] = { ...st, exitTs: now }; _saveRuleState(); continue; }
      if (now - st.exitTs >= stableMs && !st.exitedFired) {
        _ruleState[rule.id] = { ...st, exitedFired: true };
        _saveRuleState();
        _monitorRuleAction(rule, `geofence exit (${Math.round(d)}m/${t.radius_m}m, speed=${speed.toFixed(1)}km/h, estável ${Math.round((now - st.exitTs)/1000)}s)`);
      }
    } else if (clearlyOutside) {
      // Saiu claramente da zona (>1.5× raio): rearma as flags de borda pra a próxima
      // entrada real re-armar o monitor. Jitter pequeno perto da zona não rearma
      // (histerese). Re-entrada ainda exige estabilidade (stableMs) antes de monitorar.
      const st2 = { ...st, entryTs: 0, enteredFired: false, exitTs: 0, exitedFired: false, lastFireTs: 0 };
      if (st.entryTs || st.enteredFired || st.exitTs || st.exitedFired || st.lastFireTs) {
        _ruleState[rule.id] = st2; _saveRuleState();
      }
    }
  }
}

// Endpoint pra o app auditar as execuções (mostra na aba Automações).
app.get('/api/automation-events', requireAuth, (req, res) => {
  const limit = Math.min(500, parseInt(req.query.limit) || 100);
  res.json({ ok: true, events: _autoEvents.slice(-limit).reverse() });
});

// Health do executor APK/Shizuku: infere pelo verify das automações.
// - success: phase termina com verify (v1 ok) OU verify2 ok.
// - fail: verify2 com verified=false (comando não teve efeito).
// Health do executor APK/Shizuku.
// A versão antiga só olhava `main-verify`/`verify2` — o verify feito PELO BRIDGE. Esse
// caminho morreu em 06/07/2026, quando as automações passaram a ser executadas dentro
// do carro (phase `apk-fired`). Resultado: o painel congelou em "4 falhas seguidas ·
// últ. ok 585h atrás" enquanto 116 automações rodavam ok — métrica lendo canal morto.
// Agora conta os três sinais que existem hoje:
//   verified===true  (main-verify* ok, monitor-ok)   → efeito CONFIRMADO
//   verified===false (main-verify* fail, monitor-fail) → efeito NEGADO (expected≠actual)
//   apk-fired                                        → o APK disparou a regra; prova
//     que o executor está vivo, mas NÃO que o carro obedeceu
// `signal_age_ms` diz quando foi o último sinal confirmado — sem isso um streak velho
// se pinta de vermelho pra sempre.
function _apkExecutorHealth() {
  const now = Date.now();
  const cut24 = now - 24 * 3600_000;
  let lastOk = 0, lastFail = 0, ok24 = 0, fail24 = 0, failStreak = 0;
  let firedLast = 0, fired24 = 0;
  for (const e of _autoEvents) {
    const ph = e.phase || '';
    if (ph === 'apk-fired') {
      if (e.ok !== false) { firedLast = Math.max(firedLast, e.ts); if (e.ts >= cut24) fired24++; }
      continue;
    }
    if (e.verified !== true && e.verified !== false) continue;   // fase sem veredito
    const ok = e.verified === true;
    if (e.ts >= cut24) { if (ok) ok24++; else fail24++; }
    if (ok) { lastOk = Math.max(lastOk, e.ts); failStreak = 0; }
    else    { lastFail = Math.max(lastFail, e.ts); failStreak++; }
  }
  const lastSignal = Math.max(lastOk, lastFail);
  return {
    last_ok_ms:   lastOk || null,
    last_fail_ms: lastFail || null,
    ok_24h:       ok24,
    fail_24h:     fail24,
    fail_streak:  failStreak,
    fired_last_ms: firedLast || null,
    fired_24h:    fired24,
    signal_age_ms: lastSignal ? (now - lastSignal) : null,
    // Suspeito só se a streak for RECENTE (1h). Streak velha é cicatriz, não falha:
    // com o carro parado ninguém manda comando e o número fica pendurado.
    healthy: !(failStreak >= 2 && lastFail > 0 && (now - lastFail) < 3600_000),
  };
}

// ── Resolver de campos de condição das regras ────────────────────────────────
// Regras usam `car.basic.vehicle_speed`, etc. Mapa mínimo pros campos comuns.
const _RULE_FIELD_MAP = {
  'car.basic.vehicle_speed':      () => +state.speed_kmh || 0,
  'car.basic.outside_temp':       () => +state.outside_temp || 0,
  'car.basic.inside_temp':        () => +state.inside_temp || 0,
  'car.basic.driving_ready_state':() => state.driving_ready,
  'car.basic.engine_state':       () => state.engine_state,
  'car.basic.lock_state':         () => state.lock_state,
  'car.basic.sunroof_status':     () => +state.skylight_level || 0,
  'car.basic.remain_fuel_percentage': () => +state.fuel_pct || 0,
  'car.hvac.pm2.5_value':         () => +state.hvac_pm25 || 0,
  'car.hvac.cycle_mode':          () => state.hvac_cycle_mode,
  'car.ev_info.charging_state':   () => state.charging_state,
  'car.basic.soc_pct':            () => +state.soc_pct || 0,
};
function _resolveRuleField(field) {
  const fn = _RULE_FIELD_MAP[field];
  return fn ? fn() : undefined;
}
function _cmpValues(a, op, b) {
  const na = Number(a), nb = Number(b);
  const num = Number.isFinite(na) && Number.isFinite(nb);
  if (op === '==') return num ? na === nb : String(a) === String(b);
  if (op === '!=') return num ? na !== nb : String(a) !== String(b);
  if (!num) return false;
  if (op === '>')  return na > nb;
  if (op === '<')  return na < nb;
  if (op === '>=') return na >= nb;
  if (op === '<=') return na <= nb;
  return false;
}
// Avalia items AND/OR. `time` items: dias da semana + janela HH:MM.
function _evalConditions(conds) {
  if (!conds || !Array.isArray(conds.items) || !conds.items.length) return true;
  const op = (conds.op || 'AND').toUpperCase();
  const results = conds.items.map(it => {
    if (it.type === 'time') {
      const now = new Date();
      const dow = now.getDay();
      const hm = now.getHours() * 60 + now.getMinutes();
      if (Array.isArray(it.days) && !it.days.includes(dow)) return false;
      const from = +it.from_hhmm || 0, to = +it.to_hhmm || 1439;
      return from <= to ? (hm >= from && hm <= to) : (hm >= from || hm <= to);
    }
    if (it.type === 'visited') return true;   // não avaliamos server-side
    // default: state field comparison
    const val = _resolveRuleField(it.field);
    if (val === undefined) return false;   // campo não mapeado → não bloqueia? melhor conservador: FALSE.
    return _cmpValues(val, it.cmp || '==', it.value);
  });
  return op === 'OR' ? results.some(Boolean) : results.every(Boolean);
}

function saveRules() {
  try { atomicWriteFileSync(RULES_FILE, JSON.stringify(automationRules, null, 2)); }
  catch (e) { console.error('saveRules:', e.message); }
}
// Publica a lista completa no carro (RETIDO → chega mesmo se o carro estava off).
function relayRules() {
  if (!mqttClient?.connected) return false;
  try {
    mqttClient.publish(`${MQTT_PREFIX}/cmd/rules/set`, JSON.stringify(automationRules), { qos: 1, retain: true });
    return true;
  } catch (e) { console.error('relayRules:', e.message); return false; }
}

// GET /api/rules?since=  → array (espelha SyncedList: _updated_ms + X-Tombstones)
app.get('/api/rules', (req, res) => {
  setSyncWatermark(res);
  const since = parseSince(req);
  const arr = since > 0 ? automationRules.filter(r => (r._updated_ms || 0) > since) : automationRules;
  if (Array.isArray(deletedIds.rules) && deletedIds.rules.length) {
    res.setHeader('X-Tombstones', deletedIds.rules.join(','));
    res.setHeader('Access-Control-Expose-Headers', 'X-Tombstones');
  }
  res.json(arr);
});

// POST /api/rules  → cria/atualiza uma regra (upsert por id) + relay pro carro.
app.post('/api/rules', (req, res) => {
  const r = req.body;
  if (!r || typeof r !== 'object' || !r.trigger || !r.action) {
    return res.status(400).json({ error: 'regra inválida (precisa de trigger e action)' });
  }
  if (!r.id) r.id = 'rule_' + Date.now();
  r._updated_ms = Date.now();
  if (r.enabled === undefined) r.enabled = true;
  const idx = automationRules.findIndex(x => x.id === r.id);
  if (idx >= 0) automationRules[idx] = r; else automationRules.push(r);
  saveRules();
  const relayed = relayRules();
  res.json({ ok: true, rule: r, relayed });
});

// POST /api/rules/enabled  { ids: [...], enabled: bool } → liga/desliga em lote.
//
// Existe pra o app não precisar reenviar a regra inteira só pra virar um botão:
// reenviar corpo inteiro a partir de um cliente que pode estar com uma cópia
// velha é como se perde condição ajustada no carro. Aqui só o `enabled` muda.
//
// O relay publica a lista completa RETIDA, então desligar com o carro dormindo
// vale: ele lê o retido ao conectar e já acorda com a configuração certa.
app.post('/api/rules/enabled', (req, res) => {
  const ids = Array.isArray(req.body?.ids) ? req.body.ids.map(String) : [];
  const on = !!req.body?.enabled;
  if (!ids.length) return res.status(400).json({ error: 'ids obrigatório' });
  const mudou = [];
  for (const id of ids) {
    const r = automationRules.find(x => String(x.id) === id);
    if (!r) continue;
    if (r.enabled === on) continue;
    r.enabled = on; r._updated_ms = Date.now();
    mudou.push(id);
  }
  if (mudou.length) { saveRules(); }
  const relayed = relayRules();
  console.log(`[rules] ${on ? 'ligadas' : 'desligadas'}: ${ids.join(', ')} (mudaram: ${mudou.length})`);
  res.json({ ok: true, enabled: on, mudou, relayed });
});

// DELETE /api/rules/:id → remove + tombstone + relay
app.delete('/api/rules/:id', (req, res) => {
  const id = String(req.params.id);
  const idx = automationRules.findIndex(x => String(x.id) === id);
  if (idx === -1) return res.status(404).json({ error: 'não encontrada' });
  automationRules.splice(idx, 1);
  markDeleted('rules', id);
  saveRules();
  const relayed = relayRules();
  res.json({ ok: true, relayed });
});

// ── Locais de AUTOMAÇÃO (separados dos Locais Conhecidos de recarga/trajeto) ───
// Automação LÊ os locais conhecidos (pra oferecer como opção), mas o que cria na
// automação fica AQUI — nunca polui known_places.
let automationPlaces = [];
try {
  if (fs.existsSync(AUTO_PLACES_FILE)) automationPlaces = JSON.parse(fs.readFileSync(AUTO_PLACES_FILE, 'utf8'));
  if (!Array.isArray(automationPlaces)) automationPlaces = [];
} catch (_) { automationPlaces = []; }
function saveAutoPlaces() {
  try { atomicWriteFileSync(AUTO_PLACES_FILE, JSON.stringify(automationPlaces, null, 2)); }
  catch (e) { console.error('saveAutoPlaces:', e.message); }
}

