app.get('/api/maintenance', (_req, res) => {
  const totalCost = maintenance.history.reduce((s, h) => s + (h.cost || 0), 0);
  let costPerKm = 0;
  const curOdo = +state.odometer_km || 0;
  if (totalCost > 0 && curOdo > 0) costPerKm = totalCost / curOdo;
  res.json({
    intervals: maintenance.intervals,
    history:   [...maintenance.history].sort((a, b) => (b.date_ms || 0) - (a.date_ms || 0)),
    next:      computeMaintenance(),
    current_odometer_km: +state.odometer_km || 0,
    daily_km_avg: parseFloat(avgDailyKm(30).toFixed(1)),
    total_cost:  parseFloat(totalCost.toFixed(2)),
    cost_per_km: parseFloat(costPerKm.toFixed(4)),
  });
});

// POST /api/maintenance/intervals  — cria ou atualiza um intervalo
app.post('/api/maintenance/intervals', (req, res) => {
  const { id, label, every_km, every_months, icon, alert_km, alert_days, category } = req.body || {};
  const km   = parseFloat(every_km)   || 0;
  const mths = parseFloat(every_months) || 0;
  if (!label || (!(km > 0) && !(mths > 0)))
    return res.status(400).json({ error: 'label e pelo menos every_km ou every_months > 0 obrigatórios' });
  const slug = String(label).trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 28);
  const safeId = id ? String(id).trim() : slug + '-' + Math.random().toString(36).slice(2, 6);
  const interval = {
    id: safeId,
    label: String(label).trim(),
    category: category ? String(category).trim() : 'outros',
    every_km:     km,
    every_months: mths,
    alert_km:    parseFloat(alert_km)   || 500,
    alert_days:  parseFloat(alert_days) || 15,
    icon: icon || '🔧',
  };
  const idx = maintenance.intervals.findIndex(i => i.id === interval.id);
  if (idx >= 0) maintenance.intervals[idx] = interval;
  else maintenance.intervals.push(interval);
  saveMaintenance();
  res.json({ ok: true, interval });
});

app.delete('/api/maintenance/intervals/:id', (req, res) => {
  const idx = maintenance.intervals.findIndex(i => i.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'não encontrado' });
  maintenance.intervals.splice(idx, 1);
  saveMaintenance();
  res.json({ ok: true });
});

// POST /api/maintenance/history — registra manutenção feita
// type_id nulo = entrada avulsa (não periódica); nesse caso label obrigatório.
app.post('/api/maintenance/history', (req, res) => {
  const { type_id, label, category, odometer_km, date_ms, notes, cost } = req.body || {};
  const tid = type_id ? String(type_id).trim() : null;
  if (!tid && !label) return res.status(400).json({ error: 'type_id ou label obrigatório' });
  if (tid && !maintenance.intervals.find(i => i.id === tid))
    return res.status(400).json({ error: 'type_id inválido' });
  const odo = parseFloat(odometer_km);
  if (!(odo > 0)) return res.status(400).json({ error: 'odometer_km > 0 obrigatório' });
  const rec = {
    id: 'h-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    type_id: tid,
    odometer_km: odo,
    date_ms: parseInt(date_ms) || Date.now(),
    notes: notes ? String(notes).slice(0, 240) : '',
  };
  if (!tid) rec.label = String(label).slice(0, 120);
  if (category) rec.category = String(category).slice(0, 40);
  const c = parseFloat(cost);
  if (!isNaN(c) && c > 0) rec.cost = parseFloat(c.toFixed(2));
  maintenance.history.push(rec);
  if (maintenance._alerts && tid) delete maintenance._alerts[tid];
  saveMaintenance();
  res.json({ ok: true, record: rec });
});

app.delete('/api/maintenance/history/:id', (req, res) => {
  const idx = maintenance.history.findIndex(h => h.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'não encontrado' });
  maintenance.history.splice(idx, 1);
  // Reseta alertas pros tipos afetados — recompute pode mover o "último"
  if (maintenance._alerts) maintenance._alerts = {};
  saveMaintenance();
  res.json({ ok: true });
});

// PATCH /api/maintenance/history/:id — edita registro existente
// (próximas manutenções recalculam automaticamente em computeMaintenance)
app.patch('/api/maintenance/history/:id', (req, res) => {
  const rec = maintenance.history.find(h => h.id === req.params.id);
  if (!rec) return res.status(404).json({ error: 'não encontrado' });
  const b = req.body || {};
  if (b.odometer_km !== undefined) {
    const o = parseFloat(b.odometer_km);
    if (!(o > 0)) return res.status(400).json({ error: 'odometer_km > 0 obrigatório' });
    rec.odometer_km = o;
  }
  if (b.date_ms !== undefined) {
    const d = parseInt(b.date_ms);
    if (!(d > 0)) return res.status(400).json({ error: 'date_ms inválido' });
    rec.date_ms = d;
  }
  if (b.type_id !== undefined) {
    if (b.type_id && !maintenance.intervals.find(i => i.id === b.type_id))
      return res.status(400).json({ error: 'type_id inválido' });
    rec.type_id = b.type_id ? String(b.type_id) : null;
  }
  if (b.notes    !== undefined) rec.notes    = String(b.notes).slice(0, 240);
  if (b.label    !== undefined) rec.label    = b.label ? String(b.label).slice(0, 120) : undefined;
  if (b.category !== undefined) rec.category = b.category ? String(b.category).slice(0, 40) : undefined;
  if (b.cost !== undefined) {
    const c = parseFloat(b.cost);
    if (!isNaN(c) && c > 0) rec.cost = parseFloat(c.toFixed(2));
    else delete rec.cost;
  }
  if (maintenance._alerts) maintenance._alerts = {};
  saveMaintenance();
  res.json({ ok: true, record: rec, next: computeMaintenance() });
});

// ── Abastecimentos ──────────────────────────────────────────────────────────
app.get('/api/refuels', (req, res) => {
  setSyncWatermark(res);
  const since = parseSince(req);
  const all = [...refuels].sort((a, b) => (b.timestamp_ms || 0) - (a.timestamp_ms || 0));
  // Suporta fetch incremental: ?since=ts retorna só registros novos/editados após o ts
  const filtered = since > 0
    ? all.filter(r => (r.timestamp_ms || 0) > since || (r._updated_ms || 0) > since)
    : all;
  if (Array.isArray(deletedIds.refuels) && deletedIds.refuels.length) {
    res.setHeader('X-Tombstones', deletedIds.refuels.join(','));
    res.setHeader('Access-Control-Expose-Headers', 'X-Tombstones');
  }
  res.json({
    refuels: filtered,
    tank_avg_price_per_l: state.tank_avg_price_per_l || 0,
    fuel_l_current: +state.fuel_l || 0,
    tank_capacity_l: TANK_CAPACITY_L,
  });
});

// POST /api/refuels — registro manual (ou completar pendente via PATCH)
app.post('/api/refuels', (req, res) => {
  const b = req.body || {};
  const liters = parseFloat(b.liters_added);
  if (!(liters > 0)) return res.status(400).json({ error: 'liters_added obrigatório' });
  const pricePerL = parseFloat(b.price_per_liter) || 0;
  const total     = parseFloat(b.total_cost) || (pricePerL * liters);
  const finalPrice = pricePerL > 0 ? pricePerL : (total > 0 ? total / liters : 0);
  const rec = {
    id: 'r-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    timestamp_ms: parseInt(b.timestamp_ms) || Date.now(),
    fuel_l_before: parseFloat(b.fuel_l_before) || 0,
    fuel_l_after:  parseFloat(b.fuel_l_after)  || 0,
    liters_added: liters,
    price_per_liter: finalPrice,
    total_cost: finalPrice * liters,
    odometer_km: parseFloat(b.odometer_km) || (+state.odometer_km || 0),
    location_name: b.location_name || '',
    notes: b.notes ? String(b.notes).slice(0, 240) : '',
    pending: !(finalPrice > 0),
  };
  refuels.push(rec);
  recomputeTankAvgPrice();
  broadcast('new_refuel', rec);
  res.json({ ok: true, refuel: rec, tank_avg_price_per_l: state.tank_avg_price_per_l });
});

// PATCH /api/refuels/:id — atualiza campos (preço, posto, notas)
app.patch('/api/refuels/:id', (req, res) => {
  const r = refuels.find(x => x.id === req.params.id || String(x.timestamp_ms) === req.params.id);
  if (!r) return res.status(404).json({ error: 'não encontrado' });
  const b = req.body || {};
  if (b.price_per_liter !== undefined) {
    const p = parseFloat(b.price_per_liter);
    if (!(p > 0)) return res.status(400).json({ error: 'price_per_liter inválido' });
    r.price_per_liter = p;
    r.total_cost = p * (+r.liters_added || 0);
    r.pending = false;
  } else if (b.total_cost !== undefined) {
    const t = parseFloat(b.total_cost);
    if (!(t > 0)) return res.status(400).json({ error: 'total_cost inválido' });
    r.total_cost = t;
    r.price_per_liter = (+r.liters_added || 0) > 0 ? t / r.liters_added : 0;
    r.pending = false;
  }
  if (b.liters_added !== undefined) {
    const newL = parseFloat(b.liters_added);
    if (newL > 0) { r.liters_added = newL; r.pending = false; }
  }
  if (b.location_name !== undefined) r.location_name = String(b.location_name).slice(0, 80);
  if (b.notes !== undefined)         r.notes = String(b.notes).slice(0, 240);
  if (b.timestamp_ms !== undefined)  r.timestamp_ms = parseInt(b.timestamp_ms) || r.timestamp_ms;
  if (b.odometer_km !== undefined)   r.odometer_km = parseFloat(b.odometer_km) || r.odometer_km;
  // Recoeficiente total se price ou liters mudaram
  if (r.price_per_liter > 0 && r.liters_added > 0) r.total_cost = r.price_per_liter * r.liters_added;
  saveRefuels();
  recomputeTankAvgPrice();
  res.json({ ok: true, refuel: r, tank_avg_price_per_l: state.tank_avg_price_per_l });
});

app.delete('/api/refuels/:id', (req, res) => {
  const idx = refuels.findIndex(x => x.id === req.params.id || String(x.timestamp_ms) === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'não encontrado' });
  refuels.splice(idx, 1);
  saveRefuels();
  recomputeTankAvgPrice();
  res.json({ ok: true, tank_avg_price_per_l: state.tank_avg_price_per_l });
});

// POST /api/fuel-calibrate — corrige leitura errada do sensor de combustível.
// Body: { actual_l: 15 }  → aplica offset = actual - fuel_l_atual, atualiza
// state.fuel_l imediatamente e persiste o offset no state.json.
app.post('/api/fuel-calibrate', requireAuth, (req, res) => {
  const actual = parseFloat(req.body.actual_l);
  if (!isFinite(actual) || actual < 0 || actual > TANK_CAPACITY_L) {
    return res.status(400).json({ error: 'actual_l inválido' });
  }
  const delta = actual - state.fuel_l;
  state.fuel_calib_offset_l = +((state.fuel_calib_offset_l || 0) + delta).toFixed(2);
  state.fuel_l = +actual.toFixed(1);
  scheduleStateSave();
  console.log(`[fuel-calib] offset ajustado em ${delta > 0 ? '+' : ''}${delta.toFixed(1)}L → offset total=${state.fuel_calib_offset_l}L fuel_l=${state.fuel_l}L`);
  res.json({ ok: true, fuel_l: state.fuel_l, fuel_calib_offset_l: state.fuel_calib_offset_l });
});

// PATCH /api/charges/:ts/location
// Body: { name?, lat?, lng?, save_known? }
// - Se name === '' → limpa localização
// - Se só lat+lng → tenta auto-match em locais conhecidos
// - Se name + (lat+lng) + save_known → salva como local favorito também
app.patch('/api/charges/:ts/location', (req, res) => {
  const ts = parseInt(req.params.ts);
  const charge = chargesArr.find(c => (c.timestamp_ms || 0) === ts);
  if (!charge) return res.status(404).json({ error: 'recarga não encontrada' });

  const { name, lat, lng, save_known } = req.body || {};

  if (name === '') {
    // Limpar localização
    delete charge.location_name;
    delete charge.location_lat;
    delete charge.location_lng;
    charge._updated_ms = Date.now();
    scheduleChargesFlush();
    return res.json(charge);
  }

  if (!name && (lat != null || lng != null)) {
    // Auto-tag por GPS (chamado pela PWA quando recarga termina)
    if (lat != null) charge.location_lat = lat;
    if (lng != null) charge.location_lng = lng;
    const match = autoMatchLocation(lat, lng);
    if (match) charge.location_name = match.name;
    charge._updated_ms = Date.now();
    scheduleChargesFlush();
    return res.json(charge);
  }

  if (name?.trim()) charge.location_name = name.trim();
  if (lat != null)  charge.location_lat  = lat;
  if (lng != null)  charge.location_lng  = lng;

  if (save_known && name?.trim() && lat != null && lng != null) {
    // Salva no sistema unificado knownPlaces (radius_m padrão 200m)
    const dup = knownPlaces.find(p =>
      p.name.trim().toLowerCase() === name.trim().toLowerCase() ||
      (p.lat && p.lng && haversineM(p.lat, p.lng, lat, lng) < 50)
    );
    if (!dup) {
      knownPlaces.push({ id: Date.now(), name: name.trim(), lat, lng, radius_m: 200 });
      saveKnownPlaces();
    }
  }

  charge._updated_ms = Date.now();
  scheduleChargesFlush();
  res.json(charge);
});

// PATCH /api/charges/:ts/charger_kwh — kWh marcado no carregador externo
app.patch('/api/charges/:ts/charger_kwh', (req, res) => {
  const ts     = parseInt(req.params.ts, 10);
  // Aceita ambas as chaves: PWA antigo cacheado mandava `kwh`; PWA novo manda
  // `charger_kwh`. Sem isso, body com `kwh` era lido como undefined e o campo
  // era SILENCIOSAMENTE deletado — valor sumia após o próximo refetch/restart.
  const body = req.body || {};
  const raw = body.charger_kwh != null ? body.charger_kwh : body.kwh;
  const charge = chargesArr.find(c => (c.timestamp_ms || 0) === ts);
  if (!charge) return res.status(404).json({ error: 'not found' });
  const val = parseFloat(raw) || 0;
  if (val > 0) charge.charger_kwh = val; else delete charge.charger_kwh;
  charge._updated_ms = Date.now();
  scheduleChargesFlush();
  res.json(charge);
});

// PATCH /api/charges/:ts/cost — override de custo de recarga
/// O R$/kWh desta sessão é atípico? Devolve o motivo ou null.
///
/// Dois critérios, pedidos pelo dono em 05/08:
///  1. Acima de R$ 2,00/kWh — atípico em qualquer lugar, sempre pergunta.
///  2. Mais de 10% distante da MEDIANA daquele local.
///
/// Mediana e não média: um único erro de digitação (como o 2,56/kWh que apareceu na
/// série) desloca a média e passa a legitimar o próximo erro. A mediana ignora o
/// outlier em vez de incorporá-lo.
///
/// Existe porque um custo errado não fica contido: ele entra na média ponderada da
/// bateria e contamina o custo de TODAS as viagens seguintes — em 31/07 uma sessão
/// levou a média de 0,69 pra 1,54 e ela demorou dias pra voltar.
function _precoAtipico(charge, perKwh) {
  if (!(perKwh > 0)) return null;
  if (perKwh > 2.0) {
    return { motivo: 'acima_de_2', texto: `R$ ${perKwh.toFixed(2)}/kWh é atípico (acima de R$ 2,00)` };
  }
  const local = String(charge.location_name || '').trim();
  if (!local) return null;   // sem local não há mediana pra comparar
  const precos = chargesArr
    .filter(c => c.timestamp_ms !== charge.timestamp_ms
              && String(c.location_name || '').trim() === local)
    .map(c => {
      const e = +c.energy_kwh || 0, o = c.cost_override;
      if (!o || e < 0.05) return 0;
      if (o.free === true) return 0;
      return +o.total > 0 ? (+o.total / e) : (+o.perKwh || 0);
    })
    .filter(p => p > 0 && p < 5)
    .sort((a, b) => a - b);
  if (precos.length < 3) return null;   // amostra pequena: mediana não significa nada
  const meio = Math.floor(precos.length / 2);
  const mediana = precos.length % 2 ? precos[meio] : (precos[meio - 1] + precos[meio]) / 2;
  if (mediana <= 0) return null;
  const desvio = (perKwh - mediana) / mediana;
  if (Math.abs(desvio) > 0.10) {
    return {
      motivo: 'fora_da_mediana', mediana: +mediana.toFixed(3),
      desvioPct: +(desvio * 100).toFixed(1), local, amostras: precos.length,
      texto: `R$ ${perKwh.toFixed(2)}/kWh está ${desvio > 0 ? 'acima' : 'abaixo'} `
           + `${Math.abs(desvio * 100).toFixed(0)}% da mediana de ${local} `
           + `(R$ ${mediana.toFixed(2)}/kWh em ${precos.length} recargas)`,
    };
  }
  return null;
}

/// Confirma um custo marcado como atípico — o dono diz "é isso mesmo".
app.post('/api/charges/:ts/confirm-cost', requireAuth, (req, res) => {
  const ts = parseInt(req.params.ts, 10);
  const c = chargesArr.find(x => x.timestamp_ms === ts);
  if (!c) return res.status(404).json({ error: 'recarga não encontrada' });
  delete c._precoAtipico;
  c._precoConfirmado = true;
  // Bump OBRIGATÓRIO: o app sincroniza incremental (`?since=`) e o GET filtra por
  // `_updated_ms`. Sem mexer nele o registro não conta como alterado, não é reenviado,
  // e o app segue com a cópia em cache — o aviso continuava na tela mesmo com o
  // servidor já tendo apagado a flag (19/08, "mesmo clicando em É isso mesmo").
  c._updated_ms = Date.now();
  // `saveCharges()` não existe — o nome certo é `scheduleChargesFlush()`. Este handler
  // lançava ReferenceError e devolvia 500 desde que eu o escrevi (06/08): confirmar
  // custo atípico nunca persistiu.
  scheduleChargesFlush();
  console.log(`[charge] custo atípico CONFIRMADO pelo dono ts=${ts}`);
  res.json({ ok: true });
});

app.patch('/api/charges/:ts/cost', (req, res) => {
  const ts     = parseInt(req.params.ts, 10);
  const { total, per_kwh, free } = req.body || {};
  const charge = chargesArr.find(c => (c.timestamp_ms || 0) === ts);
  if (!charge) return res.status(404).json({ error: 'not found' });
  const t = parseFloat(total) || 0;
  if (free === true)  charge.cost_override = { total: 0, perKwh: 0, free: true };
  else if (t > 0)     charge.cost_override = { total: t, perKwh: parseFloat(per_kwh) || 0 };
  // Avalia DEPOIS de gravar: precisa do valor final pra comparar com a mediana.
  if (free !== true) {
    const e = +charge.energy_kwh || 0;
    const efetivo = e > 0.05 && t > 0 ? (t / e) : (parseFloat(per_kwh) || 0);
    const aviso = _precoAtipico(charge, efetivo);
    if (aviso) {
      charge._precoAtipico = { ...aviso, perKwh: +efetivo.toFixed(3), ts: Date.now() };
      delete charge._precoConfirmado;
      console.warn(`[charge] custo atípico ts=${charge.timestamp_ms}: ${aviso.texto}`);
      // Push pra não depender de o dono abrir a tela e notar sozinho.
      sendPush('⚡ Custo de recarga fora do padrão', aviso.texto + ' — confira no app.',
               'charge_cost_odd').catch(() => {});
    } else {
      delete charge._precoAtipico;
    }
  }
  else                delete charge.cost_override;
  charge._updated_ms = Date.now();
  scheduleChargesFlush();
  recomputeBatteryAvgPrice();   // recalcula mix da bateria após override
  res.json(charge);
});

// PATCH /api/charges/:ts/edit — edita SOC início/fim, energia injetada e duração.
// Sobrescreve dados do Android pra corrigir leituras incorretas do carro (falhas
// de comunicação). Armazenado em `manual_overrides`; o merge MQTT preserva o
// objeto, então re-publicações do Android NÃO sobrescrevem a edição.
// Body: { soc_start?, soc_end?, energy_kwh?, duration_sec? } — campos ausentes
// ou null limpam aquele override individual. Para limpar TUDO: { clear: true }.
app.patch('/api/charges/:ts/edit', (req, res) => {
  const ts     = parseInt(req.params.ts, 10);
  const charge = chargesArr.find(c => (c.timestamp_ms || 0) === ts);
  if (!charge) return res.status(404).json({ error: 'not found' });
  const body = req.body || {};

  if (body.clear === true) {
    delete charge.manual_overrides;
    charge._updated_ms = Date.now();
    scheduleChargesFlush();
    return res.json(applyChargeOverrides(charge));
  }

  const ov = { ...(charge.manual_overrides || {}) };
  const setOrClear = (field, raw, parser, validate) => {
    if (!(field in body)) return;             // não enviado → mantém como está
    if (raw === null || raw === '') { delete ov[field]; return; }  // explícito clear
    const v = parser(raw);
    if (!Number.isFinite(v) || !validate(v)) return;  // inválido → ignora
    ov[field] = v;
  };
  setOrClear('soc_start',    body.soc_start,    parseFloat, v => v >= 0 && v <= 100);
  setOrClear('soc_end',      body.soc_end,      parseFloat, v => v >= 0 && v <= 100);
  setOrClear('energy_kwh',   body.energy_kwh,   parseFloat, v => v >= 0 && v < 1000);
  setOrClear('duration_sec', body.duration_sec, x => parseInt(x, 10), v => v >= 0 && v < 86400 * 7);

  if (Object.keys(ov).length > 0) charge.manual_overrides = ov;
  else                            delete charge.manual_overrides;
  charge._updated_ms = Date.now();
  scheduleChargesFlush();
  // energy_kwh editado muda o mix da bateria
  recomputeBatteryAvgPrice();
  res.json(applyChargeOverrides(charge));
});

// ── Proxy de tiles OSM para o canvas do Snapshot ──────────────────────────────
// Evita CORS: o canvas carrega via apiFetch (com auth) e recebe PNG do OSM
app.get('/api/tiles/:z/:x/:y', (req, res) => {
  const z = parseInt(req.params.z, 10);
  const x = parseInt(req.params.x, 10);
  const y = parseInt(req.params.y, 10);
  if (isNaN(z) || isNaN(x) || isNaN(y) || z < 0 || z > 19) return res.status(400).end();
  const opts = {
    hostname: 'tile.openstreetmap.org',
    path:     `/${z}/${x}/${y}.png`,
    method:   'GET',
    timeout:  8000,
    headers: {
      'User-Agent': 'EcotripBridge/1.0 (https://github.com/rafaelcs28/haval-ecotrip)',
      'Accept':     'image/png',
    },
  };
  const proxyReq = https.get(opts, proxyRes => {
    res.setHeader('Content-Type',  'image/png');
    res.setHeader('Cache-Control', 'public, max-age=86400');
    res.status(proxyRes.statusCode || 200);
    proxyRes.pipe(res);
  });
  proxyReq.on('timeout', () => { proxyReq.destroy(); res.status(504).end(); });
  proxyReq.on('error',   () => res.status(502).end());
});

// POST /api/admin/test-charging — simula uma recarga em andamento por N segundos.
// Útil pra testar Live Activity, notificações ao vivo e UX da Dash sem o
// carro estar realmente plugado. Body: { duration_sec?: 60, soc?: 50, power_kw?: 7.2 }
let _testChargingTimer = null;
let _testChargingSnapshot = null;
app.post('/api/admin/test-charging', (req, res) => {
  const { duration_sec, soc, power_kw, remaining_min } = req.body || {};
  const dur  = Math.max(15, Math.min(600, parseInt(duration_sec) || 60));
  const _soc = Math.max(0, Math.min(100, parseFloat(soc) || 50));
  const _pwr = Math.max(0, parseFloat(power_kw) || 7.2);
  const _rem = Math.max(0, parseInt(remaining_min) || 120);

  // Salva snapshot do estado atual (se ainda não houver) pra restaurar depois
  if (!_testChargingSnapshot) {
    _testChargingSnapshot = {
      charging_state:        state.charging_state,
      soc_pct:               state.soc_pct,
      charge_power_kw:       state.charge_power_kw,
      charge_session_kwh:    state.charge_session_kwh,
      charge_remaining_min:  state.charge_remaining_min,
      charge_start_soc_pct:  state.charge_start_soc_pct,
    };
  }
  // Mock state
  state.charging_state       = 'Carregando';
  state.soc_pct              = _soc;
  state.charge_power_kw      = _pwr;
  state.charge_session_kwh   = 1.2;
  state.charge_remaining_min = _rem;
  state.charge_start_soc_pct = _soc - 5;
  broadcast('update', state);

  // Injeta notif no histórico (app nativo iOS vai pegar via polling em ~30s)
  sendPush('⚡ Recarga iniciada (teste)',
           `${_pwr.toFixed(1)} kW · ~${_rem} min · SOC ${_soc.toFixed(0)}%`,
           'charge_start');

  // Restaura estado depois de `dur` segundos
  if (_testChargingTimer) clearTimeout(_testChargingTimer);
  _testChargingTimer = setTimeout(() => {
    if (_testChargingSnapshot) {
      Object.assign(state, _testChargingSnapshot);
      _testChargingSnapshot = null;
      broadcast('update', state);
      sendPush('✅ Recarga concluída (teste)',
               `SOC ${_soc.toFixed(0)}% · sessão encerrada`,
               'charge_end');
    }
    _testChargingTimer = null;
  }, dur * 1000);

  res.json({ ok: true, duration_sec: dur, ends_at: new Date(Date.now() + dur * 1000).toISOString() });
});

// POST /api/admin/restart  body: { "token": "..." }
// Admin usa ADMIN_TOKEN se definido, senão cai para BRIDGE_TOKEN
// Aceita token via Authorization header (PWA novo) ou body.token (retrocompat)
function adminCheckToken(req, res) {
  const adminToken = process.env.ADMIN_TOKEN ? sha256hex(process.env.ADMIN_TOKEN) : BRIDGE_TOKEN_HASH;
  if (!adminToken) { res.status(503).json({ error: 'ADMIN_TOKEN not configured' }); return false; }
  const auth  = req.headers['authorization'] || '';
  const token = (auth.startsWith('Bearer ') ? auth.slice(7).trim() : '')
             || req.body?.token || req.query.token || '';
  const adminValid = token === adminToken || sha256hex(token) === adminToken;
  if (!adminValid) { res.status(401).json({ error: 'unauthorized' }); return false; }
  return true;
}

app.post('/api/admin/restart', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  res.json({ ok: true, msg: 'reiniciando em 500ms...' });
  setTimeout(() => {
    console.log('[admin] Restart solicitado remotamente');
    process.exit(0);
  }, 500);
});

// POST /api/admin/notify { token, title, body } — push de aviso admin (ex.:
// renovação TestFlight). Manda APNs alert (banner real na tela bloqueada, app
// fechado) gated SÓ pro device do Rafael (ADMIN_DEVICE_ID) — assim não vaza pro
// iPhone da Grasi. Web Push no PWA iOS só aparece com o app em foco, por isso
// agora vai pelo APNs nativo. skipHistory pra não poluir o feed.
const ADMIN_DEVICE_ID = process.env.ADMIN_DEVICE_ID || '';
app.post('/api/admin/notify', async (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const title = String(req.body?.title || 'Ecotrip').slice(0, 120);
  const body  = String(req.body?.body  || '').slice(0, 400);
  try {
    await sendPush(title, body, null, {
      skipHistory: true,
      onlyDeviceIds: ADMIN_DEVICE_ID ? [ADMIN_DEVICE_ID] : undefined,
    });
    res.json({ ok: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── Veículo (chassi GWM) ─────────────────────────────────────────────────────
// GET retorna config ATIVA (a que o bridge subiu com) + a que está salva em
// vehicle.json — podem divergir se o user editou mas não reiniciou.
// Lê o conteúdo inteiro do vehicle.json (chassi + model_name)
function _loadVehicleFile() {
  try {
    if (!fs.existsSync(VEHICLE_FILE)) return {};
    return JSON.parse(fs.readFileSync(VEHICLE_FILE, 'utf8')) || {};
  } catch (_) { return {}; }
}

app.get('/api/vehicle', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const onDisk = _loadVehicleFile();
  res.json({
    active:        GWM_CHASSI || null,
    active_source: GWM_CHASSI_SOURCE,
    saved_in_file: onDisk.chassi || null,
    env_value:     _chassiFromEnv || null,
    model_name:    onDisk.model_name || 'Haval H6 PHEV',
    needs_restart: !!(onDisk.chassi && onDisk.chassi !== GWM_CHASSI),
  });
});

// POST { chassi?, model_name? } — aceita atualização parcial. Salva o que vier.
app.post('/api/vehicle', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const body = req.body || {};
  const current = _loadVehicleFile();
  const out = { ...current };
  let needsRestart = false;
  // Chassi (opcional na chamada, mas se vier precisa ser válido)
  if (body.chassi !== undefined) {
    const raw = String(body.chassi).toLowerCase().trim();
    if (!/^lgw[a-z0-9]{14}$/.test(raw)) {
      return res.status(400).json({ error: 'Formato de chassi inválido. Esperado: lgw + 14 alfanuméricos' });
    }
    out.chassi = raw;
    needsRestart = raw !== GWM_CHASSI;
  }
  // Nome do modelo (opcional)
  if (body.model_name !== undefined) {
    const name = String(body.model_name).trim().slice(0, 60);
    if (!name) return res.status(400).json({ error: 'Nome do modelo vazio' });
    out.model_name = name;
  }
  if (Object.keys(out).length === Object.keys(current).length &&
      Object.keys(out).every(k => out[k] === current[k])) {
    return res.json({ ok: true, unchanged: true });
  }
  out.updated_at = Date.now();
  try {
    atomicWriteFileSync(VEHICLE_FILE, JSON.stringify(out, null, 2));
    res.json({ ok: true, ...out, needs_restart: needsRestart });
  } catch (e) {
    res.status(500).json({ error: 'Falha ao gravar vehicle.json: ' + e.message });
  }
});

// ── Auto-serviço: cada dono configura a conexão do PRÓPRIO broker + HA + chassi ──
// (Multi-tenant Modelo B: a instância conecta no broker da HA da pessoa, via tailnet.)
// Atualiza chaves específicas no .env do tenant, preservando o resto.
function _updateEnvKeys(updates) {
  const envPath = path.join(DATA_DIR, '.env');
  let lines = [];
  try { lines = fs.readFileSync(envPath, 'utf8').split('\n'); } catch (_) {}
  const keys = Object.keys(updates);
  const kept = lines.filter(l => !keys.some(k => l.startsWith(k + '=')));
  for (const k of keys) kept.push(`${k}=${updates[k]}`);
  atomicWriteFileSync(envPath, kept.join('\n').replace(/\n+$/, '') + '\n');
}

app.get('/api/my-setup', (req, res) => {
  res.json({
    mqtt_host:   MQTT_HOST.replace(/^mqtts?:\/\//, ''),   // sem o scheme (a UI mostra limpo)
    mqtt_port:   MQTT_PORT, mqtt_user: MQTT_USER,
    mqtt_tls:    MQTT_HOST.startsWith('mqtts://'),         // TLS = scheme mqtts://
    car_mqtt_host: CAR_MQTT_HOST, car_mqtt_port: CAR_MQTT_PORT, car_mqtt_tls: CAR_MQTT_TLS,
    mqtt_prefix: MQTT_PREFIX, has_mqtt_pass: !!MQTT_PASS,
    chassi:      GWM_CHASSI, ha_url: HA_URL, has_ha_token: !!HA_TOKEN,
    mqtt_connected: !!(mqttClient && mqttClient.connected),
  });
});

app.post('/api/my-setup', (req, res) => {
  const b = req.body || {};
  const env = {};
  // Host + TLS: broker público da pessoa usa mqtts:// (TLS na 8883). Sem TLS → mqtt://.
  if (b.mqtt_host !== undefined) {
    const bare = String(b.mqtt_host).trim().replace(/^mqtts?:\/\//, '');
    if (bare) env.MQTT_HOST = (b.mqtt_tls ? 'mqtts://' : 'mqtt://') + bare;
  }
  if (b.mqtt_port   !== undefined) env.MQTT_PORT   = String(parseInt(b.mqtt_port, 10) || 1883);
  // Broker PÚBLICO do carro (pareamento) — separado do host local do bridge.
  if (b.car_mqtt_host !== undefined) env.CAR_MQTT_HOST = String(b.car_mqtt_host).trim().replace(/^mqtts?:\/\//, '');
  if (b.car_mqtt_port !== undefined) env.CAR_MQTT_PORT = String(parseInt(b.car_mqtt_port, 10) || 8883);
  if (b.car_mqtt_tls  !== undefined) env.CAR_MQTT_TLS  = b.car_mqtt_tls ? 'true' : 'false';
  if (b.mqtt_user   !== undefined) env.MQTT_USER   = String(b.mqtt_user).trim();
  if (b.mqtt_pass)                 env.MQTT_PASS   = String(b.mqtt_pass);          // só troca se veio
  if (b.mqtt_prefix !== undefined) env.MQTT_PREFIX = String(b.mqtt_prefix).trim().replace(/\/+$/, '');
  if (b.ha_url      !== undefined) env.HA_URL      = String(b.ha_url).trim().replace(/\/+$/, '');
  if (b.ha_token)                  env.HA_TOKEN    = String(b.ha_token);            // só troca se veio
  // Chassi → vehicle.json (mesma fonte da aba Veículo)
  if (b.chassi !== undefined) {
    const raw = String(b.chassi).toLowerCase().trim();
    if (raw && !/^lgw[a-z0-9]{14}$/.test(raw)) return res.status(400).json({ error: 'Chassi inválido (esperado: lgw + 14 alfanuméricos)' });
    try { const cur = _loadVehicleFile(); atomicWriteFileSync(VEHICLE_FILE, JSON.stringify({ ...cur, chassi: raw, updated_at: Date.now() }, null, 2)); }
    catch (e) { return res.status(500).json({ error: 'Falha ao salvar chassi: ' + e.message }); }
  }
  try { if (Object.keys(env).length) _updateEnvKeys(env); }
  catch (e) { return res.status(500).json({ error: 'Falha ao salvar config: ' + e.message }); }
  res.json({ ok: true, restarting: true });
  // .env é lido no boot → reinicia pra aplicar (pm2 sobe de novo).
  console.log('[my-setup] config atualizada — reiniciando pra aplicar…');
  setTimeout(() => process.exit(0), 800);
});

app.post('/api/admin/update', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const { exec } = require('child_process');
  const repoDir = path.join(__dirname, '..');
  // 1) Diagnóstico rápido: remote + branch atual
  exec('git remote -v && git branch --show-current', { cwd: repoDir }, (e0, s0) => {
    const diagInfo = (s0 || '').trim();
    // 2) fetch + reset --hard evita falhar por mudanças locais ou merge conflicts
    exec('git fetch origin 2>&1 && git reset --hard origin/main 2>&1', { cwd: repoDir, shell: true }, (err, stdout, stderr) => {
      const pullOut = (stdout || '').trim() || (stderr || '').trim() || '(sem saída)';
      if (err) {
        console.error('[admin] update falhou:', err.message);
        return res.json({ ok: false, msg: `Diagnóstico:\n${diagInfo}\n\nErro:\n${pullOut}` });
      }
      console.log('[admin] update OK:', pullOut);
      res.json({ ok: true, msg: pullOut + '\n\nReiniciando servidor...' });
      setTimeout(() => {
        console.log('[admin] Reiniciando após update');
        process.exit(0);
      }, 500);
    });
  });
});

app.post('/api/admin/change-password', (req, res) => {
  // Autenticação já foi verificada pelo middleware requireAuth
  const { newHash } = req.body || {};
  console.log('[change-password] recebido newHash length:', newHash?.length, 'body keys:', Object.keys(req.body || {}));
  if (!newHash || typeof newHash !== 'string' || newHash.length < 4) {
    return res.status(400).json({ error: 'Nova senha muito curta (mínimo 4 caracteres)' });
  }
  // Atualiza o .env: substitui BRIDGE_TOKEN e BRIDGE_TOKEN_HASH pelo novo hash
  const envPath = path.join(DATA_DIR, '.env');
  let envContent = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
  envContent = envContent.split('\n')
    .filter(l => !l.startsWith('BRIDGE_TOKEN=') && !l.startsWith('BRIDGE_TOKEN_HASH='))
    .join('\n').trimEnd();
  envContent += '\nBRIDGE_TOKEN_HASH=' + newHash + '\n';
  atomicWriteFileSync(envPath, envContent, 'utf8');
  BRIDGE_TOKEN_HASH = newHash;
  console.log('[admin] Senha alterada. Novo BRIDGE_TOKEN_HASH:', newHash.substring(0, 8) + '…');
  res.json({ ok: true, msg: 'Senha alterada com sucesso.' });
});

// ── Backup & Restore completo ─────────────────────────────────────────────────
// Monta o objeto de backup do ecotrip (trips + autotrips com telemetria +
// charges + lifetime snapshots + prefs). Compartilhado por /api/backup e
// /api/system-backup.
function _buildEcotripBackup() {
  const autotripsWithSamples = [];
  const atFiles = fs.readdirSync(AUTOTRIPS_DIR).filter(f => f.endsWith('.json'));
  for (const f of atFiles) {
    try {
      const d = JSON.parse(fs.readFileSync(path.join(AUTOTRIPS_DIR, f), 'utf8'));
      autotripsWithSamples.push(d);  // { tripId, autoTrip, samples }
    } catch (_) {}
  }
  autotripsWithSamples.sort((a, b) =>
    (b.autoTrip?.startMs || 0) - (a.autoTrip?.startMs || 0));

  // Telemetria de recargas — um arquivo por sessão em charge_telemetry/
  const chargeTelemetry = {};
  try {
    const ctFiles = fs.readdirSync(CHARGE_TELEMETRY_DIR).filter(f => f.endsWith('.json'));
    for (const f of ctFiles) {
      const ts = f.replace('.json', '');
      try {
        chargeTelemetry[ts] = JSON.parse(fs.readFileSync(path.join(CHARGE_TELEMETRY_DIR, f), 'utf8'));
      } catch (_) {}
    }
  } catch (_) {}

  return {
    version:           4,
    exportedAt:        new Date().toISOString(),
    // Histórico (trips manuais A/B descontinuados — campo legado pra compat v2)
    trips:             [],
    autotrips:         autotripsWithSamples,
    charges:           chargesArr,
    chargeTelemetry,                                // novo v4: samples por sessão de recarga
    refuels,                                        // abastecimentos
    lifeSnapshots,
    telemetryHistory,                               // snapshots diários (anomalia)
    // Configurações
    notifPrefs,
    maintenance,                                    // intervalos + histórico + alerts
    knownPlaces,                                    // locais conhecidos
    chargeLocations,                                // locais antigos (compat)
    deletedIds,                                     // tombstones de deleção
    // NÃO inclui: auth.json (TOTP secret), state.json (runtime, recomputado),
    // cert.pem/key.pem (per-server).
  };
}

// GET /api/backup — exporta tudo em um único JSON (trips + autotrips com
// telemetria + charges + lifetime snapshots + prefs de notificação).
// Protegido por requireAuth (middleware global).
app.get('/api/backup', (req, res) => {
  if (!adminCheckToken(req, res)) return;  // exige token (Authorization header OR ?token=)
  try {
    const backup = _buildEcotripBackup();
    const filename = `ecotrip-backup-${new Date().toISOString().slice(0, 10)}.json`;
    // Pré-serializa pra saber o tamanho exato — expõe via X-Original-Size pro
    // PWA calcular % de progresso (com gzip ativo, Content-Length some).
    const buf = Buffer.from(JSON.stringify(backup), 'utf8');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader('X-Original-Size', String(buf.length));
    res.setHeader('Access-Control-Expose-Headers', 'X-Original-Size');
    res.send(buf);
    const mb = (buf.length / 1024 / 1024).toFixed(2);
    console.log(`✓ Backup v4 exportado (${mb} MB): ${backup.autotrips.length} auto-trips · ${backup.charges.length} recargas (${Object.keys(backup.chargeTelemetry).length} com telemetria) · ${backup.refuels.length} abastecimentos · ${backup.maintenance.history.length} manutenções · ${backup.knownPlaces.length} locais`);
  } catch (e) {
    console.error('[backup] Erro:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// GET /api/system-backup — backup noturno consolidado dos 6 processos do Mac
// (bridge ecotrip, gateway multi-tenant, ellevar-clockin, gwm-bridge,
// whats-assistant, radicale). Puxado pela HA do Sítio (única forma de tirar
// os dados do Mac pra fora, já que ele não tem IP fixo pra receber push).
// Lê tudo via filesystem local (mesmo usuário Unix, sem precisar de auth
// cruzada entre processos) e empacota num .tar.gz único.
const HOME_DIR = require('os').homedir();
app.get('/api/system-backup', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const { execFileSync } = require('child_process');
  const tmpDir = fs.mkdtempSync(path.join(require('os').tmpdir(), 'sysbackup-'));
  try {
    // 1. Export fresco do ecotrip (mesmo conteúdo do /api/backup).
    fs.writeFileSync(path.join(tmpDir, 'ecotrip-backup.json'), JSON.stringify(_buildEcotripBackup()));

    // 2. Artefatos já curados pelos backups internos de cada serviço — só
    //    pega o mais recente de cada um, não recomputa nada.
    const latestByMtime = (dir, filter) => {
      try {
        const entries = fs.readdirSync(dir).filter(filter).map(f => ({
          f, mtime: fs.statSync(path.join(dir, f)).mtimeMs,
        }));
        entries.sort((a, b) => b.mtime - a.mtime);
        return entries[0]?.f || null;
      } catch (_) { return null; }
    };

    const items = [];  // [srcAbsPath, arcName] — arcName vira o path dentro do tar
    const ellevarSqlite = latestByMtime(path.join(HOME_DIR, 'ellevar-clockin/data/backups'), f => f.endsWith('.sqlite'));
    if (ellevarSqlite) items.push([path.join(HOME_DIR, 'ellevar-clockin/data/backups', ellevarSqlite), `ellevar/${ellevarSqlite}`]);
    if (fs.existsSync(path.join(HOME_DIR, 'ellevar-clockin/data/leave-attachments')))
      items.push([path.join(HOME_DIR, 'ellevar-clockin/data/leave-attachments'), 'ellevar/leave-attachments']);

    const whatsDay = latestByMtime(path.join(HOME_DIR, 'whats-assistant/backups'), () => true);
    if (whatsDay) items.push([path.join(HOME_DIR, 'whats-assistant/backups', whatsDay), `whats/backups/${whatsDay}`]);
    // Gaps não cobertos pelo backup.sh diário do whats-assistant.
    for (const rel of ['data/assistant-rafael-files', 'auth-state', 'auth-state-rafael', 'radicale/users.htpasswd']) {
      const abs = path.join(HOME_DIR, 'whats-assistant', rel);
      if (fs.existsSync(abs)) items.push([abs, `whats/${rel}`]);
    }

    // gwm-bridge: sessão/cache com a nuvem GWM (deviceid, imsi, comandos).
    if (fs.existsSync(path.join(HOME_DIR, 'gwm-bridge/haval-h6-mqtt/storage')))
      items.push([path.join(HOME_DIR, 'gwm-bridge/haval-h6-mqtt/storage'), 'gwm-bridge/storage']);

    // ecotrip-gateway: registro dos tenants + secret de sessão.
    for (const f of ['tenants/registry.json', 'tenants/gateway_secret']) {
      const abs = path.join(__dirname, f);
      if (fs.existsSync(abs)) items.push([abs, `ecotrip-gateway/${path.basename(f)}`]);
    }

    // Monta um diretório staging pra poder dar um `tar -czf` só, com paths
    // relativos simples (evita -C repetido / paths absolutos vazando no tar).
    // `cp -R` aborta ao 1º arquivo transiente que some entre readdir/open —
    // acontece em auth-state-rafael (Baileys grava/apaga session keys em
    // rajada de milhares por hora) e derrubava o backup TODO com "Command
    // failed: cp -R". Solução: tar-streaming (tar -cf - src | tar -xf - dest);
    // stderr do -cf pode ter warnings de arquivos sumidos, mas o pipe segue
    // e o exit do `sh -c` reflete o -xf (que sempre sucede se stream chega).
    // rsync do macOS é BSD 2.6.9 sem --ignore-missing-args, então tar é o fix.
    const failed = [];
    for (const [src, arcName] of items) {
      const destParent = path.join(tmpDir, path.dirname(arcName));
      fs.mkdirSync(destParent, { recursive: true });
      try {
        if (fs.statSync(src).isDirectory()) {
          const srcParent = path.dirname(src);
          const srcBase   = path.basename(src);
          execFileSync('sh', ['-c',
            `tar -cf - -C "${srcParent}" "${srcBase}" 2>/dev/null | tar -xf - -C "${destParent}"`,
          ]);
          // Renomeia se arcName final difere do basename original
          const created = path.join(destParent, srcBase);
          const dest = path.join(tmpDir, arcName);
          if (created !== dest && fs.existsSync(created)) {
            fs.renameSync(created, dest);
          }
        } else {
          execFileSync('cp', ['-p', src, path.join(tmpDir, arcName)]);
        }
      } catch (e) {
        failed.push(arcName);
        console.warn(`[system-backup] item falhou (segue): ${arcName} — ${e.message.slice(0, 120)}`);
      }
    }
    if (failed.length) console.warn(`[system-backup] itens com falha parcial: ${failed.join(', ')}`);

    const tarPath = path.join(tmpDir, 'out.tar.gz');
    const entries = ['ecotrip-backup.json', ...items.map(([, arcName]) => arcName.split('/')[0])];
    const uniqueTop = [...new Set(entries)];
    execFileSync('tar', ['-czf', tarPath, '-C', tmpDir, ...uniqueTop]);

    const buf = fs.readFileSync(tarPath);
    const filename = `mac-backup-${new Date().toISOString().slice(0, 10)}.tar.gz`;
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.setHeader('Content-Type', 'application/gzip');
    res.send(buf);
    console.log(`✓ System-backup exportado (${(buf.length / 1024 / 1024).toFixed(1)} MB): ${uniqueTop.join(', ')}`);
  } catch (e) {
    console.error('[system-backup] Erro:', e.message);
    res.status(500).json({ error: e.message });
  } finally {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
});

// POST /api/restore — importa backup gerado por /api/backup e reconstrói
// todos os dados em disco e em memória (sem precisar reiniciar o servidor).
app.post('/api/restore', (req, res) => {
  try {
    const bk = req.body;

    // Validação básica — aceita v2 (legado), v3 e v4 (completo)
    if (!bk || (bk.version !== 2 && bk.version !== 3 && bk.version !== 4)) {
      return res.status(400).json({ error: 'Formato inválido. Use um backup gerado por GET /api/backup (version 2, 3 ou 4).' });
    }
    if (!Array.isArray(bk.trips) || !Array.isArray(bk.autotrips) || !Array.isArray(bk.charges)) {
      return res.status(400).json({ error: 'Backup incompleto: trips, autotrips e charges são obrigatórios.' });
    }

    // 1. Trips manuais
    // Trip A/B descontinuados — backup v2 podia conter trips manuais, mas
    // não são mais restaurados. Ignora bk.trips silenciosamente.

    // 2. Auto-trips (com telemetria completa)
    const existingFiles = fs.readdirSync(AUTOTRIPS_DIR).filter(f => f.endsWith('.json'));
    existingFiles.forEach(f => { try { fs.unlinkSync(path.join(AUTOTRIPS_DIR, f)); } catch (_) {} });
    autoTripsArr.length = 0;

    for (const at of bk.autotrips) {
      const safeId = String(at.tripId || at.autoTrip?.startMs || '').replace(/\D/g, '');
      if (!safeId) continue;
      // Preserva hybridTimeSec/hybridDistKm se vieram no backup, senão recalcula.
      const hybrid = (at.hybridTimeSec != null && at.hybridDistKm != null)
        ? { hybridTimeSec: at.hybridTimeSec, hybridDistKm: at.hybridDistKm }
        : _calcHybrid(at.samples || []);
      fs.writeFileSync(
        path.join(AUTOTRIPS_DIR, `${safeId}.json`),
        JSON.stringify({
          tripId: safeId,
          autoTrip: at.autoTrip || {},
          samples: at.samples || [],
          hybridTimeSec: hybrid.hybridTimeSec,
          hybridDistKm:  hybrid.hybridDistKm,
        })
      );
      if (at.autoTrip) {
        autoTripsArr.push({
          tripId: safeId, ...at.autoTrip, ...hybrid,
        });
      }
    }
    autoTripsArr.sort((a, b) => (b.startMs || 0) - (a.startMs || 0));

    // 3. Recargas
    chargesArr.length = 0;
    chargesArr.push(...bk.charges);
    atomicWriteFileSync(CHARGES_FILE, JSON.stringify({ charges: chargesArr }, null, 2));

    // 4. Lifetime snapshots (para Stats da PWA)
    if (Array.isArray(bk.lifeSnapshots)) {
      lifeSnapshots.length = 0;
      lifeSnapshots.push(...bk.lifeSnapshots);
      try { fs.writeFileSync(SNAPSHOTS_FILE, JSON.stringify(lifeSnapshots)); } catch (_) {}
    }

    // 5. Preferências de notificação
    if (bk.notifPrefs && typeof bk.notifPrefs === 'object') {
      Object.assign(notifPrefs, bk.notifPrefs);
      try { fs.writeFileSync(NOTIF_PREFS_FILE, JSON.stringify(notifPrefs, null, 2)); } catch (_) {}
    }

    // 6. Refuels (abastecimentos) — só se backup v3+
    if (Array.isArray(bk.refuels)) {
      refuels.length = 0;
      refuels.push(...bk.refuels);
      saveRefuels();
      recomputeTankAvgPrice();
    }

    // 7. Maintenance (intervalos + histórico)
    if (bk.maintenance && typeof bk.maintenance === 'object') {
      maintenance.intervals = bk.maintenance.intervals || maintenance.intervals;
      maintenance.history   = bk.maintenance.history   || maintenance.history;
      maintenance._alerts   = bk.maintenance._alerts   || {};
      saveMaintenance();
    }

    // 8. Locais conhecidos
    if (Array.isArray(bk.knownPlaces)) {
      knownPlaces.length = 0;
      knownPlaces.push(...bk.knownPlaces);
      saveKnownPlaces();
    }

    // 9. Telemetry history (snapshots diários — alertas de anomalia)
    if (Array.isArray(bk.telemetryHistory)) {
      telemetryHistory.length = 0;
      telemetryHistory.push(...bk.telemetryHistory);
      try { fs.writeFileSync(TELEMETRY_LOG_FILE, JSON.stringify(telemetryHistory, null, 2)); } catch (_) {}
    }

    // 10. Tombstones — preserva memória de o que foi deletado
    if (bk.deletedIds && typeof bk.deletedIds === 'object') {
      deletedIds.autotrips = bk.deletedIds.autotrips || [];
      deletedIds.charges   = bk.deletedIds.charges   || [];
      deletedIds.refuels   = bk.deletedIds.refuels   || [];
      for (const k of ['autotrips', 'charges', 'refuels']) {
        deletedIdsSets[k] = new Set(deletedIds[k].map(String));
      }
      saveDeletedIds();
    }

    // 11. Telemetria de recargas (v4+) — restaura arquivos charge_telemetry/{ts}.json
    let chargeTelemetryRestored = 0;
    if (bk.chargeTelemetry && typeof bk.chargeTelemetry === 'object') {
      // Limpa diretório antes de restaurar
      try {
        fs.readdirSync(CHARGE_TELEMETRY_DIR)
          .filter(f => f.endsWith('.json'))
          .forEach(f => { try { fs.unlinkSync(path.join(CHARGE_TELEMETRY_DIR, f)); } catch (_) {} });
      } catch (_) {}
      for (const [ts, samples] of Object.entries(bk.chargeTelemetry)) {
        try {
          fs.writeFileSync(path.join(CHARGE_TELEMETRY_DIR, `${ts}.json`), JSON.stringify(samples));
          chargeTelemetryRestored++;
        } catch (_) {}
      }
    }

    // Recalcula preço médio da bateria após restore
    recomputeBatteryAvgPrice();

    const summary = {
      autotrips:         autoTripsArr.length,
      charges:           chargesArr.length,
      chargeTelemetry:   chargeTelemetryRestored,
      refuels:           refuels.length,
      lifeSnapshots:     lifeSnapshots.length,
      maintenance:       maintenance.history.length,
      knownPlaces:       knownPlaces.length,
      tombstones:        (deletedIds.autotrips.length + deletedIds.charges.length + deletedIds.refuels.length),
    };
    console.log('✓ Restore completo:', summary);
    res.json({ ok: true, msg: 'Restore concluído com sucesso.', ...summary });
  } catch (e) {
    console.error('[restore] Erro:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// POST /api/admin/sync — sincroniza servidor com lista do cliente.
// O PWA envia keep_autotrips + keep_charges (+ opcional keep_refuels) com
// os IDs que existem no cache local. Tudo no servidor que NÃO está nessas
// listas é deletado e marcado como tombstone (não volta nem por MQTT).
app.post('/api/admin/sync', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const b = req.body || {};
  const keepA = new Set((b.keep_autotrips || []).map(String));
  const keepC = new Set((b.keep_charges   || []).map(v => parseInt(v, 10)));
  const keepR = b.keep_refuels ? new Set(b.keep_refuels.map(String)) : null;

  // Autotrips
  let remA = 0;
  for (let i = autoTripsArr.length - 1; i >= 0; i--) {
    const t = autoTripsArr[i];
    const id = String(t.tripId || t.startMs || '');
    if (!keepA.has(id)) {
      markDeleted('autotrips', id);
      autoTripsArr.splice(i, 1);
      try { fs.unlinkSync(path.join(AUTOTRIPS_DIR, `${id}.json`)); } catch (_) {}
      remA++;
    }
  }

  // Charges
  let remC = 0;
  for (let i = chargesArr.length - 1; i >= 0; i--) {
    const ts = chargesArr[i].timestamp_ms || 0;
    if (!keepC.has(ts)) {
      markDeleted('charges', ts);
      chargesArr.splice(i, 1);
      remC++;
    }
  }
  if (remC > 0) scheduleChargesFlush();

  // Refuels (opcional — só sincroniza se o cliente enviou keep_refuels)
  let remR = 0;
  if (keepR) {
    for (let i = refuels.length - 1; i >= 0; i--) {
      if (!keepR.has(String(refuels[i].id || ''))) {
        markDeleted('refuels', refuels[i].id);
        refuels.splice(i, 1);
        remR++;
      }
    }
    if (remR > 0) { saveRefuels(); recomputeTankAvgPrice(); }
  }

  console.log(`✓ Sync: removidas ${remA} viagens + ${remC} recargas${keepR ? ` + ${remR} abastecimentos` : ''}`);
  res.json({ ok: true, removed_autotrips: remA, removed_charges: remC, removed_refuels: remR });
});

app.post('/api/admin/clear-history', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  try {
    // 1. Recargas
    chargesArr.length = 0;
    atomicWriteFileSync(CHARGES_FILE, JSON.stringify({ charges: [] }, null, 2));

    // 3. Auto-trips — apaga todos os arquivos da pasta
    const files = fs.readdirSync(AUTOTRIPS_DIR).filter(f => f.endsWith('.json'));
    for (const f of files) fs.unlinkSync(path.join(AUTOTRIPS_DIR, f));
    autoTripsArr.length = 0;

    // 4. Grava timestamp do clear — impede que dados MQTT retained anteriores
    //    (re-publicados pelo Android ao reconectar) restaurem o histórico apagado.
    const clearedAt = Date.now();
    state.charges_cleared_at = clearedAt;
    state.trips_cleared_at   = clearedAt;
    atomicWriteFileSync(STATE_FILE, JSON.stringify(state, null, 2));

    console.log('[admin] Histórico apagado (trips, charges, auto-trips)');
    res.json({ ok: true, msg: 'Histórico apagado com sucesso.' });
  } catch (e) {
    console.error('[admin] Erro ao apagar histórico:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ── Auto-trips + Telemetria ───────────────────────────────────────────────────

// Detecta re-POST do mesmo trecho (retry de rede): o trecho `incoming` já está no
// FIM dos `existing` (pós-merge anterior). Compara assinatura de coords (lat/lng/spd)
// no início/meio/fim — o rebasing de `t` no resume só altera o `t`, não as coords.
function _isDuplicateTail(existing, incoming) {
  if (incoming.length === 0 || existing.length < incoming.length) return false;
  const tail = existing.slice(existing.length - incoming.length);
  const eq = (a, b) => Math.abs((a || 0) - (b || 0)) < 1e-5;
  const idxs = [0, incoming.length >> 1, incoming.length - 1];
  return idxs.every(i =>
    eq(tail[i].lat, incoming[i].lat) &&
    eq(tail[i].lng, incoming[i].lng) &&
    eq(tail[i].spd, incoming[i].spd));
}

// Distância derivada dos samples — integração de velocidade (dt<=5s, igual ao
// score) com fallback/sanidade por GPS (haversine). Usada pra blindar o distKm
// vindo do APK quando o hodômetro re-baseia no meio da viagem e injeta um pulo
// (ex.: viagem de 5km vira o acumulado do dia). Retorna {spdKm, gpsKm}.
// ── Sanidade física dos samples ─────────────────────────────────────────────
// Teto de velocidade implícita entre dois samples. O carro não passa de ~200
// km/h; acima de MAX_IMPLIED_KMH o par não é deslocamento, é salto de
// coordenada (GPS resetando, sample de outro trecho, merge desalinhado).
// Sem esse corte, 278 samples com saltos somaram 5.703 km na viagem de 27/07 e
// inflaram o distKm reconciliado de 16,9 pra 19,8 km.
const MAX_IMPLIED_KMH = 250;
// Samples no MESMO instante (dt<=0) não podem estar a mais que isto de distância.
const MAX_SAME_INSTANT_KM = 0.2;

function _kmBetween(a, b) {
  const R = 6371, rad = d => d * Math.PI / 180;
  const dLa = rad(b.lat - a.lat), dLo = rad(b.lng - a.lng);
  const h = Math.sin(dLa / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLo / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** Par consecutivo representa um salto fisicamente impossível? */
function _isTeleport(a, b) {
  if (!(a && b && a.lat && a.lng && b.lat && b.lng)) return false;
  const km = _kmBetween(a, b);
  const dt = (b.t || 0) - (a.t || 0);
  if (dt <= 0) return km > MAX_SAME_INSTANT_KM;
  return (km / (dt / 3600)) > MAX_IMPLIED_KMH;
}

/**
 * Descarta samples cuja posição é impossível vindo do último ponto bom. Mantém
 * a âncora anterior ao comparar, pra que um único ponto ruim no meio não derrube
 * todo o resto da série.
 */
function _dropTeleports(samples) {
  if (!Array.isArray(samples) || samples.length < 2) return { clean: samples || [], dropped: 0 };
  const clean = [samples[0]];
  let dropped = 0;
  for (let i = 1; i < samples.length; i++) {
    if (_isTeleport(clean[clean.length - 1], samples[i])) { dropped++; continue; }
    clean.push(samples[i]);
  }
  return { clean, dropped };
}

/**
 * O trecho `inner` já está coberto pela rota `outer`? Amostra pontos de inner e
 * checa se cada um tem algum ponto de outer por perto.
 *
 * Serve pra decidir merge: quando o APK posta a viagem COMPLETA e o bridge já
 * tem live samples de um pedaço dela, concatenar duplica a rota. Em 27/07 os 278
 * live cobriam 2,9km do FIM do trajeto e foram concatenados ANTES dos 2544 do
 * APK — a rota ia ao fim, voltava ao começo e refazia tudo (20,0km em vez de
 * 16,9km). Comparar só primeiro/último ponto não pegaria: nem coincidem com as
 * pontas do outro trecho.
 */
function _isContainedIn(inner, outer, tolKm = 0.15) {
  const pi = (inner || []).filter(s => s.lat && s.lng);
  const po = (outer || []).filter(s => s.lat && s.lng);
  if (pi.length < 2 || po.length < 2) return false;
  const STEPS = 12;                                   // amostra barata da série
  const step = Math.max(1, Math.floor(pi.length / STEPS));
  let checked = 0, near = 0;
  for (let i = 0; i < pi.length; i += step) {
    checked++;
    for (const o of po) {
      if (_kmBetween(pi[i], o) <= tolKm) { near++; break; }
    }
  }
  return checked > 0 && near / checked >= 0.8;
}

function _sampleDistKm(samples) {
  let spdKm = 0, gpsKm = 0, coveredSec = 0;
  if (!Array.isArray(samples)) return { spdKm, gpsKm, coveredSec };
  for (let i = 1; i < samples.length; i++) {
    const a = samples[i - 1], b = samples[i];
    const dt = (b.t || 0) - (a.t || 0);
    if (dt > 0 && dt <= 5) { spdKm += ((a.spd || 0) + (b.spd || 0)) / 2 / 3600 * dt; coveredSec += dt; }
    if (a.lat && a.lng && b.lat && b.lng) {
      // Salto impossível não é distância percorrida — ignora no total.
      if (_isTeleport(a, b)) continue;
      gpsKm += _kmBetween(a, b);
    }
  }
  return { spdKm, gpsKm, coveredSec };
}

// Score de condução (0-100): combina economia (energia-equiv/100km) com suavidade
// (poucas acelerações/frenagens bruscas, detectadas pela variação de velocidade).
// Energia atribuível ao RELEVO da viagem (kWh): subir custa, descer recupera.
// Mesmas constantes do estimador de leg (≈0,0064 kWh/m subindo, recuperação
// ≈0,0035 kWh/m descendo) — calibradas pro relevo de Goiânia.
function terrainKwh(t) {
  return (+t.elevGainM || 0) * 0.0064 - (+t.elevLossM || 0) * 0.0035;
}
// (A) energy-eq/100km CORRIGIDO por relevo: tira o custo/ganho de altitude pra
// nota refletir condução, não se o trajeto é mais de subida ou descida.
function adjEnergyEq(t) {
  const distKm = +t.distKm || 0;
  if (distKm < 1) return null;
  const eqKwh = (+t.netKwh || 0) + (+t.fuelL || 0) * 8.9 - terrainKwh(t);
  return eqKwh / distKm * 100;
}
// (B) baseline auto-relativo por trajeto+sentido: mediana do energy-eq corrigido
// (A) das viagens ANTERIORES no mesmo sentido (origem≈ e destino≈ até ~180m).
// Quando há histórico (≥3), a nota mede "conduziu bem PRA ESTE trajeto" em vez de
// economia absoluta — subida e descida do mesmo par viram notas próximas.
function routeEqBaseline(t) {
  if (t.startLat == null || t.endLat == null) return null;
  const near = (aLat, aLng, bLat, bLng) => {
    if (bLat == null || bLng == null) return false;
    const dLat = (aLat - bLat) * 111320;
    const dLng = (aLng - bLng) * 111320 * Math.cos(aLat * Math.PI / 180);
    return Math.hypot(dLat, dLng) <= 180;
  };
  const id = String(t.startMs || t.tripId || '').replace(/\D/g, '');
  const eqs = [];
  for (const o of autoTripsArr) {
    const oid = String(o.startMs || o.tripId || '').replace(/\D/g, '');
    if (oid && oid === id) continue;     // não se compara consigo mesmo
    if (!near(t.startLat, t.startLng, o.startLat, o.startLng)) continue;
    if (!near(t.endLat,   t.endLng,   o.endLat,   o.endLng))   continue;
    const e = adjEnergyEq(o);
    if (e != null) eqs.push(e);
  }
  if (eqs.length < 3) return null;
  eqs.sort((a, b) => a - b);
  const m = Math.floor(eqs.length / 2);
  return eqs.length % 2 ? eqs[m] : (eqs[m - 1] + eqs[m]) / 2;
}

// Nota de condução: economia 50% + suavidade 35% + disciplina de velocidade 15%.
// A economia é corrigida por relevo (A) e, quando há histórico do trajeto,
// misturada com a economia relativa ao usual dele (B). Suavidade e velocidade
// são neutras a relevo — medem a FORMA de conduzir.
function computeDriveScore(samples, t) {
  const distKm = +t.distKm || 0;
  // (A) economia corrigida por relevo
  const eqAdj = adjEnergyEq(t);
  let econ = eqAdj != null ? Math.max(0, Math.min(100, 100 - (eqAdj - 13) * (70 / 13))) : 70;
  // (B) com histórico do trajeto, mistura 50/50 a economia relativa (bater o
  // usual do trajeto ≈ 85). Sem histórico (≥3), fica só o absoluto corrigido.
  if (eqAdj != null) {
    const base = routeEqBaseline(t);
    if (base != null) {
      const rel = Math.max(0, Math.min(100, 85 - (eqAdj - base) * (70 / 13)));
      econ = 0.5 * econ + 0.5 * rel;
    }
  }
  // suavidade (eventos bruscos/km) + (C) disciplina de velocidade (fração do
  // tempo em movimento acima de ~115 km/h — escolha do condutor, não relevo).
  let ha = 0, hb = 0, moving = 0, over = 0;
  if (Array.isArray(samples)) {
    for (let i = 0; i < samples.length; i++) {
      const spd = samples[i].spd || 0;
      if (spd > 5) { moving++; if (spd > 115) over++; }
      if (i === 0) continue;
      const dt = (samples[i].t || 0) - (samples[i - 1].t || 0);
      if (dt <= 0 || dt > 5) continue;
      const a = (spd - (samples[i - 1].spd || 0)) / dt;  // km/h por s
      if (a > 9) ha++; else if (a < -11) hb++;     // ~2,5 / 3,0 m/s²
    }
  }
  const perKm = distKm > 0.5 ? (ha + hb) / distKm : 0;
  const smooth = Math.max(0, 100 - perKm * 18);    // cada evento brusco/km tira ~18 pts
  const speed = moving >= 10 ? Math.max(0, 100 - (over / moving) * 200) : 100;
  const score = Math.max(0, Math.min(100, Math.round(0.50 * econ + 0.35 * smooth + 0.15 * speed)));
  return { score, harshAcc: ha, harshBrake: hb };
}

// Ingest de um auto-trip. Compartilhado entre o POST HTTP /api/autotrips e o
// handler MQTT autotrips/history (sync resiliente que não depende do Funnel).
// Retorna { status, body }. `opts.suppressPush` evita o push "Viagem concluída"
// (usado no backlog republicado por MQTT pra não spammar).
/// Preenche o começo de uma viagem que o APK não gravou, usando o histórico de
/// localização do celular do dono.
///
/// Existe porque em 01/08 o APK ficou fora do ar das 19:35 às 23:06 e só abriu a
/// viagem 9 min depois do carro ligar: o trajeto de volta apareceu com 1,7 km em vez
/// de ~7 km, e "zerou" na cara do dono quando o app voltou. O celular estava junto e
/// tinha o caminho inteiro — a informação existia, só não era usada.
///
/// Conservador de propósito: só age quando há prova de que o carro ANDOU antes da
/// viagem começar, e sempre marca o resultado como estimado. Devolve true se mexeu.
function _completaInicioComCelular(autoTrip, samples, tripId) {
  try {
    // Âncora: o motor ligando OU a janela em que o CAN ficou mudo com o carro
    // andando — o que for MAIS ANTIGO. O reinício da multimídia reescreve o
    // `_engine_on_ms` no meio do trajeto perdido, e só com ele o trecho nunca era
    // recuperado (22/09).
    const mudoMs = +state._can_mudo_desde_ms || 0;
    const mudoVale = mudoMs > 0 && autoTrip && autoTrip.startMs > mudoMs
      && (autoTrip.startMs - mudoMs) < 3 * 3600_000;
    const ligouMs = mudoVale
      ? Math.min(+state._engine_on_ms || Infinity, mudoMs)
      : (+state._engine_on_ms || 0);
    if (!ligouMs || !Number.isFinite(ligouMs) || !autoTrip || !autoTrip.startMs) return false;
    const atraso = autoTrip.startMs - ligouMs;
    // < 3 min é a partida normal (APK leva alguns segundos pra abrir a trip).
    // > 3 h não é "o mesmo trajeto": provavelmente o motor ficou marcado ligado.
    if (atraso < 3 * 60_000 || atraso > 3 * 3600_000) return false;
    const dev = _havalOwnerDeviceId;
    if (!dev) return false;

    const pts = _phoneHistRead(dev, ligouMs - 60_000, autoTrip.startMs)
      .filter(p => _validLatLng(p.lat, p.lng))
      .sort((a, b) => a.ts - b.ts);
    if (pts.length < 2) return false;

    // O celular precisa provar deslocamento: se ele ficou parado onde a viagem
    // começou, não havia trecho perdido — o carro é que demorou a ligar.
    const desloc = haversineM(pts[0].lat, pts[0].lng, autoTrip.startLat, autoTrip.startLng);
    // ...E precisa ser PLAUSÍVEL. Só o piso de 300 m deixava passar telefone a
    // centenas de km: esta função pressupõe o celular DENTRO do carro, e quando o dono
    // viaja separado (ou outra pessoa dirige) a premissa cai. Em 02/09 o celular estava
    // em Barra do Garças e o carro rodou só dentro de Goiânia — as 5 amostras do
    // telefone viraram uma reta de 366 km numa viagem local, com velocidade máxima
    // registrada de 67 km/h denunciando a impossibilidade.
    //
    // Teto = o que o carro conseguiria cobrir no atraso a 120 km/h, limitado a 50 km.
    // Acima disso não é trecho perdido, é celular em outro lugar.
    const tetoM = Math.min(120 * (atraso / 3600_000) * 1000, 50_000);
    if (!(desloc > 300 && desloc <= tetoM)) {
      if (desloc > tetoM) {
        console.warn(`[trip-inicio] celular a ${(desloc / 1000).toFixed(1)}km do início da `
          + `viagem (teto ${(tetoM / 1000).toFixed(1)}km em ${Math.round(atraso / 60000)}min) `
          + `— não estava no carro, início NÃO completado`);
      }
      return false;
    }

    const novoStart = pts[0].ts;
    const off = Math.round((autoTrip.startMs - novoStart) / 1000);
    // Só posição e tempo. spd/rpm/potência ficam zerados: inventar telemetria que
    // ninguém mediu contaminaria consumo, nota de condução e split EV/HEV.
    const pref = pts.map(p => ({
      t: Math.round((p.ts - novoStart) / 1000),
      lat: p.lat, lng: p.lng, spd: 0, rpm: 0, evKw: 0, pwr: 0,
      soc: autoTrip.startSocPct || 0, src: 'phone',
    }));
    for (const sm of samples) sm.t = (sm.t || 0) + off;
    samples.unshift(...pref);

    let extraM = 0;
    for (let i = 1; i < pts.length; i++) {
      extraM += haversineM(pts[i-1].lat, pts[i-1].lng, pts[i].lat, pts[i].lng);
    }
    extraM += haversineM(pts[pts.length-1].lat, pts[pts.length-1].lng, autoTrip.startLat, autoTrip.startLng);

    // Consumida: não pode valer pra próxima viagem.
    state._can_mudo_desde_ms = 0; scheduleStateSave();
    autoTrip.startMs  = novoStart;
    autoTrip.startLat = pts[0].lat;
    autoTrip.startLng = pts[0].lng;
    autoTrip.timeSec  = Math.round((autoTrip.endMs - novoStart) / 1000);
    // Piso, não valor exato: com ~1 ponto/min a linha reta corta as curvas.
    autoTrip.distKm   = parseFloat(((autoTrip.distKm || 0) + extraM / 1000).toFixed(3));
    // Energia: o APK só mediu o pedaço que gravou, então o consumo sairia ridículo
    // (0,3 kWh pra 6,8 km). O ΔSOC cobre a viagem inteira — usa a viagem anterior
    // como âncora do SOC inicial, já que o carro ficou parado entre as duas.
    const camposEstimados = ['startMs', 'startLat', 'startLng', 'distKm', 'timeSec'];
    const ant = autoTripsArr
      .filter(t => t.endMs && t.endMs <= novoStart && t.endSocPct > 0)
      .sort((a, b) => b.endMs - a.endMs)[0];
    if (ant && ant.endSocPct > (autoTrip.endSocPct || 0)) {
      const cap = _capacityKwh();
      const net = +(cap * (ant.endSocPct - autoTrip.endSocPct) / 100).toFixed(4);
      if (net > 0 && net < 40) {
        autoTrip.startSocPct = ant.endSocPct;
        autoTrip.netKwh    = net;
        // Piso: a regeneração do trecho perdido também não foi medida.
        autoTrip.energyKwh = +(net + (autoTrip.regenKwh || 0)).toFixed(4);
        camposEstimados.push('startSocPct', 'netKwh', 'energyKwh');
      }
    }
    autoTrip._estimated = true;
    autoTrip._estimatedFields = camposEstimados;
    autoTrip._estimatedReason =
      `APK não gravou os primeiros ${Math.round(atraso/60_000)}min; trecho reconstituído `
      + `de ${pts.length} pontos do celular (~1/min) — distância é piso`;
    console.log(`[autotrip] ${tripId}: início reconstituído do celular `
      + `(+${(extraM/1000).toFixed(2)}km, ${pts.length} pontos, APK atrasou ${Math.round(atraso/60_000)}min)`);
    return true;
  } catch (e) {
    console.warn('[autotrip] reconstituição do início falhou:', e.message);
    return false;
  }
}

function ingestAutoTrip({ tripId, autoTrip, samples }, opts = {}) {
  const suppressPush = !!opts.suppressPush;
  // Motivo de estimativa quando a viagem é FINALIZADA pelo bridge (APK morreu no
  // meio e nunca postou o autotrip final). Marca _estimated pra UI, SEM gravar
  // _estimatedValues (sticky) — se o APK ressuscitar e re-postar o dado real, ele
  // vence normalmente em vez de ficar preso na estimativa do bridge.
  const estimatedReason = opts.estimatedReason || null;
  {
    if (!tripId || !autoTrip) return { status: 400, body: { error: 'missing fields' } };

    // Sanitiza tripId (só dígitos — é o startMs em ms)
    const safeId = String(tripId).replace(/\D/g, '');
    if (!safeId) return { status: 400, body: { error: 'invalid tripId' } };

    // Bloqueia viagens explicitamente deletadas pelo usuário (tombstone)
    if (isDeleted('autotrips', safeId)) {
      console.log(`↷ AutoTrip ${safeId} bloqueada (tombstoned)`);
      return { status: 200, body: { ok: true, skipped: true, reason: 'tombstoned' } };
    }

    // Descarta viagens irrelevantes: energia E distância zeradas com menos de 1 min
    const _distKm  = autoTrip.distKm  || 0;
    const _netKwh  = autoTrip.netKwh  || 0;
    const _timeSec = autoTrip.timeSec || 0;
    if (_distKm <= 0 && _netKwh < 0.10 && _timeSec < 60) {
      console.log(`↷ AutoTrip ${safeId} ignorado (dist=0 energy=0 time=${_timeSec}s)`);
      return { status: 200, body: { ok: true, skipped: true } };
    }

    const filePath = path.join(AUTOTRIPS_DIR, `${safeId}.json`);

    // Merge de samples com o que já existe no arquivo. Resolve o caso clássico
    // de RESUME no APK em que os samples antigos foram deletados localmente
    // pós-sync (linha 1258 do TripManager.kt) — o POST do resume só traz os
    // samples do trecho NOVO. Sem este merge, a rota visual + startLat/Lng do
    // primeiro trecho desaparecem da viagem combinada.
    //
    // Estratégia: deduplica por `t` arredondado (offset em segundos relativo
    // a startMs). Em conflito, prefere o sample NOVO (mais fresco). Os samples
    // antigos sobrevivem nos `t` que o novo POST não cobre.
    let existingSamples = [], existingWasLive = false;
    if (fs.existsSync(filePath)) {
      try {
        const existing = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        existingSamples = existing.samples || [];
        existingWasLive = !!existing._liveSamples;
      } catch (_) {}
    }

    // Limpa saltos impossíveis ANTES de qualquer decisão de merge. Um trecho
    // podre inflava a distância integrada, e era justamente essa distância que a
    // heurística de merge usava pra escolher entre concatenar e substituir —
    // decidia com o número errado (27/07: 278 samples somando 5.703 km).
    {
      const a = _dropTeleports(existingSamples);
      if (a.dropped) {
        console.warn(`⚠ AutoTrip ${safeId}: ${a.dropped} sample(s) existentes descartados por salto impossível (>${MAX_IMPLIED_KMH} km/h implícitos)`);
        existingSamples = a.clean;
      }
      const b = _dropTeleports(samples || []);
      if (b.dropped) {
        console.warn(`⚠ AutoTrip ${safeId}: ${b.dropped} sample(s) do POST descartados por salto impossível`);
        samples = b.clean;
      }
    }

    const newSamples = samples || [];
    let finalSamples = newSamples;
    let didMerge = false;

    if (existingSamples.length > 0) {
      if (newSamples.length === 0) {
        // POST sem samples (sync metadata-only) — preserva existentes
        finalSamples = existingSamples;
      } else if (newSamples.length > existingSamples.length
                 && _isContainedIn(existingSamples, newSamples)) {
        // O POST traz a viagem inteira e os existentes são um pedaço dela
        // (típico: bridge só gravou live nos minutos em que teve GPS). Concatenar
        // duplicaria esse pedaço e inflaria distKm — substitui.
        finalSamples = newSamples;
        console.log(`↻ AutoTrip ${safeId}: ${existingSamples.length} live samples já contidos na rota do POST (${newSamples.length}) — substituídos`);
      } else {
        // Atenção: `t` é em segundos (offset de startMs) e múltiplos samples no
        // mesmo segundo são comuns (tick de 500ms). Dedupe por t inteiro colapsa
        // samples legítimos. Estratégia: comparar os RANGES de `t` dos dois sets.
        //   - Disjuntos (typical resume): concatena e ordena
        //   - Overlap: assume que os existentes cobrem a parte mais antiga e os
        //     novos a mais recente; corta no maxExistingT
        const maxExistingT = existingSamples.reduce((m, s) => Math.max(m, s.t || 0), 0);
        const minNewT      = newSamples.reduce((m, s) => Math.min(m, s.t || 0), Infinity);
        if (existingWasLive) {
          // Existentes vieram do buffer LIVE do bridge (mesma viagem, mesma janela
          // de tempo) — os samples do APK são a versão autoritativa. Re-basear e
          // concatenar aqui era o bug que dobrava/triplicava o trajeto no app.
          // Mantém só a cabeça live anterior ao 1º sample do APK (origem real).
          const liveHead = existingSamples.filter(s => (s.t || 0) < minNewT);
          finalSamples = [...liveHead, ...newSamples];
          console.log(`↻ AutoTrip ${safeId}: samples live (${existingSamples.length}) substituídos pelos do APK (${newSamples.length}, head=${liveHead.length})`);
        } else if (minNewT > maxExistingT) {
          // Ranges disjuntos — apenas concatena
          finalSamples = [...existingSamples, ...newSamples];
        } else if (_isDuplicateTail(existingSamples, newSamples)) {
          // Re-POST do mesmo trecho (retry de rede): o trecho novo já está no fim
          // dos existentes. Mantém como está pra não duplicar.
          finalSamples = existingSamples;
        } else {
          // Overlap de `t` SEM ser duplicata = RESUME em que o APK re-baseou o `t`
          // do segundo trecho (começa perto de 0 de novo). Se a gente cortasse em
          // maxExistingT, TODO o segundo trecho sumiria do trajeto (era o bug: km e
          // tempo vinham completos do autoTrip, mas a rota só mostrava o 1º trecho).
          // Correção: re-baseia o `t` do trecho novo pra continuar DEPOIS do
          // existente, preservando o espaçamento interno, e concatena.
          const offset = maxExistingT + 1 - minNewT;
          const rebased = newSamples.map(s => ({ ...s, t: (s.t || 0) + offset }));
          const candidate = [...existingSamples, ...rebased];
          // Sanidade: resume legítimo cobre geografia NOVA e a distância integrada
          // do merge ≈ distKm da viagem. Se estourar (>1.4× + 2km), é re-POST do
          // mesmo trecho (retry/sync) — concatenar duplicaria a rota.
          const repKm = +autoTrip.distKm || 0;
          const { spdKm: candKm } = _sampleDistKm(candidate);
          if (repKm > 1 && candKm > repKm * 1.4 + 2) {
            finalSamples = newSamples;
            console.log(`↻ AutoTrip ${safeId}: merge rejeitado (integraria ${candKm.toFixed(1)}km vs ${repKm.toFixed(1)}km reais) — mantém samples do POST`);
          } else {
            finalSamples = candidate;
            console.log(`↻ AutoTrip ${safeId}: resume detectado (t re-baseado +${offset}s) — 2º trecho preservado`);
          }
        }
        if (finalSamples.length > newSamples.length) {
          didMerge = true;
          const preserved = finalSamples.length - newSamples.length;
          console.log(`↻ AutoTrip ${safeId}: merge — ${existingSamples.length} existentes + ${newSamples.length} novos = ${finalSamples.length} (${preserved} antigos preservados)`);
        }
      }
    }

    // Se o merge preservou samples antigos, recalcula start/end com o primeiro
    // e último ponto com GPS válido — corrige o startLat/Lng que o APK enviou
    // baseado só nos samples do trecho novo (pode estar no meio da viagem real).
    if (didMerge) {
      const firstGps = finalSamples.find(s => s.lat && s.lat !== 0);
      const lastGps  = [...finalSamples].reverse().find(s => s.lat && s.lat !== 0);
      if (firstGps && (firstGps.lat !== autoTrip.startLat || firstGps.lng !== autoTrip.startLng)) {
        // Mesmo teto da âncora: num merge de resume o primeiro sample da lista
        // pode ser de outro trecho. Refinar sim, teletransportar não.
        const jumpM = (+autoTrip.startLat && +autoTrip.startLng)
          ? haversineM(firstGps.lat, firstGps.lng, +autoTrip.startLat, +autoTrip.startLng)
          : 0;
        if (jumpM > START_FIX_MAX_M) {
          console.warn(`⚠ AutoTrip ${safeId}: 1º sample ${firstGps.lat.toFixed(5)},${firstGps.lng.toFixed(5)} ignorado como start — Δ${Math.round(jumpM)}m (>${START_FIX_MAX_M}m)`);
        } else {
          console.log(`↻ AutoTrip ${safeId}: startLat ${(+autoTrip.startLat||0).toFixed(5)},${(+autoTrip.startLng||0).toFixed(5)} → ${firstGps.lat.toFixed(5)},${firstGps.lng.toFixed(5)}`);
          autoTrip.startLat = firstGps.lat;
          autoTrip.startLng = firstGps.lng;
        }
      }
      if (lastGps && (lastGps.lat !== autoTrip.endLat || lastGps.lng !== autoTrip.endLng)) {
        autoTrip.endLat = lastGps.lat;
        autoTrip.endLng = lastGps.lng;
      }
    }

    // Âncora: se temos snapshot do GPS no INSTANTE da ignição (via current_trip),
    // e ele diverge >200m do que ficou em startLat/Lng, usa o snapshot — cobre o
    // caso em que o APK perdeu GPS nos primeiros minutos e o "primeiro sample"
    // ficou no meio da rota.
    //
    // Teto de plausibilidade: a âncora vem de arquivo já existente da trip e num
    // resume pode ser de OUTRO trecho. Em 27/07 isso jogou a origem de Casa pra
    // Santa Genoveva (Δ10.589m) por cima de um startLat que o APK mandou certo.
    // Acima de START_FIX_MAX_M a "correção" não é refino, é troca de viagem.
    try {
      const existingFile = fs.existsSync(filePath) ? JSON.parse(fs.readFileSync(filePath, 'utf8')) : null;
      const anchor = existingFile && existingFile.actualStart;
      const apkHasStart = !!(+autoTrip.startLat && +autoTrip.startLng);
      if (anchor && anchor.lat && anchor.lng) {
        const distM = haversineM(anchor.lat, anchor.lng,
                                 +autoTrip.startLat || 0, +autoTrip.startLng || 0);
        if (apkHasStart && distM > START_FIX_MAX_M) {
          console.warn(`⚠ AutoTrip ${safeId}: âncora ${anchor.lat.toFixed(5)},${anchor.lng.toFixed(5)} ignorada — Δ${Math.round(distM)}m do start do APK (>${START_FIX_MAX_M}m, provável trecho de outra viagem)`);
        } else if (distM > 200) {
          console.log(`↻ AutoTrip ${safeId}: âncora do start ${anchor.lat.toFixed(5)},${anchor.lng.toFixed(5)} substitui ${(+autoTrip.startLat||0).toFixed(5)},${(+autoTrip.startLng||0).toFixed(5)} (Δ${Math.round(distM)}m)`);
          autoTrip.startLat = anchor.lat;
          autoTrip.startLng = anchor.lng;
          // Prepende um sample sintético em t=0 pra fechar o polyline.
          if (finalSamples.length && finalSamples[0].t > 0) {
            finalSamples.unshift({ t: 0, lat: anchor.lat, lng: anchor.lng, spd: 0, rpm: 0, pwr: 0, soc: finalSamples[0].soc || 0 });
          }
        }
      }
    } catch (e) { console.warn('[ingest] anchor check falhou:', e.message); }

    // Blindagem do distKm: o hodômetro do APK re-baseia no meio da viagem e
    // ora INFLA (soma o acumulado do dia: 5km vira 38km) ora SUBCONTA (perde um
    // trecho num gap de telemetria: 27km vira 23km). Em ambos o tempo/energia
    // ficam certos, só a distância erra. Quando os samples são CONFIÁVEIS (densos
    // e spd↔gps concordando) eles batem com a realidade (o scrubber do app usa a
    // mesma integração) → reconcilia o distKm pra eles, nos dois sentidos.
    {
      const rep = +autoTrip.distKm || 0;
      const tSec = +autoTrip.timeSec || 0;
      const { spdKm, gpsKm, coveredSec } = _sampleDistKm(finalSamples);
      const sampleKm = Math.max(spdKm, gpsKm);
      const avgKmh = tSec >= 60 ? rep / (tSec / 3600) : 0;
      // Telemetria confiável: a integração de velocidade cobre ~toda a duração
      // (sem gaps grandes) e spd/gps concordam (mesma ordem de grandeza). Exclui
      // o caso Palmeiras (gps 2× spd, cobertura furada por timestamps sujos), onde
      // os samples subcontam um trecho e NÃO podem ditar a distância.
      const covRatio = tSec >= 60 ? coveredSec / tSec : 0;
      const agree = spdKm > 0.5 && gpsKm > 0.5 && Math.min(spdKm, gpsKm) / Math.max(spdKm, gpsKm) >= 0.75;
      const dense = covRatio >= 0.85 && covRatio <= 1.5;
      const reliableKm = (spdKm + gpsKm) / 2;
      // Sinal do bug clássico (só infla): média fisicamente impossível, mesmo sem
      // samples confiáveis. Corrige pro piso de samples (não-zero).
      const implausible = (avgKmh > 130) || (avgKmh > 90 && sampleKm > 0.5 && rep > sampleKm * 1.8 + 3);
      // Carro PARADO ligado: o hodômetro do APK re-baseia e copia o
      // avg_vehicle_speed_since_startup como se fosse km (bug do trip
      // "Limpa Gyn→Limpa Gyn 35,90km / 0,13kWh"). Assinatura: dist reportada
      // mas SEM movimento real (samples ~0) E energia desprezível pro tanto de
      // km (um EV a 35km gastaria ~6kWh; 0,13kWh => não andou). Fisicamente
      // impossível → zera pros samples (≈0).
      const eqKwh = (+autoTrip.netKwh || 0) + (+autoTrip.fuelL || 0) * 8.9;
      const parkedPhantom = rep > 1 && sampleKm < 0.3 && eqKwh < rep * 0.02;
      if (parkedPhantom) {
        // Não é viagem: carro ligado parado. Descarta (tombstone + remove arquivo)
        // pra não poluir totais nem deixar card residual; reprocess limpa o legado.
        console.log(`↷ AutoTrip ${safeId} descartado: fantasma de carro parado ${rep.toFixed(1)}km (eq=${eqKwh.toFixed(2)}kWh sampleKm=${sampleKm.toFixed(2)})`);
        markDeleted('autotrips', safeId);
        try { fs.unlinkSync(filePath); } catch (_) {}
        const _i = autoTripsArr.findIndex(t => t.tripId === safeId || String(t.startMs) === safeId);
        if (_i >= 0) autoTripsArr.splice(_i, 1);
        return { status: 200, body: { ok: true, skipped: true, reason: 'parked_phantom' } };
      }
      if (dense && agree && tSec >= 60) {
        // Reconciliação bidirecional: diverge >12% (e >2km) → manda nos samples.
        if (Math.abs(rep - reliableKm) > Math.max(2, reliableKm * 0.12)) {
          const fixed = parseFloat(reliableKm.toFixed(3));
          console.log(`⚠ AutoTrip ${safeId}: distKm reconciliado ${rep.toFixed(1)}km → ${fixed}km (samples densos spd=${spdKm.toFixed(2)} gps=${gpsKm.toFixed(2)} cov=${covRatio.toFixed(2)})`);
          autoTrip.distKm = fixed;
        }
      } else if (implausible && sampleKm > 0.5) {
        const fixed = parseFloat(sampleKm.toFixed(3));
        console.log(`⚠ AutoTrip ${safeId}: distKm implausível ${rep.toFixed(1)}km (avg ${avgKmh.toFixed(0)}km/h, ${tSec}s) → ${fixed}km (spd=${spdKm.toFixed(2)} gps=${gpsKm.toFixed(2)})`);
        autoTrip.distKm = fixed;
      }
    }

    // Invariante: net = energy − regen SEMPRE. O APK antigo clampava net≥0,
    // escondendo o ganho quando a bateria foi recarregada pelo motor térmico
    // (HEV) — net negativo = ganho líquido, credita no custo. Recompõe aqui pra
    // ser imune à versão do APK; o estimated logo abaixo ainda pode sobrescrever.
    if (autoTrip.energyKwh != null && autoTrip.regenKwh != null) {
      autoTrip.netKwh = (+autoTrip.energyKwh || 0) - (+autoTrip.regenKwh || 0);
    }
    if (Array.isArray(autoTrip.segments)) {
      for (const s of autoTrip.segments) {
        if (s.energyKwh != null && s.regenKwh != null) {
          s.netKwh = (+s.energyKwh || 0) - (+s.regenKwh || 0);
        }
      }
    }

    // Calcula tempo e distância em modo híbrido (ICE ligado, rpm > 0).
    // Se o arquivo existente foi marcado como _estimated (telemetria parou no
    // meio da viagem e os hybrid foram inferidos por média histórica), PRESERVA
    // a estimativa em vez de recalcular dos samples (que dariam 0 ou subestimaria).
    let existingEstimated = null;
    if (fs.existsSync(filePath)) {
      try {
        const ex = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        if (ex._estimated) {
          existingEstimated = {
            hybridTimeSec:        ex.hybridTimeSec,
            hybridDistKm:         ex.hybridDistKm,
            _estimated:           true,
            _estimatedFields:     ex._estimatedFields  || ['hybridDistKm','hybridTimeSec'],
            _estimatedReason:     ex._estimatedReason  || '',
            _estimatedAppliedAt:  ex._estimatedAppliedAt || '',
            // Valores corrigidos por viagem (distKm/netKwh/fuelL/etc). Sem isso o
            // re-POST do APK revertia a estimativa pro dado parcial cru (bug do
            // trip Palmeiras→Limpa Gyn 25/05 que voltava pra 6,8km de ~84km).
            _estimatedValues:     ex._estimatedValues || null,
          };
        }
      } catch (_) {}
    }

    // Re-aplica os valores estimados (sticky) por cima do que o APK mandou cru.
    // O autoTrip do APK sempre traz a telemetria parcial; a correção mora só aqui.
    if (existingEstimated && existingEstimated._estimatedValues) {
      for (const [k, v] of Object.entries(existingEstimated._estimatedValues)) {
        if (v != null) autoTrip[k] = v;
      }
    }

    let hybridTimeSec, hybridDistKm;
    if (existingEstimated && existingEstimated.hybridTimeSec != null && existingEstimated.hybridDistKm != null) {
      hybridTimeSec = existingEstimated.hybridTimeSec;
      hybridDistKm  = existingEstimated.hybridDistKm;
      console.log(`↻ AutoTrip ${safeId}: hybrid preservado (estimado): ${hybridDistKm}km / ${hybridTimeSec}s`);
    } else {
      hybridTimeSec = 0;
      hybridDistKm  = 0;
      for (let i = 1; i < finalSamples.length; i++) {
        const a = finalSamples[i - 1], b = finalSamples[i];
        const dt = (b.t || 0) - (a.t || 0);
        if (dt > 0 && dt < 30 && (a.rpm || 0) > 50) {
          hybridTimeSec += dt;
          hybridDistKm  += ((a.spd || 0) + (b.spd || 0)) / 2 / 3600 * dt;
        }
      }
      hybridTimeSec = Math.round(hybridTimeSec);
      hybridDistKm  = parseFloat(hybridDistKm.toFixed(3));
    }

    // Score de condução (economia + suavidade) — grava no autoTrip pra fluir pra
    // todos os caminhos (persist, record, push, reprocess).
    {
      const drive = computeDriveScore(finalSamples, autoTrip);
      autoTrip.driveScore = drive.score;
      autoTrip.harshAcc = drive.harshAcc;
      autoTrip.harshBrake = drive.harshBrake;
      const ot = +state.outside_temp;   // temperatura externa no fim da viagem (proxy do ambiente)
      if (ot) autoTrip.outsideTemp = Math.round(ot * 10) / 10;
    }

    // Trip que começou DEPOIS do motor ligar: o APK esteve fora no início e o
    // trecho não foi gravado por ninguém. Roda ANTES do naming, pra a partida
    // reconstituída também ganhar nome.
    _completaInicioComCelular(autoTrip, finalSamples, safeId);

    // Auto-naming por Locais Conhecidos (KP) — grava em autoTrip.startKp/endKp pra
    // SOBREVIVER restart do bridge (o disco persiste só `autoTrip`, não o `record`).
    {
      // Nomes já gravados no arquivo (reprocess-places / geocode de cidade fora de
      // KP). O APK não manda startKp/endKp, então sem este fallback o re-POST
      // zerava a ponta sem KP (bug do trip Palmeiras→Limpa Gyn: cidade de origem
      // não é Local Conhecido, voltava "sem nome" a cada sync do APK).
      let prevStartKp = null, prevEndKp = null;
      if (fs.existsSync(filePath)) {
        try {
          const ex = JSON.parse(fs.readFileSync(filePath, 'utf8'));
          prevStartKp = ex.autoTrip?.startKp || null;
          prevEndKp   = ex.autoTrip?.endKp   || null;
        } catch (_) {}
      }
      const _sp = matchKnownPlace(autoTrip.startLat, autoTrip.startLng, 80);
      const _ep = matchKnownPlace(autoTrip.endLat,   autoTrip.endLng, 80);
      if (_sp) autoTrip.startKp = _sp.name;
      if (_ep) autoTrip.endKp   = _ep.name;
      // Fim sem KP mas com destino mandado pro carro recentemente → usa o nome digitado.
      if (!_ep) {
        const navName = _navDestNameFor(autoTrip.endLat, autoTrip.endLng);
        if (navName) autoTrip.endKp = navName;
      }
      // Partida sem KP: se o carro não saiu do lugar desde a viagem anterior, herda o
      // nome de onde ela terminou. Vem antes do prev* porque é mais específico —
      // prevStartKp pode ser justamente o bairro que queremos evitar.
      if (!autoTrip.startKp) {
        const herdado = _nomeDaChegadaAnterior(autoTrip.startLat, autoTrip.startLng, autoTrip.startMs);
        if (herdado) autoTrip.startKp = herdado;
      }
      // Preserva o nome reprocessado quando não há KP/nav pra essa ponta.
      if (!autoTrip.startKp && prevStartKp) autoTrip.startKp = prevStartKp;
      if (!autoTrip.endKp   && prevEndKp)   autoTrip.endKp   = prevEndKp;
      if (autoTrip.startKp && autoTrip.endKp && !autoTrip.name) {
        autoTrip.name = `${autoTrip.startKp} → ${autoTrip.endKp}`;
      }
    }

    // Watermark de ingest (relógio do SERVIDOR): viagem que chega atrasada
    // (fallback MQTT horas depois) tem startMs antigo — sem isto, o sync
    // incremental dos apps (?since=) nunca a veria.
    autoTrip._updated_ms = Date.now();
    // Persiste hybrid junto — boot não precisa recalcular.
    // Se foi estimado, marca o arquivo também com os campos _estimated*.
    const persisted = {
      tripId: safeId, autoTrip, samples: finalSamples, hybridTimeSec, hybridDistKm,
    };
    if (existingEstimated) {
      persisted._estimated          = true;
      persisted._estimatedFields    = existingEstimated._estimatedFields;
      persisted._estimatedReason    = existingEstimated._estimatedReason;
      persisted._estimatedAppliedAt = existingEstimated._estimatedAppliedAt;
      persisted._estimatedValues    = existingEstimated._estimatedValues;
    } else if (estimatedReason) {
      persisted._estimated          = true;
      persisted._estimatedFields    = [];
      persisted._estimatedReason    = estimatedReason;
      persisted._estimatedAppliedAt = new Date().toISOString();
    }
    atomicWriteFileSync(filePath, JSON.stringify(persisted));

    const record = { tripId: safeId, ...autoTrip, hybridTimeSec, hybridDistKm };
    if (existingEstimated) {
      record._estimated       = true;
      record._estimatedFields = existingEstimated._estimatedFields;
      record._estimatedReason = existingEstimated._estimatedReason;
    } else if (estimatedReason) {
      record._estimated       = true;
      record._estimatedFields = [];
      record._estimatedReason = estimatedReason;
    }

    // Auto-naming por Locais Conhecidos
    const _sp = matchKnownPlace(autoTrip.startLat, autoTrip.startLng, 80);
    const _ep = matchKnownPlace(autoTrip.endLat,   autoTrip.endLng, 80);
    if (_sp) record.knownStart = _sp.name;
    if (_ep) record.knownEnd   = _ep.name;
    // Fim NÃO é um local salvo, mas você compartilhou esse destino pelo Waze/Maps →
    // usa o nome digitado (ex.: "Shopping Flamboyant") no lugar do bairro+cidade.
    let _endName = _ep ? _ep.name : null;
    if (!_ep) {
      const navName = _navDestNameFor(autoTrip.endLat, autoTrip.endLng);
      if (navName) { record.endKp = navName; record.knownEnd = navName; _endName = navName; }
    }
    // Mesma herança do lado da partida (ver _nomeDaChegadaAnterior).
    let _startName = _sp ? _sp.name : null;
    if (!_startName) {
      const herdado = _nomeDaChegadaAnterior(autoTrip.startLat, autoTrip.startLng, autoTrip.startMs);
      if (herdado) { record.startKp = herdado; record.knownStart = herdado; _startName = herdado; }
    }
    if (_startName && _endName) {
      record.name = `${_startName} → ${_endName}`;
      pendingRenames.push({ id: `kp-${safeId}`, type: 'auto', tripId: safeId, name: record.name, createdAt: Date.now() });
      try { fs.writeFileSync(RENAMES_FILE, JSON.stringify(pendingRenames, null, 2)); } catch (_) {}
    }

    const idx = autoTripsArr.findIndex(t => t.tripId === safeId);
    if (idx >= 0) autoTripsArr[idx] = record;
    else {
      autoTripsArr.unshift(record);
      autoTripsArr.sort((a, b) => (b.startMs || 0) - (a.startMs || 0));
    }

    console.log(`✓ AutoTrip: ${safeId} (${(samples || []).length} amostras)`);
    // Notifica a PWA em tempo real — qualquer aba aberta recebe o evento imediatamente
    broadcast('new_autotrip', {
      tripId:  safeId,
      startMs: autoTrip.startMs || 0,
      distKm:  autoTrip.distKm  || 0,
    });
    addEvent('trip_end', `Viagem concluída: ${(autoTrip.distKm||0).toFixed(1)} km`);
    // Push: viagem concluída (só se >1 km OU >3 min). On/off por device.
    if (!suppressPush) {
      const distKm = autoTrip.distKm  || 0;
      const sec    = autoTrip.timeSec || 0;
      if (distKm > 1 || sec > 180) {
        const netKwh = autoTrip.netKwh || 0;
        const fuelL  = autoTrip.fuelL  || 0;
        const dist   = distKm.toFixed(1);
        const dur    = sec >= 3600
          ? `${Math.floor(sec / 3600)}h ${Math.floor((sec % 3600) / 60)}min`
          : `${Math.floor(sec / 60)}min`;
        const kwh100 = distKm > RAZAO_MIN_KM && netKwh > 0 ? (netKwh / distKm * 100).toFixed(1) : null;
        const kmL    = fuelL  > 0.01              ? (distKm / fuelL).toFixed(1)         : null;
        // Custo da viagem usa preços PONDERADOS pelo mix de combustível/recargas
        // do tanque/bateria, recalculados a cada refuel/charge. Sem isso, o
        // valor exibido ignorava se a recarga foi grátis ou se o tanque tinha
        // mix de preços diferentes.
        const pKwh = state.battery_avg_price_per_kwh || state.price_kwh || 0;
        const pGas = state.tank_avg_price_per_l      || state.price_gas_per_l || 0;
        const cost = (pGas > 0 || pKwh > 0) ? fuelL * pGas + netKwh * pKwh : 0;

        const dropSoc = (autoTrip.startSocPct || 0) - (autoTrip.endSocPct || 0);
        const drive = autoTrip.driveScore;   // score de condução (economia + suavidade)

        const parts = [`${dist} km`, dur];
        if (dropSoc > 0.5)  parts.push(`−${Math.round(dropSoc)}% bateria`);
        if (netKwh > 0.01)       parts.push(`${netKwh.toFixed(2)} kWh`);
        else if (netKwh < -0.01) parts.push(`+${(-netKwh).toFixed(2)} kWh recuperado`);
        if (kwh100)        parts.push(`${kwh100} kWh/100`);
        if (fuelL > 0.01)  parts.push(`${fuelL.toFixed(2)} L`);
        if (kmL)           parts.push(`${kmL} km/L`);
        if (cost  > 0.01)  parts.push(`R$ ${cost.toFixed(2)}`);
        if (drive != null) parts.push(`condução ${drive}`);

        sendPush('🏁 Viagem concluída', parts.join(' · '), 'trip_end');

        // #9: resumo narrado pela Lari (opt-in + km mínimo configuráveis no app).
        if (notifPrefs.trip_summary_narrated && distKm >= (notifPrefs.trip_summary_min_km || 0)) {
          notifyLariTripSummary({
            distKm, timeSec: sec, netKwh, fuelL, cost,
            kwh100: kwh100 ? +kwh100 : null,
            kmL: kmL ? +kmL : null,
            dropSocPct: dropSoc > 0.5 ? Math.round(dropSoc) : 0,
            driveScore: drive ?? null,
            destination: record.knownEnd || record.endKp || record.name || null,
            startMs: autoTrip.startMs || 0,
            endMs: autoTrip.endMs || Date.now(),
          });
        }
      }
    }
    return { status: 200, body: { ok: true } };
  }
}

app.post('/api/autotrips', (req, res) => {
  // DEBUG temporário: loga TODA tentativa pra rastrear viagens travadas no APK
  const ua = req.headers['user-agent'] || '?';
  const auth = req.headers['authorization'] ? 'OK' : 'FALTANDO';
  const tid = req.body?.tripId || 'sem tripId';
  console.log(`[autotrip] POST recebido · tripId=${tid} · auth=${auth} · ua=${ua.slice(0,40)} · ip=${req.ip}`);
  try {
    const r = ingestAutoTrip(req.body || {});
    res.status(r.status).json(r.body);
  } catch (e) {
    console.error('Erro ao salvar auto-trip:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ── Breadcrumb: APK morreu com viagem aberta ───────────────────────────────
// O APK reporta no boot seguinte que havia uma viagem aberta quando o processo
// morreu (OTA planejado, crash, force-stop, OOM). Guarda um NDJSON pra medir a
// frequência e o motivo dominante das mortes mid-trip. Fire-and-forget do APK.
const APK_DEATHS_FILE = path.join(DATA_DIR, 'apk_deaths.ndjson');
/// Mortes recentes em memória — usadas pra distinguir crash real de reconexão de
/// rede no detector de "loop". Ler o ndjson a cada tick do watchdog seria caro.
const _apkDeaths = [];
app.post('/api/apk-death', (req, res) => {
  try {
    const b = req.body || {};
    const rec = {
      at: new Date().toISOString(),
      tripId: String(b.tripId || ''),
      reason: String(b.reason || 'unknown').slice(0, 300),
      sessionEndedCleanly: !!b.sessionEndedCleanly,
      version: String(b.version || '?'),
      deviceTs: Number(b.ts) || null,
    };
    fs.appendFileSync(APK_DEATHS_FILE, JSON.stringify(rec) + '\n');
    _apkDeaths.push(rec);
    while (_apkDeaths.length > 50) _apkDeaths.shift();
    console.log(`[apk-death] trip=${rec.tripId} reason="${rec.reason}" clean=${rec.sessionEndedCleanly} v${rec.version}`);
    // Fallback ATIVO: se APK morreu com viagem NÃO finalizada limpa, tenta
    // criar autotrip a partir do snapshot em memória ANTES de perder dados.
    // Antes o handler só logava, e a trip só existia em memória (_liveTrip) —
    // se motor desligasse depois sem POST autoritativo, os dados sumiam.
    if (!rec.sessionEndedCleanly) {
      try {
        const created = _finalizeAbandonedTrip(_lastTripSnapshot);
        if (created) console.log(`[apk-death] fallback finalizou trip a partir do snapshot`);
      } catch (e) { console.warn('[apk-death] fallback falhou:', e.message); }
    }
    res.json({ ok: true });
  } catch (e) {
    console.error('Erro ao registrar apk-death:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ── Compartilhamento de trajeto por link (sem auth) ────────────────────────
// Token curto e imprevisível ↔ tripId. Expira em 30 dias (limpa periodicamente).
const SHARED_TRIPS_FILE = path.join(DATA_DIR, 'shared-trips.json');
const SHARED_TRIP_TTL_MS = 30 * 24 * 3600_000;
let _sharedTrips = {};
try { if (fs.existsSync(SHARED_TRIPS_FILE)) _sharedTrips = JSON.parse(fs.readFileSync(SHARED_TRIPS_FILE, 'utf8')) || {}; } catch (_) {}
function _saveSharedTrips() {
  try { atomicWriteFileSync(SHARED_TRIPS_FILE, JSON.stringify(_sharedTrips)); } catch (_) {}
}
function _cleanupSharedTrips() {
  const now = Date.now();
  let dirty = false;
  for (const [tok, e] of Object.entries(_sharedTrips)) {
    if (!e || !e.expiresAt || e.expiresAt < now) { delete _sharedTrips[tok]; dirty = true; }
  }
  if (dirty) _saveSharedTrips();
}
setInterval(_cleanupSharedTrips, 6 * 3600_000);
_cleanupSharedTrips();

// Cria (ou retorna existente ainda válido) o token de compartilhamento.
app.post('/api/autotrips/:tripId/share', requireAuth, (req, res) => {
  const tripId = String(req.params.tripId).replace(/\D/g, '');
  if (!tripId) return res.status(400).json({ error: 'tripId inválido' });
  const fp = path.join(AUTOTRIPS_DIR, `${tripId}.json`);
  if (!fs.existsSync(fp)) return res.status(404).json({ error: 'viagem não encontrada' });
  const now = Date.now();
  // Reutiliza token existente se ainda válido pra próximos 7 dias.
  for (const [tok, e] of Object.entries(_sharedTrips)) {
    if (e.tripId === tripId && e.expiresAt > now + 7 * 24 * 3600_000) {
      return res.json({ ok: true, token: tok, expiresAt: e.expiresAt });
    }
  }
  // Token curto (8 chars base62 = 48 bits). Retenta se colisão (raríssimo).
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let token = '';
  for (let attempt = 0; attempt < 8; attempt++) {
    const buf = crypto.randomBytes(8);
    token = Array.from(buf).map(b => alphabet[b % alphabet.length]).join('');
    if (!_sharedTrips[token]) break;
    token = '';
  }
  if (!token) return res.status(500).json({ error: 'falha ao gerar token' });
  _sharedTrips[token] = { tripId, createdAt: now, expiresAt: now + SHARED_TRIP_TTL_MS };
  _saveSharedTrips();
  res.json({ ok: true, token, expiresAt: _sharedTrips[token].expiresAt });
});

// Revoga um token de compartilhamento.
app.delete('/api/autotrips/:tripId/share/:token', requireAuth, (req, res) => {
  const tok = String(req.params.token);
  const e = _sharedTrips[tok];
  if (!e || e.tripId !== String(req.params.tripId).replace(/\D/g, '')) return res.status(404).json({ error: 'token não encontrado' });
  delete _sharedTrips[tok];
  _saveSharedTrips();
  res.json({ ok: true });
});

// Endpoint público (sem auth) — retorna metadata + samples da viagem por token.
app.get('/api/shared-trip/:token', (req, res) => {
  const tok = String(req.params.token);
  const e = _sharedTrips[tok];
  if (!e || e.expiresAt < Date.now()) return res.status(404).json({ error: 'link expirado ou inválido' });
  const fp = path.join(AUTOTRIPS_DIR, `${e.tripId}.json`);
  if (!fs.existsSync(fp)) return res.status(404).json({ error: 'viagem removida' });
  try {
    const d = JSON.parse(fs.readFileSync(fp, 'utf8'));
    res.json({ ok: true, autoTrip: d.autoTrip || null, samples: d.samples || [] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Página compartilhada — serve o mesmo HTML pra qualquer token (a página lê da URL).
app.get('/shared-trip/:token', (_req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'shared-trip.html'));
});
// Alias curto: /t/TOKEN → mesmo HTML (redirect pra manter a URL bonita).
app.get('/t/:token', (req, res) => {
  res.redirect(302, `/shared-trip/${encodeURIComponent(req.params.token)}`);
});

app.get('/api/autotrips', (req, res) => {
  setSyncWatermark(res);
  const since = parseSince(req);
  // Inclui também viagens ATUALIZADAS (rename, reprocessamento de locais) via
  // _updated_ms — senão o sync incremental do app (que filtra por startMs) nunca
  // recebe o nome novo de uma viagem antiga.
  const arr   = since > 0
    ? autoTripsArr.filter(t => (t.startMs || 0) > since || (t._updated_ms || 0) > since)
    : autoTripsArr;
  if (Array.isArray(deletedIds.autotrips) && deletedIds.autotrips.length) {
    res.setHeader('X-Tombstones', deletedIds.autotrips.join(','));
    res.setHeader('Access-Control-Expose-Headers', 'X-Tombstones');
  }
  // Teto de 300 truncava o histórico EM SILÊNCIO: em 15/08 o app mostrava 1 viagem em
  // maio quando havia 80 no disco (12→31/05), porque maio caía fora do corte. Sync
  // completo (`since=0`) tem que devolver tudo — é ele que popula o histórico do app.
  // Cap alto só como rede de segurança, e com log quando morder.
  const CAP = 5000;
  if (arr.length > CAP) {
    console.warn(`[autotrips] TRUNCADO: ${arr.length} → ${CAP} (histórico maior que o teto)`);
  }
  res.json(arr.slice(0, CAP));
});

// ── Rotina: horário típico da 1ª saída do dia, por dia da semana ──────────────
// Determinístico (sem LLM): agrupa as auto-trips por dia local, pega a 1ª viagem
// de cada dia e tira a MEDIANA do horário por dia da semana. A Lari usa pra
// antecipar pré-clima quando não há compromisso na agenda. Janela default 56d.
const _DOW_LABEL = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
function _median(nums) {
  if (!nums.length) return null;
  const a = [...nums].sort((x, y) => x - y);
  const m = a.length >> 1;
  return a.length % 2 ? a[m] : Math.round((a[m - 1] + a[m]) / 2);
}
function _minToHHMM(min) {
  if (min == null) return null;
  const h = Math.floor(min / 60) % 24, m = min % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}
app.get('/api/routine/departure', (req, res) => {
  const lookbackDays = Math.min(180, Math.max(7, parseInt(req.query.days, 10) || 56));
  const minSamples = Math.max(2, parseInt(req.query.min, 10) || 3);
  const since = Date.now() - lookbackDays * 86400_000;

  // 1ª viagem de cada dia local → { dayKey: {dow, minuteOfDay} }
  const firstOfDay = new Map();
  for (const t of autoTripsArr) {
    const ms = t.startMs || 0;
    if (ms < since) continue;
    if (!((t.distKm || 0) > 0.3 || (t.timeSec || 0) >= 120)) continue; // ignora micro-movimento
    const d = new Date(ms);
    const dayKey = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    const minuteOfDay = d.getHours() * 60 + d.getMinutes();
    const cur = firstOfDay.get(dayKey);
    if (!cur || minuteOfDay < cur.minuteOfDay) firstOfDay.set(dayKey, { dow: d.getDay(), minuteOfDay });
  }

  const byDow = Array.from({ length: 7 }, () => []);
  const weekdayPool = [], weekendPool = [];
  for (const { dow, minuteOfDay } of firstOfDay.values()) {
    byDow[dow].push(minuteOfDay);
    (dow === 0 || dow === 6 ? weekendPool : weekdayPool).push(minuteOfDay);
  }

  const perDow = {};
  for (let d = 0; d < 7; d++) {
    const med = byDow[d].length >= minSamples ? _median(byDow[d]) : null;
    perDow[d] = { label: _DOW_LABEL[d], hhmm: _minToHHMM(med), samples: byDow[d].length };
  }
  const dow = /^[0-6]$/.test(String(req.query.dow)) ? +req.query.dow : new Date().getDay();
  const isWeekend = dow === 0 || dow === 6;
  const pool = isWeekend ? weekendPool : weekdayPool;
  const poolMed = pool.length >= minSamples ? _median(pool) : null;
  // hoje: usa a mediana do próprio dia da semana; cai pro pool (úteis/fim) se faltar amostra
  const todayMed = byDow[dow].length >= minSamples ? _median(byDow[dow]) : poolMed;

  res.json({
    ok: true,
    lookbackDays, daysObserved: firstOfDay.size,
    today: { dow, label: _DOW_LABEL[dow], hhmm: _minToHHMM(todayMed), samples: byDow[dow].length },
    weekdayMedian: { hhmm: _minToHHMM(weekdayPool.length >= minSamples ? _median(weekdayPool) : null), samples: weekdayPool.length },
    weekendMedian: { hhmm: _minToHHMM(weekendPool.length >= minSamples ? _median(weekendPool) : null), samples: weekendPool.length },
    perDow,
  });
});

// ── Rotina por LOCAL: destinos recorrentes + dwell (quanto tempo fica) ────────
// Agrupa os destinos das viagens (grade ~110m) e, pareando cada chegada com a
// saída seguinte do mesmo lugar, aprende: nº de visitas, hora típica de chegada,
// duração típica da parada (dwell) e dias da semana. A Lari usa pra antecipar
// climatização da volta (ex: almoço diário de ~40 min com calor lá fora).
function _placeKey(lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return `${lat.toFixed(3)},${lng.toFixed(3)}`; // ~110m
}
function _computeRoutinePlaces(lookbackDays, minVisits) {
  const since = Date.now() - lookbackDays * 86400_000;
  // ascendente p/ parear chegada→próxima saída do mesmo lugar
  const trips = autoTripsArr.filter(t => (t.startMs || 0) >= since).sort((a, b) => (a.startMs || 0) - (b.startMs || 0));
  const places = new Map(); // key → {name, lat, lng, arrivals[], dwells[], dows[]}
  for (let i = 0; i < trips.length; i++) {
    const t = trips[i];
    const key = _placeKey(+t.endLat, +t.endLng);
    if (!key || !(t.endMs > 0)) continue;
    let p = places.get(key);
    if (!p) { p = { key, names: {}, lat: +t.endLat, lng: +t.endLng, arrivals: [], dwells: [], dows: Array(7).fill(0) }; places.set(key, p); }
    if (t.endKp) p.names[t.endKp] = (p.names[t.endKp] || 0) + 1;
    const d = new Date(t.endMs);
    p.arrivals.push(d.getHours() * 60 + d.getMinutes());
    p.dows[d.getDay()]++;
    // dwell = início da PRÓXIMA viagem que sai daqui − chegada (mesma grade)
    const nxt = trips[i + 1];
    if (nxt && _placeKey(+nxt.startLat, +nxt.startLng) === key && nxt.startMs > t.endMs) {
      const min = Math.round((nxt.startMs - t.endMs) / 60000);
      if (min >= 10 && min <= 360) p.dwells.push(min);
    }
  }
  const out = [];
  for (const p of places.values()) {
    if (p.arrivals.length < minVisits) continue;
    const name = Object.entries(p.names).sort((a, b) => b[1] - a[1])[0]?.[0] || null;
    const topDow = p.dows.map((n, d) => ({ d, n })).sort((a, b) => b.n - a.n)[0];
    out.push({
      key: p.key, name, lat: +p.lat.toFixed(5), lng: +p.lng.toFixed(5),
      visits: p.arrivals.length,
      arrivalHHMM: _minToHHMM(_median(p.arrivals)),
      dwellMin: p.dwells.length ? _median(p.dwells) : null,
      dwellSamples: p.dwells.length,
      topDow: topDow ? { dow: topDow.d, label: _DOW_LABEL[topDow.d], count: topDow.n } : null,
      // "quase todo dia" = visto em >=60% dos dias observados da janela
      frequent: p.arrivals.length >= Math.max(minVisits, Math.round(lookbackDays * 0.6 / 7)),
    });
  }
  out.sort((a, b) => b.visits - a.visits);
  return out;
}
app.get('/api/routine/places', (req, res) => {
  const lookbackDays = Math.min(365, Math.max(7, parseInt(req.query.days, 10) || 60));
  const minVisits = Math.max(2, parseInt(req.query.min, 10) || 4);
  const out = _computeRoutinePlaces(lookbackDays, minVisits).map(({ key, ...p }) => p);
  res.json({ ok: true, lookbackDays, places: out.slice(0, 30) });
});

// temp atual REAL no ponto (open-meteo) — NÃO usar ambient_c do carro: congela
// quando o carro dorme. null se indisponível.
async function _liveTempC(lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  try {
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}`
      + `&current=temperature_2m&timezone=auto`;
    const r = await fetch(url, { signal: AbortSignal.timeout(9000) });
    if (!r.ok) return null;
    const j = await r.json();
    const t = j?.current?.temperature_2m;
    return Number.isFinite(+t) ? +t : null;
  } catch { return null; }
}

// GET /api/routine/return-suggestion — "o carro está num lugar recorrente,
// perto da hora típica de sair, e tá quente lá fora? sugerir ligar o AC antes".
// Estado puro: decide com base no estado VIVO (gps, motor) + dwell decorrido
// (desde a última chegada) + temp REAL via open-meteo. A cadência/janela/dedup
// é responsabilidade de quem chama (poller da Lari).
app.get('/api/routine/return-suggestion', async (req, res) => {
  const tempThresh = Number.isFinite(+req.query.temp) ? +req.query.temp : 30;
  const dwellPct   = Number.isFinite(+req.query.dwellpct) ? +req.query.dwellpct : 0.7;
  const graceMin   = Number.isFinite(+req.query.grace) ? +req.query.grace : 30;
  const lookbackDays = Math.min(365, Math.max(7, parseInt(req.query.days, 10) || 60));
  const minVisits = Math.max(2, parseInt(req.query.min, 10) || 4);

  const engineOff = String(state.engine_state) === '0';
  const last = autoTripsArr[0]; // mais recente (ordenado desc por startMs)
  const parkedKey = last ? _placeKey(+last.endLat, +last.endLng) : null;
  const parkedSinceMs = last?.endMs || 0;

  const base = { ok: true, suggest: false };
  if (!engineOff) return res.json({ ...base, reason: 'motor ligado / em movimento' });
  if (!parkedKey || !(parkedSinceMs > 0)) return res.json({ ...base, reason: 'sem viagem recente p/ ancorar' });

  const place = _computeRoutinePlaces(lookbackDays, minVisits).find(p => p.key === parkedKey && p.frequent);
  if (!place) return res.json({ ...base, reason: 'não é um local recorrente' });
  if (!(place.dwellMin > 0)) return res.json({ ...base, reason: 'sem tempo de permanência típico p/ esse local' });

  const dwellElapsedMin = Math.round((Date.now() - parkedSinceMs) / 60000);
  const windowFrom = Math.round(place.dwellMin * dwellPct);
  const windowTo   = place.dwellMin + graceMin; // janela de saída: não nagueia eternamente
  const place4 = { name: place.name, lat: place.lat, lng: place.lng, dwellMin: place.dwellMin, dwellElapsedMin };
  if (dwellElapsedMin < windowFrom) return res.json({ ...base, reason: 'ainda longe da hora típica de sair', place: place4 });
  if (dwellElapsedMin > windowTo)   return res.json({ ...base, reason: 'já passou da janela típica de saída (fora de rotina)', place: place4 });

  const tempC = await _liveTempC(place.lat, place.lng);
  if (tempC == null) return res.json({ ...base, reason: 'temp local indisponível', place: place4 });
  if (tempC < tempThresh) return res.json({ ...base, reason: `tá ${Math.round(tempC)}° lá (abaixo de ${tempThresh}°)`, place: place4, tempC });

  res.json({
    ok: true, suggest: true, place: place4, tempC,
    reason: `parado em ${place.name || 'local recorrente'} há ${dwellElapsedMin}min (típico ~${place.dwellMin}min) e tá ${Math.round(tempC)}° lá fora`,
    action: { type: 'car_command', name: 'ac_on' },
  });
});

// ── Logbook: diário de bordo agregado por mês ────────────────────────────────
// Reusa as autotrips já ingeridas (autoTripsArr) — só agrega por mês, calcula o
// custo por viagem (mesmos preços ponderados do push) e exporta CSV. Pra IRPF /
// reembolso de km. Mês no formato YYYY-MM, fuso local do servidor.
function _tripMonthKey(ms) {
  const d = new Date(ms || 0);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}
function _tripCost(t) {
  const pKwh = +state.battery_avg_price_per_kwh || +state.price_kwh || 0;
  const pGas = +state.tank_avg_price_per_l      || +state.price_gas_per_l || 0;
  const netKwh = +t.netKwh || 0;
  const fuelL  = +t.fuelL  || 0;
  return (pGas > 0 || pKwh > 0) ? fuelL * pGas + netKwh * pKwh : 0;
}
function _logbookTrips(month) {
  return autoTripsArr
    .filter(t => (t.startMs || 0) > 0 && _tripMonthKey(t.startMs) === month)
    .map(t => {
      const km = +t.distKm || 0, sec = +t.timeSec || 0;
      return {
        tripId:   t.tripId,
        startMs:  t.startMs || 0,
        name:     t.name || '',
        from:     t.knownStart || t.startKp || '',
        to:       t.knownEnd   || t.endKp   || '',
        km, kwh: +t.netKwh || 0, fuelL: +t.fuelL || 0,
        cost:     _tripCost(t),
        durationSec: sec,
        avgKmh:   sec >= 60 ? km / (sec / 3600) : 0,
        driveScore: t.driveScore != null ? t.driveScore : null,
      };
    })
    .sort((a, b) => a.startMs - b.startMs);
}
function _logbookTotals(trips) {
  const sum = (k) => trips.reduce((s, t) => s + (t[k] || 0), 0);
  const km = sum('km'), cost = sum('cost');
  return {
    trips: trips.length,
    km, kwh: sum('kwh'), fuelL: sum('fuelL'), cost,
    durationSec: sum('durationSec'),
    costPerKm: km > 0.5 ? cost / km : 0,
  };
}

// GET /api/logbook?month=YYYY-MM — agregado do mês + lista de viagens.
app.get('/api/logbook', (req, res) => {
  const month = String(req.query.month || _tripMonthKey(Date.now()));
  if (!/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'month inválido (YYYY-MM)' });
  // Meses que têm pelo menos uma viagem (pro seletor do app).
  const months = [...new Set(autoTripsArr.filter(t => t.startMs).map(t => _tripMonthKey(t.startMs)))].sort().reverse();
  const trips = _logbookTrips(month);
  res.json({ ok: true, month, months, totals: _logbookTotals(trips), trips });
});

// GET /api/logbook/export?month=YYYY-MM&fmt=csv — CSV anexável (IRPF/reembolso).
app.get('/api/logbook/export', (req, res) => {
  const month = String(req.query.month || _tripMonthKey(Date.now()));
  if (!/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'month inválido (YYYY-MM)' });
  const trips = _logbookTrips(month);
  const fmt = String(req.query.fmt || 'csv');
  if (fmt !== 'csv') return res.status(400).json({ error: 'fmt suportado: csv' });
  const esc = (v) => {
    const s = String(v ?? '');
    return /[",;\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const fmtDur = (sec) => `${Math.floor(sec / 3600)}h${String(Math.floor((sec % 3600) / 60)).padStart(2, '0')}`;
  const rows = [['Data', 'Início', 'Origem', 'Destino', 'km', 'kWh', 'Litros', 'Custo R$', 'Duração', 'km/h méd', 'Condução']];
  for (const t of trips) {
    const d = new Date(t.startMs);
    rows.push([
      d.toLocaleDateString('pt-BR'),
      d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
      t.from, t.to,
      t.km.toFixed(1), t.kwh.toFixed(2), t.fuelL.toFixed(2),
      t.cost.toFixed(2), fmtDur(t.durationSec), t.avgKmh.toFixed(0),
      t.driveScore != null ? t.driveScore : '',
    ]);
  }
  const tot = _logbookTotals(trips);
  rows.push([]);
  rows.push(['TOTAL', '', '', '', tot.km.toFixed(1), tot.kwh.toFixed(2), tot.fuelL.toFixed(2),
             tot.cost.toFixed(2), fmtDur(tot.durationSec), '', '']);
  const csv = '﻿' + rows.map(r => r.map(esc).join(';')).join('\r\n');
  res.setHeader('Content-Type', 'text/csv; charset=utf-8');
  res.setHeader('Content-Disposition', `attachment; filename="logbook-${month}.csv"`);
  res.send(csv);
});

// ── Estatísticas de economia por modo de condução ───────────────────────────
// Agrega os `segments[]` de todas as viagens por combinação de modos
// (one-pedal / regeneração / estilo / powertrain) e ranqueia por economia.
// Filtro opcional de rota: ?route=<tripId> usa a origem/destino daquela viagem,
// ou slat/slng/elat/elng explícitos. radius em metros (default 250).
const _PEDAL_LBL = { '-1': '?', '0': 'Off', '1': 'On' };
const _REGEN_LBL = { '-1': '?', '0': 'Normal', '1': 'Alto', '2': 'Baixo' };
const _DRIVE_LBL = { '-1': '?', '0': 'Normal', '1': 'Sport', '2': 'Eco', '3': 'Neve', '4': 'Areia', '5': 'Lama', '11': 'AWD' };
const _PWRT_LBL  = { '-1': '?', '0': 'HEV', '1': 'Prior.EV', '3': 'EV puro' };

app.get('/api/stats/by-mode', (req, res) => {
  const pKwh = +state.battery_avg_price_per_kwh || +state.price_kwh || 0;
  const pGas = +state.tank_avg_price_per_l      || +state.price_gas_per_l || 0;
  const radius = Math.max(20, +req.query.radius || 250);

  // Referência de rota (opcional)
  let ref = null;
  if (req.query.route) {
    const rid = String(req.query.route).replace(/\D/g, '');
    const rt = autoTripsArr.find(t => t.tripId === rid || String(t.startMs) === rid);
    if (rt && rt.startLat) ref = { slat: rt.startLat, slng: rt.startLng, elat: rt.endLat, elng: rt.endLng };
  } else if (req.query.slat && req.query.slng && req.query.elat && req.query.elng) {
    ref = { slat: +req.query.slat, slng: +req.query.slng, elat: +req.query.elat, elng: +req.query.elng };
  }
  const matchesRoute = (t) => {
    if (!ref) return true;
    if (!t.startLat || !t.endLat) return false;
    return haversineM(t.startLat, t.startLng, ref.slat, ref.slng) <= radius
        && haversineM(t.endLat,   t.endLng,   ref.elat, ref.elng) <= radius;
  };

  const combos = new Map();
  let segTrips = 0;
  for (const t of autoTripsArr) {
    const segs = t.segments;
    if (!Array.isArray(segs) || segs.length === 0) continue;
    if (!matchesRoute(t)) continue;
    segTrips++;
    for (const s of segs) {
      // Com one-pedal ativo o nível de regeneração é irrelevante — agrupa tudo junto.
      const effRegen = s.onePedal === 1 ? 0 : s.regenLevel;
      const key = `${s.onePedal}|${effRegen}|${s.driveMode}|${s.powertrain}`;
      let c = combos.get(key);
      if (!c) {
        c = { onePedal: s.onePedal, regenLevel: effRegen, driveMode: s.driveMode, powertrain: s.powertrain,
              distKm: 0, netKwh: 0, regenKwh: 0, energyKwh: 0, fuelL: 0, timeSec: 0,
              engineDistKm: 0, engineSec: 0, segCount: 0, tripIds: new Set() };
        combos.set(key, c);
      }
      c.distKm       += +s.distKm       || 0;
      c.netKwh       += +s.netKwh       || 0;
      c.regenKwh     += +s.regenKwh     || 0;
      c.energyKwh    += +s.energyKwh    || 0;
      c.fuelL        += +s.fuelL        || 0;
      c.timeSec      += +s.timeSec      || 0;
      c.engineDistKm += +s.engineDistKm || 0;
      c.engineSec    += +s.engineSec    || 0;
      c.segCount  += 1;
      c.tripIds.add(t.tripId);
    }
  }

  const ranking = [];
  for (const c of combos.values()) {
    if (c.distKm < 0.5) continue;   // descarta amostras triviais
    const isHev  = c.powertrain === 0;   // motor a combustão é a fonte de energia
    const netPos = Math.max(0, c.netKwh);
    // O `continue` de distKm < 0.5 acima já garante o piso; o null é a resposta
    // honesta caso alguém afrouxe aquele filtro depois. Zero aqui leria como
    // "eficiência perfeita".
    const kwh100 = c.distKm > RAZAO_MIN_KM ? (c.netKwh / c.distKm) * 100 : null;
    // km/L: em HEV o motor propulsiona; a economia real é km por litro sobre a
    // distância com motor ligado (engineDistKm) — não sobre a distância total,
    // que incluiria trechos EV. Fora de HEV, km/L só faz sentido se houve fuel.
    const kmL = c.fuelL > 0.01
      ? (isHev && c.engineDistKm > 0.1 ? c.engineDistKm : c.distKm) / c.fuelL
      : null;
    // km/L equivalente e R$/km:
    //   HEV → a bateria é recarregada pelo MOTOR (custo já está no combustível);
    //         não credita/penaliza kWh. Economia = km/L (combustível) e R$/km de gás.
    //   EV/Prior.EV → a bateria vem da tomada; converte kWh→litros equivalentes.
    let kmLeq, rPerKm;
    if (isHev) {
      kmLeq  = (c.fuelL > 0.01) ? c.distKm / c.fuelL : null;
      rPerKm = (pGas > 0) ? (c.fuelL * pGas) / c.distKm : null;
    } else {
      const kwhAsL = (pGas > 0 && pKwh > 0) ? netPos * pKwh / pGas : netPos / 8.9;
      const totEqL = c.fuelL + kwhAsL;
      kmLeq  = totEqL > 0.001 ? c.distKm / totEqL : null;
      rPerKm = (pGas > 0 || pKwh > 0) ? (c.fuelL * pGas + netPos * pKwh) / c.distKm : null;
    }
    ranking.push({
      key: `${c.onePedal}|${c.regenLevel}|${c.driveMode}|${c.powertrain}`,
      onePedal: c.onePedal, regenLevel: c.regenLevel, driveMode: c.driveMode, powertrain: c.powertrain,
      isHev,
      label: {
        onePedal:   _PEDAL_LBL[String(c.onePedal)]   ?? '?',
        regenLevel: _REGEN_LBL[String(c.regenLevel)] ?? '?',
        driveMode:  _DRIVE_LBL[String(c.driveMode)]  ?? '?',
        powertrain: _PWRT_LBL[String(c.powertrain)]  ?? '?',
      },
      distKm:   +c.distKm.toFixed(2),
      engineDistKm: +c.engineDistKm.toFixed(2),
      timeMin:  Math.round(c.timeSec / 60),
      netKwh:   +c.netKwh.toFixed(2),
      regenKwh: +c.regenKwh.toFixed(2),
      fuelL:    +c.fuelL.toFixed(2),
      // kWh/100km só é informativo fora de HEV (em HEV o motor recarrega a bateria)
      kwh100:   isHev ? null : +kwh100.toFixed(1),
      kmL:      kmL   != null ? +kmL.toFixed(1)   : null,
      kmLeq:    kmLeq != null ? +kmLeq.toFixed(1) : null,
      rPerKm:   rPerKm != null ? +rPerKm.toFixed(3) : null,
      segCount: c.segCount,
      tripCount: c.tripIds.size,
      lowSample: c.distKm < 10,  // <10 km de amostra → ranking pouco confiável
    });
  }
  // Mais econômico primeiro: maior km/L-equivalente. Combos sem métrica (sem
  // fuel nem kWh) vão pro fim.
  ranking.sort((a, b) => {
    const av = a.kmLeq != null ? a.kmLeq : -Infinity;
    const bv = b.kmLeq != null ? b.kmLeq : -Infinity;
    return bv - av;
  });

  res.json({
    prices: { pKwh, pGas },
    route: ref ? { ...ref, radius } : null,
    tripsConsidered: segTrips,
    ranking,
  });
});

// ── Economia vitalícia vs carro a gasolina ──────────────────────────────────
// Compara o que um SUV equivalente só-gasolina teria gastado para rodar a mesma
// distância contra o que o usuário realmente pagou (eletricidade + combustível).
// Baseline km/L de SUV gasolina classe H6 ~9 km/L (env ICE_BASELINE_KML).
const ICE_BASELINE_KML = +process.env.ICE_BASELINE_KML || 9.0;
const KWH_PER_L_EQUIV   = 8.9;   // 1 L gasolina ≈ 8,9 kWh (mesma conversão do by-mode)

app.get('/api/stats/savings', (req, res) => {
  const distKm = +state.lifetime?.distance_km || 0;
  const fuelL  = +state.lifetime?.fuel_l      || 0;
  const netKwh = Math.max(0, +state.lifetime?.net_kwh || 0);

  // Custo real de eletricidade: valora cada sessão pelo override (total/perKwh)
  // ou cai no SEED — mesma lógica do recomputeBatteryAvgPrice.
  let elecCost = 0, elecKwh = 0;
  for (const c of chargesArr) {
    const energy = +c.energy_kwh || 0;
    if (energy < 0.05) continue;
    const ovr = c.cost_override;
    let pKwh = ovr?.free === true ? 0
             : ovr && +ovr.total  > 0 ? (+ovr.total / energy)
             : ovr && +ovr.perKwh > 0 ? +ovr.perKwh
             : SEED_KWH_PRICE;
    if (pKwh > 5) pKwh = SEED_KWH_PRICE;   // anti-outlier
    elecCost += energy * pKwh;
    elecKwh  += energy;
  }

  // Custo real de combustível: total_cost quando registrado, senão litros × SEED.
  let fuelCost = 0, fuelLitersBought = 0;
  for (const r of refuels) {
    const liters = +r.liters_added || 0;
    if (liters <= 0) continue;
    fuelLitersBought += liters;
    fuelCost += (+r.total_cost > 0) ? +r.total_cost : liters * SEED_GAS_PRICE_PER_L;
  }

  const gasPrice = +state.tank_avg_price_per_l || +state.price_gas_per_l || SEED_GAS_PRICE_PER_L;

  // Baseline: SUV gasolina rodando distKm.
  const baselineLiters = ICE_BASELINE_KML > 0 ? distKm / ICE_BASELINE_KML : 0;
  const baselineCost   = baselineLiters * gasPrice;

  const actualCost = elecCost + fuelCost;
  const saved      = baselineCost - actualCost;

  // Litros-equivalentes de energia poupados vs só-gasolina.
  const kwhAsL       = netKwh / KWH_PER_L_EQUIV;
  const energyEqL    = fuelL + kwhAsL;
  const litersSaved  = baselineLiters - energyEqL;

  // Km rodados na eletricidade (share da energia que veio da bateria).
  const electricShare = energyEqL > 0.001 ? kwhAsL / energyEqL : 0;
  const electricKm    = distKm * electricShare;

  res.json({
    distanceKm:     +distKm.toFixed(1),
    electricKm:     +electricKm.toFixed(1),
    electricShare:  +(electricShare * 100).toFixed(0),
    fuelL:          +fuelL.toFixed(1),
    netKwh:         +netKwh.toFixed(1),
    cost: {
      electricity:  +elecCost.toFixed(2),
      fuel:         +fuelCost.toFixed(2),
      actual:       +actualCost.toFixed(2),
      iceBaseline:  +baselineCost.toFixed(2),
    },
    savedBrl:       +saved.toFixed(2),
    litersSaved:    +litersSaved.toFixed(1),
    baselineLiters: +baselineLiters.toFixed(1),
    assumptions: {
      iceBaselineKmL: ICE_BASELINE_KML,
      gasPricePerL:   +gasPrice.toFixed(2),
      kwhPerLitre:    KWH_PER_L_EQUIV,
    },
  });
});

// GET /api/health-score — índice consolidado de saúde do carro (0-100).
// Junta 4 subscores: bateria 12V, pneus, autonomia ICE (tendência) e manutenção.
app.get('/api/health-score', (_req, res) => {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const subs = [];
  const issues = [];

  // ── Bateria 12V: nível atual (90%→100, 50%→0) + penalidade de tendência ──
  // Não basta o % instantâneo: uma 12V que perde carga rápido falha mesmo
  // estando "ok" hoje. A regressão sobre o histórico projeta quando cruza 50%
  // e desconta proporcionalmente — quanto mais perto da troca, menor o score.
  const v12 = +state.batt_12v_pct || 0;
  if (v12 > 0) {
    let s = Math.round(clamp((v12 - 50) / 40 * 100, 0, 100));
    let detail = `${v12}%`;
    const reg = batt12Regression();
    if (reg && reg.slope < -0.05 && reg.daysTo50 != null && reg.daysTo50 > 0) {
      // ≤30d p/ troca → −60; ≥365d → ~0. Penaliza a queda projetada.
      const trendPenalty = clamp((365 - reg.daysTo50) / 335 * 60, 0, 60);
      s = Math.round(clamp(s - trendPenalty, 0, 100));
      const d = Math.round(reg.daysTo50);
      detail = `${v12}% · −${reg.perWeek}%/sem · troca em ~${d > 365 ? '365+' : d}d`;
      if (reg.daysTo50 <= 60) issues.push(`Bateria 12V: troca prevista em ~${d}d`);
    } else if (reg && reg.slope >= -0.05) {
      detail = `${v12}% · estável`;
    }
    subs.push({ key: 'batt12', label: 'Bateria 12V', score: s, detail });
    if (s < 60 && !issues.some(i => i.startsWith('Bateria 12V'))) issues.push('Bateria 12V baixa');
  }

  // ── Pneus: pior pneu. 32 psi→100, 26 psi→0 ──
  const tyres = ['tyre_fl', 'tyre_fr', 'tyre_rl', 'tyre_rr'].map(k => +state[k] || 0).filter(v => v > 0);
  if (tyres.length) {
    const worst = Math.min(...tyres);
    const s = Math.round(clamp((worst - 26) / 6 * 100, 0, 100));
    subs.push({ key: 'tyres', label: 'Pneus', score: s, detail: `mín ${worst.toFixed(0)} psi` });
    if (s < 60) issues.push('Pressão de pneu baixa');
  }

  // ── Autonomia ICE (tendência): queda >10% com tanque similar penaliza ──
  const last = telemetryHistory[telemetryHistory.length - 1];
  if (last && last.fuel_l > 5) {
    const recent = telemetryHistory.filter(s => Math.abs((s.fuel_l || 0) - last.fuel_l) < 3 && (s.autonomy_ice || 0) > 0).sort((a, b) => a.ts - b.ts);
    if (recent.length >= 5) {
      const f3 = recent.slice(0, 3).map(s => s.autonomy_ice);
      const l3 = recent.slice(-3).map(s => s.autonomy_ice);
      const avgF = f3.reduce((a, b) => a + b, 0) / f3.length;
      const avgL = l3.reduce((a, b) => a + b, 0) / l3.length;
      const dropPct = avgF > 0 ? (avgF - avgL) / avgF * 100 : 0;
      const s = Math.round(clamp(100 - Math.max(0, dropPct) * 3, 0, 100));
      subs.push({ key: 'ice', label: 'Consumo combustão', score: s, detail: dropPct > 1 ? `−${dropPct.toFixed(0)}% autonomia` : 'estável' });
      if (s < 60) issues.push('Autonomia de combustão caindo');
    }
  }

  // ── Manutenção: cada vencida −25, cada próxima −8 ──
  const maint = computeMaintenance();
  const overdue = maint.filter(m => m.status === 'overdue').length;
  const soon    = maint.filter(m => m.status === 'soon').length;
  if (maint.length) {
    const s = clamp(100 - overdue * 25 - soon * 8, 0, 100);
    subs.push({ key: 'maint', label: 'Manutenção', score: s, detail: overdue ? `${overdue} vencida${overdue > 1 ? 's' : ''}` : soon ? `${soon} próxima${soon > 1 ? 's' : ''}` : 'em dia' });
    if (overdue) issues.push(`${overdue} manutenção${overdue > 1 ? 'ões' : ''} vencida${overdue > 1 ? 's' : ''}`);
  }

  const weights = { batt12: 0.25, tyres: 0.25, ice: 0.20, maint: 0.30 };
  let wsum = 0, acc = 0;
  for (const s of subs) { const w = weights[s.key] || 0; acc += s.score * w; wsum += w; }
  const total = wsum > 0 ? Math.round(acc / wsum) : null;
  const label = total == null ? '—' : total >= 85 ? 'Ótimo' : total >= 70 ? 'Bom' : total >= 50 ? 'Atenção' : 'Crítico';

  res.json({ ok: true, total, label, subs, issues });
});

// GET /api/routine/trips-cost — custo por TRAJETO recorrente (origem→destino).
// Agrupa viagens pelo par (grade de origem, grade de destino), soma
// energia/combustível, valora pelos preços ponderados do tanque/bateria e
// compara com baseline 100% gasolina. Devolve custo total do período (todas as
// viagens) + custo total/médio dos trajetos mais recorrentes.
app.get('/api/routine/trips-cost', (req, res) => {
  const lookbackDays = Math.min(365, Math.max(7, parseInt(req.query.days, 10) || 90));
  const minTrips = Math.max(2, parseInt(req.query.min, 10) || 2);
  const since = Date.now() - lookbackDays * 86400_000;

  const pKwh = +state.battery_avg_price_per_kwh || +state.price_kwh || SEED_KWH_PRICE;
  const pGas = +state.tank_avg_price_per_l      || +state.price_gas_per_l || SEED_GAS_PRICE_PER_L;

  const routes = new Map(); // key origem→destino → agregado
  let totalCost = 0, totalGas = 0, totalTrips = 0;
  for (const t of autoTripsArr) {
    if ((t.startMs || 0) < since) continue;
    const dist = +t.distKm || 0;
    if (dist < 0.5) continue;
    const cost = Math.max(0, +t.netKwh || 0) * pKwh + (+t.fuelL || 0) * pGas;
    const gas  = ICE_BASELINE_KML > 0 ? (dist / ICE_BASELINE_KML) * pGas : 0;
    totalCost += cost; totalGas += gas; totalTrips += 1;

    const sk = _placeKey(+t.startLat, +t.startLng);
    const ek = _placeKey(+t.endLat, +t.endLng);
    if (!sk || !ek) continue;
    const key = `${sk}>${ek}`;
    let r = routes.get(key);
    if (!r) { r = { key, name: null, names: {}, trips: 0, km: 0, cost: 0, gas: 0 }; routes.set(key, r); }
    const nm = t.name || ((t.startKp || t.endKp) ? `${t.startKp || '?'} → ${t.endKp || '?'}` : null);
    if (nm) r.names[nm] = (r.names[nm] || 0) + 1;
    r.trips += 1; r.km += dist; r.cost += cost; r.gas += gas;
  }

  const out = [];
  for (const r of routes.values()) {
    if (r.trips < minTrips) continue;
    const savedPct = r.gas > 0.01 ? Math.round((r.gas - r.cost) / r.gas * 100) : 0;
    out.push({
      name: Object.entries(r.names).sort((a, b) => b[1] - a[1])[0]?.[0] || 'Trajeto sem nome',
      trips: r.trips,
      avgKm:   +(r.km / r.trips).toFixed(1),
      totalCost: +r.cost.toFixed(2),
      avgCost: +(r.cost / r.trips).toFixed(2),
      avgGasCost: +(r.gas / r.trips).toFixed(2),
      savedPct,
    });
  }
  out.sort((a, b) => b.trips - a.trips || b.totalCost - a.totalCost);
  res.json({
    ok: true, lookbackDays, gasPricePerL: +pGas.toFixed(2), kwhPrice: +pKwh.toFixed(2),
    totalCost: +totalCost.toFixed(2), totalGasCost: +totalGas.toFixed(2), totalTrips,
    trips: out.slice(0, 20),
  });
});

app.delete('/api/autotrips/:tripId', (req, res) => {
  const id = String(req.params.tripId).replace(/\D/g, '');
  if (!id) return res.status(400).json({ error: 'invalid tripId' });
  const idx = autoTripsArr.findIndex(t => t.tripId === id || String(t.startMs) === id);
  console.log(`[delete] AutoTrip lookup id=${id} idx=${idx} total=${autoTripsArr.length}`);
  // Mesmo se já não está em memória (ex: APK reenviou e bridge ignorou), grava
  // tombstone — bloqueia futuras tentativas do APK de inserir esse ID.
  markDeleted('autotrips', id);
  if (idx < 0) return res.status(404).json({ error: 'not found', id, tombstoned: true });
  autoTripsArr.splice(idx, 1);
  const filePath = path.join(AUTOTRIPS_DIR, `${id}.json`);
  try { fs.unlinkSync(filePath); } catch (_) {}
  console.log(`[delete] AutoTrip ${id} removido (tombstone gravado)`);
  res.json({ ok: true });
});

// ── Unir dois auto-trips em um só ────────────────────────────────────────────
app.post('/api/autotrips/merge', (req, res) => {
  try {
    const { tripAId, tripBId } = req.body;
    if (!tripAId || !tripBId) return res.status(400).json({ error: 'missing tripAId or tripBId' });

    const safeA = String(tripAId).replace(/\D/g, '');
    const safeB = String(tripBId).replace(/\D/g, '');
    if (!safeA || !safeB || safeA === safeB) return res.status(400).json({ error: 'invalid ids' });

    const fileA = path.join(AUTOTRIPS_DIR, `${safeA}.json`);
    const fileB = path.join(AUTOTRIPS_DIR, `${safeB}.json`);
    if (!fs.existsSync(fileA)) return res.status(404).json({ error: `trip not found: ${safeA}` });
    if (!fs.existsSync(fileB)) return res.status(404).json({ error: `trip not found: ${safeB}` });

    const dataA = JSON.parse(fs.readFileSync(fileA, 'utf8'));
    const dataB = JSON.parse(fs.readFileSync(fileB, 'utf8'));
    const atA = dataA.autoTrip || {}, samplesA = dataA.samples || [];
    const atB = dataB.autoTrip || {}, samplesB = dataB.samples || [];

    // Garante ordem cronológica: early = mais antigo
    const [earlyId, earlyAT, earlySamples, lateId, lateAT, lateSamples] =
      (atA.startMs || parseInt(safeA,10)) <= (atB.startMs || parseInt(safeB,10))
        ? [safeA, atA, samplesA, safeB, atB, samplesB]
        : [safeB, atB, samplesB, safeA, atA, samplesA];

    const merged = {
      startMs:      earlyAT.startMs,
      endMs:        lateAT.endMs,
      startSocPct:  earlyAT.startSocPct  || 0,
      endSocPct:    lateAT.endSocPct     || 0,
      startFuelPct: earlyAT.startFuelPct || 0,
      endFuelPct:   lateAT.endFuelPct    || 0,
      distKm:   parseFloat(((earlyAT.distKm   ||0)+(lateAT.distKm   ||0)).toFixed(3)),
      timeSec:  Math.round ((earlyAT.timeSec  ||0)+(lateAT.timeSec  ||0)),
      energyKwh:parseFloat(((earlyAT.energyKwh||0)+(lateAT.energyKwh||0)).toFixed(4)),
      regenKwh: parseFloat(((earlyAT.regenKwh ||0)+(lateAT.regenKwh ||0)).toFixed(4)),
      netKwh:   parseFloat(((earlyAT.netKwh   ||0)+(lateAT.netKwh   ||0)).toFixed(4)),
      fuelL:    parseFloat(((earlyAT.fuelL    ||0)+(lateAT.fuelL    ||0)).toFixed(4)),
      startLat: earlyAT.startLat || 0,  startLng: earlyAT.startLng || 0,
      endLat:   lateAT.endLat   || 0,  endLng:   lateAT.endLng   || 0,
    };
    // Campos que NÃO são soma. Sem isto o merge apagava os rótulos e os picos: a
    // viagem virava "? → ?" sem velocidade máxima nem nota, porque `merged` só
    // continha os campos somáveis e o resto sumia junto com os arquivos absorvidos.
    const kpIni = earlyAT.startKp, kpFim = lateAT.endKp;
    if (kpIni) merged.startKp = kpIni;
    if (kpFim) merged.endKp   = kpFim;
    // O nome descreve o percurso inteiro, então recompõe das duas pontas em vez de
    // herdar o do primeiro trecho (que terminava no meio do caminho).
    merged.name = (kpIni && kpFim) ? `${kpIni} → ${kpFim}` : (earlyAT.name || lateAT.name);
    if (!merged.name) delete merged.name;

    const somaN = (a, b) => (a || 0) + (b || 0);
    const maxN  = (a, b) => Math.max(a || 0, b || 0);
    merged.maxSpeedKmh  = maxN(earlyAT.maxSpeedKmh, lateAT.maxSpeedKmh);
    merged.maxPowerPct  = maxN(earlyAT.maxPowerPct, lateAT.maxPowerPct);
    merged.harshAcc     = somaN(earlyAT.harshAcc,   lateAT.harshAcc);
    merged.harshBrake   = somaN(earlyAT.harshBrake, lateAT.harshBrake);
    merged.elevGainM    = somaN(earlyAT.elevGainM,  lateAT.elevGainM);
    merged.elevLossM    = somaN(earlyAT.elevLossM,  lateAT.elevLossM);
    merged.engineOffSec = somaN(earlyAT.engineOffSec, lateAT.engineOffSec);
    merged.parkedInPSec = somaN(earlyAT.parkedInPSec, lateAT.parkedInPSec);
    // Nota do trecho: pondera por distância, senão um trecho de 300 m com nota ruim
    // pesaria igual aos 9 km seguintes. Sem distância nos dois, cai na média simples.
    const dE = earlyAT.distKm || 0, dL = lateAT.distKm || 0;
    const nE = earlyAT.driveScore, nL = lateAT.driveScore;
    if (nE != null && nL != null) {
      merged.driveScore = (dE + dL) > 0
        ? Math.round((nE * dE + nL * dL) / (dE + dL))
        : Math.round((nE + nL) / 2);
    } else if (nE != null || nL != null) merged.driveScore = nE != null ? nE : nL;
    // Temperatura externa é do começo do percurso, não somável.
    if (earlyAT.outsideTempC != null) merged.outsideTempC = earlyAT.outsideTempC;
    if (earlyAT.outsideTemp  != null) merged.outsideTemp  = earlyAT.outsideTemp;

    // Samples unificados — já estão em ordem cronológica
    const mergedSamples = [...earlySamples, ...lateSamples];

    // Recalcula métricas híbridas
    let hybridTimeSec = 0, hybridDistKm = 0;
    for (let i = 1; i < mergedSamples.length; i++) {
      const a = mergedSamples[i-1], b = mergedSamples[i];
      const dt = (b.t||0)-(a.t||0);
      if (dt > 0 && dt < 30 && (a.rpm||0) > 50) {
        hybridTimeSec += dt;
        hybridDistKm  += ((a.spd||0)+(b.spd||0))/2/3600*dt;
      }
    }
    hybridTimeSec = Math.round(hybridTimeSec);
    hybridDistKm  = parseFloat(hybridDistKm.toFixed(3));

    // Marker: lista das tripIds originais antes deste merge. Preserva o
    // histórico se for um merge encadeado (A+B+C — segunda chamada já vê o
    // merged_from da primeira). Bridge depois exibe isso pra usuario saber.
    const prevMergedFrom = Array.isArray(dataA.merged_from) ? dataA.merged_from
                          : Array.isArray(dataB.merged_from) ? dataB.merged_from
                          : [];
    const mergedFrom = Array.from(new Set([...prevMergedFrom, lateId]));

    // Salva arquivo unificado (ID da viagem mais antiga) — hybrid persistido pra
    // boot não recalcular.
    fs.writeFileSync(
      path.join(AUTOTRIPS_DIR, `${earlyId}.json`),
      JSON.stringify({
        tripId: earlyId, autoTrip: merged, samples: mergedSamples,
        hybridTimeSec, hybridDistKm, merged_from: mergedFrom,
      })
    );
    // Remove arquivo da viagem mais recente
    try { fs.unlinkSync(path.join(AUTOTRIPS_DIR, `${lateId}.json`)); } catch (_) {}

    // Marca tombstone pro lateId — sem isso, PWAs com cache local
    // continuam mostrando a viagem absorvida como fantasma. O endpoint
    // GET /api/autotrips devolve esses ids no header X-Tombstones e o
    // PWA limpa o cache.
    markDeleted('autotrips', lateId);

    // Atualiza array em memória
    autoTripsArr = autoTripsArr.filter(t => t.tripId !== earlyId && t.tripId !== lateId);
    const record = { tripId: earlyId, ...merged, hybridTimeSec, hybridDistKm, merged_from: mergedFrom };
    autoTripsArr.push(record);
    autoTripsArr.sort((a, b) => (b.startMs||0)-(a.startMs||0));

    console.log(`[merge] ${earlyId} + ${lateId} → ${earlyId} (${merged.distKm} km, ${mergedSamples.length} amostras, merged_from=${mergedFrom.length})`);
    res.json({ ok: true, mergedId: earlyId, trip: record });
  } catch (e) {
    console.error('[merge]', e);
    res.status(500).json({ error: String(e.message) });
  }
});

// DELETE /api/trips/:id retorna 410 (Gone) — Trip A/B descontinuados.

// ── Renomear trips (PWA → fila → Android) ─────────────────────────────────────
// Carrega fila persistida
let pendingRenames = [];
try {
  if (fs.existsSync(RENAMES_FILE))
    pendingRenames = JSON.parse(fs.readFileSync(RENAMES_FILE, 'utf8')) || [];
} catch (_) {}

function savePendingRenames() {
  // Mantém só últimos 30 dias para não acumular para sempre
  const cutoff = Date.now() - 30 * 86_400_000;
  pendingRenames = pendingRenames.filter(r => r.createdAt > cutoff);
  atomicWriteFileSync(RENAMES_FILE, JSON.stringify(pendingRenames, null, 2));
}

// POST /api/rename  { tripId, type, name, ts? }
// type: 'auto' | 'manual' | 'trip_finish' | 'trip_name'
// trip_finish / trip_name: tripId deve ser 'A' ou 'B'; name opcional para trip_finish
app.post('/api/rename', (req, res) => {
  const { tripId, type, name, ts } = req.body || {};
  if (!tripId) return res.status(400).json({ error: 'tripId obrigatório' });

  const isTripCmd = type === 'trip_finish' || type === 'trip_name';

  // Comandos de trip A/B: validação específica
  if (isTripCmd) {
    if (!['A', 'B'].includes(String(tripId).toUpperCase())) {
      return res.status(400).json({ error: 'tripId deve ser A ou B para trip commands' });
    }
    if (type === 'trip_name' && !name) {
      return res.status(400).json({ error: 'name obrigatório para trip_name' });
    }
  } else {
    // Renames normais: name obrigatório
    if (!name) return res.status(400).json({ error: 'name obrigatório' });
  }

  const trimmed = name ? String(name).trim().slice(0, 80) : '';

  if (type === 'auto') {
    // Atualiza array em memória + marca _updated_ms (pro sync incremental do app).
    const t = autoTripsArr.find(r => r.tripId === String(tripId));
    if (t) { t.name = trimmed; t._updated_ms = Date.now(); }
    // Atualiza arquivo do auto-trip
    const safeId   = String(tripId).replace(/\D/g, '');
    const filePath = path.join(AUTOTRIPS_DIR, `${safeId}.json`);
    if (fs.existsSync(filePath)) {
      try {
        const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        data.autoTrip = data.autoTrip || {};
        data.autoTrip.name = trimmed;
        data._updated_ms = Date.now();
        fs.writeFileSync(filePath, JSON.stringify(data));
      } catch (_) {}
    }
  }
  // type 'manual' (Trip A/B) descontinuado — ignora rename silenciosamente
  // trip_finish / trip_name: sem dados locais para atualizar — o carro aplica ao ligar

  // Enfileira para o Android consumir
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  const entry = { id, tripId: String(tripId), type: type || 'auto', name: trimmed, createdAt: Date.now() };
  if (isTripCmd && ts) entry.ts = Number(ts);
  pendingRenames.push(entry);
  savePendingRenames();
  console.log(`✓ Rename enfileirado: [${type}] ${tripId} → "${trimmed}"`);
  res.json({ ok: true, id });  // id necessário para PWA rastrear status de confirmação
});

