// POST /api/notif/prefs/:device_id  { key, value }
app.post('/api/notif/prefs/:device_id', (req, res) => {
  const id = req.params.device_id;
  const { key, value } = req.body || {};
  const _danger = k => k === '__proto__' || k === 'constructor' || k === 'prototype';
  if (_danger(id) || _danger(key)) return res.status(400).json({ error: 'chave inválida' });
  // Aceita chaves do Haval (NOTIF_DEFAULTS) E as do BYD/Grasi (prefixo `byd_`,
  // inclui as sub-chaves de geofence por local byd_geofence_*_<locId>).
  const isByd = typeof key === 'string' && key.startsWith('byd_');
  if (!key || (!Object.prototype.hasOwnProperty.call(NOTIF_DEFAULTS, key) && !isByd)) return res.status(400).json({ error: 'chave inválida' });
  if (!notifPrefsByDevice[id]) notifPrefsByDevice[id] = {};
  const def = NOTIF_DEFAULTS[key];
  if (Array.isArray(def)) {
    if (!Array.isArray(value)) return res.status(400).json({ error: 'esperado array' });
    notifPrefsByDevice[id][key] = value.map(String);
  } else if (typeof def === 'number') {
    const n = parseInt(value);
    if (isNaN(n)) return res.status(400).json({ error: 'valor numérico inválido' });
    notifPrefsByDevice[id][key] = Math.max(1, Math.min(60, n));
  } else if (isByd && typeof value === 'number') {
    // Prefs numéricas do BYD (ex.: byd_unlocked_min) — minutos/limiares.
    notifPrefsByDevice[id][key] = Math.max(0, Math.min(240, value));
  } else if (isByd && (key === 'byd_role' || key === 'byd_name') && typeof value === 'string') {
    // Identidade do device (string): role={grasi|companion|other}, nome de exibição.
    // Usado pra feature 1 (LA "companion indo até Grasi") e 2 (quem está dirigindo).
    if (key === 'byd_role' && !['grasi', 'companion', 'other'].includes(value)) {
      return res.status(400).json({ error: 'role inválido' });
    }
    notifPrefsByDevice[id][key] = String(value).slice(0, 40);
  } else {
    notifPrefsByDevice[id][key] = !!value;
  }
  saveNotifPrefsByDevice();
  res.json({ ok: true, prefs: getPrefsForDevice(id) });
});

// ── Live Activities: masters GLOBAIS (nível da instância) ─────────────────────
const LA_PREF_KEYS = ['la_charge', 'la_preclimat', 'la_trip', 'la_motor', 'la_security', 'la_infra', 'la_songpro', 'la_songpro_trip', 'preclimat_steps'];
app.get('/api/la-prefs', (_req, res) => {
  const out = {};
  for (const k of LA_PREF_KEYS) out[k] = notifPrefs[k] !== false;   // default ligado
  res.json(out);
});
app.post('/api/la-prefs', (req, res) => {
  const { key, value } = req.body || {};
  if (!LA_PREF_KEYS.includes(key)) return res.status(400).json({ error: 'chave inválida' });
  notifPrefs[key] = !!value;
  saveNotifPrefs();
  res.json({ ok: true, key, value: notifPrefs[key] });
});

// ── Pareamento do carro (provisioning) ────────────────────────────────────
// Celular gera um código curto (one-time, expira). O carro resgata via
// /api/pair/redeem (SEM login) e recebe a config MQTT — assim ninguém digita
// broker/senha no carro nem vê as credenciais lá.
const _pairCodes = new Map();            // code -> { config, expiresAt }
const PAIR_TTL_MS = 10 * 60_000;
const _PAIR_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';   // sem I/O/0/1 (ambíguos)
function _prunePairCodes() { const now = Date.now(); for (const [k, v] of _pairCodes) if (v.expiresAt < now) _pairCodes.delete(k); }
function _genPairCode() {
  const buf = require('crypto').randomBytes(6); let c = '';
  for (let i = 0; i < 6; i++) c += _PAIR_ALPHABET[buf[i] % _PAIR_ALPHABET.length];
  return c;
}
app.post('/api/pair/generate', (_req, res) => {   // autenticado (passa pelo guard /api)
  _prunePairCodes();
  const code = _genPairCode();
  // O CARRO usa o endereço PÚBLICO (CAR_MQTT_*); se não configurado, cai pro local
  // (MQTT_HOST) — que só funciona se o carro estiver na mesma rede do broker.
  const carHost = CAR_MQTT_HOST || MQTT_HOST.replace(/^mqtts?:\/\//, '');
  const carPort = CAR_MQTT_HOST ? CAR_MQTT_PORT : MQTT_PORT;
  const carTls  = CAR_MQTT_HOST ? CAR_MQTT_TLS : MQTT_HOST.startsWith('mqtts://');
  // BRIDGE URL/TOKEN pra HTTP (POST /api/autotrips no fim da viagem).
  // Detecta a URL externa: prioridade BRIDGE_PUBLIC_URL → Tailscale funnel → vazio.
  const bridgeUrl = (process.env.BRIDGE_PUBLIC_URL ||
                     process.env.TAILSCALE_FUNNEL_URL ||
                     'https://bridge.malha.dev').replace(/\/+$/, '');
  // Token: o hash do .env (o bridge aceita tanto plain quanto hash como Bearer).
  const bridgeToken = BRIDGE_TOKEN_HASH || '';
  _pairCodes.set(code, {
    expiresAt: Date.now() + PAIR_TTL_MS,
    config: {
      mqtt_host:    carHost,
      mqtt_port:    carPort,
      mqtt_user:    MQTT_USER,
      mqtt_pass:    MQTT_PASS,
      mqtt_prefix:  MQTT_PREFIX,
      mqtt_tls:     carTls,
      bridge_url:   bridgeUrl,    // pra POST /api/autotrips no fim da viagem
      bridge_token: bridgeToken,  // Authorization: Bearer <token>
    },
  });
  console.log(`[pair] código gerado (expira em ${PAIR_TTL_MS / 60000} min)`);
  res.json({ code, expires_in_sec: Math.round(PAIR_TTL_MS / 1000) });
});
// SEM auth — gateado pelo código one-time + expiração + rate-limit por IP.
const _pairRedeemHits = new Map();
app.post('/api/pair/redeem', (req, res) => {
  const ip = req.ip || 'unknown', now = Date.now();
  const hits = (_pairRedeemHits.get(ip) || []).filter(t => now - t < 60_000);
  if (hits.length >= 10) return res.status(429).json({ error: 'muitas tentativas' });
  hits.push(now); _pairRedeemHits.set(ip, hits);
  _prunePairCodes();
  const code = String((req.body || {}).code || '').toUpperCase().trim();
  const entry = _pairCodes.get(code);
  if (!entry) return res.status(404).json({ error: 'código inválido ou expirado' });
  _pairCodes.delete(code);   // one-time
  console.log(`[pair] código resgatado por ${ip}`);
  res.json({ ok: true, config: entry.config });
});

// ── Reativar Live Activities em andamento ─────────────────────────────────
// Se o usuário dispensou (swipe) uma LA sem querer, re-lança via push-to-start
// com o ESTADO ATUAL (continua dali, como se nunca tivesse saído).
/// Encerra à força a LA de viagem. Existe porque o encerramento normal depende de
/// um update token vivo: quando a LA nasce por push-to-start com o app morto, o
/// bridge nunca recebe token e não consegue empurrar o fim — a LA fica presa "em
/// curso" (aconteceu em 01/08: viagem terminou 13:53 e o card seguia em andamento).
/// Manda o fim por TODOS os tokens conhecidos do tipo, com dispensa imediata.
/// Comanda a conectividade do carro (4G, prioridade de WiFi, trocar de rede).
/// O celular NÃO fala com o Impulse: quem tem acesso ao provider é o EcoTrip dentro
/// do carro, então isto só encaminha por MQTT. retain:false — é evento, não estado;
/// retido faria o comando ser reexecutado a cada reconexão do APK.
// ── Medidor de CPU/RAM do APK (sob demanda, pelo app iOS) ──────────────────
// Existe pra decidir com DADO se vale mover a leitura do CAN pro Impulse. Sem
// medição isso é palpite, e trocar um sistema que funciona por acoplamento novo
// sem evidência sai caro.
let _perf = { ativo: false, inicioMs: 0, fimMs: 0, amostras: [], procs: {},
              nCores: 8, memKind: 'rss', cpuScale: 'system_total', totalProcs: null };
const PERF_MAX_AMOSTRAS = 2000;   // ~66min a 2s; além disso descarta as antigas

// POST /api/overlay — mostra/esconde o botão flutuante de destino no carro.
// body: { mostrar: bool }. Estado guardado aqui pro app refletir sem perguntar ao
// carro; o APK persiste do lado dele e lê no arranque, então sobrevive a reinício.
app.post('/api/overlay', requireAuth, (req, res) => {
  const mostrar = req.body?.mostrar !== false;
  try {
    // retain:true de propósito: se o carro estiver offline agora, ele recebe o
    // estado ao reconectar. Sem retain, o toggle se perderia com o carro dormindo.
    mqttClient.publish(`${MQTT_PREFIX}/cmd/overlay`, mostrar ? '1' : '0', { qos: 1, retain: true });
  } catch (e) { return res.status(502).json({ error: e.message }); }
  state.overlay_destino = mostrar;
  scheduleStateSave();
  console.log(`[overlay] botão flutuante ${mostrar ? 'MOSTRADO' : 'escondido'}`);
  res.json({ ok: true, mostrar });
});

app.post('/api/perf', requireAuth, (req, res) => {
  const ligar = !!req.body?.ativo;
  try {
    mqttClient.publish(`${MQTT_PREFIX}/cmd/perf`, ligar ? '1' : '0', { qos: 1, retain: false });
  } catch (e) { return res.status(502).json({ error: e.message }); }
  if (ligar) _perf = { ativo: true, inicioMs: Date.now(), fimMs: 0, amostras: [], procs: {},
                      nCores: 8, memKind: 'rss', cpuScale: 'system_total', totalProcs: null };
  else { _perf.ativo = false; _perf.fimMs = Date.now(); }
  console.log(`[perf] medição ${ligar ? 'LIGADA' : 'desligada'}`);
  res.json({ ok: true, ativo: ligar });
});

/// Resumo da sessão. Média E pico: média sozinha esconde picos que travam a UI, e
/// pico sozinho não diz se é constante ou pontual.
app.get('/api/perf', requireAuth, (_req, res) => {
  const a = _perf.amostras;
  const nums = (k) => a.map(x => x[k]).filter(v => Number.isFinite(v));
  const med = (v) => v.length ? +(v.reduce((x, y) => x + y, 0) / v.length).toFixed(2) : null;
  const max = (v) => v.length ? +Math.max(...v).toFixed(2) : null;
  const cpu = nums('cpuPct'), pss = nums('pssMb'), heap = nums('heapMb');
  res.json({
    ativo: _perf.ativo,
    inicioMs: _perf.inicioMs || null,
    duracaoS: _perf.inicioMs ? Math.round(((_perf.fimMs || Date.now()) - _perf.inicioMs) / 1000) : 0,
    amostras: a.length,
    cpuPctMedia: med(cpu), cpuPctPico: max(cpu),
    pssMbMedia: med(pss), pssMbPico: max(pss),
    heapMbMedia: med(heap), heapMbPico: max(heap),
    threadsPico: max(nums('threads')),
    // Android inteiro — dá régua pro número do processo e mostra se o gargalo é o
    // aparelho, não o app.
    sysCpuPctMedia: med(nums('sysCpuPct')), sysCpuPctPico: max(nums('sysCpuPct')),
    ramUsadaMbMedia: med(nums('ramUsadaMb')), ramUsadaMbPico: max(nums('ramUsadaMb')),
    ramTotalMb: a.length ? a[a.length - 1].ramTotalMb ?? null : null,
    ramLivreMbMin: nums('ramLivreMb').length ? +Math.min(...nums('ramLivreMb')).toFixed(2) : null,
    load1Pico: max(nums('load1')),
    // Quantas amostras o sistema reportou pressão de memória: é o gatilho de morte
    // de processo que derrubou viagem e recarga.
    lowMemoryAmostras: a.filter(x => x.lowMemory === true).length,
    // Impulse (via resourceUsage, vc7284+). `impulseRamMb` é o número que fecha a
    // comparação: EcoTrip vs Impulse lado a lado, o que nenhum dos dois consegue
    // medir sozinho.
    impulseRamMbMedia: med(nums('impulseRamMb')), impulseRamMbPico: max(nums('impulseRamMb')),
    // CPU/RAM do sistema pela régua DELE — serve de conferência cruzada da minha
    // leitura de /proc/stat. Divergência grande entre as duas é sinal de que uma das
    // contas está errada, e vale saber qual.
    impCpuPctMedia: med(nums('impCpuPct')), impRamPctMedia: med(nums('impRamPct')),
    // ── Tabela por processo ──────────────────────────────────────────────────
    // memKind/cpuScale vão junto de propósito: é RSS (não PSS) e o cpuPct está em
    // % do SISTEMA, escala diferente do cpuPct do EcoTrip (% de um núcleo). Quem
    // desenha precisa rotular certo, senão 10% e 1,2% parecem comparáveis.
    memKind: _perf.memKind, cpuScale: _perf.cpuScale, nCores: _perf.nCores,
    totalProcs: _perf.totalProcs,
    procs: Object.values(_perf.procs).map(a => ({
      pkg: a.pkg, state: a.state, amostras: a.amostras,
      rssMbMedia: a.rssN ? +(a.rssSoma / a.rssN).toFixed(0) : null, rssMbPico: a.rssPico || null,
      cpuPctMedia: a.cpuN ? +(a.cpuSoma / a.cpuN).toFixed(1) : null, cpuPctPico: a.cpuPico || null,
    })).sort((x, y) => (y.rssMbMedia || 0) - (x.rssMbMedia || 0)),
    versaoApk: a.length ? a[a.length - 1].versao : null,
    // Série reduzida pro app desenhar tendência sem baixar 2000 pontos.
    serie: a.filter((_, i) => i % Math.max(1, Math.ceil(a.length / 60)) === 0)
             .map(x => ({ ts: x.ts, cpu: x.cpuPct ?? null, pss: x.pssMb ?? null })),
  });
});

// ── Volta o limite de dados ao piso na virada do ciclo ───────────────────────
// O dono sobe o limite ao longo do mês pra não ser cortado. Na virada o CONSUMO
// zera mas o limite fica onde parou, e um limite alto no dia 1 permite gastar o
// mês inteiro na primeira semana. Aqui ele volta ao piso quando o ciclo vira.
//
// Três coisas que o desenho tem que respeitar:
//
// 1. `cmd/uplink` vai SEM retain. Se o carro estiver dormindo à meia-noite o
//    comando evapora — então não basta disparar no horário: tem que insistir até
//    o carro CONFIRMAR o novo limite no `uplink.limiteMb`.
// 2. O bridge pode estar fora no dia 1. Por isso o gatilho não é "são 00:00", é
//    "o ciclo corrente ainda não foi tratado" — vale quando o bridge voltar.
// 3. Se o dono mexer no limite durante o ciclo, isso é deliberado e vence. Um
//    `setDataLimit` manual carimba o ciclo como tratado e o automático não
//    encosta mais até a próxima virada.
const UPLINK_LIMITE_BASE_MB = parseInt(process.env.UPLINK_LIMITE_BASE_MB || '250', 10);

// ── Limite de dados: mandar não é aplicar ────────────────────────────────────
// `cmd/uplink` sai QoS1 SEM retain, e o APK conecta com `isCleanSession = true`
// (MqttManager.kt) — então enquanto o carro dorme o broker NÃO enfileira nada: o
// comando é descartado e não chega nem quando o carro liga. Foi o que aconteceu
// em 14/09, o dono ajustou com o carro dormindo e não pegou.
//
// E com o carro acordado também falha de vez em quando: no mesmo minuto, um
// `setDataLimit` ficou 30s sem qualquer resposta e o seguinte, idêntico, aplicou
// na hora. Em vez de perseguir a causa (publish silencioso, blip de rede), trato o
// sintoma, que é o mesmo nos dois casos: guardo o valor pedido e reenvio até o
// carro CONFIRMAR em `uplink.limiteMb`. Só tenta com o APK vivo — mandar pra um
// carro dormindo é jogar fora.
let _limitePend = null;   // { mb, desdeMs, ultimaMs, tentativas, origem }
const LIMITE_RETRY_MS  = 20_000;
const LIMITE_DESISTE_MS = 24 * 3600_000;

function _pedeLimiteDados(mb, origem) {
  _limitePend = { mb, desdeMs: Date.now(), ultimaMs: 0, tentativas: 0, origem };
  state.uplink_limite_pendente = { mb, origem, desdeMs: _limitePend.desdeMs };
  _tentaLimiteDados();
}

function _tentaLimiteDados() {
  const p = _limitePend;
  if (!p) return;
  const atual = +state.uplink?.limiteMb || 0;
  if (atual === p.mb) {
    console.log(`[uplink-limite] confirmado ${p.mb}MB pelo carro (${p.origem}, `
      + `${p.tentativas} envio(s), ${Math.round((Date.now() - p.desdeMs) / 1000)}s)`);
    _limitePend = null; delete state.uplink_limite_pendente; scheduleStateSave();
    return;
  }
  if (Date.now() - p.desdeMs > LIMITE_DESISTE_MS) {
    console.warn(`[uplink-limite] desistindo de ${p.mb}MB após 24h sem confirmação (carro segue em ${atual}MB)`);
    _limitePend = null; delete state.uplink_limite_pendente; scheduleStateSave();
    return;
  }
  const apkVivo = state.last_apk_ms > 0 && Date.now() - state.last_apk_ms < 90_000;
  if (!apkVivo || !mqttClient?.connected) return;
  if (Date.now() - p.ultimaMs < LIMITE_RETRY_MS) return;
  p.ultimaMs = Date.now(); p.tentativas++;
  try {
    mqttClient.publish(`${MQTT_PREFIX}/cmd/uplink`,
      JSON.stringify({ metodo: 'setDataLimit', mb: p.mb }), { qos: 1, retain: false });
    console.log(`[uplink-limite] envio #${p.tentativas} de ${p.mb}MB (${p.origem}) — carro em ${atual}MB`);
  } catch (e) { console.warn('[uplink-limite] publish falhou:', e.message); }
}
setInterval(_tentaLimiteDados, 10_000).unref?.();

/** Rótulo do ciclo de faturamento corrente ("2026-09"). Antes do dia de virada
 *  ainda estamos no ciclo que começou no mês anterior. */
function _cicloUplink(diaCiclo) {
  const d = new Date();
  const atrasado = d.getDate() < diaCiclo ? 1 : 0;
  const ref = new Date(d.getFullYear(), d.getMonth() - atrasado, 1);
  return `${ref.getFullYear()}-${String(ref.getMonth() + 1).padStart(2, '0')}`;
}

function _carimbaCicloUplink(motivo) {
  const dia = +state.uplink?.diaCiclo >= 1 ? +state.uplink.diaCiclo : 1;
  const ciclo = _cicloUplink(dia);
  if (state.uplink_limite_ciclo !== ciclo) {
    state.uplink_limite_ciclo = ciclo;
    scheduleStateSave();
    console.log(`[uplink-limite] ciclo ${ciclo} carimbado (${motivo})`);
  }
}

function _reporLimiteDoCiclo() {
  const u = state.uplink;
  if (!u) return;
  const dia = +u.diaCiclo >= 1 ? +u.diaCiclo : 1;
  const ciclo = _cicloUplink(dia);
  // Primeira execução: carimba o ciclo corrente SEM mandar nada. Sem isto, ligar
  // esta rotina no meio do mês derrubaria o limite que o dono acabou de subir —
  // exatamente o estrago que ela existe pra evitar.
  if (!state.uplink_limite_ciclo) return _carimbaCicloUplink('primeira execução — ciclo corrente preservado');
  if (state.uplink_limite_ciclo === ciclo) return;

  const atual = +u.limiteMb || 0;
  if (atual > 0 && atual <= UPLINK_LIMITE_BASE_MB) {
    return _carimbaCicloUplink(`já estava em ${atual}MB`);
  }
  if (_limitePend?.mb === UPLINK_LIMITE_BASE_MB) return;   // já insistindo
  console.log(`[uplink-limite] ciclo virou para ${ciclo} (estava ${atual}MB)`);
  _pedeLimiteDados(UPLINK_LIMITE_BASE_MB, `virada do ciclo ${ciclo}`);
}
setInterval(_reporLimiteDoCiclo, 5 * 60_000).unref?.();
// Uma passada no arranque, depois que o retained do uplink já chegou: sem isto a
// primeira avaliação só aconteceria até 5 min depois do boot, e o carimbo inicial
// (que protege o ciclo corrente) ficava dependendo da sorte de o processo durar.
setTimeout(_reporLimiteDoCiclo, 90_000).unref?.();

app.get('/api/silence-zones', (_req, res) => {
  // `dentro` diz qual zona contém o carro AGORA — o app mostra isso na lista, e é
  // também o que torna a regra verificável sem esperar 20min de silêncio.
  const atual = _zonaDeSilencio();
  res.json({
    zones: _silenceZones.map(z => ({ ...z, dentro: !!atual && atual.id === z.id })),
    carro: { lat: +state.gps_lat || null, lng: +state.gps_lng || null },
    emZona: atual ? atual.id : null,
  });
});

app.post('/api/silence-zones', requireAuth, (req, res) => {
  const b = req.body || {};
  const nome = String(b.name || '').trim();
  if (!nome) return res.status(400).json({ error: 'name obrigatório' });
  // Sem lat/lng no corpo, usa onde o carro está — é o caso de uso real: o dono
  // está no lugar, o carro acabou de emudecer, e ele marca dali mesmo.
  const lat = b.lat !== undefined ? +b.lat : +state.gps_lat;
  const lng = b.lng !== undefined ? +b.lng : +state.gps_lng;
  if (!_validLatLng(lat, lng)) return res.status(400).json({ error: 'sem coordenada válida (nem no corpo nem no carro)' });
  const raio = Math.min(2000, Math.max(50, parseInt(b.radiusM, 10) || 250));
  const perto = _silenceZones.find(z => haversineM(lat, lng, z.lat, z.lng) < 100);
  if (perto) return res.json({ ok: true, zone: perto, jaExistia: true });
  const z = { id: 'z-' + Date.now().toString(36), name: nome.slice(0, 60), lat, lng, radiusM: raio, createdMs: Date.now() };
  _silenceZones.push(z); _saveSilenceZones();
  console.log(`[zona-silencio] criada '${z.name}' (${z.lat.toFixed(5)},${z.lng.toFixed(5)} r=${z.radiusM}m)`);
  res.json({ ok: true, zone: z });
});

app.delete('/api/silence-zones/:id', requireAuth, (req, res) => {
  const i = _silenceZones.findIndex(z => z.id === req.params.id);
  if (i < 0) return res.status(404).json({ error: 'não encontrada' });
  const [fora] = _silenceZones.splice(i, 1); _saveSilenceZones();
  console.log(`[zona-silencio] removida '${fora.name}'`);
  res.json({ ok: true });
});

app.patch('/api/silence-zones/:id', requireAuth, (req, res) => {
  const z = _silenceZones.find(x => x.id === req.params.id);
  if (!z) return res.status(404).json({ error: 'não encontrada' });
  if (req.body?.name)    z.name    = String(req.body.name).trim().slice(0, 60);
  if (req.body?.radiusM) z.radiusM = Math.min(2000, Math.max(50, parseInt(req.body.radiusM, 10) || z.radiusM));
  _saveSilenceZones();
  res.json({ ok: true, zone: z });
});

app.post('/api/uplink/cmd', requireAuth, (req, res) => {
  const metodo = String(req.body?.metodo || '');
  // API completa do Impulse (vc7261). setWifiEnabled fica FORA de propósito: desligar
  // o WiFi pode cortar o próprio canal remoto quando o carro só tem internet por WiFi
  // — comando que se auto-sabota não entra por HTTP. addWifi também fica fora: o
  // próprio handoff diz que não persiste neste head unit (WifiManager.addNetwork
  // devolve netId e a rede não aparece nas salvas).
  const OK = ['setMobileControl', 'setMobileBlock', 'setBlockOnWifi', 'setBlockOnProjection',
              'setAutoblock', 'setDataLimit', 'setCycleDay',
              'scanWifi', 'connectWifi', 'listSavedWifi', 'setWifiPriority',
              // setWifiEnabled(false) pode cortar o próprio canal remoto se o carro
              // só tem internet por WiFi. Vai atrás de confirmação dupla no app; aqui
              // o guard é logar alto, porque depois dele talvez não haja mais log.
              // addWifi ficou FORA: testado em 04/08 e não persiste neste head unit
              // (addNetwork devolve netId e a rede não entra nas salvas). Expor um
              // comando que sempre falha só gera dúvida sobre o que funciona.
              'setWifiEnabled'];
  if (!OK.includes(metodo)) return res.status(400).json({ error: 'metodo inválido', aceitos: OK });
  const msg = { metodo };
  if (req.body?.valor !== undefined) msg.valor = !!req.body.valor;
  if (req.body?.ssid) msg.ssid = String(req.body.ssid).slice(0, 64);
  if (metodo === 'connectWifi' && !msg.ssid) return res.status(400).json({ error: 'connectWifi exige ssid' });

  const PRECISA_BOOL = ['setMobileControl', 'setMobileBlock', 'setBlockOnWifi',
                        'setBlockOnProjection', 'setAutoblock', 'setWifiPriority',
                        'setWifiEnabled'];
  if (PRECISA_BOOL.includes(metodo) && msg.valor === undefined) {
    return res.status(400).json({ error: metodo + ' exige valor (bool)' });
  }
  for (const k of ['mb', 'gb', 'day']) {
    if (req.body?.[k] !== undefined) msg[k] = parseInt(req.body[k], 10) || 0;
  }
  if (metodo === 'setDataLimit' && msg.mb === undefined && msg.gb === undefined) {
    return res.status(400).json({ error: 'setDataLimit exige mb ou gb' });
  }
  if (metodo === 'setCycleDay' && !(msg.day >= 1 && msg.day <= 31)) {
    return res.status(400).json({ error: 'setCycleDay exige day entre 1 e 31' });
  }
  try {
    mqttClient.publish(`${MQTT_PREFIX}/cmd/uplink`, JSON.stringify(msg), { qos: 1, retain: false });
  } catch (e) { return res.status(502).json({ error: e.message }); }
  // Ajuste manual do dono vence o automático até a próxima virada.
  if (metodo === 'setDataLimit') {
    _carimbaCicloUplink('limite ajustado na mão');
    // Registra como pendente pra INSISTIR até o carro confirmar. O publish acima
    // conta como a primeira tentativa — sem isto, um comando perdido (carro
    // dormindo, blip) sumia em silêncio e o app mostrava sucesso.
    const mbPedido = msg.mb !== undefined ? msg.mb : (msg.gb || 0) * 1024;
    if (mbPedido > 0) {
      _pedeLimiteDados(mbPedido, 'app');
      if (_limitePend) { _limitePend.ultimaMs = Date.now(); _limitePend.tentativas = 1; }
    }
  }
  if (metodo === 'setWifiEnabled' && msg.valor === false) {
    console.warn('[uplink] ⚠️ DESLIGANDO o WiFi do carro — se ele não tiver 4G, o acesso remoto cai aqui');
  }
  console.log(`[uplink] comando ${metodo}${msg.ssid ? ' ssid=' + msg.ssid : ''}${msg.valor !== undefined ? ' valor=' + msg.valor : ''}`);
  // Só o encaminhamento é confirmado aqui. O resultado real chega em
  // uplink/result e no uplink/status seguinte — o app lê de lá.
  res.json({ ok: true, enviado: msg, aviso: 'resultado chega em /api/state (uplink) em alguns segundos' });
});

app.post('/api/la/end-trip', async (req, res) => {
  if (!apnsLive.enabled) return res.status(503).json({ error: 'apns desativado' });
  const tinhaToken = apnsLive.hasUpdateToken(TRIP_LA_TYPE);
  const cs = _tripContentState(_lastTripSnapshot || autoTripsArr[0] || {}, false);
  let erro = tinhaToken ? null : 'sem update token — o app precisa estar aberto pra registrar um';
  if (tinhaToken) {
    try {
      await apnsLive.pushUpdate(TRIP_LA_TYPE, {}, cs, { isFinal: true, dismissalDate: Date.now() });
    } catch (e) { erro = e.message; }
  }
  _tripActive = false;
  _cancelTripEndTimer();
  apnsLive.clearUpdateTokensByType(TRIP_LA_TYPE);
  console.log(`[trip-la] encerramento forçado (token=${tinhaToken}${erro ? ', erro: ' + erro : ''})`);
  res.json({ ok: !erro, tinhaToken, erro, current_trip: state.current_trip ? 'presente' : 'null' });
});

app.post('/api/la/relaunch', async (req, res) => {
  if (!apnsLive.enabled) return res.status(503).json({ error: 'apns desativado' });
  const done = [];
  try {
    if (state.charging_state === 'Carregando' && notifPrefs.la_charge !== false) {
      // iOS ignora pushStart se já existe LA do mesmo tipo "viva" (mesmo que
      // o user tenha dispensado por swipe). Encerra a existente PRIMEIRO
      // (isFinal + dismissalDate imediata) e DEPOIS cria nova. Garante que
      // o card reaparece visível ao usuário.
      try {
        await apnsLive.pushUpdate('ChargeActivityAttributes', {}, _chargeContentState(),
          { isFinal: true, dismissalDate: Date.now() });
      } catch (_) {}
      // Pequeno delay pra iOS processar o end antes do start.
      await new Promise(r => setTimeout(r, 250));
      await apnsLive.pushStart('ChargeActivityAttributes', '', { carName: 'Haval H6 PHEV' }, _chargeContentState(),
        { staleDate: Date.now() + 3600_000, alert: { title: '⚡ Recarga', body: 'Card reativado — acompanhe na tela bloqueada.' } });
      done.push('recarga');
    }
    if (_tripActive && notifPrefs.la_trip !== false) {
      await apnsLive.pushStart(TRIP_LA_TYPE, '', { carName: 'Haval H6 PHEV' }, _tripContentState(_lastTripSnapshot || {}, true),
        { staleDate: Date.now() + 6 * 3600_000, alert: { title: '🚗 Viagem', body: 'Card reativado.' } });
      done.push('viagem');
    }
    if (_motorActive && notifPrefs.la_motor !== false) {
      await apnsLive.pushStart(MOTOR_LA_TYPE, '', { carName: 'Haval H6 PHEV' }, _motorContentState(true),
        { staleDate: Date.now() + 3 * 3600_000, alert: { title: '🔑 Motor ligado', body: 'Card reativado.' } });
      done.push('motor');
    }
    if (['starting', 'engine_on', 'cooling'].includes(preclimatStatus.phase) && _activeSched && notifPrefs.la_preclimat !== false) {
      const pdev = _activeSched.device_id || '';
      await apnsLive.pushStart(PRECLIMAT_LA_TYPE, pdev, _preclimatAttributes(), _preclimatContentState(),
        { staleDate: preclimatStatus.endsAtMs || (Date.now() + 1800_000), alert: { title: '❄️ Pré-climatização', body: 'Card reativado.' },
          allow: pdev ? undefined : (d) => getPrefsForDevice(d).la_preclimat !== false });
      done.push('pre-clima');
    }
    if (_securityActive && notifPrefs.la_security !== false) {
      _securityActive = false; _evalSecurityAlert();   // re-cria se ainda há problema
      done.push('seguranca');
    }
    // "Voltar ao carro": se o card estava vivo (talvez dispensado por swipe),
    // recria com os números reais já conhecidos. Se NÃO estava vivo, deixa o
    // eval decidir — só abre com fix fresco do dono e >100m. Nunca fabrica 0m.
    if (_parkedLoc && notifPrefs.la_parking !== false) {
      if (_parkingActive && _parkingLast.dist >= 0) {
        try {
          await apnsLive.pushUpdate(PARKING_LA_TYPE, {}, _parkingContentState(_parkingLast.dist, _parkingLast.brg),
            { isFinal: true, dismissalDate: Date.now() });
        } catch (_) {}
        await new Promise(r => setTimeout(r, 250));
        await apnsLive.pushStart(PARKING_LA_TYPE, '', { carName: 'Haval H6 PHEV' },
          _parkingContentState(_parkingLast.dist, _parkingLast.brg),
          { staleDate: Date.now() + 12 * 3600_000, alert: { title: '🅿️ Voltar ao carro', body: 'Card reativado — acompanhe na tela bloqueada.' } });
        done.push('estacionamento');
      } else {
        const was = _parkingActive;
        _evalParkingLA();
        if (_parkingActive && !was) done.push('estacionamento');
      }
    }
    // BYD Song Pro (Grasi) — só relança se sessão ativa e algum device opt-in.
    if (_songProSession && _songProSession.active && _songProEnabled()) {
      const cs = _songProContentState(true);
      await apnsLive.pushStart(SONGPRO_LA_TYPE, '', { carName: 'BYD Song Pro' }, cs,
        { staleDate: Date.now() + 6 * 3600_000, alert: { title: '🔵 BYD da Grasi carregando', body: 'Card reativado.' },
          allow: (deviceId) => getPrefsForDevice(deviceId).la_songpro === true });
      done.push('song-pro');
    }
  } catch (e) { return res.status(500).json({ error: e.message }); }
  console.log(`[la-relaunch] reativadas: ${done.join(', ') || '(nenhuma ativa)'}`);
  res.json({ ok: true, relaunched: done });
});

// ── 🤖 AI local (Ollama) — pergunte sobre viagens/recargas ────────────────
// 100% local: nenhum dado sai do Mac Mini. Modelo configurável via .env
// (default llama3.1:8b). Bridge monta contexto com últimas viagens/recargas/
// estado e manda pro Ollama. Resposta em PT-BR.
const OLLAMA_URL   = process.env.OLLAMA_URL   || 'http://localhost:11434';
const OLLAMA_MODEL = process.env.OLLAMA_MODEL || 'llama3.1:8b';

// Tier de nuvem (Claude via CLI `claude -p`, mesmo padrão do whats-assistant):
// usado como fallback quando o Ollama falha e como motor primário pra perguntas
// analíticas/complexas. Desliga com AI_CLOUD_FALLBACK=0.
const CLAUDE_BIN        = process.env.CLAUDE_BIN || '/usr/local/bin/claude';
const CLAUDE_CHAT_MODEL = process.env.CLAUDE_CHAT_MODEL || 'sonnet';
const AI_CLOUD          = (process.env.AI_CLOUD_FALLBACK ?? '1') !== '0';

// Roda o claude CLI com o prompt no stdin e devolve o texto puro da resposta.
// USER/LOGNAME explícitos: sob pm2 o lookup da credencial no Keychain quebra sem
// eles. cwd neutro pra não carregar CLAUDE.md de algum projeto.
function _askClaude(sys, userMsgs, timeoutMs = 60_000) {
  const { execFile } = require('child_process');
  const os = require('os');
  return new Promise((resolve, reject) => {
    const u = os.userInfo().username;
    const env = { ...process.env, USER: process.env.USER || u, LOGNAME: process.env.LOGNAME || u };
    const thread = userMsgs
      .map(m => `${m.role === 'user' ? 'Usuário' : 'Assistente'}: ${m.content}`)
      .join('\n\n');
    const prompt = `${sys}\n\nHISTÓRICO DA CONVERSA:\n${thread}\n\nResponda à última mensagem do usuário em português, de forma direta e concisa.`;
    const child = execFile(CLAUDE_BIN, ['-p', '--model', CLAUDE_CHAT_MODEL],
      { timeout: timeoutMs, maxBuffer: 1024 * 1024, cwd: os.tmpdir(), env },
      (err, stdout, stderr) => err
        ? reject(new Error(`${err.message} ${String(stderr).slice(0, 200)}`))
        : resolve(String(stdout).trim()));
    child.stdin.on('error', () => {});   // evita EPIPE virar uncaught e derrubar o processo
    child.stdin.write(prompt);
    child.stdin.end();
  });
}

// Gate de complexidade: perguntas longas ou analíticas/comparativas escalam pro
// Claude direto; perguntas simples (status/lookup) ficam no Ollama local.
function _aiIsComplex(userMsgs) {
  const last = (userMsgs[userMsgs.length - 1]?.content || '');
  if (last.length > 280) return true;
  // Analíticas/comparativas OU agregadas/históricas (totais por mês, contagens,
  // gastos, extremos) — precisam do histórico completo, que só vai pro Claude.
  return /\b(compar|por que|porqu[êe]|analis|explic|tend[êe]nc|recomend|sugest|proje[çc]|melhor|pior|vale a pena|deveria|estrat[ée]g|otimiz|m[ée]dia|padr[ãa]o|total|totais|quanto|gast|economi|maior|menor|mais long|mais cara?|mais barat|quant[ao]s|no m[êe]s|por m[êe]s|neste m[êe]s|esse m[êe]s|este m[êe]s|jan|fev|mar[çc]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro|semana|ano|hist[óo]ric|desde)/i.test(last);
}

// Resumo compacto de uma viagem — agrega samples por modo (HEV/EV) e calcula
// km/L só do HEV (assumindo que todo combustível foi queimado em HEV, que é
// quase sempre verdade num PHEV: motor ICE só liga em HEV).
function _summarizeTrip(tripFile) {
  try {
    const t = JSON.parse(fs.readFileSync(tripFile, 'utf8'));
    const a = t.autoTrip || {};
    const ss = t.samples || [];
    let evDist = 0, evTime = 0, hevDist = 0, hevTime = 0;
    for (let i = 1; i < ss.length; i++) {
      const dt = Math.max(0, (ss[i].t || 0) - (ss[i-1].t || 0));
      const spd = +ss[i].spd || 0;
      const dKm = spd * dt / 3600;
      if ((+ss[i].rpm || 0) > 0) { hevDist += dKm; hevTime += dt; }
      else                       { evDist  += dKm; evTime  += dt; }
    }
    const kmLhev = (a.fuelL > 0) ? (hevDist / a.fuelL) : null;
    return {
      startMs: a.startMs, endMs: a.endMs,
      origem: a.startAddress || null, destino: a.endAddress || null,
      distKm: +(a.distKm || 0).toFixed(1),
      timeMin: Math.round((a.timeSec || 0) / 60),
      fuelL: +(a.fuelL || 0).toFixed(2),
      netKwh: +(a.netKwh || 0).toFixed(2),
      maxSpeedKmh: a.maxSpeedKmh,
      socStart: a.startSocPct, socEnd: a.endSocPct,
      modo_ev:  { distKm: +evDist.toFixed(1),  timeMin: Math.round(evTime/60)  },
      modo_hev: { distKm: +hevDist.toFixed(1), timeMin: Math.round(hevTime/60), kmL: kmLhev ? +kmLhev.toFixed(2) : null },
    };
  } catch (e) { return null; }
}

function _buildAiContext(N = 10) {
  // Últimas N viagens
  const files = fs.readdirSync(AUTOTRIPS_DIR)
    .filter(f => f.endsWith('.json'))
    .sort()
    .slice(-N);
  const trips = files.map(f => _summarizeTrip(path.join(AUTOTRIPS_DIR, f))).filter(Boolean);

  // Últimas N recargas
  let charges = [];
  try {
    const cj = JSON.parse(fs.readFileSync(CHARGES_FILE, 'utf8'));
    charges = (cj.charges || []).slice(-N).map(c => ({
      timestamp: c.timestamp,
      duration_min: Math.round((c.duration_sec || 0) / 60),
      energy_kwh_bateria: c.energy_kwh,
      energy_kwh_medidor: c.charger_kwh || null,
      soc: `${c.soc_start}→${c.soc_end}%`,
      avg_power_kw: c.avg_power_kw,
      local: c.location_name || null,
      custo_brl: c.cost_override?.total || null,
      preco_kwh_efetivo: (c.cost_override?.total && c.energy_kwh > 0) ? +(c.cost_override.total / c.energy_kwh).toFixed(2) : null,
    }));
  } catch (_) {}

  const cur = {
    soc_pct: state.soc_pct,
    charging_state: state.charging_state,
    charge_power_kw: state.charge_power_kw,
    odometer_km: state.odometer_km,
    autonomy_ev_km: state.autonomy_ev_km,
    autonomy_ice_km: state.autonomy_ice_km,
    fuel_l: state.fuel_l,
    gps: (state.gps_lat && state.gps_lng) ? { lat: state.gps_lat, lng: state.gps_lng } : null,
  };

  // Locais salvos (casa/trabalho/etc) — dão ao modelo as coordenadas pra resolver
  // perguntas como "chego no trabalho?". Distância real de estrada vem em `rotas`
  // (preenchido pelo resolver quando a pergunta é de autonomia/trajeto).
  const locais = knownPlaces
    .filter(p => Number.isFinite(+p.lat) && Number.isFinite(+p.lng))
    .map(p => ({ nome: p.name, lat: +p.lat, lng: +p.lng }));

  return {
    now_iso: new Date().toISOString(),
    atual: cur,
    locais_salvos: locais,
    viagens_recentes: trips,
    recargas_recentes: charges,
  };
}

// Preços correntes pra estimar custo de viagem (kWh líquido + combustível).
function _aiPrices() {
  return {
    pKwh: +state.battery_avg_price_per_kwh || +state.price_kwh || 0,
    pGas: +state.tank_avg_price_per_l      || +state.price_gas_per_l || 0,
  };
}
function _ymSaoPaulo(ms) {
  if (!ms) return null;
  try {
    const p = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit' }).format(new Date(ms));
    return p.slice(0, 7); // YYYY-MM
  } catch { return new Date(ms).toISOString().slice(0, 7); }
}

// Listas COMPACTAS de TODAS as viagens/recargas (sem samples) — pra perguntas
// históricas/agregadas (totais, comparações, extremos) que a janela de
// `viagens_recentes` (últimas N) não cobre. Lê os arrays em memória, não disco.
function _aiFullHistory() {
  const { pKwh, pGas } = _aiPrices();
  const r1 = (n) => Math.round((+n || 0) * 10) / 10;
  const r2 = (n) => Math.round((+n || 0) * 100) / 100;
  const viagens = [...autoTripsArr]
    .sort((a, b) => (a.startMs || 0) - (b.startMs || 0))
    .map(t => {
      const net = +t.netKwh || 0, fuel = +t.fuelL || 0;
      return {
        data: _ymSaoPaulo(t.startMs), ms: t.startMs,
        rota: t.name || (t.startKp && t.endKp ? `${t.startKp} → ${t.endKp}` : null),
        km: r1(t.distKm), min: Math.round((+t.timeSec || 0) / 60),
        netKwh: r2(net), fuelL: r2(fuel), custoBrl: r2(net * pKwh + fuel * pGas),
        soc: `${t.startSocPct}→${t.endSocPct}%`, vmax: r1(t.maxSpeedKmh), score: t.driveScore,
      };
    });
  let recargas = [];
  try {
    recargas = [...chargesArr]
      .sort((a, b) => (a.timestamp_ms || 0) - (b.timestamp_ms || 0))
      .map(c => {
        const kwh = +c.energy_kwh || 0;
        const custo = (c.cost_override && c.cost_override.total != null) ? +c.cost_override.total : r2(kwh * pKwh);
        return {
          data: _ymSaoPaulo(c.timestamp_ms), ms: c.timestamp_ms,
          local: c.location_name || null, min: Math.round((+c.duration_sec || 0) / 60),
          kwh: r2(kwh), soc: `${c.soc_start}→${c.soc_end}%`,
          potKw: r2(c.avg_power_kw), custoBrl: r2(custo),
        };
      });
  } catch (_) {}
  return { viagens, recargas };
}

// Rollups por mês (YYYY-MM) sobre TODO o histórico — payload pequeno que resolve
// "quanto gastei/quantos km/quantas recargas em <mês>" sem depender da lista cheia.
function _aiMonthlyRollups() {
  const { pKwh, pGas } = _aiPrices();
  const r1 = (n) => Math.round((+n || 0) * 10) / 10;
  const r2 = (n) => Math.round((+n || 0) * 100) / 100;
  const m = {};
  const slot = (ym) => (m[ym] = m[ym] || { viagens: 0, km: 0, viagem_custo_brl: 0, net_kwh: 0, fuel_l: 0, recargas: 0, recarga_kwh: 0, recarga_custo_brl: 0 });
  for (const t of autoTripsArr) {
    const ym = _ymSaoPaulo(t.startMs); if (!ym) continue;
    const s = slot(ym); const net = +t.netKwh || 0, fuel = +t.fuelL || 0;
    s.viagens++; s.km += +t.distKm || 0; s.net_kwh += net; s.fuel_l += fuel;
    s.viagem_custo_brl += net * pKwh + fuel * pGas;
  }
  for (const c of chargesArr) {
    const ym = _ymSaoPaulo(c.timestamp_ms); if (!ym) continue;
    const s = slot(ym); const kwh = +c.energy_kwh || 0;
    s.recargas++; s.recarga_kwh += kwh;
    s.recarga_custo_brl += (c.cost_override && c.cost_override.total != null) ? +c.cost_override.total : kwh * pKwh;
  }
  const out = {};
  for (const ym of Object.keys(m).sort()) {
    const s = m[ym];
    out[ym] = { viagens: s.viagens, km: r1(s.km), viagem_custo_brl: r2(s.viagem_custo_brl),
      net_kwh: r2(s.net_kwh), fuel_l: r2(s.fuel_l), recargas: s.recargas,
      recarga_kwh: r2(s.recarga_kwh), recarga_custo_brl: r2(s.recarga_custo_brl) };
  }
  return out;
}

// Resolve os destinos citados numa pergunta de autonomia/trajeto e calcula a
// distância real de estrada de cada perna (GPS atual → A → B …). Devolve null
// quando a pergunta não é sobre trajeto/autonomia ou não há GPS do carro.
//   1. gate de intenção (regex) pra não geocodar pergunta de status.
//   2. extrai os destinos em ordem (Claude, JSON) — texto livre tipo "Jardins Lisboa".
//   3. resolve cada um: match em locais_salvos primeiro, senão _geocode.
//   4. encadeia as pernas com _routeElevation e acumula km.
async function _resolveRouteContext(question) {
  const q = String(question || '');
  if (!/\b(consigo|chego|chegar|alcan[çc]|autonom|d[áa] pra ir|range|sem chegar|aguenta|quantos? km|dist[âa]ncia|vai dar|volto|ida e volta)\b/i.test(q))
    return null;
  const oLat = +state.gps_lat, oLng = +state.gps_lng;
  if (!oLat || !oLng) return null;
  if (!AI_CLOUD) return null;   // extração depende do Claude; sem nuvem, pula

  // Extrai os destinos em ordem de visita, mapeando pra um local salvo quando
  // fizer sentido (ex.: "trabalho" → nome da empresa salva, "casa" → "Casa").
  const savedNames = knownPlaces.filter(p => p.name && p.lat && p.lng).map(p => p.name);
  let dests = [];
  try {
    const raw = await _askClaude(
      'Extraia APENAS os destinos/lugares mencionados na pergunta abaixo, na ordem de visita. ' +
      'LOCAIS SALVOS do usuário: ' + JSON.stringify(savedNames) + '. ' +
      'Se um destino citado corresponder a um local salvo (inclusive por sinônimo óbvio — ' +
      '"trabalho"/"serviço" → empresa, "casa"/"em casa" → residência), retorne o NOME SALVO exato. ' +
      'Senão, retorne o texto do lugar como veio. ' +
      'Responda SÓ um array JSON de strings, sem texto extra. Se nenhum lugar for citado, responda [].',
      [{ role: 'user', content: q }], 20_000);
    const m = raw.match(/\[[\s\S]*\]/);
    if (m) dests = JSON.parse(m[0]).filter(s => typeof s === 'string' && s.trim()).slice(0, 4);
  } catch (e) { console.warn('[ai] extração de destinos falhou:', e.message); return null; }
  if (!dests.length) return null;

  // Resolve coords: locais salvos primeiro (match por nome), senão geocoding.
  const resolved = [];
  for (const d of dests) {
    const dl = d.trim().toLowerCase();
    const kp = knownPlaces.find(p => p.name && p.lat && p.lng &&
      (p.name.trim().toLowerCase() === dl || p.name.trim().toLowerCase().includes(dl) || dl.includes(p.name.trim().toLowerCase())));
    if (kp) { resolved.push({ nome: kp.name, lat: +kp.lat, lng: +kp.lng, fonte: 'salvo' }); continue; }
    const g = await _geocode(d);
    if (g) resolved.push({ nome: g.name || d, lat: g.lat, lng: g.lng, fonte: 'geocode' });
    else   resolved.push({ nome: d, lat: null, lng: null, fonte: 'não encontrado' });
  }

  // Encadeia as pernas a partir do GPS atual.
  const pernas = [];
  let pLat = oLat, pLng = oLng, acc = 0, origem = 'posição atual';
  for (const r of resolved) {
    if (r.lat == null) { pernas.push({ de: origem, para: r.nome, status: 'destino não localizado' }); continue; }
    const leg = await _routeElevation(pLat, pLng, r.lat, r.lng);
    if (!leg) { pernas.push({ de: origem, para: r.nome, status: 'rota indisponível' }); origem = r.nome; pLat = r.lat; pLng = r.lng; continue; }
    acc += leg.distanceKm;
    pernas.push({
      de: origem, para: r.nome,
      distancia_km: leg.distanceKm, duracao_min: leg.durationMin,
      subida_m: leg.climbM, descida_m: leg.descentM,
      acumulado_km: +acc.toFixed(1),
    });
    origem = r.nome; pLat = r.lat; pLng = r.lng;
  }
  return { origem: 'posição GPS atual do carro', pernas, distancia_total_km: +acc.toFixed(1) };
}

app.post('/api/ai/ask', async (req, res) => {
  // Aceita 2 formatos:
  //   { question: '...' }       — single-turn (backward compat).
  //   { messages: [...] }       — multi-turn (chat com histórico).
  // Em multi-turn, o cliente envia toda a thread (user+assistant alternados);
  // o bridge antepõe um system prompt com o contexto atual.
  let userMsgs;
  if (Array.isArray(req.body?.messages) && req.body.messages.length > 0) {
    userMsgs = req.body.messages
      .filter(m => m && (m.role === 'user' || m.role === 'assistant') && m.content)
      .map(m => ({ role: m.role, content: String(m.content).slice(0, 4000) }));
    if (!userMsgs.length) return res.status(400).json({ error: 'messages vazias' });
  } else {
    const question = (req.body?.question || '').toString().trim();
    if (!question) return res.status(400).json({ error: 'question vazia' });
    if (question.length > 2000) return res.status(400).json({ error: 'question muito longa' });
    userMsgs = [{ role: 'user', content: question }];
  }
  // Limita histórico ao máximo de 20 turnos pra evitar context window estourar.
  if (userMsgs.length > 20) userMsgs = userMsgs.slice(-20);

  const ctx = _buildAiContext(req.body?.context_size || 10);
  // Rollups mensais de TODO o histórico — payload pequeno, fica sempre no
  // contexto (resolve "quanto gastei/quantos km em <mês>" em qualquer motor).
  ctx.totais_mensais = _aiMonthlyRollups();

  // Resolve trajeto/distâncias quando a pergunta é de autonomia (camada 2).
  const lastUser = [...userMsgs].reverse().find(m => m.role === 'user')?.content || '';
  try {
    const rotas = await _resolveRouteContext(lastUser);
    if (rotas) ctx.rotas = rotas;
  } catch (e) { console.warn('[ai] resolver de rota falhou:', e.message); }

  // Roteamento entre motor local (Ollama) e nuvem (Claude):
  //   prefer=local → só Ollama  ·  prefer=cloud → Claude (fallback Ollama)
  //   prefer=auto (default) → Ollama; escala pro Claude se a pergunta for
  //   complexa OU se o Ollama falhar.
  const prefer = (req.body?.prefer || 'auto').toString();
  const cloudFirst = AI_CLOUD && (prefer === 'cloud' || (prefer === 'auto' && _aiIsComplex(userMsgs)));

  // Histórico COMPLETO compacto (todas as viagens/recargas) só quando vai pro
  // Claude — bloataria a janela curta do Ollama. Atende extremos/comparações
  // ("viagem mais longa de todas", "recarga mais cara") além dos rollups.
  if (cloudFirst) {
    const h = _aiFullHistory();
    ctx.viagens_todas = h.viagens;
    ctx.recargas_todas = h.recargas;
  }

  const sys = `Você é um assistente especializado em telemetria de carros híbridos plug-in (PHEV) integrado ao app Haval EcoTrip. Responda em português brasileiro, com clareza e precisão. Use APENAS os dados fornecidos abaixo no JSON de contexto pra responder. Não invente números. Se a pergunta exigir algo fora do contexto, diga.

CONTEXTO (JSON):
${JSON.stringify(ctx, null, 2)}

DICAS:
- "Modo HEV" = motor térmico ligado (rpm > 0). "Modo EV" = elétrico puro.
- "kWh efetivo" da recarga = custo / energia que entrou na bateria.
- Datas em viagens_recentes.startMs/endMs são milissegundos epoch (use Date(ms).toLocaleString se precisar formatar).
- "atual.autonomy_ev_km" é a autonomia elétrica estimada AGORA. "atual.soc_pct" é a carga atual.
- "totais_mensais" agrega TODO o histórico por mês (YYYY-MM, fuso de Brasília): use-o pra totais/médias por mês (custo, km, kWh, nº de viagens/recargas).
- "viagens_todas"/"recargas_todas" (quando presentes) listam TODAS as viagens/recargas em forma compacta — use pra extremos, comparações e contagens no histórico inteiro. Quando ausentes, baseie-se em "totais_mensais" e nos "recentes".
- "rotas" (quando presente) traz as distâncias reais de estrada de cada perna a partir do GPS do carro. Pra responder se a bateria chega: compare a distância acumulada com autonomy_ev_km; se o usuário pedir reserva (ex.: "sem ficar abaixo de 20%"), desconte essa fração da autonomia (autonomy_ev_km × (1 − reserva)) antes de comparar. Subida (subida_m) gasta mais; mencione se relevante.
- "locais_salvos" tem as coordenadas de lugares nomeados (casa/trabalho/etc).
- Seja conciso. Tabelas simples ou bullets quando útil.
- Mantenha continuidade da conversa: se o usuário pergunta "e nessa outra?" assume o contexto da mensagem anterior.`;

  async function viaOllama() {
    const t0 = Date.now();
    const r = await fetch(`${OLLAMA_URL}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: OLLAMA_MODEL,
        messages: [{ role: 'system', content: sys }, ...userMsgs],
        stream: false,
        options: { temperature: 0.2, num_ctx: 8192 },
      }),
    });
    if (!r.ok) throw new Error(`Ollama ${r.status}`);
    const o = await r.json();
    return {
      answer: o.message?.content || '(sem resposta)',
      duration_sec: o.total_duration ? +(o.total_duration/1e9).toFixed(2) : +((Date.now()-t0)/1000).toFixed(2),
      tokens: o.eval_count || null,
      engine: 'ollama',
    };
  }
  async function viaClaude() {
    const t0 = Date.now();
    const answer = await _askClaude(sys, userMsgs);
    return { answer, duration_sec: +((Date.now()-t0)/1000).toFixed(2), tokens: null, engine: 'claude' };
  }

  // Primário + fallback no outro motor.
  if (cloudFirst) {
    try { return res.json(await viaClaude()); }
    catch (e) { console.warn('[ai] claude falhou, fallback ollama:', e.message); }
    try { return res.json(await viaOllama()); }
    catch (e) { console.warn('[ai] ollama falhou:', e.message);
                return res.status(502).json({ error: 'falha nos dois motores de IA: ' + e.message }); }
  } else {
    try { return res.json(await viaOllama()); }
    catch (e) { console.warn('[ai] ollama falhou:', e.message);
      if (AI_CLOUD && prefer !== 'local') {
        try { return res.json(await viaClaude()); }
        catch (e2) { console.warn('[ai] claude (fallback) falhou:', e2.message);
                     return res.status(502).json({ error: 'falha nos dois motores de IA: ' + e2.message }); }
      }
      return res.status(502).json({ error: 'falha ao consultar Ollama: ' + e.message });
    }
  }
});

// PATCH /api/notif/devices/:device_id  { device_name }
app.patch('/api/notif/devices/:device_id', (req, res) => {
  const id = req.params.device_id;
  const name = (req.body?.device_name || '').toString().trim();
  if (!name) return res.status(400).json({ error: 'device_name vazio' });
  const sub = pushSubs.find(s => s.device_id === id);
  if (!sub) return res.status(404).json({ error: 'device não encontrado' });
  sub.device_name = name.slice(0, 50);
  savePushSubs();
  res.json({ ok: true, device_id: id, device_name: sub.device_name });
});

// DELETE /api/notif/devices/:device_id — remove subscription E prefs
app.delete('/api/notif/devices/:device_id', (req, res) => {
  const id = req.params.device_id;
  const before = pushSubs.length;
  pushSubs = pushSubs.filter(s => s.device_id !== id);
  savePushSubs();
  if (notifPrefsByDevice[id]) {
    delete notifPrefsByDevice[id];
    saveNotifPrefsByDevice();
  }
  res.json({ ok: true, removed: before - pushSubs.length });
});

// GET /api/push/history  — central de notificações
// History é gravado globalmente (pra log/diagnóstico) mas o PWA filtra por
// device: só mostra entradas cujo `type` está ON nas prefs daquele device.
// Entradas sem `type` (testes/genéricas) sempre passam.
app.get('/api/push/history', (req, res) => {
  const deviceId = req.query.device_id || '';
  // Mesmo critério do gating de envio (getPrefsForDevice): device sem id usa a
  // config global; com prefs próprias usa elas. Nunca retorna o histórico cru.
  const prefs = getPrefsForDevice(deviceId);
  const filtered = notifHistory.filter(n => !n.type || prefs[n.type] === true);
  res.json(filtered);
});

// POST /api/push/history/clear  — limpa histórico de notificações
app.post('/api/push/history/clear', (_req, res) => {
  notifHistory = [];
  saveNotifHistory();
  res.json({ ok: true });
});

// ── Remote Actions ────────────────────────────────────────────────────────────
// Cada ação do PWA mapeia 1:1 num button.* da integração GWM Brasil.
// O bridge dispara publicando PRESS direto no tópico de comando MQTT do bridge
// GWM standalone (gwm-bridge no pm2, mqtt://localhost:1883) — SEM passar pelo HA.
// Assim os comandos sobrevivem ao HA estar fora do ar.
//   homeassistant/button/gwmbrasil_<chassi>_<code>/press  payload 'PRESS'
const ACTION_TO_GWM_BUTTON_CODE = {
  engine_on:      'hyengsts_engineon',
  engine_off:     'hyengsts_engineoff',
  lock_open:      '2208001_doorsopen',
  lock_close:     '2208001_doorsclose',
  windows_open:   '2210001_windowsopen',
  windows_close:  '2210001_windowsclose',
  trunk_open:     '2206001_trunkopen',
  trunk_close:    '2206001_trunkclose',
  sunroof_open:   '2210005_skywindowopen',
  sunroof_close:  '2210005_skywindowclose',
  ac_on:          '2202001_airconditioner',
  charge_stop:    '2041142_stopcharging',
  charge_history: '2013021_charginglogs',
  find_car:       '2103010_findcar',
  find_car_honk:  '2103010_findcarhonk',
};
const ALLOWED_ACTIONS = new Set(Object.keys(ACTION_TO_GWM_BUTTON_CODE));

// ── Confirmação de comando pelo estado do carro ──────────────────────────────
// A nuvem GWM responde 'timeout' com frequência mesmo com o comando executado
// (ela leva 20-30s pra fechar o loop e desiste antes). Nessas ações o estado do
// carro é evidência melhor que o veredito dela.
//
// Só entram ações cujo sinal é inequívoco. `engine_state` (hyengsts) vale porque
// reflete o carro ligado independente do head unit estar acordado. lock_* está
// de fora de propósito: a polaridade de `lock_state` é ambígua e um falso
// "confirmado" em tranca é pior que um falso "não respondeu".
const ACTION_STATE_CHECK = {
  engine_on:  () => String(state.engine_state) === '1',
  engine_off: () => String(state.engine_state) === '0',
};
// 60s < watchdog de 70s do app (CarStore.setCommandProgress): o bridge tem que
// dar o veredito ANTES do cliente desistir, senão o falso "não respondeu" aparece
// de qualquer forma. Cobre com folga os 20-30s típicos da nuvem GWM.
const CMD_VERIFY_WINDOW_MS = 60_000;
const CMD_VERIFY_POLL_MS   = 3_000;
let _pendingCommandSeq = 0;

// Observa o estado até a ação se confirmar ou a janela fechar. O critério é o
// estado DESEJADO estar satisfeito, não a transição: se o carro já está ligado e
// veio um engine_on, "Motor ligado" é o que o usuário quer ver — é também o que o
// resto do app mostra. Já um engine_off que não desligou continua reprovando,
// porque aí o estado desejado não se realiza.
function _verifyCommandByState(action, sentMs) {
  const check = ACTION_STATE_CHECK[action];
  if (!check) return Promise.resolve(false);
  return new Promise(resolve => {
    const deadline = sentMs + CMD_VERIFY_WINDOW_MS;
    const tick = () => {
      let ok = false;
      try { ok = !!check(); } catch (_) { ok = false; }
      if (ok)                  return resolve(true);
      if (Date.now() >= deadline) return resolve(false);
      setTimeout(tick, CMD_VERIFY_POLL_MS);
    };
    tick();
  });
}

// Caminho LOCAL das ações que têm equivalente no carro (APK atua via Shizuku/
// IVehicle, sem passar pela nuvem GWM). Quando o APK está vivo (WiFi/Starlink),
// preferimos isto — a nuvem GWM morre quando o 4G do carro acaba. Cada entrada é
// uma lista de [tópico_cmd, payload] publicados em sequência.
// EXCLUÍDOS de propósito: lock_*/engine_* são telematics (carro dormindo = head
// unit desligado → não há atuador local vivo, e o IVehicle não dá partida
// remota); trunk_*/charge_* não têm mapeamento local seguro/confirmado. Esses
// seguem só na nuvem.
const ACTION_LOCAL = {
  windows_open:  [['cmd/vehicle/window_all', '0']],    // 0=aberto
  windows_close: [['cmd/vehicle/window_all', '1']],    // 1=fechado
  sunroof_open:  [['cmd/vehicle/skylight',   '100']],  // 100=aberto
  sunroof_close: [['cmd/vehicle/skylight',   '0']],    // 0=fechado
  ac_on:         [['cmd/hvac/power', '1'], ['cmd/hvac/ac_enable', '1']],
};

// ── Reverse-geocode via Nominatim (1 req/s, cache em memória) ─────────────
// Usado pelo reprocessamento de trips/charges. Para o uso runtime do PWA,
// cada cliente faz o seu (Nominatim aceita); aqui o foco é batch server-side.
const _geocodeMem = new Map();
function _geocodeMemKey(lat, lng) {
  return (Math.round(lat * 1000) / 1000) + ',' + (Math.round(lng * 1000) / 1000);
}
async function _reverseGeocode(lat, lng) {
  const k = _geocodeMemKey(lat, lng);
  if (_geocodeMem.has(k)) return _geocodeMem.get(k);
  try {
    const r = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=16`, {
      headers: {
        'Accept': 'application/json',
        'User-Agent': 'ecotrip-bridge/1.0 (https://github.com/rafaelcs28/haval-ecotrip)',
      },
    });
    const j = await r.json();
    const a = j.address || {};
    const result = {
      city:   a.city || a.town || a.village || a.county || '',
      suburb: a.suburb || a.neighbourhood || a.quarter || a.borough || a.city_district || '',
    };
    _geocodeMem.set(k, result);
    return result;
  } catch (_) {
    _geocodeMem.set(k, { city: '', suburb: '' });
    return { city: '', suburb: '' };
  }
}
function _formatPlace(g, otherG) {
  // Mesma cidade do oposto → "Bairro, Cidade"; cidade diferente → só cidade
  const sameCity = otherG && g.city && otherG.city && g.city === otherG.city;
  if (sameCity && g.suburb && g.city) return g.suburb + ', ' + g.city;
  if (sameCity && g.suburb)           return g.suburb;
  return g.city || g.suburb || '';
}

let _reprocessRunning = false;
let _reprocessStatus = null;  // { kind, total, done, current, errors }

function _broadcastReprocess() {
  broadcast('reprocess_progress', _reprocessStatus);
}

// POST /api/admin/reprocess-places  body { kind: 'trips'|'charges'|'all', force?: bool }
// Itera tudo, faz reverse-geocode 1/s. Resposta imediata; progresso via WS.
app.post('/api/admin/reprocess-places', async (req, res) => {
  if (!adminCheckToken(req, res)) return;
  if (_reprocessRunning) return res.status(409).json({ error: 'já em execução', status: _reprocessStatus });
  const kind  = req.body?.kind || 'all';   // 'trips' | 'charges' | 'all'
  const force = !!req.body?.force;
  const tripFiles = (kind === 'trips' || kind === 'all')
    ? fs.readdirSync(AUTOTRIPS_DIR).filter(f => f.endsWith('.json'))
    : [];
  const chargesTodo = (kind === 'charges' || kind === 'all')
    ? chargesArr.filter(c => c.location_lat && c.location_lng && (force || !c.location_name))
    : [];
  const total = tripFiles.length + chargesTodo.length;
  _reprocessRunning = true;
  _reprocessStatus = { kind, total, done: 0, trips_updated: 0, charges_updated: 0, errors: 0, current: '' };
  res.json({ ok: true, total, kind });
  // Resolve um lado: prioridade pra knownPlace (autoMatchLocation, raio 200m);
  // só cai no Nominatim quando o GPS está fora de qualquer KP. SEMPRE retorna
  // o geocode (mesmo quando é KP) pra que a regra "mesma cidade" funcione no
  // OUTRO lado da viagem.
  async function _resolveSide(lat, lng) {
    // Local conhecido (com tolerância de GPS) → outro matcher → destino mandado
    // pro carro (≤300 m) → senão geocode. Mesma régua do fim da viagem.
    const kp = matchKnownPlace(lat, lng, 80) || autoMatchLocation(lat, lng);
    const geo = await _reverseGeocode(lat, lng);
    await new Promise(r => setTimeout(r, 1100));
    if (kp?.name) return { name: kp.name, from_kp: true, geo };
    const nav = _navDestNameFor(lat, lng);
    if (nav) return { name: nav, from_kp: true, geo };
    return { name: null, from_kp: false, geo };
  }
  // Roda em background
  (async () => {
    try {
      // Trips
      for (const f of tripFiles) {
        try {
          const filePath = path.join(AUTOTRIPS_DIR, f);
          const d = JSON.parse(fs.readFileSync(filePath, 'utf8'));
          const at = d.autoTrip || {};
          const skip = !force && at.startKp && at.endKp;
          if (!skip && at.startLat && at.endLat) {
            const s = await _resolveSide(at.startLat, at.startLng);
            const e = await _resolveSide(at.endLat, at.endLng);
            // KP tem prioridade; senão "Bairro, Cidade" (se mesma cidade do oposto)
            const newStart = s.from_kp ? s.name : _formatPlace(s.geo, e.geo);
            const newEnd   = e.from_kp ? e.name : _formatPlace(e.geo, s.geo);
            if (force || !at.startKp) at.startKp = newStart || at.startKp || null;
            if (force || !at.endKp)   at.endKp   = newEnd   || at.endKp   || null;
            _reprocessStatus.current = (at.startKp || '?') + ' → ' + (at.endKp || '?');
            fs.writeFileSync(filePath, JSON.stringify(d, null, 2));
            // Atualiza também o array em memória (servido por GET /api/autotrips) —
            // sem isso os nomes só apareciam após restart do bridge.
            const _rec = autoTripsArr.find(t => String(t.tripId) === String(d.tripId));
            if (_rec) { _rec.startKp = at.startKp; _rec.endKp = at.endKp; }
            _reprocessStatus.trips_updated++;
          }
        } catch (e) { _reprocessStatus.errors++; }
        _reprocessStatus.done++;
        if (_reprocessStatus.done % 3 === 0) _broadcastReprocess();
      }
      // Charges — também prioriza KP. Sem KP: "Cidade" (sem oposto, fica só cidade).
      for (const c of chargesTodo) {
        try {
          const kp = autoMatchLocation(c.location_lat, c.location_lng);
          let name = kp?.name || null;
          if (!name) {
            const g = await _reverseGeocode(c.location_lat, c.location_lng);
            await new Promise(r => setTimeout(r, 1100));
            name = _formatPlace(g, null);
          }
          if (name) {
            c.location_name = name;
            c._updated_ms = Date.now();
            _reprocessStatus.current = name;
            _reprocessStatus.charges_updated++;
          }
        } catch (e) { _reprocessStatus.errors++; }
        _reprocessStatus.done++;
        if (_reprocessStatus.done % 3 === 0) _broadcastReprocess();
      }
      if (_reprocessStatus.charges_updated > 0) scheduleChargesFlush();
      _broadcastReprocess();
      broadcast('reprocess_done', _reprocessStatus);
      console.log(`✓ Reprocess: trips=${_reprocessStatus.trips_updated} charges=${_reprocessStatus.charges_updated} errors=${_reprocessStatus.errors}`);
    } finally {
      _reprocessRunning = false;
    }
  })();
});

app.get('/api/admin/reprocess-places/status', (_req, res) => {
  res.json({ running: _reprocessRunning, status: _reprocessStatus });
});

// POST /api/admin/bulk-set-cost-by-location  { location, per_kwh, use_charger? }
// Aplica preço unitário fixo (R$/kWh) em todas as recargas de um local.
// Total = per_kwh * (charger_kwh quando use_charger=true e disponível,
// senão energy_kwh do carro). Útil pra retroceder histórico em locais com
// tarifa fixa conhecida.
app.post('/api/admin/bulk-set-cost-by-location', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const location = (req.body?.location || '').toString().trim();
  const perKwh   = parseFloat(req.body?.per_kwh);
  const useCharger = req.body?.use_charger !== false;  // default true
  if (!location)          return res.status(400).json({ error: 'location obrigatório' });
  if (!(perKwh >= 0))     return res.status(400).json({ error: 'per_kwh inválido' });
  let updated = 0, skipped = 0;
  const details = [];
  for (const c of chargesArr) {
    if (c.location_name !== location) continue;
    const kwh = useCharger && c.charger_kwh > 0 ? c.charger_kwh
              : c.energy_kwh > 0 ? c.energy_kwh
              : 0;
    if (kwh <= 0) {
      skipped++;
      details.push({ ts: c.timestamp_ms, action: 'skipped', reason: 'sem kWh' });
      continue;
    }
    const total = +(kwh * perKwh).toFixed(2);
    c.cost_override = perKwh === 0
      ? { total: 0, perKwh: 0, free: true }
      : { total, perKwh: perKwh };
    c._updated_ms = Date.now();
    updated++;
    details.push({ ts: c.timestamp_ms, action: 'updated', kwh, total });
  }
  if (updated > 0) {
    scheduleChargesFlush();
    recomputeBatteryAvgPrice();
  }
  console.log(`[bulk-cost] "${location}" @ R$ ${perKwh}/kWh: ${updated} atualizadas, ${skipped} puladas`);
  res.json({ ok: true, location, per_kwh: perKwh, updated, skipped, details });
});

// POST /api/admin/recompute-trip-costs — recalcula o custo de TODAS as viagens
// usando o preço médio que valia NO MOMENTO de cada viagem (não o atual).
// body: { dry_run?: bool } — dry_run só conta quantas seriam afetadas
// O resultado vai pra `autoTrip.costRecomputed = { total, kwhPrice, gasPrice, ts }`,
// preservando o `cost` original. PWA usa o recomputed quando presente.
app.post('/api/admin/recompute-trip-costs', async (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const dryRun = req.body?.dry_run === true;
  // Garante que battery_avg_after/tank_avg_after estão atualizados em todas
  // recargas/abastecimentos antes de iterar viagens.
  recomputeBatteryAvgPrice();
  recomputeTankAvgPrice();
  let updated = 0, skipped = 0, errors = 0;
  try {
    const files = fs.readdirSync(AUTOTRIPS_DIR).filter(f => f.endsWith('.json'));
    let _i = 0;
    for (const f of files) {
      // Cede o event loop a cada 10 arquivos — sem isto o loop síncrono congelava
      // o bridge inteiro (WS/MQTT/requests) por segundos com muitos trips.
      if (++_i % 10 === 0) await new Promise(r => setImmediate(r));
      try {
        const filePath = path.join(AUTOTRIPS_DIR, f);
        const d = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        const at = d.autoTrip;
        if (!at?.endMs) { skipped++; continue; }
        const netKwh = +at.netKwh || 0;
        const fuelL  = +at.fuelL  || 0;
        if (netKwh < 0.01 && fuelL < 0.01) { skipped++; continue; }
        // Preço usado: o que valia no FIM da viagem (consumiu durante o trajeto)
        const { kwhPrice, gasPrice } = priceMixAtMs(at.endMs);
        const total = +(netKwh * kwhPrice + fuelL * gasPrice).toFixed(2);
        at.costRecomputed = {
          total,
          kwhPrice: +kwhPrice.toFixed(4),
          gasPrice: +gasPrice.toFixed(3),
          ts:       Date.now(),
        };
        if (!dryRun) {
          fs.writeFileSync(filePath, JSON.stringify(d, null, 2));
          // Espelha em memória pra que /api/autotrips reflita imediato
          const mem = autoTripsArr.find(t => t.tripId === d.tripId);
          if (mem) mem.costRecomputed = at.costRecomputed;
        }
        updated++;
      } catch (_) { errors++; }
    }
  } catch (e) {
    return res.status(500).json({ error: 'Falha ao iterar autotrips: ' + e.message });
  }
  res.json({ ok: true, dry_run: dryRun, updated, skipped, errors });
});

// POST /api/admin/recompute-drive-scores — preenche driveScore/harshAcc/harshBrake
// nas viagens antigas (gravadas antes de computeDriveScore existir) usando os
// samples já persistidos. body { force?: bool } — force=true reprocessa também
// viagens que já têm driveScore.
app.post('/api/admin/recompute-drive-scores', async (req, res) => {
  if (!adminCheckToken(req, res)) return;
  const force = req.body?.force === true;
  let updated = 0, skipped = 0, errors = 0;
  try {
    const files = fs.readdirSync(AUTOTRIPS_DIR).filter(f => f.endsWith('.json'));
    let _i = 0;
    for (const f of files) {
      // computeDriveScore varre todos os samples — sem ceder, trava o bridge.
      if (++_i % 10 === 0) await new Promise(r => setImmediate(r));
      try {
        const filePath = path.join(AUTOTRIPS_DIR, f);
        const d = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        const at = d.autoTrip;
        if (!at) { skipped++; continue; }
        const hasScore = at.driveScore != null;
        if (hasScore && !force) { skipped++; continue; }
        const samples = Array.isArray(d.samples) ? d.samples : [];
        const drive = computeDriveScore(samples, at);
        at.driveScore = drive.score;
        at.harshAcc = drive.harshAcc;
        at.harshBrake = drive.harshBrake;
        at._updated_ms = Date.now();   // força o app a re-sincronizar essa viagem
        fs.writeFileSync(filePath, JSON.stringify(d, null, 2));
        // Espelha em memória pra que /api/autotrips reflita sem restart.
        const mem = autoTripsArr.find(t => String(t.tripId) === String(d.tripId));
        if (mem) {
          mem.driveScore = at.driveScore;
          mem.harshAcc = at.harshAcc;
          mem.harshBrake = at.harshBrake;
          mem._updated_ms = at._updated_ms;
        }
        updated++;
      } catch (_) { errors++; }
    }
  } catch (e) {
    return res.status(500).json({ error: 'Falha ao iterar autotrips: ' + e.message });
  }
  console.log(`✓ recompute-drive-scores: updated=${updated} skipped=${skipped} errors=${errors} force=${force}`);
  res.json({ ok: true, updated, skipped, errors, force });
});

// POST /api/admin/reset-tyre-baseline — zera o histórico de PSI dos pneus.
// Outras métricas (12V, autonomia, combustível) permanecem. Útil quando a
// média 14d ficou viciada com leituras em movimento (pneu quente).
app.post('/api/admin/reset-tyre-baseline', (req, res) => {
  if (!adminCheckToken(req, res)) return;
  let cleared = 0;
  for (const snap of telemetryHistory) {
    for (const pos of ['fl', 'fr', 'rl', 'rr']) {
      if (snap[`tyre_${pos}`]) { snap[`tyre_${pos}`] = 0; cleared++; }
    }
  }
  try { fs.writeFileSync(TELEMETRY_LOG_FILE, JSON.stringify(telemetryHistory, null, 2)); } catch (_) {}
  // Limpa flags de "alerta já enviado hoje" pra que novos alertas legítimos
  // (a frio) voltem a disparar sem precisar passar a data
  for (const k of Object.keys(_anomalyAlerted)) {
    if (k.startsWith('tyre_')) delete _anomalyAlerted[k];
  }
  console.log(`✓ Baseline de pneus zerado (${cleared} valores limpos)`);
  res.json({ ok: true, cleared, entries: telemetryHistory.length });
});

// Publica comando MQTT esperando até `waitMs` pela reconexão se o cliente estiver
// fora no momento. A conexão bridge↔broker oscila com keepalive timeout/connack
// timeout — sem espera, o user perde o comando por 200ms de gap. Tentar 3s
// cobre 95% dos saltos vistos nos logs.
async function publishCmdWithRetry(topic, payload, opts, waitMs = 3000) {
  const t0 = Date.now();
  while (!mqttClient?.connected && (Date.now() - t0) < waitMs) {
    await new Promise(r => setTimeout(r, 200));
  }
  if (!mqttClient?.connected) {
    const e = new Error('MQTT offline'); e.code = 'MQTT_OFFLINE'; throw e;
  }
  return new Promise((resolve, reject) => {
    mqttClient.publish(topic, payload, opts, err => err ? reject(err) : resolve());
  });
}

// POST /api/charge-limit/refresh — pede pro APK reler o limite real do carro
