app.post('/api/action/:name', async (req, res) => {
  const { name } = req.params;
  console.log(`[action] recebido name='${name}'`);
  const code = ACTION_TO_GWM_BUTTON_CODE[name];
  if (!code) {
    console.warn(`[action] ${name} REJEITADO: ação desconhecida`);
    return res.status(400).json({ error: 'ação desconhecida' });
  }
  // Caminho LOCAL preferido: se a ação tem equivalente no carro E o APK está vivo
  // (publicou nos últimos 90s = alcançável via WiFi/Starlink), atua direto pelo
  // APK e pula a nuvem GWM — que morre quando o 4G do carro acaba. Sem APK fresco
  // (carro dormindo/longe), cai pro botão da nuvem como antes.
  const local = ACTION_LOCAL[name];
  const apkFresh = state.last_apk_ms && (Date.now() - state.last_apk_ms) < 90_000;
  if (local && apkFresh && mqttClient?.connected) {
    try {
      for (const [topic, payload] of local) {
        mqttClient.publish(`${MQTT_PREFIX}/${topic}`, payload, { qos: 1, retain: false });
      }
      if (name === 'engine_on') markRemoteEngineStart();
      console.log(`[action] ${name} → LOCAL (APK via WiFi, nuvem GWM ignorada)`);
      return res.json({ ok: true, via: 'local' });
    } catch (e) {
      console.warn(`[action] ${name} local falhou (${e.message}) — tentando nuvem GWM`);
    }
  }
  if (!mqttClient?.connected) {
    console.warn(`[action] ${name} REJEITADO: MQTT offline`);
    return res.status(503).json({ error: 'MQTT offline' });
  }
  const pressTopic = `homeassistant/button/${GWM_TOPIC_PREFIX}_${code}/press`;
  mqttClient.publish(pressTopic, 'PRESS', { qos: 1, retain: false }, err => {
    if (err) {
      console.error(`[action] ${name} → ${pressTopic} erro: ${err.message}`);
      return res.status(502).json({ error: 'falha ao publicar no MQTT' });
    }
    console.log(`[action] ${name} → ${pressTopic} OK (GWM via MQTT)`);
    // Arma o feed de andamento: o standalone vai publicar sent→done/timeout em
    // gwmbrasil_<vin>/command_progress/state, que casamos com esta ação por tempo.
    const cmdId = ++_pendingCommandSeq;
    _pendingCommand = { action: name, code, ts: Date.now(), id: cmdId };
    broadcast('command_progress', { action: name, phase: 'sent', resultCode: null, ts: Date.now() });
    // A nuvem GWM às vezes não publica NADA em command_progress/state — nem done,
    // nem timeout. Aí o bridge ficava calado e o watchdog de 70s do app declarava
    // "Carro não respondeu" com o comando já executado (engine_off de 28/07:
    // desligou o carro e mostrou timeout). Então a verificação por estado corre em
    // paralelo ao envio, sem depender da nuvem responder.
    if (ACTION_STATE_CHECK[name]) {
      _verifyCommandByState(name, Date.now()).then(confirmado => {
        // Só fala se a nuvem não resolveu antes (pending ainda é este comando).
        if (!confirmado || _pendingCommand?.id !== cmdId) return;
        _pendingCommand = null;
        broadcast('command_progress', {
          action: name, phase: 'done', resultCode: null,
          ok: true, verifiedByState: true, ts: Date.now(),
        });
        console.log(`[cmd-progress] action=${name} confirmado pelo estado (nuvem não respondeu)`);
      });
    }
    // Ligar motor pelo app arma a LA de lembrete (confirma no engine_state='1').
    if (name === 'engine_on') markRemoteEngineStart();
    res.json({ ok: true, via: 'gwm' });
  });
});

// ── Pré-climatização — lista de agendamentos ──────────────────────────────
app.get('/api/preclimat', requireAuth, (_req, res) =>
  res.json({ schedules: preclimat.schedules, status: preclimatStatus }));

// Força um pushUpdate da LA de pré-clima com o content state atual (pra trocar
// tempOut pela leitura do OpenWeather, refrescar tempIn, etc — sem mudar phase).
app.post('/api/preclimat/repush', requireAuth, async (_req, res) => {
  if (!apnsLive.enabled) return res.status(503).json({ ok: false, error: 'APNs LA desabilitado' });
  // _activeSched é em memória — se restartou no meio, fallback: pega o schedule
  // que está com startedDate=hoje e ainda não disparou ou está cooling.
  let dev = _activeSched && _activeSched.device_id;
  if (!dev) {
    const today = new Date().toISOString().slice(0, 10);
    const cand = preclimat.schedules.find(s => s.startedDate === today && s.enabled);
    if (cand) { _activeSched = cand; dev = cand.device_id || ''; }
  }
  try {
    await _refreshCarWeather();
    // Push pra device específico OU broadcast (sem deviceId) quando o schedule
    // não tinha device — todas as LAs ativas do tipo recebem.
    const filter = dev ? { deviceId: dev } : {};
    await apnsLive.pushUpdate(PRECLIMAT_LA_TYPE, filter,
      _preclimatContentState(), { staleDate: preclimatStatus.endsAtMs || undefined });
    res.json({ ok: true, dev: dev || '(broadcast)', state: _preclimatContentState() });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// Clima local via OpenWeather (cache 10min). Endpoint público pra Lari (whats-
// assistant) consultar antes de compromissos em outros locais e sugerir pré-clima.
// Uso: GET /api/weather?lat=-16.62&lng=-49.27 com Bearer BRIDGE_TOKEN.
app.get('/api/weather', requireAuth, async (req, res) => {
  const lat = parseFloat(req.query.lat), lng = parseFloat(req.query.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    return res.status(400).json({ ok: false, error: 'lat/lng obrigatórios' });
  }
  const data = await getLocalWeather(lat, lng);
  if (!data) return res.status(503).json({ ok: false, error: 'OpenWeather indisponível (sem chave ou falha de rede)' });
  res.json({ ok: true, lat, lng, ...data });
});

// Contexto pra UI do modal: temp da cabine (com idade do dado) e temp local
// via OpenWeather (cacheada). Usado pelo "Planejar saída" no PWA.
app.get('/api/preclimat/context', requireAuth, async (_req, res) => {
  const insideTemp = +state.inside_temp;
  const insideMs   = +state._inside_temp_ms || 0;
  const outsideTemp = +state.outside_temp;
  const lat = +state.gps_lat, lng = +state.gps_lng;
  const weather = await getLocalWeather(lat, lng);
  res.json({
    ok: true,
    cabin: {
      tempC: Number.isFinite(insideTemp) && insideTemp !== 0 ? insideTemp : null,
      ageMs: insideMs ? Date.now() - insideMs : null,
      fresh: insideMs ? (Date.now() - insideMs) <= PRECLIMAT_FRESH_MAX_MS : false,
    },
    carSensor: { tempC: Number.isFinite(outsideTemp) && outsideTemp !== 0 ? outsideTemp : null },
    weather,
  });
});

// Cria (sem id) ou atualiza (com id) um agendamento.
app.post('/api/preclimat/schedule', requireAuth, (req, res) => {
  const b = req.body || {};
  if (b.time !== undefined && !/^\d{2}:\d{2}$/.test(b.time))
    return res.status(400).json({ error: 'time inválido (HH:MM)' });
  if (b.recurrence !== undefined && !['once', 'daily', 'weekdays', 'weekends'].includes(b.recurrence))
    return res.status(400).json({ error: 'recurrence inválido' });
  const t = b.temp !== undefined ? parseFloat(b.temp) : null;
  if (t !== null && (isNaN(t) || t < 16 || t > 32)) return res.status(400).json({ error: 'temp fora de 16-32' });
  const f = b.fan !== undefined ? parseInt(b.fan, 10) : null;
  if (f !== null && (isNaN(f) || f < 1 || f > 7)) return res.status(400).json({ error: 'fan fora de 1-7' });
  const dur = b.duration !== undefined ? parseInt(b.duration, 10) : null;
  if (dur !== null && (isNaN(dur) || dur < 0 || dur > 180)) return res.status(400).json({ error: 'duration fora de 0-180' });
  const lead = b.leadMin !== undefined ? parseInt(b.leadMin, 10) : null;
  if (lead !== null && (isNaN(lead) || lead < 0 || lead > 60)) return res.status(400).json({ error: 'leadMin fora de 0-60' });
  // onceAtMs: timestamp absoluto p/ pré-clima por compromisso. 0/null limpa o modo.
  let onceAt = null;
  if (b.onceAtMs !== undefined) {
    onceAt = b.onceAtMs === null ? 0 : parseInt(b.onceAtMs, 10);
    if (isNaN(onceAt) || onceAt < 0 || onceAt > Date.now() + 30 * 86400_000)
      return res.status(400).json({ error: 'onceAtMs inválido' });
  }
  // departureMs/label: metadados da "viagem planejada" (só p/ exibir na lista).
  let departureMs = null;
  if (b.departureMs !== undefined) {
    departureMs = b.departureMs === null ? 0 : parseInt(b.departureMs, 10);
    if (isNaN(departureMs) || departureMs < 0 || departureMs > Date.now() + 30 * 86400_000)
      return res.status(400).json({ error: 'departureMs inválido' });
  }
  const label = b.label !== undefined ? String(b.label).slice(0, 80) : null;

  // Contexto de viagem (opcional) p/ recompute de trânsito server-side. Aceita
  // destino por coordenadas OU nome (geocodado no recompute). eventStartMs = hora
  // do compromisso (chegada); bufferMin = folga antes da viagem; climateMin = tempo
  // de climatização. O bridge recalcula onceAtMs ~20 min antes com o ETA ao vivo.
  let eventStartMs = null;
  if (b.eventStartMs !== undefined) {
    eventStartMs = b.eventStartMs === null ? 0 : parseInt(b.eventStartMs, 10);
    if (isNaN(eventStartMs) || eventStartMs < 0 || eventStartMs > Date.now() + 30 * 86400_000)
      return res.status(400).json({ error: 'eventStartMs inválido' });
  }
  const destLat   = b.destLat   !== undefined ? (+b.destLat   || 0) : null;
  const destLng   = b.destLng   !== undefined ? (+b.destLng   || 0) : null;
  const destName  = b.destName  !== undefined ? String(b.destName).slice(0, 120) : null;
  const bufferMin = b.bufferMin !== undefined ? Math.max(0, Math.min(60,  parseInt(b.bufferMin, 10) || 0)) : null;
  const climateMin= b.climateMin!== undefined ? Math.max(0, Math.min(180, parseInt(b.climateMin,10) || 0)) : null;

  let sched = b.id ? preclimat.schedules.find(s => s.id === b.id) : null;
  if (!sched) { sched = { ...PRECLIMAT_SCHED_DEFAULTS, id: _genSchedId() }; preclimat.schedules.push(sched); }

  const timeChanged = b.time !== undefined && b.time !== sched.time;
  const disabling   = b.enabled !== undefined && !b.enabled && sched.enabled;
  const enabling    = b.enabled !== undefined && !!b.enabled && !sched.enabled;

  if (b.device_id)        sched.device_id  = String(b.device_id);
  if (b.time !== undefined)       sched.time = b.time;
  if (b.recurrence !== undefined) sched.recurrence = b.recurrence;
  if (t !== null)         sched.temp = t;
  if (f !== null)         sched.fan = f;
  if (dur !== null)       sched.duration = dur;
  if (lead !== null)      sched.leadMin = lead;
  if (onceAt !== null) { sched.onceAtMs = onceAt; if (onceAt > 0) { sched.recurrence = 'once'; sched.lastFiredDate = ''; sched.startedDate = ''; } }
  if (departureMs !== null) sched.departureMs = departureMs;
  if (label !== null)       sched.label = label;
  if (eventStartMs !== null) sched.eventStartMs = eventStartMs;
  if (destLat !== null)     sched.destLat = destLat;
  if (destLng !== null)     sched.destLng = destLng;
  if (destName !== null)    sched.destName = destName;
  if (bufferMin !== null)   sched.bufferMin = bufferMin;
  if (climateMin !== null)  sched.climateMin = climateMin;
  if (eventStartMs !== null || destLat !== null || destLng !== null || destName !== null) sched.trafficAdjAt = 0;
  if (b.enabled !== undefined)    sched.enabled = !!b.enabled;

  // Efeitos: mudar horário ou desativar encerra a LA ativa deste agendamento;
  // reagendar/reabilitar libera disparo/criação de novo hoje.
  if (timeChanged || disabling) _dismissPreclimatLA(sched);
  if (timeChanged || disabling || enabling) { sched.lastFiredDate = ''; sched.startedDate = ''; }

  savePreclimat();
  res.json(sched);
});

// Remove um agendamento por id.
app.delete('/api/preclimat/schedule/:id', requireAuth, (req, res) => {
  const sched = preclimat.schedules.find(s => s.id === req.params.id);
  if (sched) {
    _dismissPreclimatLA(sched);
    preclimat.schedules = preclimat.schedules.filter(s => s.id !== req.params.id);
    savePreclimat();
  }
  res.json({ ok: true });
});

// Cancela a pré-climatização em andamento (ou agendada e ainda não disparada).
// Antes do disparo: descarta a LA. Em andamento: restaura AC + desliga motor.
app.post('/api/preclimat/cancel', requireAuth, async (_req, res) => {
  try {
    const r = await cancelPreClimat('cancelado pelo app');
    res.status(r.ok ? 200 : 409).json(r);
  } catch (e) {
    console.error('[preclimat] cancel erro:', e.message);
    res.status(500).json({ ok: false, error: e.message });
  }
});

// ── Leave-by planner ──────────────────────────────────────────────────────
// "Saio às 8h" → a bateria chega no alvo a tempo? E quando armar o pré-clima
// pra cabine ficar pronta na partida? Read-only: combina o ETA de recarga
// (chargeEtaMin/potência) com uma sugestão de pré-clima. O app arma o pré-clima
// chamando /api/preclimat/schedule com onceAtMs (já existente).
app.get('/api/leave-by', requireAuth, (req, res) => {
  const now = Date.now();
  // Partida: atMs absoluto, ou HH:MM → próxima ocorrência (hoje se futuro, senão amanhã).
  let departureMs = 0;
  if (req.query.atMs) {
    departureMs = parseInt(req.query.atMs, 10);
  } else if (/^\d{1,2}:\d{2}$/.test(String(req.query.at || ''))) {
    const [h, m] = String(req.query.at).split(':').map(Number);
    const d = new Date(); d.setHours(h, m, 0, 0);
    if (d.getTime() <= now) d.setDate(d.getDate() + 1);
    departureMs = d.getTime();
  }
  if (!departureMs || isNaN(departureMs) || departureMs <= now)
    return res.status(400).json({ error: 'horário de partida inválido (use at=HH:MM ou atMs futuro)' });

  const minutesUntil = (departureMs - now) / 60000;
  const soc    = +state.soc_pct || 0;
  const target = Math.min(100, Math.max(1, +req.query.target || _effectiveChargeTarget()));
  const charging = state.charging_state === 'Carregando';

  // Potência: média da janela recente, senão a média da sessão.
  const win = _chargePwrWin.filter(s => now - s.ts <= CHARGE_ETA_WIN_MS);
  const powerKw = charging
    ? (win.length ? win.reduce((a, s) => a + s.kw, 0) / win.length : (+state.charge_avg_power_kw || 0))
    : 0;

  const needKwh = Math.max(0, (target - soc) / 100 * BATTERY_CAPACITY_KWH);
  let etaMin = 0, finishAtMs = null, projectedSoc = soc;
  if (needKwh <= 0.05) {
    projectedSoc = soc;                        // já no alvo
  } else if (charging && powerKw > 0.3) {
    etaMin = needKwh / powerKw * 60;
    finishAtMs = now + etaMin * 60000;
    const gainedKwh = powerKw * (minutesUntil / 60);
    projectedSoc = Math.min(target, soc + gainedKwh / BATTERY_CAPACITY_KWH * 100);
  }
  const willReachTarget = needKwh <= 0.05 || (charging && powerKw > 0.3 && etaMin <= minutesUntil + 0.5);
  const deficitPct = Math.max(0, target - projectedSoc);

  // Pré-clima: arma pra terminar na partida. Temp sugerida pela externa quando o
  // app não manda uma preferência.
  const durationMin = Math.min(60, Math.max(5, parseInt(req.query.preclimatMin, 10) || 20));
  const outside = +state.outside_temp || 0;
  let temp = parseFloat(req.query.cabin);
  if (isNaN(temp)) temp = outside >= 26 ? 21 : (outside > 0 && outside < 16 ? 24 : 22);
  temp = Math.min(32, Math.max(16, temp));
  const fireAtMs = departureMs - durationMin * 60000;

  res.json({
    departureMs, minutesUntil: Math.round(minutesUntil),
    soc, target, charging, powerKw: +powerKw.toFixed(1),
    etaMin: Math.round(etaMin), finishAtMs,
    projectedSoc: +projectedSoc.toFixed(0),
    willReachTarget, deficitPct: +deficitPct.toFixed(0),
    needKwh: +needKwh.toFixed(1),
    preclimat: {
      fireAtMs, durationMin, temp,
      tooSoon: fireAtMs <= now,           // partida tão próxima que o pré-clima já deveria estar rodando
    },
  });
});

// ── Histórico de modos — GET /api/drive-history ───────────────────────────
app.get('/api/drive-history', requireAuth, (req, res) => {
  const since = parseInt(req.query.since || '0', 10);
  const segs   = since > 0 ? driveHistory.filter(s => s.to_ts > since) : driveHistory;

  // Agrega: soma duração e conta por combinação dm+tm
  const map = new Map();
  for (const s of segs) {
    const key = `${s.dm}_${s.tm}`;
    const dur = s.to_ts - s.from_ts;
    if (!map.has(key)) map.set(key, { dm: s.dm, tm: s.tm, total_ms: 0, count: 0 });
    const e = map.get(key);
    e.total_ms += dur;
    e.count++;
  }

  // Segmento aberto (modo atual ainda em andamento)
  if (_dmSegment) {
    const key = `${_dmSegment.dm}_${_dmSegment.tm}`;
    const dur = Date.now() - _dmSegment.from_ts;
    if (!map.has(key)) map.set(key, { dm: _dmSegment.dm, tm: _dmSegment.tm, total_ms: 0, count: 0 });
    map.get(key).total_ms += dur;
  }

  const stats = [...map.values()].sort((a, b) => b.total_ms - a.total_ms);
  res.json({ stats, segments: segs.length + (_dmSegment ? 1 : 0) });
});

// ── Drive history clear ───────────────────────────────────────────────────────
app.post('/api/drive-history/clear', requireAuth, (req, res) => {
  driveHistory.length = 0;
  _dmSegment = null;
  try { fs.writeFileSync(DRIVE_HISTORY_FILE, '[]'); } catch (_) {}
  res.json({ ok: true });
});

// ── HVAC commands ────────────────────────────────────────────────────────────
// Publica em `${MQTT_PREFIX}/cmd/hvac/<control>` — o APK escuta e usa
// CarDataManager.requestSetting() pra escrever no barramento via Shizuku.
// Cada controle tem range/tipo validados aqui antes do publish pra evitar
// que valores fora de faixa cheguem no carro.
const HVAC_CONTROLS = {
  driver_temp:    { type: 'float', min: 16, max: 32, step: 0.5 },
  passenger_temp: { type: 'float', min: 16, max: 32, step: 0.5 },
  fan_speed:      { type: 'int',   min: 0,  max: 7 },
  sync:           { type: 'bool' },
  auto:           { type: 'bool' },
  cycle_mode:     { type: 'int',   min: 0,  max: 1 },
  blower_mode:    { type: 'int',   min: 0,  max: 4 },   // 0=frente,1=frente+pés,2=pés,3=pés+parabrisa,4=parabrisa
  seat_vent_drv:  { type: 'int',   min: 0,  max: 3 },
  seat_vent_pass: { type: 'int',   min: 0,  max: 3 },
  // Liga/desliga o compressor do AC (não só o fan). Mapeia para
  // `car.hvac.ac_enable` no barramento via Shizuku. Usar junto com fan_speed
  // pra garantir que liga o AC e não só sopra ar.
  ac_enable:      { type: 'bool' },
  // ON/OFF "inteligente" do AC: o APK guarda o fan anterior. OFF→fan=0;
  // ON→ac_enable=1 + restaura o fan que estava antes de desligar.
  power:          { type: 'bool' },
  // Extras (toggles on/off)
  acmax:          { type: 'bool' },   // resfriamento máximo
  anion:          { type: 'bool' },   // ionizador
  aqs:            { type: 'bool' },   // recirc. automática por qualidade do ar
  heating:        { type: 'bool' },   // aquecimento
  front_defrost:  { type: 'bool' },   // desembaçador dianteiro
  rear_defrost:   { type: 'bool' },   // desembaçador traseiro
  auto_defrost:   { type: 'bool' },   // desembaçar automático
};

// ── HF mode (alta frequência sob demanda) ─────────────────────────────────
// PWA chama este endpoint quando entra na aba cluster/conforto pra forçar o
// APK a publicar a 250ms em vez do intervalo configurado (5s default).
// Heartbeat: PWA bate a cada 5s. Se passar 10s sem chamada, o watchdog
// publica '0' automaticamente — evita ficar travado em HF se o PWA crashar.
let _hfModeActive = false;
// Ref-count POR CLIENTE: HF fica ON enquanto QUALQUER cliente quiser, e só
// desliga quando todos saem ou expiram. Acaba o flapping (múltiplos clientes
// brigando pelo estado global, ou o app indo pro background por segundos).
const _hfClients = new Map();   // clientId -> lastBeatMs
// 15s: cada cliente bate heartbeat a cada 3s. Margem cobre throttle de timer do
// iOS e o app indo pro background por poucos segundos (volta sem "congelar").
const HF_HEARTBEAT_TIMEOUT_MS = 15_000;
function _publishHfMode(active) {
  if (!mqttClient?.connected) return;
  mqttClient.publish(`${MQTT_PREFIX}/cmd/hf_mode`, active ? '1' : '0', { qos: 1, retain: false });
}
function _recomputeHf() {
  const now = Date.now();
  for (const [id, ts] of _hfClients) if (now - ts > HF_HEARTBEAT_TIMEOUT_MS) _hfClients.delete(id);
  const want = _hfClients.size > 0;
  if (want !== _hfModeActive) {
    _hfModeActive = want;
    _publishHfMode(want);
    console.log(`[hf_mode] ${want ? 'ON' : 'OFF'} (clients=${_hfClients.size})`);
  }
}
setInterval(_recomputeHf, 2000);
app.post('/api/hf_mode', (req, res) => {
  const active = req.body?.active === true;
  const cid = String(req.body?.client_id || req.ip || 'anon');
  if (active) _hfClients.set(cid, Date.now()); else _hfClients.delete(cid);
  _recomputeHf();
  res.json({ ok: true, active: _hfModeActive, clients: _hfClients.size });
});

// Resultados dos comandos físicos de teste, por sub (window/skylight/...).
const _vehicleResults = {};

// POST /api/vehicle/test  { sub, payload } — dispara cmd/vehicle/<sub> no carro e
// aguarda o /result (até 12s). Atalho pra descobrir o valor de "abrir" vidro etc.
//   sub: window | skylight | shade | door | windows_status
//   payload: objeto ou string. Ex: window → {"window":0,"status":0}; skylight → "1"
app.post('/api/vehicle/test', async (req, res) => {
  const sub = String(req.body?.sub || '').trim();
  if (!sub) return res.status(400).json({ error: 'sub obrigatório (window|skylight|shade|door|windows_status)' });
  if (!mqttClient?.connected) return res.status(503).json({ error: 'MQTT offline' });
  let payload = req.body?.payload;
  if (payload === undefined || payload === null) payload = '';
  if (typeof payload !== 'string') payload = JSON.stringify(payload);
  delete _vehicleResults[sub];
  mqttClient.publish(`${MQTT_PREFIX}/cmd/vehicle/${sub}`, payload, { qos: 1, retain: false });
  const start = Date.now();
  while (Date.now() - start < 12_000) {
    if (_vehicleResults[sub]) return res.json({ ok: true, sub, sent: payload, result: _vehicleResults[sub].value });
    await new Promise(r => setTimeout(r, 250));
  }
  res.json({ ok: true, sub, sent: payload, result: null, note: 'sem resposta em 12s (carro dormindo?)' });
});

// SPIKE: POST /api/mic-test  { sec?, source? } — dispara cmd/mic_test no carro e
// aguarda o /result (até 20s, pois grava ~3s por source). Prova se a central
// deixa um app 3rd-party capturar o mic integrado.
let _micTestResult = null;
app.post('/api/mic-test', requireAuth, async (req, res) => {
  if (!mqttClient?.connected) return res.status(503).json({ error: 'MQTT offline' });
  const payload = JSON.stringify({
    sec: parseInt(req.body?.sec) || 3,
    source: String(req.body?.source || ''),
  });
  _micTestResult = null;
  mqttClient.publish(`${MQTT_PREFIX}/cmd/mic_test`, payload, { qos: 1, retain: false });
  const start = Date.now();
  while (Date.now() - start < 20_000) {
    if (_micTestResult) return res.json({ ok: true, sent: payload, result: _micTestResult.value });
    await new Promise(r => setTimeout(r, 250));
  }
  res.json({ ok: true, sent: payload, result: null, note: 'sem resposta em 20s (carro dormindo?)' });
});

// ── Gravação de cabine por viagem (controle manual pelo iOS) ───────────────
// O carro grava localmente (WAV) e só transfere sob demanda. Estes endpoints
// só disparam start/stop/list via MQTT e devolvem o /result do carro. O
// download do arquivo é LAN direto (APK /api/rec/file/<id>); o bridge é só
// fallback de controle/listagem quando fora da LAN.
const _recResults = {};   // { rec_start|rec_stop|rec_list: { value, ts } }
async function _recCommand(res, cmd, payload, waitMs) {
  if (!mqttClient?.connected) return res.status(503).json({ error: 'MQTT offline' });
  _recResults[cmd] = null;
  mqttClient.publish(`${MQTT_PREFIX}/cmd/${cmd}`, payload, { qos: 1, retain: false });
  const start = Date.now();
  while (Date.now() - start < waitMs) {
    if (_recResults[cmd]) return res.json({ ok: true, result: _recResults[cmd].value });
    await new Promise(r => setTimeout(r, 200));
  }
  const carOnline = (Date.now() - (state.last_apk_ms || 0)) < 90_000;
  res.json({ ok: true, result: null, note: carOnline ? 'sem resposta do app (timeout)' : 'carro offline' });
}
